// Centralizes the Waitlist <-> Opportunity consistency invariant (Human-
// acceptance repair pass, §4/§5): a Contact cannot stay Waiting/Invited for
// a relationship they already have an active Opportunity for — Sarah Jones
// had an Approved Opportunity while her Living Example entry still said
// Waiting, because nothing but the Waitlist's OWN "Convert to Opportunity"
// button ever flipped an entry, and an Opportunity created or advanced
// through any other path (New Opportunity, an Application, drag-and-drop
// on the Kanban, a future integration) never went through it.
//
// This is wired into dataProvider.ts's ONE "deals" resource's
// afterCreate/afterUpdate lifecycle callbacks — every write to a Deal,
// regardless of which UI screen made it, funnels through those two hooks,
// so this is the single place the invariant is enforced (never scattered
// "also update the waitlist" calls across individual pages).
// waitlistActions.ts's own convertToOpportunity calls this directly too
// (its reuse-existing-deal branch writes nothing to "deals", so the
// dataProvider hook never fires for it) — see that file's own comment.
import type { DataProvider } from "ra-core";

import type { Deal, WaitlistEntry } from "../types";
import { ACTIVE_WAITLIST_STATUSES } from "./waitlistConstants";

// A Deal "establishes an active sales relationship" once it exists without
// having exited — archived or given an exit outcome (needs_higher_care /
// not_fit / nurture / lost). Deliberately broader than waitlistActions.ts's
// own isActiveDeal (which excludes Won, for a DIFFERENT purpose — deciding
// whether to reuse a deal instead of creating a duplicate): a Won deal is
// certainly not "still waiting" either, so it must still convert any
// compatible entry.
const establishesActiveSalesRelationship = (
  deal: Pick<Deal, "archived_at" | "outcome">,
) => deal.archived_at == null && deal.outcome == null;

// Compatible = same Contact + Offer, and:
// - a cohort-specific entry (cohort_id set) matches only that exact Cohort
//   ("a September-specific waitlist because the person has a November
//   Opportunity" must NOT convert), or
// - an offer-level entry (cohort_id null — "I want this generally") is
//   satisfied by ANY cohort of that Offer, since that's what "generally"
//   meant, and trivially by an individual Offer's own null cohort (LE).
const isCompatible = (entry: WaitlistEntry, deal: Deal) =>
  entry.contact_id === deal.contact_id &&
  entry.offer_id === deal.offer_id &&
  (entry.cohort_id == null || entry.cohort_id === deal.cohort_id);

// Finds every active Waitlist Entry compatible with this Deal and marks
// them Converted, linked to it. Idempotent (only touches entries still
// waiting/invited) and safe to call redundantly — a no-op once every
// compatible entry is already Converted.
export const syncWaitlistForActiveDeal = async (
  deal: Deal,
  dataProvider: DataProvider,
): Promise<void> => {
  if (!establishesActiveSalesRelationship(deal)) return;

  const { data: entries } = await dataProvider.getList<WaitlistEntry>(
    "waitlist_entries",
    {
      filter: { contact_id: deal.contact_id, offer_id: deal.offer_id },
      pagination: { page: 1, perPage: 100 },
      sort: { field: "id", order: "ASC" },
    },
  );

  const compatible = entries.filter(
    (entry) =>
      ACTIVE_WAITLIST_STATUSES.has(entry.status) && isCompatible(entry, deal),
  );
  if (compatible.length === 0) return;

  const convertedAt = new Date().toISOString();
  await Promise.all(
    compatible.map((entry) =>
      dataProvider.update("waitlist_entries", {
        id: entry.id,
        data: {
          status: "converted",
          converted_at: convertedAt,
          converted_opportunity_id: deal.id,
        },
        previousData: entry,
      }),
    ),
  );
};

// Gmail delivery does not exist yet. The invitation DOMAIN model is real
// and deployed (batches, per-person invitations, history, booking
// attribution) — but the bulk execution UI would read, in plain English, as
// "these 37 people have been invited" while nothing is actually sent.
//
// That ambiguity is unacceptable in production, so the bulk action stays
// hidden until a delivery mechanism exists. Nothing is deleted or rolled
// back: the schema, domain actions, types, tests and Contact-history
// integration all ship, and flipping this flag turns the UI on.
//
// Same mechanism the app already uses to gate a whole settings section on
// VITE_INBOUND_EMAIL — unset means the feature is simply not there.
//
// The individual "Mark Invited" action is deliberately NOT gated: it means
// "Leif invited this person himself, outside the CRM", which is truthful
// today and records a real invitation with delivery_method 'manual'.
export const isBulkInviteDeliveryEnabled = (): boolean =>
  import.meta.env.VITE_ENABLE_WAITLIST_INVITE_DELIVERY === "true";

import type { DataProvider, Identifier } from "ra-core";

import type {
  WaitlistEntry,
  WaitlistInvitation,
  WaitlistInvitationBatch,
  WaitlistInvitationDeliveryMethod,
} from "../types";

// The ONE canonical way a waitlist invitation comes into existence.
//
// Leif's real workflow: the sales-call calendar fills, he stops inviting;
// when capacity reopens he invites a large batch (30-40 people) off a
// waitlist to go book. That is a durable business event, and Gmail will
// later be a DELIVERY MECHANISM attached to these records — not the place
// the event lives.
//
// Both entry points use this module, so bulk and individual invites can
// never diverge into "bulk creates history, individual silently changes a
// status".

// Which memberships may be included in a new batch. A membership that has
// already converted or been removed is finished; a currently waiting OR
// previously invited one may legitimately be invited again (the August /
// October / January re-invite case is the whole reason invitations are
// their own records).
export const INVITABLE_WAITLIST_STATUSES: ReadonlySet<WaitlistEntry["status"]> =
  new Set(["waiting", "invited"]);

export const isInvitable = (entry: Pick<WaitlistEntry, "status">) =>
  INVITABLE_WAITLIST_STATUSES.has(entry.status);

export type PrepareInvitationBatchInput = {
  offerId: Identifier;
  cohortId?: Identifier | null;
  label?: string | null;
  entryIds: Identifier[];
};

export type PrepareInvitationBatchResult = {
  batch: WaitlistInvitationBatch;
  invitations: WaitlistInvitation[];
  // Entries asked for but not invitable (already converted/removed, or
  // gone). Reported rather than silently dropped.
  skippedEntryIds: Identifier[];
};

/**
 * Creates one batch plus one invitation per selected membership.
 *
 * Deliberately does NOT send anything and does NOT touch
 * waitlist_entries.status: nothing has been delivered yet, and marking
 * somebody Invited because a checkbox was ticked would be a lie. The
 * membership transitions only when a real send succeeds — see
 * recordInvitationSent below.
 */
export const prepareInvitationBatch = async (
  dataProvider: DataProvider,
  {
    offerId,
    cohortId = null,
    label = null,
    entryIds,
  }: PrepareInvitationBatchInput,
): Promise<PrepareInvitationBatchResult> => {
  const entries = await Promise.all(
    entryIds.map((id) =>
      dataProvider
        .getOne<WaitlistEntry>("waitlist_entries", { id })
        .then((res) => res.data)
        .catch(() => null),
    ),
  );

  const invitable: WaitlistEntry[] = [];
  const skippedEntryIds: Identifier[] = [];
  const seen = new Set<string>();
  for (const entry of entries) {
    if (!entry || !isInvitable(entry)) {
      continue;
    }
    // One invitation per membership per batch — a duplicated selection is
    // collapsed rather than creating two rows the unique index would
    // reject anyway.
    if (seen.has(String(entry.id))) continue;
    seen.add(String(entry.id));
    invitable.push(entry);
  }
  for (const [index, entry] of entries.entries()) {
    if (!entry || !isInvitable(entry)) skippedEntryIds.push(entryIds[index]!);
  }

  const { data: batch } = await dataProvider.create<WaitlistInvitationBatch>(
    "waitlist_invitation_batches",
    {
      data: {
        offer_id: offerId,
        cohort_id: cohortId,
        label,
        status: "prepared",
      } as Partial<WaitlistInvitationBatch>,
    },
  );

  const invitations: WaitlistInvitation[] = [];
  for (const entry of invitable) {
    const { data: invitation } = await dataProvider.create<WaitlistInvitation>(
      "waitlist_invitations",
      {
        data: {
          batch_id: batch.id,
          waitlist_entry_id: entry.id,
          contact_id: entry.contact_id,
          status: "prepared",
          prepared_at: new Date().toISOString(),
        } as Partial<WaitlistInvitation>,
      },
    );
    invitations.push(invitation);
  }

  return { batch, invitations, skippedEntryIds };
};

/**
 * Records that ONE invitation was genuinely delivered, and only then moves
 * that person's membership to Invited.
 *
 * This is the hook the Gmail integration will call once per successful
 * send. It is per-person on purpose: one person's success must never mark
 * anybody else invited, and one person's failure must never roll back the
 * people who did receive theirs.
 */
export const recordInvitationSent = async (
  dataProvider: DataProvider,
  invitationId: Identifier,
  deliveryMethod: WaitlistInvitationDeliveryMethod,
): Promise<{ applied: boolean }> => {
  const { data: invitation } = await dataProvider.getOne<WaitlistInvitation>(
    "waitlist_invitations",
    { id: invitationId },
  );
  if (invitation.status === "sent") return { applied: false };

  const now = new Date().toISOString();
  await dataProvider.update<WaitlistInvitation>("waitlist_invitations", {
    id: invitation.id,
    data: {
      status: "sent",
      sent_at: now,
      delivery_method: deliveryMethod,
      failed_at: null,
      failure_reason: null,
    },
    previousData: invitation,
  });

  // The membership follows the delivery, never the selection. Only a
  // still-waiting entry moves: a converted or removed one is finished, and
  // an already-invited one is simply invited again (its status is already
  // correct, and the new invitation row is what records the repeat).
  const { data: entry } = await dataProvider.getOne<WaitlistEntry>(
    "waitlist_entries",
    { id: invitation.waitlist_entry_id },
  );
  if (entry.status === "waiting") {
    await dataProvider.update<WaitlistEntry>("waitlist_entries", {
      id: entry.id,
      data: { status: "invited", invited_at: now },
      previousData: entry,
    });
  }

  return { applied: true };
};

/**
 * Records that ONE invitation failed to deliver. It stays retryable and
 * nobody's membership changes.
 */
export const recordInvitationFailed = async (
  dataProvider: DataProvider,
  invitationId: Identifier,
  failureReason: string,
): Promise<{ applied: boolean }> => {
  const { data: invitation } = await dataProvider.getOne<WaitlistInvitation>(
    "waitlist_invitations",
    { id: invitationId },
  );
  if (invitation.status === "sent") return { applied: false };

  await dataProvider.update<WaitlistInvitation>("waitlist_invitations", {
    id: invitation.id,
    data: {
      status: "failed",
      failed_at: new Date().toISOString(),
      failure_reason: failureReason,
    },
    previousData: invitation,
  });
  return { applied: true };
};

/**
 * Records an invitation Leif sent himself, outside the CRM — the truthful
 * meaning of the existing single-person "Mark Invited" action. It creates
 * the same canonical batch + invitation records a Gmail send will, with
 * delivery_method 'manual', so individual invites appear in history
 * identically to batched ones.
 */
export const recordManualInvitation = async (
  dataProvider: DataProvider,
  entryId: Identifier,
): Promise<{ applied: boolean; reason?: "not-invitable" }> => {
  const { data: entry } = await dataProvider.getOne<WaitlistEntry>(
    "waitlist_entries",
    { id: entryId },
  );
  if (!isInvitable(entry)) return { applied: false, reason: "not-invitable" };

  const { invitations } = await prepareInvitationBatch(dataProvider, {
    offerId: entry.offer_id,
    cohortId: entry.cohort_id ?? null,
    entryIds: [entry.id],
  });
  const invitation = invitations[0];
  if (!invitation) return { applied: false, reason: "not-invitable" };

  await recordInvitationSent(dataProvider, invitation.id, "manual");
  return { applied: true };
};

/**
 * Attributes a booking to the most recent still-open invitation for this
 * membership — the fact that makes "has this person booked since we asked?"
 * (and therefore "is a no-booking follow-up still eligible?") answerable.
 *
 * Not wired to anything yet: the Gmail slice owns the follow-up sequence,
 * and the booking signal itself already exists (an Acuity booking creates
 * or attaches an Opportunity, which is what flips the membership to
 * converted via waitlistSync.ts). This is the seam that slice attaches to.
 */
export const attributeBookingToInvitation = async (
  dataProvider: DataProvider,
  {
    waitlistEntryId,
    salesCallId,
    bookedAt,
  }: {
    waitlistEntryId: Identifier;
    salesCallId: Identifier;
    bookedAt: string;
  },
): Promise<{ applied: boolean }> => {
  const { data: invitations } = await dataProvider.getList<WaitlistInvitation>(
    "waitlist_invitations",
    {
      filter: { waitlist_entry_id: waitlistEntryId },
      pagination: { page: 1, perPage: 100 },
      sort: { field: "id", order: "DESC" },
    },
  );
  const target = invitations.find(
    (invitation) =>
      invitation.status === "sent" && invitation.booked_sales_call_id == null,
  );
  if (!target) return { applied: false };

  await dataProvider.update<WaitlistInvitation>("waitlist_invitations", {
    id: target.id,
    data: { booked_sales_call_id: salesCallId, booked_at: bookedAt },
    previousData: target,
  });
  return { applied: true };
};

// Shared validation for Waitlist Entries (Waitlists slice, §4/§19),
// enforced identically wherever an entry can be created — the FakeRest
// lifecycle hook (dataProvider.ts) and the addToWaitlist domain action
// both call this, mirroring how offerCohortValidation.ts is shared between
// FakeRest and the UI's understanding of the same rule the Postgres
// trigger enforces (handle_waitlist_entry_saved()). The real DB's partial
// unique index (waitlist_entries_active_unique_idx) is defense-in-depth
// for direct SQL/races — FakeRest has no constraint engine at all, so this
// function is the *only* thing that can enforce the rule there.
import type { DataProvider, Identifier } from "ra-core";

import type { WaitlistEntry } from "../types";
import { ACTIVE_WAITLIST_STATUSES } from "./waitlistConstants";

export class DuplicateActiveWaitlistEntryError extends Error {}

// Finds an existing active (waiting/invited) entry for this exact
// Contact + Offer + Cohort combination, if any. `cohortId` must be passed
// as `null` (not `undefined`) for an offer-level check — undefined would
// match "don't filter by cohort" instead of "cohort is null" against a
// FakeRest-style equality filter.
export const findActiveWaitlistEntry = async (
  dataProvider: DataProvider,
  {
    contactId,
    offerId,
    cohortId,
  }: {
    contactId: Identifier;
    offerId: Identifier;
    cohortId: Identifier | null;
  },
): Promise<WaitlistEntry | null> => {
  const { data: entries } = await dataProvider.getList<WaitlistEntry>(
    "waitlist_entries",
    {
      filter: { contact_id: contactId, offer_id: offerId },
      pagination: { page: 1, perPage: 100 },
      sort: { field: "id", order: "ASC" },
    },
  );

  const match = entries.find(
    (entry) =>
      ACTIVE_WAITLIST_STATUSES.has(entry.status) &&
      (entry.cohort_id ?? null) === cohortId,
  );
  return match ?? null;
};

export const assertNoDuplicateActiveWaitlistEntry = async (
  dataProvider: DataProvider,
  params: {
    contactId: Identifier;
    offerId: Identifier;
    cohortId: Identifier | null;
  },
): Promise<void> => {
  const existing = await findActiveWaitlistEntry(dataProvider, params);
  if (existing) {
    throw new DuplicateActiveWaitlistEntryError(
      `Contact ${params.contactId} already has an active waitlist entry (#${existing.id}) for offer ${params.offerId}${
        params.cohortId != null ? ` / cohort ${params.cohortId}` : ""
      }`,
    );
  }
};

import type { WaitlistEntryStatus } from "../types";

export const waitlistEntryStatuses: {
  value: WaitlistEntryStatus;
  label: string;
}[] = [
  { value: "waiting", label: "Waiting" },
  { value: "invited", label: "Invited" },
  { value: "converted", label: "Converted" },
  { value: "removed", label: "Removed" },
];

export const waitlistEntryStatusLabels: Record<WaitlistEntryStatus, string> = {
  waiting: "Waiting",
  invited: "Invited",
  converted: "Converted",
  removed: "Removed",
};

export const waitlistEntryStatusBadgeVariant: Record<
  WaitlistEntryStatus,
  "default" | "secondary" | "destructive" | "outline"
> = {
  waiting: "outline",
  invited: "default",
  converted: "secondary",
  removed: "secondary",
};

// "Active" mirrors the DB's partial unique index predicate exactly
// (status IN ('waiting','invited')) — the only two statuses that count
// toward duplicate prevention, program waitlist counts, and Person-page
// "currently waiting" displays.
export const ACTIVE_WAITLIST_STATUSES: ReadonlySet<WaitlistEntryStatus> =
  new Set(["waiting", "invited"]);

// Centralizes every Waitlist Entry status transition (Waitlists slice,
// §11/§12/§13/§19/§25) — the UI only ever calls these, business rules
// never live in a button's onClick. Each re-fetches the entry's current
// state before deciding (never trusts the caller's own possibly-stale
// copy) so a double-click, a cached tab, or Back/Forward can never
// silently re-apply or overwrite a newer transition — mirroring
// applications/reviewApplication.ts's idempotency approach exactly.
import type { DataProvider, Identifier } from "ra-core";

import { isContactDoNotEngage } from "../contacts/doNotEngageGuard";
import type { Deal, Offer, WaitlistEntry } from "../types";
import { recordManualInvitation } from "./waitlistInvitations";
import { syncWaitlistForActiveDeal } from "./waitlistSync";

export type WaitlistTransitionResult =
  | { applied: true }
  | { applied: false; reason: "not-active" | "not-waiting" };

// waiting -> invited. Never creates an Opportunity by itself (§13: Invited
// only means "I offered them the opening" — Converted is a distinct,
// explicit later choice).
export const markInvited = async (
  dataProvider: DataProvider,
  entryId: Identifier,
): Promise<WaitlistTransitionResult> => {
  // Routed through the canonical invitation model so a single-person
  // invite produces the same durable history a batch does — otherwise bulk
  // invites would build a record and individual ones would silently change
  // a status. It records an invitation Leif sent himself
  // (delivery_method 'manual'), which is what this action has always
  // meant, and only then moves the membership.
  //
  // An already-invited membership is invitable again (the repeat-invite
  // case): the new invitation row records the repeat, and the status is
  // already correct.
  const result = await recordManualInvitation(dataProvider, entryId);
  if (!result.applied) {
    return { applied: false, reason: "not-waiting" };
  }
  return { applied: true };
};

// waiting/invited -> removed. History is preserved (§2/§11): the row
// stays, the Contact and any prior Opportunities are untouched.
export const removeFromWaitlist = async (
  dataProvider: DataProvider,
  entryId: Identifier,
): Promise<WaitlistTransitionResult> => {
  const { data: entry } = await dataProvider.getOne<WaitlistEntry>(
    "waitlist_entries",
    { id: entryId },
  );
  if (entry.status !== "waiting" && entry.status !== "invited") {
    return { applied: false, reason: "not-active" };
  }

  await dataProvider.update("waitlist_entries", {
    id: entry.id,
    data: { status: "removed", removed_at: new Date().toISOString() },
    previousData: entry,
  });
  return { applied: true };
};

export type ConvertToOpportunityResult =
  | { applied: true; dealId: Identifier; reusedExisting: boolean }
  | {
      applied: false;
      reason: "not-active" | "do-not-engage";
    };

// "Active" Opportunity for reuse detection — the same active-pipeline
// definition DealList.tsx's own query already uses (not won, not
// archived, no exit outcome). Deliberately narrow: an Enrollment/past
// Opportunity does not block conversion — only a currently-open one does
// (§12: "If an existing active Opportunity already exists ... do NOT
// create a duplicate").
const isActiveDeal = (deal: Pick<Deal, "stage" | "outcome" | "archived_at">) =>
  deal.archived_at == null && deal.stage !== "won" && deal.outcome == null;

// waiting/invited -> converted. Creates (or reuses) an Opportunity for the
// same Contact + Offer + Cohort, starting at "Interested" — never a later
// stage, since a waitlisted person may not have applied yet, and
// fabricating sales history (Application Received/Approved/Call Booked)
// would misrepresent what actually happened (§12).
export const convertToOpportunity = async (
  dataProvider: DataProvider,
  entryId: Identifier,
): Promise<ConvertToOpportunityResult> => {
  const { data: entry } = await dataProvider.getOne<WaitlistEntry>(
    "waitlist_entries",
    { id: entryId },
  );
  if (entry.status !== "waiting" && entry.status !== "invited") {
    return { applied: false, reason: "not-active" };
  }

  // DNE is a durable "no future direct sales" gate (Native Applications
  // repair pass, §5) — it can't be bypassed just because the waitlist
  // entry predates the Contact becoming DNE.
  if (await isContactDoNotEngage(dataProvider, entry.contact_id)) {
    return { applied: false, reason: "do-not-engage" };
  }

  const { data: existingDeals } = await dataProvider.getList<Deal>("deals", {
    filter: {
      contact_id: entry.contact_id,
      offer_id: entry.offer_id,
      ...(entry.cohort_id != null ? { cohort_id: entry.cohort_id } : {}),
    },
    pagination: { page: 1, perPage: 100 },
    sort: { field: "id", order: "ASC" },
  });
  const existingActiveDeal = existingDeals.find(isActiveDeal);

  let dealId: Identifier;
  let reusedExisting: boolean;

  if (existingActiveDeal) {
    dealId = existingActiveDeal.id;
    reusedExisting = true;
    // Reusing writes nothing to "deals", so dataProvider.ts's centralized
    // afterCreate/afterUpdate sync (waitlistSync.ts) never fires for this
    // path — call it directly, the only place that needs to. It marks
    // THIS entry (and any other compatible one, e.g. a sibling general-
    // Offer-level entry — §4) Converted, so no separate update is needed
    // here.
    await syncWaitlistForActiveDeal(existingActiveDeal, dataProvider);
  } else {
    const { data: offer } = await dataProvider.getOne<Offer>("offers", {
      id: entry.offer_id,
    });
    // The "deals" afterCreate hook (dataProvider.ts) runs
    // syncWaitlistForActiveDeal for the new deal before create() resolves
    // (FakeRest calls are sequential/awaited — see ensureEnrollmentFor-
    // WonDeal's own comment) — this entry is already Converted by the
    // time this call returns; nothing further to do here either.
    const { data: createdDeal } = await dataProvider.create<Deal>("deals", {
      data: {
        contact_id: entry.contact_id,
        offer_id: entry.offer_id,
        cohort_id: entry.cohort_id ?? null,
        stage: "interested",
        outcome: null,
        amount: offer.current_price,
        source: entry.source ?? null,
        description: "",
      },
    });
    dealId = createdDeal.id;
    reusedExisting = false;
  }

  return { applied: true, dealId, reusedExisting };
};

import { useGetList, useGetMany, type Identifier } from "ra-core";

import type { Contact, WaitlistEntry, WaitlistEntryStatus } from "../types";
import { ACTIVE_WAITLIST_STATUSES } from "./waitlistConstants";

export type WaitlistEntryRow = {
  entryId: Identifier;
  contactId: Identifier;
  name: string;
  // Every email on file, joined — used only for local search matching
  // (WaitlistSection.tsx, human-acceptance repair pass §1), never
  // displayed. No dedicated Instagram-handle field exists on Contact yet,
  // so search matches name/email only — see that file's own comment.
  email: string | null;
  status: WaitlistEntryStatus;
  joinedAt: string;
  desiredTiming: string | null;
  notes: string | null;
  priority: number | null;
};

// Backs every "Waitlist" section (Living Example / Group Program / Cohort
// pages, §7/§8) and their counts (Programs hub / Dashboard cards, §6/§15,
// and program capacity cards) — real WaitlistEntry + Contact data only.
// Returns *active* (waiting/invited) entries only: a Program/Cohort page's
// live waitlist is a current-operations view, not a history log — see
// waitlist/useContactWaitlists.ts for the Contact-side lifetime history
// (including converted/removed).
//
// `cohortId: null` means offer-level entries only (cohort_id IS NULL —
// general "wants this Offer" waiting, never silently including
// cohort-specific entries); `offerId` is required in this case. `cohortId:
// <id>` means that Cohort's entries only — a Cohort id alone already
// disambiguates, so `offerId` isn't needed (and is ignored) in this case,
// letting callers that only have a cohort id on hand (useCohortCapacity)
// use this without an extra Offer fetch. Never pass `undefined` for
// cohortId — pass `null` explicitly, so an offer-level and a
// cohort-specific query can never be confused with each other.
export const useWaitlistEntries = ({
  offerId,
  cohortId,
}: {
  offerId?: Identifier;
  cohortId: Identifier | null;
}) => {
  const { data: entries, isPending: entriesPending } =
    useGetList<WaitlistEntry>(
      "waitlist_entries",
      {
        filter:
          cohortId != null
            ? { cohort_id: cohortId }
            : { offer_id: offerId, "cohort_id@is": null },
        pagination: { page: 1, perPage: 1000 },
        sort: { field: "joined_at", order: "ASC" },
      },
      { enabled: cohortId != null || offerId != null },
    );

  const activeEntries = (entries ?? []).filter((entry) =>
    ACTIVE_WAITLIST_STATUSES.has(entry.status),
  );

  const contactIds = [
    ...new Set(activeEntries.map((entry) => entry.contact_id)),
  ];
  const { data: contacts, isPending: contactsPending } = useGetMany<Contact>(
    "contacts",
    { ids: contactIds },
    { enabled: contactIds.length > 0 },
  );

  const isPending =
    entriesPending || (contactIds.length > 0 && contactsPending);

  if (isPending) {
    return { isPending: true, entries: [] as WaitlistEntryRow[] };
  }

  const contactById = new Map(
    (contacts ?? []).map((contact) => [String(contact.id), contact]),
  );
  const nameFor = (contactId: Identifier) => {
    const contact = contactById.get(String(contactId));
    return contact ? `${contact.first_name} ${contact.last_name}` : "";
  };
  const emailFor = (contactId: Identifier) => {
    const emails = (contactById.get(String(contactId))?.email_jsonb ?? [])
      .map((entry) => entry.email)
      .filter(Boolean);
    return emails.length > 0 ? emails.join(", ") : null;
  };

  const rows: WaitlistEntryRow[] = activeEntries
    .map((entry) => ({
      entryId: entry.id,
      contactId: entry.contact_id,
      name: nameFor(entry.contact_id),
      email: emailFor(entry.contact_id),
      status: entry.status,
      joinedAt: entry.joined_at,
      desiredTiming: entry.desired_timing ?? null,
      notes: entry.notes ?? null,
      priority: entry.priority ?? null,
    }))
    // Priority first (lower = sooner) when set, then joined date — a
    // sortable hint, never a rigid FIFO rule (§14).
    .sort((a, b) => {
      if (a.priority != null && b.priority != null) {
        return a.priority - b.priority || a.joinedAt.localeCompare(b.joinedAt);
      }
      if (a.priority != null) return -1;
      if (b.priority != null) return 1;
      return a.joinedAt.localeCompare(b.joinedAt);
    });

  return { isPending: false, entries: rows };
};

import { useGetList, useGetMany, type Identifier } from "ra-core";

import type { Cohort, Offer, WaitlistEntry } from "../types";

export type ContactWaitlistRow = {
  entryId: Identifier;
  offerId: Identifier;
  offerName: string;
  cohortId: Identifier | null;
  cohortName: string | null;
  status: WaitlistEntry["status"];
  joinedAt: string;
  desiredTiming: string | null;
  invitedAt: string | null;
  convertedAt: string | null;
  convertedOpportunityId: Identifier | null;
  removedAt: string | null;
  programPath: string;
};

// Backs ContactShow's "Waitlists" section (Waitlists slice, §10): the
// Contact's full lifetime history — active AND historical (converted/
// removed) — since a past relationship stays visible even after it ends,
// same principle as Opportunities already showing on a Contact regardless
// of stage/outcome.
export const useContactWaitlists = (contactId?: Identifier) => {
  const { data: entries, isPending: entriesPending } =
    useGetList<WaitlistEntry>(
      "waitlist_entries",
      {
        filter: { contact_id: contactId },
        pagination: { page: 1, perPage: 100 },
        sort: { field: "joined_at", order: "DESC" },
      },
      { enabled: contactId != null },
    );

  const offerIds = [...new Set((entries ?? []).map((entry) => entry.offer_id))];
  const { data: offers, isPending: offersPending } = useGetMany<Offer>(
    "offers",
    { ids: offerIds },
    { enabled: offerIds.length > 0 },
  );

  const cohortIds = [
    ...new Set(
      (entries ?? [])
        .map((entry) => entry.cohort_id)
        .filter((id): id is Identifier => id != null),
    ),
  ];
  const { data: cohorts, isPending: cohortsPending } = useGetMany<Cohort>(
    "cohorts",
    { ids: cohortIds },
    { enabled: cohortIds.length > 0 },
  );

  const isPending =
    entriesPending ||
    (offerIds.length > 0 && offersPending) ||
    (cohortIds.length > 0 && cohortsPending);

  if (isPending) {
    return { isPending: true, entries: [] as ContactWaitlistRow[] };
  }

  const offerById = new Map((offers ?? []).map((o) => [String(o.id), o]));
  const cohortById = new Map((cohorts ?? []).map((c) => [String(c.id), c]));

  const rows: ContactWaitlistRow[] = (entries ?? []).map((entry) => {
    const offer = offerById.get(String(entry.offer_id));
    const cohort =
      entry.cohort_id != null
        ? cohortById.get(String(entry.cohort_id))
        : undefined;

    return {
      entryId: entry.id,
      offerId: entry.offer_id,
      offerName: offer?.name ?? "",
      cohortId: entry.cohort_id ?? null,
      cohortName: cohort?.name ?? null,
      status: entry.status,
      joinedAt: entry.joined_at,
      desiredTiming: entry.desired_timing ?? null,
      invitedAt: entry.invited_at ?? null,
      convertedAt: entry.converted_at ?? null,
      convertedOpportunityId: entry.converted_opportunity_id ?? null,
      removedAt: entry.removed_at ?? null,
      programPath: cohort
        ? `/cohorts/${cohort.id}/show`
        : offer?.type === "individual"
          ? `/programs/individual/${entry.offer_id}`
          : `/programs/group/${entry.offer_id}`,
    };
  });

  return { isPending: false, entries: rows };
};

// The importer stamps each historical waitlist membership's notes with how
// its joined_at was derived (see write.mjs's insertHistoricalWaitlistEntry).
// That evidence is the audit trail and stays stored — it just does not
// belong in the everyday waitlist row, where 37 copies of it drown out the
// people's names. Matched on the importer's own literal prefix, never on
// anything about the wording after it, so a note Leif actually typed is
// never mistaken for migration evidence.
export const IMPORT_PROVENANCE_PREFIX = "Historical import:";

export const isImportProvenance = (notes: string): boolean =>
  notes.trimStart().startsWith(IMPORT_PROVENANCE_PREFIX);

