// established for its own many-row sections, not a new visual language.
// Capped at VISIBLE_COUNT with a "show more" toggle (same established
// pattern as dashboard/DashboardTasks.tsx) so 50+ waiting people never
// force the page itself to become enormous.
const VISIBLE_COUNT = 8;

// Human-acceptance repair pass, §1: an 8-row collapse keeps a 50-person
// list from taking over the page, but doesn't make finding ONE person in
// it easy. A tiny local search (name/email — see useWaitlistEntries.ts's
// WaitlistEntryRow.email comment on why not Instagram handle) bypasses the
// collapse for its matches; only shown once the list is actually long
// enough that the collapse (and thus a search) matters.
export const WaitlistSection = ({
  entries,
  offerId,
  offerName,
  cohortId = null,
  cohortName = null,
  // Defaults to the feature flag; an explicit value lets tests exercise
  // both the production (hidden) and post-Gmail (visible) states.
  enableBulkInvite = isBulkInviteDeliveryEnabled(),
}: {
  entries: WaitlistEntryRow[];
  // Optional so a caller that has not been given batch-invite context yet
  // simply renders the list exactly as before.
  offerId?: Identifier;
  offerName?: string;
  cohortId?: Identifier | null;
  cohortName?: string | null;
  enableBulkInvite?: boolean;
}) => {
  const translate = useTranslate();
  const [expanded, setExpanded] = useState(false);
  const [search, setSearch] = useState("");
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [inviteOpen, setInviteOpen] = useState(false);

  // Hidden in production until Gmail delivery exists — a "prepared" batch
  // must never be presented as though people were actually invited.
  const canInvite = enableBulkInvite && offerId != null && offerName != null;
  // Only a membership that has not converted or been removed can be
  // invited. A previously invited one stays selectable on purpose — that
  // is the legitimate re-invite case.
  const invitableEntries = entries.filter(isInvitable);
  const selectedEntries = entries.filter((entry) =>
    selectedIds.has(String(entry.entryId)),
  );
  const allInvitableSelected =
    invitableEntries.length > 0 &&
    invitableEntries.every((entry) => selectedIds.has(String(entry.entryId)));

  const toggleOne = (entryId: Identifier) =>
    setSelectedIds((current) => {
      const next = new Set(current);
      const key = String(entryId);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });

  // Select all covers only invitable rows — converted/removed people are
  // never silently swept into a batch.
  const toggleAll = () =>
    setSelectedIds(
      allInvitableSelected
        ? new Set()
        : new Set(invitableEntries.map((entry) => String(entry.entryId))),
    );

  const query = search.trim().toLowerCase();
  const isSearching = query !== "";
  const matchingEntries = useMemo(() => {
    if (!isSearching) return entries;
    return entries.filter(
      (entry) =>
        entry.name.toLowerCase().includes(query) ||
        (entry.email?.toLowerCase().includes(query) ?? false),
    );
  }, [entries, isSearching, query]);

  // Searching always shows every match, regardless of the collapsed state.
  const visibleEntries = isSearching
    ? matchingEntries
    : expanded
      ? matchingEntries
      : matchingEntries.slice(0, VISIBLE_COUNT);
  const remaining = isSearching
    ? 0
    : matchingEntries.length - visibleEntries.length;

  const title = `${translate("resources.waitlist_entries.name", {
    _: "Waitlist",
    smart_count: 1,
  })} · ${entries.length}`;

  return (
    <Section title={title}>
      {canInvite && invitableEntries.length > 0 && (
        <div className="mb-2 flex items-center justify-between gap-3">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="px-0 text-xs text-muted-foreground"
            onClick={toggleAll}
          >
            {allInvitableSelected
              ? translate("resources.waitlist_entries.invite.clear", {
                  _: "Clear",
                })
              : translate("resources.waitlist_entries.invite.select_all", {
                  _: "Select all",
                })}
          </Button>
          {selectedEntries.length > 0 && (
            <Button type="button" size="sm" onClick={() => setInviteOpen(true)}>
              {translate("resources.waitlist_entries.invite.action", {
                _: "Invite to Book",
              })}{" "}
              · {selectedEntries.length}
            </Button>
          )}
        </div>
      )}
      {canInvite && (
        <InviteToBookDialog
          open={inviteOpen}
          onOpenChange={setInviteOpen}
          offerId={offerId!}
          offerName={offerName!}
          cohortId={cohortId}
          cohortName={cohortName}
          selected={selectedEntries}
          onConfirmed={() => setSelectedIds(new Set())}
        />
      )}
      {entries.length === 0 ? (
        <p className="text-sm text-muted-foreground">
          {translate("resources.waitlist_entries.empty", {
            _: "Nobody waiting.",
          })}
        </p>
      ) : (
        <div className="flex flex-col gap-2">
          {entries.length > VISIBLE_COUNT && (
            <div className="relative">
              <Search className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
              <Input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder={translate(
                  "resources.waitlist_entries.search_placeholder",
                  { _: "Search name or email…" },
                )}
                className="h-8 pl-8 pr-8 text-sm"
              />
              {isSearching && (
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="absolute right-0.5 top-1/2 size-7 -translate-y-1/2"
                  onClick={() => setSearch("")}
                  aria-label={translate("ra.action.clear_input_value", {
                    _: "Clear",
                  })}
                >
                  <X className="size-3.5" />
                </Button>
              )}
            </div>
          )}
          {isSearching && matchingEntries.length === 0 ? (
            <p className="text-sm text-muted-foreground px-1">
              {translate("resources.waitlist_entries.search_empty", {
                _: "No one matches “%{query}”.",
                query: search.trim(),
              })}
            </p>
          ) : (
            <Card className="p-0">
              <CardContent className="p-0 divide-y">
                {visibleEntries.map((entry) => (
                  <div
                    key={entry.entryId}
                    className="flex items-center justify-between gap-3 px-4 py-2.5"
                  >
                    {canInvite && (
                      <Checkbox
                        className="shrink-0"
                        aria-label={entry.name}
                        disabled={!isInvitable(entry)}
                        checked={selectedIds.has(String(entry.entryId))}
                        onCheckedChange={() => toggleOne(entry.entryId)}
                      />
                    )}
                    <div className="flex min-w-0 flex-1 items-baseline gap-2">
                      <Link
                        to={`/contacts/${entry.contactId}/show`}
                        className="text-sm font-medium hover:underline shrink-0"
                      >
                        {entry.name}
                      </Link>
                      <span className="text-xs text-muted-foreground truncate">
                        {metaFor(entry, (key, fallback) =>
                          translate(key, { _: fallback }),
                        )}
                      </span>
                    </div>
                    <div className="flex items-center gap-2 shrink-0">
                      <Badge
                        variant={waitlistEntryStatusBadgeVariant[entry.status]}
                      >
                        {waitlistEntryStatusLabels[entry.status]}
                      </Badge>
                      <WaitlistEntryActions
                        entryId={entry.entryId}
                        status={entry.status}
                      />
                    </div>
                  </div>
                ))}
              </CardContent>
              {remaining > 0 && (
                <button
                  type="button"
                  onClick={() => setExpanded(true)}
                  className="text-sm text-muted-foreground underline hover:no-underline text-left px-4 pb-3 pt-1"
                >
                  {translate("crm.dashboard.tasks_load_more", {
                    _: "%{count} more",
                    count: remaining,
                  })}
                </button>
              )}
            </Card>
          )}
        </div>
      )}
    </Section>
  );
};

const metaFor = (
  entry: WaitlistEntryRow,
  translate: (key: string, fallback: string) => string,
) => {
  const joinedLabel = translate(
    "resources.waitlist_entries.fields.joined_at",
    "Joined",
  );
  const parts = [`${joinedLabel} ${formatTimestampString(entry.joinedAt)}`];
  if (entry.desiredTiming) parts.push(entry.desiredTiming);
  // Import provenance stays STORED on the row — it is the audit trail for
  // how a historical membership's joined_at was derived, and deleting it
  // would destroy that. It just does not belong in the everyday row, where
  // 37 copies of "Historical import: waitlist order 3 of 21 is
  // source-confirmed (Existing List)..." drown out the person's name. A
  // note Leif actually typed still shows; only migration evidence is held
  // back, and it remains visible in the entry's own record.
  if (entry.notes && !isImportProvenance(entry.notes)) parts.push(entry.notes);
  return parts.join(" · ");
};

import {
  useCreate,
  useDataProvider,
  useGetIdentity,
  useNotify,
  required,
  useTranslate,
  type Identifier,
} from "ra-core";
import { AutocompleteInput } from "@/components/admin/autocomplete-input";
import { ReferenceInput } from "@/components/admin/reference-input";

import type { Contact } from "../types";
import { doNotEngageValidator } from "../contacts/doNotEngageGuard";
import { personOptionText } from "../deals/PersonOption";
import { findActiveWaitlistEntry } from "./waitlistEntryValidation";

// The "Person" field for Add to Waitlist (Waitlists slice, §9) — same
// person-first conventions as the Opportunity Person field
// (deals/OpportunityPersonInput.tsx): search reuses every existing
// Contact, quick-create for a brand-new one, Do Not Engage stays visible/
// selectable but blocks submission (§5). Adds a second async validator for
// the duplicate-active-entry rule (§4) so the mistake surfaces immediately
// rather than as a raw write failure from the FakeRest hook / Postgres
// constraint.
export const WaitlistPersonInput = ({
  offerId,
  cohortId,
}: {
  offerId: Identifier;
  cohortId: Identifier | null;
}) => {
  const translate = useTranslate();
  const [create] = useCreate();
  const { identity } = useGetIdentity();
  const notify = useNotify();
  const dataProvider = useDataProvider();

  const doNotEngageMessage = translate(
    "resources.waitlist_entries.person_input.do_not_engage_error",
    {
      _: "This person is marked Do Not Engage — they can't be added to a waitlist.",
    },
  );
  const duplicateMessage = translate(
    "resources.waitlist_entries.person_input.duplicate_error",
    { _: "This person is already waiting for this program." },
  );

  const validateDuplicate = async (value?: Identifier) => {
    if (!value) return undefined;
    const existing = await findActiveWaitlistEntry(dataProvider, {
      contactId: value,
      offerId,
      cohortId,
    });
    return existing ? duplicateMessage : undefined;
  };

  const handleCreatePerson = async (name?: string) => {
    if (!name) return;
    const [firstName, ...rest] = name.trim().split(/\s+/).filter(Boolean);
    try {
      const newContact = await create(
        "contacts",
        {
          data: {
            first_name: firstName ?? name,
            last_name: rest.join(" "),
            email_jsonb: [],
            phone_jsonb: [],
            tags: [],
            sales_id: identity?.id,
            first_seen: new Date().toISOString(),
            last_seen: new Date().toISOString(),
          },
        },
        { returnPromise: true },
      );
      return newContact;
    } catch {
      notify("resources.waitlist_entries.person_input.create_error", {
        type: "error",
        messageArgs: { _: "An error occurred while creating the person" },
      });
    }
  };

  return (
    <div className="flex flex-col gap-4">
      <h3 className="text-base font-medium">
        {translate("resources.deals.person_input.label", { _: "Person" })}
      </h3>
      <ReferenceInput source="contact_id" reference="contacts_summary">
        <AutocompleteInput
          label={false}
          placeholder={translate("resources.deals.person_input.placeholder", {
            _: "Search by name or email…",
          })}
          optionText={personOptionText}
          inputText={(choice: Contact | undefined) =>
            choice ? `${choice.first_name} ${choice.last_name}` : ""
          }
          helperText={false}
          validate={[
            required(),
            doNotEngageValidator(dataProvider, doNotEngageMessage),
            validateDuplicate,
          ]}
          onCreate={handleCreatePerson}
          createLabel="resources.deals.person_input.create_label"
          createItemLabel="resources.deals.person_input.create_item_label"
        />
      </ReferenceInput>
    </div>
  );
};

