import { useState } from "react";
import { MoreVertical } from "lucide-react";
import { useDataProvider, useNotify, useRefresh, useTranslate } from "ra-core";
import type { Identifier } from "ra-core";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

import type { WaitlistEntryStatus } from "../types";
import { WaitlistEntryEditSheet } from "./WaitlistEntryEditSheet";
import {
  convertToOpportunity,
  markInvited,
  removeFromWaitlist,
} from "./waitlistActions";

// The operational actions for one active (waiting/invited) Waitlist Entry
// (Waitlists slice, §11/§12/§13) — every write goes through
// waitlistActions.ts; this component only orchestrates the click and the
// resulting notification/refresh. Never rendered for a converted/removed
// (historical) entry — those are read-only on ContactShow.
export const WaitlistEntryActions = ({
  entryId,
  status,
}: {
  entryId: Identifier;
  status: WaitlistEntryStatus;
}) => {
  const translate = useTranslate();
  const dataProvider = useDataProvider();
  const notify = useNotify();
  const refresh = useRefresh();
  const [busy, setBusy] = useState(false);
  const [editOpen, setEditOpen] = useState(false);

  const runInvite = async () => {
    setBusy(true);
    try {
      const result = await markInvited(dataProvider, entryId);
      notify(
        result.applied
          ? "resources.waitlist_entries.notifications.invited"
          : "resources.waitlist_entries.notifications.stale",
        { type: result.applied ? "info" : "warning" },
      );
    } catch {
      notify("ra.notification.http_error", { type: "error" });
    } finally {
      setBusy(false);
      refresh();
    }
  };

  const runConvert = async () => {
    setBusy(true);
    try {
      const result = await convertToOpportunity(dataProvider, entryId);
      if (!result.applied) {
        notify(
          result.reason === "do-not-engage"
            ? "resources.waitlist_entries.notifications.do_not_engage"
            : "resources.waitlist_entries.notifications.stale",
          { type: "warning" },
        );
      } else {
        notify(
          result.reusedExisting
            ? "resources.waitlist_entries.notifications.converted_existing"
            : "resources.waitlist_entries.notifications.converted",
          { type: "info" },
        );
      }
    } catch {
      notify("ra.notification.http_error", { type: "error" });
    } finally {
      setBusy(false);
      refresh();
    }
  };

  const runRemove = async () => {
    setBusy(true);
    try {
      const result = await removeFromWaitlist(dataProvider, entryId);
      notify(
        result.applied
          ? "resources.waitlist_entries.notifications.removed"
          : "resources.waitlist_entries.notifications.stale",
        { type: result.applied ? "info" : "warning" },
      );
    } catch {
      notify("ra.notification.http_error", { type: "error" });
    } finally {
      setBusy(false);
      refresh();
    }
  };

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            variant="ghost"
            size="icon"
            className="size-8"
            disabled={busy}
            aria-label={translate("resources.waitlist_entries.actions.title", {
              _: "Waitlist entry actions",
            })}
          >
            <MoreVertical className="size-4" />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuItem onClick={() => setEditOpen(true)}>
            {translate("resources.waitlist_entries.actions.edit", {
              _: "Edit",
            })}
          </DropdownMenuItem>
          {status === "waiting" && (
            <DropdownMenuItem onClick={runInvite}>
              {translate("resources.waitlist_entries.actions.mark_invited", {
                _: "Mark Invited",
              })}
            </DropdownMenuItem>
          )}
          <DropdownMenuItem onClick={runConvert}>
            {translate("resources.waitlist_entries.actions.convert", {
              _: "Convert to Opportunity",
            })}
          </DropdownMenuItem>
          <DropdownMenuItem onClick={runRemove} variant="destructive">
            {translate("resources.waitlist_entries.actions.remove", {
              _: "Remove from Waitlist",
            })}
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
      <WaitlistEntryEditSheet
        open={editOpen}
        onOpenChange={setEditOpen}
        entryId={entryId}
      />
    </>
  );
};

import { useState } from "react";
import { X } from "lucide-react";
import { useDataProvider, useNotify, useRefresh, useTranslate } from "ra-core";
import type { Identifier } from "ra-core";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

import { humanizeCohortName } from "../cohorts/humanizeCohortName";
import type { WaitlistEntryRow } from "./useWaitlistEntries";
import { prepareInvitationBatch } from "./waitlistInvitations";

// Review step before a batch is created. Leif routinely invites 30-40
// people at once, so this is one confirmation over the whole group — never
// 37 individual dialogs — with the ability to drop somebody from the
// selection before confirming.
export const InviteToBookDialog = ({
  open,
  onOpenChange,
  offerId,
  offerName,
  cohortId,
  cohortName,
  selected,
  onConfirmed,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  offerId: Identifier;
  offerName: string;
  cohortId: Identifier | null;
  cohortName?: string | null;
  selected: WaitlistEntryRow[];
  onConfirmed: () => void;
}) => {
  const translate = useTranslate();
  const dataProvider = useDataProvider();
  const notify = useNotify();
  const refresh = useRefresh();
  const [busy, setBusy] = useState(false);
  const [dropped, setDropped] = useState<Set<string>>(new Set());

  const remaining = selected.filter((row) => !dropped.has(String(row.entryId)));

  const handleConfirm = async () => {
    setBusy(true);
    try {
      const { invitations } = await prepareInvitationBatch(dataProvider, {
        offerId,
        cohortId,
        entryIds: remaining.map((row) => row.entryId),
      });
      notify("resources.waitlist_entries.notifications.invitation_prepared", {
        type: "info",
        messageArgs: {
          smart_count: invitations.length,
          _: `Prepared ${invitations.length} invitation(s). Nothing has been emailed yet.`,
        },
      });
      setDropped(new Set());
      onConfirmed();
      onOpenChange(false);
    } catch {
      notify("ra.notification.http_error", { type: "error" });
    } finally {
      setBusy(false);
      refresh();
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="sm:max-w-md gap-0 p-0"
        aria-describedby={undefined}
      >
        <DialogHeader className="border-b px-5 py-4">
          <DialogTitle className="text-base font-semibold">
            {translate("resources.waitlist_entries.invite.title", {
              _: "Invite to Book",
            })}
          </DialogTitle>
        </DialogHeader>

        <div className="flex flex-col gap-1 border-b px-5 py-3 text-sm">
          <span className="text-xs text-muted-foreground">
            {translate("resources.offers.name", {
              _: "Program",
              smart_count: 1,
            })}
          </span>
          <span>{offerName}</span>
          {cohortName && (
            <span className="text-xs text-muted-foreground">
              {humanizeCohortName(cohortName, offerName)}
            </span>
          )}
          <span className="mt-2 text-xs text-muted-foreground">
            {translate("resources.waitlist_entries.invite.selected", {
              _: "Selected: %{smart_count} people",
              smart_count: remaining.length,
            })}
          </span>
        </div>

        <ul className="max-h-[45vh] divide-y overflow-y-auto">
          {remaining.map((row) => (
            <li
              key={row.entryId}
              className="flex items-center justify-between gap-3 px-5 py-2 text-sm"
            >
              <span className="min-w-0 truncate">{row.name}</span>
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="size-7 shrink-0"
                aria-label={translate("ra.action.remove", { _: "Remove" })}
                onClick={() =>
                  setDropped((current) =>
                    new Set(current).add(String(row.entryId)),
                  )
                }
              >
                <X className="size-3.5" />
              </Button>
            </li>
          ))}
          {remaining.length === 0 && (
            <li className="px-5 py-3 text-xs text-muted-foreground">
              {translate("resources.waitlist_entries.invite.none", {
                _: "Nobody selected.",
              })}
            </li>
          )}
        </ul>

        {/* Said plainly, because it is true until Gmail exists: this
            prepares the invitations, it does not email anyone. */}
        <p className="border-t px-5 py-2 text-xs text-muted-foreground">
          {translate("resources.waitlist_entries.invite.pre_delivery_note", {
            _: "Prepares the invitations. No email is sent yet.",
          })}
        </p>

        <DialogFooter className="border-t px-5 py-3">
          <Button
            type="button"
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={busy}
          >
            {translate("ra.action.cancel", { _: "Cancel" })}
          </Button>
          <Button
            type="button"
            onClick={handleConfirm}
            disabled={busy || remaining.length === 0}
          >
            {translate("resources.waitlist_entries.invite.confirm", {
              _: "Invite to Book",
            })}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

import { Link } from "react-router";
import { useTranslate, type Identifier } from "ra-core";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { useIsMobile } from "@/hooks/use-mobile";

import { formatTimestampString } from "../deals/dealUtils";
import { humanizeCohortName } from "../cohorts/humanizeCohortName";
import { ContactAddToWaitlistButton } from "./ContactAddToWaitlistButton";
import { ContactWaitlistConvertButton } from "./ContactWaitlistConvertButton";
import { ContactWaitlistRemoveButton } from "./ContactWaitlistRemoveButton";
import {
  ACTIVE_WAITLIST_STATUSES,
  waitlistEntryStatusBadgeVariant,
  waitlistEntryStatusLabels,
} from "./waitlistConstants";
import { useContactWaitlists } from "./useContactWaitlists";

// ContactShow's "Waitlists" section (Waitlists slice, §10, actionability
// improved in the Human-acceptance repair pass, §3A/§7): the Contact's
// full lifetime history, active and historical alike, so a past
// relationship stays visible even after it converts or ends. A historical
// (converted/removed) row stays pure read-only; an active (waiting/
// invited) one additionally gets its own "Convert to Opportunity" button —
// once a compatible active Opportunity exists, the centralized sync
// (waitlist/waitlistSync.ts) will already have flipped the entry to
// Converted, so this button never has to guard against "already has one"
// itself. Heading style matches misc/AsideSection.tsx's own mobile/
// desktop split since this is used directly (not wrapped in AsideSection)
// in both contexts.
export const ContactWaitlists = ({ contactId }: { contactId: Identifier }) => {
  const translate = useTranslate();
  const isMobile = useIsMobile();
  const { isPending, entries } = useContactWaitlists(contactId);

  // Renders even with no entries now: the section header carries the
  // Contact's "Add to Waitlist" action, which is the only entry point for
  // putting THIS person on a waitlist — hiding the whole section when empty
  // would hide the action exactly when it is most needed.
  if (isPending) return null;

  return (
    <div className="flex flex-col gap-2 mb-6 text-sm">
      <div className="flex items-center justify-between gap-2">
        <h3 className={isMobile ? "text-lg font-semibold" : "font-medium pb-1"}>
          {translate("resources.waitlist_entries.name", {
            _: "Waitlists",
            smart_count: 2,
          })}
        </h3>
        <ContactAddToWaitlistButton contactId={contactId} />
      </div>
      {entries.length === 0 && (
        <p className="text-xs text-muted-foreground">
          {translate("resources.waitlist_entries.contact_detail.empty", {
            _: "Not on any waitlist.",
          })}
        </p>
      )}
      <div className="flex flex-col gap-2">
        {entries.map((entry) => (
          <Card key={entry.entryId} className="p-0">
            <CardContent className="flex flex-col gap-1.5 px-4 py-2.5">
              <div className="flex items-center justify-between gap-3">
                <div className="flex min-w-0 flex-col">
                  <Link
                    to={entry.programPath}
                    className="text-sm font-medium hover:underline truncate"
                  >
                    {/* A canonical cohort name already embeds its Offer
                        ("Growing Yourself Up — Fall 2026"), so prefixing
                        the Offer again read as "Growing Yourself Up —
                        Growing Yourself Up — Fall 2026". humanizeCohortName
                        strips whichever redundant form the name uses. */}
                    {entry.cohortName
                      ? `${entry.offerName} — ${humanizeCohortName(
                          entry.cohortName,
                          entry.offerName,
                        )}`
                      : entry.offerName}
                  </Link>
                  <span className="text-xs text-muted-foreground truncate">
                    {detailLine(entry, translate)}
                  </span>
                </div>
                <Badge
                  variant={waitlistEntryStatusBadgeVariant[entry.status]}
                  className="shrink-0"
                >
                  {waitlistEntryStatusLabels[entry.status]}
                </Badge>
              </div>
              {ACTIVE_WAITLIST_STATUSES.has(entry.status) && (
                <div className="flex items-center gap-2">
                  <ContactWaitlistConvertButton entryId={entry.entryId} />
                  {/* Remove is a lifecycle transition to Removed, never a
                      delete — the row stays on this list as history. */}
                  <ContactWaitlistRemoveButton entryId={entry.entryId} />
                </div>
              )}
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
};

const detailLine = (
  entry: ReturnType<typeof useContactWaitlists>["entries"][number],
  translate: (key: string, options: Record<string, unknown>) => string,
) => {
  const parts = [
    translate("resources.waitlist_entries.contact_detail.joined", {
      _: "Joined %{date}",
      date: formatTimestampString(entry.joinedAt),
    }),
  ];
  if (entry.desiredTiming) {
    parts.push(
      translate("resources.waitlist_entries.contact_detail.preferred", {
        _: "Preferred timing: %{timing}",
        timing: entry.desiredTiming,
      }),
    );
  }
  if (entry.convertedAt) {
    parts.push(
      translate("resources.waitlist_entries.contact_detail.converted", {
        _: "Converted %{date}",
        date: formatTimestampString(entry.convertedAt),
      }),
    );
  }
  if (entry.removedAt) {
    parts.push(
      translate("resources.waitlist_entries.contact_detail.removed", {
        _: "Removed %{date}",
        date: formatTimestampString(entry.removedAt),
      }),
    );
  }
  return parts.join(" · ");
};

import { useState } from "react";
import { useDataProvider, useNotify, useRefresh, useTranslate } from "ra-core";
import type { Identifier } from "ra-core";
import { Button } from "@/components/ui/button";

import { removeFromWaitlist } from "./waitlistActions";

// The Contact page's "Remove" action for one active (waiting/invited)
// Waitlist Entry. Mirrors ContactWaitlistConvertButton.tsx exactly and
// reuses the SAME centralized removeFromWaitlist domain action the
// Program/Cohort pages' WaitlistEntryActions.tsx already calls — never a
// second removal path, and never a delete: the entry transitions to
// Removed and stays visible on this list as history (with its removal
// date), so "they joined, then left" remains readable long after.
export const ContactWaitlistRemoveButton = ({
  entryId,
}: {
  entryId: Identifier;
}) => {
  const translate = useTranslate();
  const dataProvider = useDataProvider();
  const notify = useNotify();
  const refresh = useRefresh();
  const [busy, setBusy] = useState(false);

  const handleClick = async () => {
    setBusy(true);
    try {
      const result = await removeFromWaitlist(dataProvider, entryId);
      notify(
        result.applied
          ? "resources.waitlist_entries.notifications.removed"
          : "resources.waitlist_entries.notifications.stale",
        { type: result.applied ? "info" : "warning" },
      );
    } catch {
      notify("ra.notification.http_error", { type: "error" });
    } finally {
      setBusy(false);
      refresh();
    }
  };

  return (
    <Button
      type="button"
      size="sm"
      variant="outline"
      disabled={busy}
      onClick={handleClick}
    >
      {translate("resources.waitlist_entries.actions.remove", {
        _: "Remove",
      })}
    </Button>
  );
};

import { useState } from "react";
import { useDataProvider, useNotify, useRefresh, useTranslate } from "ra-core";
import type { Identifier } from "ra-core";
import { useNavigate } from "react-router";
import { Button } from "@/components/ui/button";

import { convertToOpportunity } from "./waitlistActions";

// The Contact page's direct "Convert to Opportunity" action for one active
// (waiting/invited) Waitlist Entry (Human-acceptance repair pass, §3A/§7):
// reuses the SAME centralized convertToOpportunity domain action the
// Program/Cohort pages' WaitlistEntryActions.tsx already calls — never a
// second conversion path. On success it navigates straight to the
// resulting Opportunity, so the Contact-page detour the ticket flagged
// ("must navigate to Opportunities, New Opportunity, remember/search
// Sarah again") never has to happen at all going the other direction
// either. When multiple active entries exist, each gets its OWN button
// (rendered per-row by ContactWaitlists.tsx) — the click itself is the
// disambiguation, never a guess.
export const ContactWaitlistConvertButton = ({
  entryId,
}: {
  entryId: Identifier;
}) => {
  const translate = useTranslate();
  const dataProvider = useDataProvider();
  const notify = useNotify();
  const refresh = useRefresh();
  const navigate = useNavigate();
  const [busy, setBusy] = useState(false);

  const handleClick = async () => {
    setBusy(true);
    try {
      const result = await convertToOpportunity(dataProvider, entryId);
      if (!result.applied) {
        notify(
          result.reason === "do-not-engage"
            ? "resources.waitlist_entries.notifications.do_not_engage"
            : "resources.waitlist_entries.notifications.stale",
          { type: "warning" },
        );
        setBusy(false);
        refresh();
        return;
      }
      notify(
        result.reusedExisting
          ? "resources.waitlist_entries.notifications.converted_existing"
          : "resources.waitlist_entries.notifications.converted",
        { type: "info" },
      );
      navigate(`/deals/${result.dealId}/show`);
    } catch {
      notify("ra.notification.http_error", { type: "error" });
      setBusy(false);
    }
  };

  return (
    <Button
      type="button"
      size="sm"
      variant="outline"
      disabled={busy}
      onClick={handleClick}
    >
      {translate("resources.waitlist_entries.actions.convert", {
        _: "Convert to Opportunity",
      })}
    </Button>
  );
};

import type { Identifier } from "ra-core";

import { ContactNewOpportunityButton } from "../contacts/ContactNewOpportunityButton";
import { ACTIVE_WAITLIST_STATUSES } from "./waitlistConstants";
import { useContactWaitlists } from "./useContactWaitlists";

// Decides between the Contact page's two sales entry points (Human-
// acceptance repair pass, §3): a Contact with at least one active
// (waiting/invited) Waitlist Entry gets its "Convert to Opportunity"
// button inline on that entry's own row (ContactWaitlists.tsx renders it
// directly — the click IS the disambiguation when there's more than one);
// a Contact with none gets the single "+ New Opportunity" fallback here.
// Always mounted (unlike ContactWaitlists.tsx, which hides itself when
// there are zero entries at all) so the fallback has a home even for a
// Contact who has never touched a waitlist.
export const ContactSalesAction = ({
  contactId,
}: {
  contactId: Identifier;
}) => {
  const { isPending, entries } = useContactWaitlists(contactId);

  if (isPending) return null;
  const hasActiveEntry = entries.some((entry) =>
    ACTIVE_WAITLIST_STATUSES.has(entry.status),
  );
  if (hasActiveEntry) return null;

  return (
    <div className="mb-6">
      <ContactNewOpportunityButton contactId={contactId} />
    </div>
  );
};

import { useEffect, useMemo } from "react";
import { useFormContext, useWatch } from "react-hook-form";
import { required, useGetOne, useTranslate, type Identifier } from "ra-core";
import { AutocompleteInput } from "@/components/admin/autocomplete-input";
import { ReferenceInput } from "@/components/admin/reference-input";
import { TextInput } from "@/components/admin/text-input";

import { CreateDialog } from "../misc/CreateDialog";
