import { useGetList } from "ra-core";

import type { Application, Deal, SalesCall, Task } from "../types";
import { classifyTaskActionKind } from "./taskActionDestination";

export type TaskActionDestination =
  | { kind: "application-review"; to: string }
  | { kind: "opportunity-context"; to: string }
  | { kind: "enrollment-context"; to: string }
  | { kind: "sales-call-needs-matching"; to: string }
  | { kind: "resolve-sales-call"; to: string }
  | { kind: "resolve-client-session-cadence"; to: string }
  // No real, resolvable destination for this Task — either its type has no
  // dedicated action screen ("other", an unrecognized custom type) or the
  // record it would have pointed to no longer exists (deleted Contact/
  // Deal/Application/SalesCall, or a Contact with no Deal at all). The
  // caller's job is to open the Task's own edit view instead of guessing
  // or navigating nowhere.
  | { kind: "task-detail" };

// Same "not archived, not won, no exit outcome" definition already used at
// submitApplication.ts/waitlist/waitlistActions.ts for "is this Deal still
// an open pipeline item" — duplicated rather than imported since those are
// private, unexported helpers local to their own modules.
const isActiveDeal = (deal: Pick<Deal, "stage" | "outcome" | "archived_at">) =>
  deal.archived_at == null && deal.stage !== "won" && deal.outcome == null;

// Resolves WHERE a Task's primary action should navigate to, given only
// what Task itself durably stores today: contact_id (Native Applications
// slice, §19 / Acuity slice: adding a deal_id/application_id FK to Task
// would be a further schema change, deliberately deferred — see this
// module's own real-infrastructure audit report for why a heuristic is
// the right call for now, not a gap silently left unaddressed). A Contact
// with more than one matching Deal/Application resolves to the most
// recently created one; this matches every other Task-resolution helper's
// own documented heuristic (reviewApplicationTask.ts, salesCallTask.ts,
// resolveSalesCallTask.ts) rather than inventing a new convention. Never
// performs a write — this is read-only resolution for navigation, kept
// strictly separate from Task completion/postpone/status logic.
export const useTaskActionDestination = (
  task: Task,
): { destination: TaskActionDestination | null; isPending: boolean } => {
  const actionKind = classifyTaskActionKind(task.type);
  const isNeedsMatching = actionKind === "sales-call-needs-matching";
  const isResolveOutcome = actionKind === "resolve-sales-call";
  // Both resolve off the same FK; only the destination differs.
  const isSalesCallTask = isNeedsMatching || isResolveOutcome;

  // Every hook below is called on EVERY render, unconditionally (Rules of
  // Hooks) — each one's own `enabled` flag is what actually gates it,
  // exactly like react-query/ra-core's own convention elsewhere. The
  // branching that decides which result actually matters for a given
  // `actionKind` happens AFTER all of them, never before — an early
  // `return` ahead of a hook call here previously skipped it for some
  // Task types but not others, a real conditional-hooks bug caught by
  // eslint's react-hooks/rules-of-hooks (not merely a style nit: it can
  // desync hook state across renders when a Task's `type` changes without
  // a full remount).

  // resolve-sales-call resolves off Task.sales_call_id when set (a real
  // FK, backfilled for pre-existing Tasks — see migration 20260904240000).
  // Falls back to a contact-scoped query only for the rare legacy Task the
  // backfill couldn't disambiguate: the Contact's own single still-
  // unresolved sales_call, if there is exactly one — never guessed when
  // there's more than one candidate.
  // Only the MATCHING task has a legacy fallback worth running: its
  // fallback query looks for the Contact's unmatched booking, which is by
  // definition never what an outcome task points at.
  const needsSalesCallLookup =
    isNeedsMatching && task.sales_call_id == null && task.contact_id != null;
  const { data: unresolvedSalesCalls, isPending: isPendingSalesCalls } =
    useGetList<SalesCall>(
      "sales_calls",
      {
        filter: {
          contact_id: task.contact_id,
          opportunity_id: null,
          dismissed_at: null,
        },
        pagination: { page: 1, perPage: 10 },
        sort: { field: "id", order: "ASC" },
      },
      { enabled: needsSalesCallLookup, retry: false },
    );

  // enrollment-context and resolve-client-session-cadence (both real FKs,
  // resolved synchronously below with no query needed) and
  // resolve-sales-call never need this Deals lookup — excluded from
  // `needsDeals` the same way they were structurally unreachable before
  // this hook when both were early returns.
  const needsDeals =
    actionKind !== "task-detail" &&
    actionKind !== "enrollment-context" &&
    actionKind !== "resolve-client-session-cadence" &&
    !isSalesCallTask &&
    task.contact_id != null;

  const { data: deals, isPending: isPendingDeals } = useGetList<Deal>(
    "deals",
    {
      filter: { contact_id: task.contact_id },
      pagination: { page: 1, perPage: 100 },
      sort: { field: "id", order: "DESC" },
    },
    // A failed resolution should fall back to "task-detail" immediately —
    // never retry-with-backoff for what's ultimately a non-critical
    // navigation affordance (react-query's default retries would only
    // delay that safe fallback, never improve it).
    { enabled: needsDeals, retry: false },
  );

  // A review Task points at a Contact, and an Application now belongs to a
  // Contact directly — so resolve by contact_id rather than by routing
  // through that Contact's Deals. Scoped to live submissions because this
  // resolves the destination for a REVIEW action; an imported historical
  // record is never the thing a review Task is about.
  const wantsApplications = actionKind === "application-review";
  const { data: applications, isPending: isPendingApplications } =
    useGetList<Application>(
      "applications",
      {
        filter: { contact_id: task.contact_id, source: "public_form" },
        pagination: { page: 1, perPage: 100 },
        sort: { field: "id", order: "DESC" },
      },
      { enabled: wantsApplications, retry: false },
    );

  // resolve-client-session-cadence resolves DETERMINISTICALLY off
  // Task.cadence_issue_id — same reasoning as enrollment-context below,
  // never the contact_id heuristic every other kind still uses.
  if (actionKind === "resolve-client-session-cadence") {
    if (task.cadence_issue_id == null) {
      return { destination: { kind: "task-detail" }, isPending: false };
    }
    return {
      destination: {
        kind: "resolve-client-session-cadence",
        to: `/client-session-cadence/${task.cadence_issue_id}/resolve`,
      },
      isPending: false,
    };
  }

  // enrollment-context resolves DETERMINISTICALLY off Task.enrollment_id —
  // never the contact_id heuristic every other kind below still uses.
  if (actionKind === "enrollment-context") {
    if (task.enrollment_id == null) {
      return { destination: { kind: "task-detail" }, isPending: false };
    }
    return {
      destination: {
        kind: "enrollment-context",
        to: `/enrollments/${task.enrollment_id}/show`,
      },
      isPending: false,
    };
  }

  // "What happened on this call?" — straight to the call's own outcome
  // screen, never the matching screen. The call is already attached to the
  // right Opportunity, so matching has nothing left to ask, and sending
  // Leif there is what made the Dashboard contradict itself.
  if (isResolveOutcome) {
    if (task.sales_call_id == null) {
      return { destination: { kind: "task-detail" }, isPending: false };
    }
    return {
      destination: {
        kind: "resolve-sales-call",
        to: `/sales-calls/${task.sales_call_id}/outcome`,
      },
      isPending: false,
    };
  }

  if (isNeedsMatching) {
    if (task.sales_call_id != null) {
      return {
        destination: {
          kind: "sales-call-needs-matching",
          to: `/sales-calls/${task.sales_call_id}/resolve`,
        },
        isPending: false,
      };
    }
    if (needsSalesCallLookup && isPendingSalesCalls) {
      return { destination: null, isPending: true };
    }
    if (unresolvedSalesCalls?.length === 1) {
      return {
        destination: {
          kind: "sales-call-needs-matching",
          to: `/sales-calls/${unresolvedSalesCalls[0].id}/resolve`,
        },
        isPending: false,
      };
    }
    return { destination: { kind: "task-detail" }, isPending: false };
  }

  if (actionKind === "task-detail") {
    return { destination: { kind: "task-detail" }, isPending: false };
  }

  if (isPendingDeals) {
    return { destination: null, isPending: true };
  }

  if (actionKind === "application-review") {
    // No longer gated on the Contact having Deals: the Application is
    // reached through its own contact_id, so a review destination resolves
    // even for an applicant with no Opportunity.
    if (isPendingApplications) {
      return { destination: null, isPending: true };
    }
    const pending = applications?.find((app) => app.status === "pending");
    const target = pending ?? applications?.[0];
    if (!target) {
      return { destination: { kind: "task-detail" }, isPending: false };
    }
    return {
      destination: {
        kind: "application-review",
        to: `/applications/${target.id}/show`,
      },
      isPending: false,
    };
  }

  // opportunity-context
  const activeDeal = deals?.find(isActiveDeal) ?? deals?.[0];
  if (!activeDeal) {
    return { destination: { kind: "task-detail" }, isPending: false };
  }
  return {
    destination: {
      kind: "opportunity-context",
      to: `/deals/${activeDeal.id}/show`,
    },
    isPending: false,
  };
};

import { useCallback, useMemo, useState } from "react";
import type { Identifier } from "ra-core";

import type { Task as TaskType } from "../types";

// Human-acceptance repair (Tasks noise): a just-completed Task stays
// visible, checked and muted, for a brief confirmation window instead of
// vanishing the instant its optimistic done_date lands (so Leif sees the
// check register) or lingering indefinitely mixed into the actionable
// list (the "growing graveyard of crossed-out tasks" human acceptance
// found). Originally inlined in DashboardTasks.tsx (its own comment
// explains why this is deliberately much shorter than tasksPredicate.ts's
// `isRecentlyDone`, a *5-minute* grace window built for a different
// purpose — avoiding flicker on an already-open list, not a completion
// acknowledgement); extracted here so ClientShow's/ContactShow's own Task
// lists (TasksListByDueDate) get the exact same short, deterministic
// removal instead of inheriting the 5-minute one. Purely a CLIENT-SIDE
// display-timing concern — the underlying done_date/status write already
// happened (or didn't) via the real mutation; this never touches server
// state, so a page reload or navigation mid-window simply shows the
// Task's real, already-persisted status with no grace period at all
// (never a source of truth on its own).
const CONFIRMATION_WINDOW_MS = 1500;

export const useRecentlyCompletedTasks = () => {
  const [recentlyCompletedIds, setRecentlyCompletedIds] = useState<
    Set<Identifier>
  >(new Set());

  const markCompleted = useCallback((task: Pick<TaskType, "id">) => {
    setRecentlyCompletedIds((prev) => new Set(prev).add(task.id));
    setTimeout(() => {
      setRecentlyCompletedIds((prev) => {
        if (!prev.has(task.id)) return prev;
        const next = new Set(prev);
        next.delete(task.id);
        return next;
      });
    }, CONFIRMATION_WINDOW_MS);
  }, []);

  const isRecentlyCompleted = useCallback(
    (id: Identifier) => recentlyCompletedIds.has(id),
    [recentlyCompletedIds],
  );

  return useMemo(
    () => ({ isRecentlyCompleted, markCompleted }),
    [isRecentlyCompleted, markCompleted],
  );
};

import { useGetList } from "ra-core";
import type { Identifier } from "ra-core";

import { CURRENT_OPERATIONAL_ENROLLMENT_STATUSES } from "../enrollments/enrollmentConstants";
import type { Deal, Enrollment } from "../types";

// Manual Task UX repair, round 2 — the person link on a Task row (only
// where a Contact isn't already the obvious page context, i.e.
// showContact=true: Dashboard, other cross-contact lists) now goes
// straight to the Client/Enrollment operational home when that's
// unambiguous, since Leif generally works Tasks from there once someone
// has a current Enrollment — same "Atomic handles certainty, Leif
// handles ambiguity" governing principle as the rest of this codebase's
// exception handling. Deliberately the SAME shared helper for every
// Task-row surface (Task.tsx is the one shared row component), never
// duplicated per-page routing logic.
//
// Walks Contact -> Deals -> Enrollments (an Enrollment has no direct
// contact_id of its own — see types.ts) exactly like
// useTaskActionDestination.ts's own opportunity-context resolution does
// for the same reason: no direct FK shortcut exists.
export const useContactLinkDestination = (
  contactId: Identifier | null | undefined,
): { to: string; isPending: boolean } => {
  const contactShowPath = `/contacts/${contactId}/show`;

  const { data: deals, isPending: dealsPending } = useGetList<Deal>(
    "deals",
    {
      filter: { contact_id: contactId },
      pagination: { page: 1, perPage: 100 },
      sort: { field: "id", order: "ASC" },
    },
    // A failed/slow resolution should fall back to the Contact page
    // immediately, same "never block on a non-critical navigation
    // affordance" reasoning as useTaskActionDestination.ts.
    { enabled: contactId != null, retry: false },
  );

  const dealIds = deals?.map((deal) => deal.id) ?? [];
  const { data: enrollments, isPending: enrollmentsPending } =
    useGetList<Enrollment>(
      "enrollments",
      {
        filter: { "opportunity_id@in": `(${dealIds.join(",")})` },
        pagination: { page: 1, perPage: 100 },
        sort: { field: "id", order: "ASC" },
      },
      { enabled: dealIds.length > 0, retry: false },
    );

  if (contactId == null) {
    return { to: contactShowPath, isPending: false };
  }
  if (dealsPending) {
    return { to: contactShowPath, isPending: true };
  }
  if (dealIds.length === 0) {
    return { to: contactShowPath, isPending: false };
  }
  if (enrollmentsPending) {
    return { to: contactShowPath, isPending: true };
  }

  const currentEnrollments = (enrollments ?? []).filter((enrollment) =>
    CURRENT_OPERATIONAL_ENROLLMENT_STATUSES.has(enrollment.status),
  );

  // Exactly one current operational Enrollment: unambiguous, go straight
  // there. Zero or 2+: never guess which one Leif means — Contact page,
  // same as before this repair.
  if (currentEnrollments.length === 1) {
    return {
      to: `/enrollments/${currentEnrollments[0].id}/show`,
      isPending: false,
    };
  }
  return { to: contactShowPath, isPending: false };
};

import { startOfToday } from "date-fns/startOfToday";
import { endOfToday } from "date-fns/endOfToday";
import { endOfTomorrow } from "date-fns/endOfTomorrow";
import { endOfWeek } from "date-fns/endOfWeek";
import { addDays } from "date-fns/addDays";
import { endOfDay } from "date-fns/endOfDay";

import { getDay, isAfter } from "date-fns";

export const isBeforeFriday = () => getDay(new Date()) < 5; // Friday is represented by 5

// Unmatched Sales Call Resolution slice, human-acceptance repair: this
// exception's own due_date is an internal implementation detail only
// (Tasks require one at the DB level, set to "now" at creation) — never a
// real dated commitment Leif made. Shown/used in two places: Task.tsx
// (suppress "Due <date>"/Postpone) and DashboardTasks.tsx (never bucket it
// as Overdue merely because its internal due_date rolled into the past —
// it always shows in Today instead, for as long as it's unresolved).
export const TASK_TYPES_WITHOUT_MEANINGFUL_DUE_DATE: ReadonlySet<string> =
  new Set([
    "sales_call_needs_matching",
    "resolve_sales_call",
    "resolve_client_session_cadence",
  ]);

type Task = {
  due_date: string;
  done_date?: string | null;
  // Optional so callers with only the legacy done_date field still compile.
  status?: "pending" | "waiting" | "completed" | "cancelled";
};

// A task is "done" (no longer needs attention) once it's checked off or
// explicitly cancelled. Checking done_date alone keeps this backward
// compatible with any record that hasn't been given a status yet.
export const isDone = (task: Task) =>
  task.done_date != null ||
  task.status === "completed" ||
  task.status === "cancelled";

// A task is recently done if it was marked as done less than 5 minutes ago
// useful to keep recently done tasks in the list to avoid flickering when a task is marked as done while the user is consulting the list of tasks. It gives a chance to the user to see that the task was marked as done and then it will disappear after 5 minutes.
export const isRecentlyDone = (task: Task) =>
  task.done_date != null &&
  isAfter(new Date(task.done_date), new Date(Date.now() - 5 * 60 * 1000));

export const isOverdue = (dateString: string) => {
  return new Date(dateString) < startOfToday();
};

export const isDueToday = (dateString: string) => {
  const dueDate = new Date(dateString);
  return dueDate >= startOfToday() && dueDate < endOfToday();
};

export const isDueTomorrow = (dateString: string) => {
  const dueDate = new Date(dateString);
  return dueDate >= endOfToday() && dueDate < endOfTomorrow();
};

export const isDueThisWeek = (dateString: string) => {
  const dueDate = new Date(dateString);
  return (
    dueDate >= endOfTomorrow() &&
    dueDate < endOfWeek(new Date(), { weekStartsOn: 0 })
  );
};

export const isDueLater = (dateString: string) => {
  const dueDate = new Date(dateString);
  return dueDate >= endOfWeek(new Date(), { weekStartsOn: 0 });
};

// Dashboard "Next 7 Days" bucket: everything after today through 7 full
// days out. Deliberately bounded (unlike isDueLater) so the Dashboard's
// Tasks section stays a short, scannable horizon — see the Dashboard/Today
// slice report for why this is a separate bucket set from the detailed
// Overdue/Today/Tomorrow/This Week/Later view used elsewhere.
export const isDueNext7Days = (dateString: string) => {
  const dueDate = new Date(dateString);
  return dueDate >= endOfToday() && dueDate <= endOfDay(addDays(new Date(), 7));
};

import type { TaskStatus } from "../types";

// Fixed system states (unlike taskTypes, not a per-tenant runtime config —
// every Task has exactly one of these regardless of business customization).
export const taskStatuses: { value: TaskStatus; label: string }[] = [
  { value: "pending", label: "Pending" },
  { value: "waiting", label: "Waiting" },
  { value: "completed", label: "Completed" },
  { value: "cancelled", label: "Cancelled" },
];

export const taskStatusLabels: Record<TaskStatus, string> = {
  pending: "Pending",
  waiting: "Waiting",
  completed: "Completed",
  cancelled: "Cancelled",
};

// Task action-destination policy (real human Auth acceptance testing found
// "Review Application: SalesId Verify" clickable nowhere useful — the type
// label was plain text, and the only real link went to the Contact, not
// the Application). A Task is an action launcher, not just a reminder:
// clicking its primary title should take the user directly to where that
// action is actually performed.
//
// Pure classification only — no data fetching, no I/O — kept separate from
// useTaskActionDestination.ts (which resolves an actual record id for a
// given Contact) so the policy itself stays trivially testable and reused
// consistently wherever Tasks render (there is exactly one shared row
// component, Task.tsx — used by the Dashboard, the Contact page's task
// list, and the mobile Tasks list alike — so fixing the policy there
// covers every surface).
//
// `Task.type` is a plain string, not a fixed union (see types.ts) — task
// types are configurable per deployment via <CRM taskTypes={...}>, so an
// unrecognized/custom type must fail safe to "task-detail", never throw or
// guess a resource.
export type TaskActionKind =
  | "application-review"
  | "opportunity-context"
  | "enrollment-context"
  // "which Opportunity does this booking belong to?" — the matching screen.
  | "sales-call-needs-matching"
  // "what happened on this call?" — the outcome screen. A DIFFERENT
  // question with a different answer, so a different destination.
  | "resolve-sales-call"
  | "resolve-client-session-cadence"
  | "task-detail";

// review_application: the actual action (Approve / Needs Higher Care /
// Not Fit / Do Not Engage) happens on the specific Application's own show
// page (ApplicationShow.tsx, embedding ApplicationReviewActions) — never
// the Contact page.
const APPLICATION_REVIEW_TYPES: ReadonlySet<string> = new Set([
  "review_application",
]);

// sales_call, follow_up, nurture_follow_up, check_payment: every one of
// these is fundamentally "go work this Opportunity" — confirmed against
// current code, not assumed. DealShow.tsx (/deals/:id/show) is the one
// real screen that already embeds both the sales-call working context
// (DealSalesCallSection) and the application/enrollment context
// (DealApplicationAndEnrollment) an Opportunity has today. check_payment
// has no dedicated billing screen yet — DealShow is the best truthful
// current destination for it too (not an invented one), and this policy's
// job is exactly to make swapping in a real screen later, if one gets
// built, a one-line change here rather than a Dashboard rewrite.
// sales_call_cancelled (GYU real-infrastructure slice, human-acceptance
// repair pass): only ever created against a specific, already-matched
// Opportunity (see cancelSalesCall.ts's ensureFollowUpIfStranded) — unlike
// resolve_sales_call below, there's no ambiguity to fall back on, so this
// belongs here too, not with the task-detail fallback types.
const OPPORTUNITY_CONTEXT_TYPES: ReadonlySet<string> = new Set([
  "sales_call",
  "follow_up",
  "nurture_follow_up",
  "check_payment",
  "sales_call_cancelled",
  // sales_call_no_show belongs here for the same reason: it is only ever
  // created against a specific, already-matched Opportunity, so there is
  // no ambiguity to fall back on. It was reaching the generic Task editor,
  // which answers nothing about whether somebody wants to rebook — found
  // by the Needs Attention inventory, which requires every type to have a
  // real destination.
  "sales_call_no_show",
]);

// onboarding_item (Contracts + Onboarding slice): retires send_contract/
// complete_access, which used to live in OPPORTUNITY_CONTEXT_TYPES above —
// wrong even when they were added, since "go work this Opportunity" was
// never actually true for post-Won client-delivery work. This type
// resolves DETERMINISTICALLY via Task.enrollment_id (a real FK, set by
// handle_deal_won() at creation) rather than the contact_id heuristic
// every OPPORTUNITY_CONTEXT_TYPES/APPLICATION_REVIEW_TYPES type still
// uses below — see useTaskActionDestination.ts.
// Client Offboarding slice: offboarding_item joins onboarding_item here
// for the same reason — resolves DETERMINISTICALLY via Task.enrollment_id
// too, no separate resolution logic needed.
const ENROLLMENT_CONTEXT_TYPES: ReadonlySet<string> = new Set([
  "onboarding_item",
  "offboarding_item",
]);

// sales_call_needs_matching (Unmatched Sales Call Resolution slice): used
// to fall back to "task-detail" (the generic Edit sheet) — genuinely not
// useful there, since the actual question ("what Opportunity does this
// booking belong to?") isn't answerable from Description/Due date/Type/
// Status. Resolves DETERMINISTICALLY via Task.sales_call_id (set at
// creation, backfilled for pre-existing rows — see migration
// 20260904240000) to the dedicated matching page, never the generic modal.
const SALES_CALL_NEEDS_MATCHING_TYPES: ReadonlySet<string> = new Set([
  "sales_call_needs_matching",
]);

// resolve_sales_call: attached to the right Opportunity already, so the
// matching page has nothing to ask. Production acceptance caught exactly
// that contradiction — the task said "needs matching", the page it opened
// said "this booking is already attached to an Opportunity". This type
// goes to the call's outcome resolution instead, offering the three
// canonical actions (call happened / no-show / cancelled).
const RESOLVE_SALES_CALL_TYPES: ReadonlySet<string> = new Set([
  "resolve_sales_call",
]);

// resolve_client_session_cadence (Client + Session Operations cadence
// correction): same "no generic Edit sheet" reasoning as
// resolve_sales_call above — the actual question ("known skip,
// rescheduled, or missed/ghosted?") isn't answerable from Description/Due
// date/Type/Status either. Resolves DETERMINISTICALLY via
// Task.cadence_issue_id (always set at creation — no legacy fallback
// needed, unlike sales_call_id's) to its own dedicated resolution page.
const RESOLVE_CLIENT_SESSION_CADENCE_TYPES: ReadonlySet<string> = new Set([
  "resolve_client_session_cadence",
]);

// "other" and any custom/unrecognized type: no type-specific destination
// exists to resolve. Falls back to "task-detail" (open the Task's own edit
// view — the existing TaskEdit/TaskEditSheet already wired to Task.tsx's
// dropdown "Edit" action) rather than guessing or silently going nowhere.
export const classifyTaskActionKind = (
  taskType: string | null | undefined,
): TaskActionKind => {
  if (taskType && APPLICATION_REVIEW_TYPES.has(taskType)) {
    return "application-review";
  }
  if (taskType && ENROLLMENT_CONTEXT_TYPES.has(taskType)) {
    return "enrollment-context";
  }
  if (taskType && SALES_CALL_NEEDS_MATCHING_TYPES.has(taskType)) {
    return "sales-call-needs-matching";
  }
  if (taskType && RESOLVE_SALES_CALL_TYPES.has(taskType)) {
    return "resolve-sales-call";
  }
  if (taskType && RESOLVE_CLIENT_SESSION_CADENCE_TYPES.has(taskType)) {
    return "resolve-client-session-cadence";
  }
  if (taskType && OPPORTUNITY_CONTEXT_TYPES.has(taskType)) {
    return "opportunity-context";
  }
  return "task-detail";
};

import { getDenverDateString } from "../dashboard/artOracle/selectDailyArtwork";
import { dateOnlyToTimestamp } from "../misc/dateOnlyToTimestamp";

// Small polish/cleanup slice: Task.tsx's postpone-tomorrow/postpone-next-
// week actions previously computed "tomorrow" as `Date.now() + 24h` and
// stored only the UTC calendar date's first 10 characters straight into
// tasks.due_date (a timestamptz) — the same class of bug already fixed in
// followUpTask.ts for deals.follow_up_date: a bare date implies UTC
// midnight, which renders one day early for any viewer west of UTC, and
// "add 24h in UTC" isn't even the right "tomorrow" for a viewer/business
// anchored to America/Denver in the first place.
//
// "Tomorrow"/"next week" here mean the CRM's established America/Denver
// business-day (completedTodaySelection.ts's own day-boundary logic),
// not the viewer's own system timezone. Explicit `now` parameter (never
// `new Date()` internally) for deterministic, timer-free testing — see
// completedTodaySelection.ts's own header for why (vitest-browser-react's
// render hangs under vi.useFakeTimers() in this codebase).
export const computePostponeDueDate = (
  now: Date,
  daysAhead: number,
): string => {
  const [year, month, day] = getDenverDateString(now).split("-").map(Number);
  // Calendar-field arithmetic (not millisecond arithmetic): JS normalizes
  // an out-of-range day (e.g. day=32) into the correct following month/
  // year on its own, immune to DST wall-clock drift.
  const target = new Date(year!, month! - 1, day! + daysAhead);
  const isoDate = [
    target.getFullYear(),
    String(target.getMonth() + 1).padStart(2, "0"),
    String(target.getDate()).padStart(2, "0"),
  ].join("-");
  return dateOnlyToTimestamp(isoDate);
};

