import { useGetList } from "ra-core";
import type { Identifier } from "ra-core";

import type {
  ClientSession,
  ClientSessionCadenceIssue,
  EnrollmentExpectedSession,
} from "../types";
import {
  computeClientSessionCadenceSummary,
  type ClientSessionCadenceSummary,
} from "./computeClientSessionCadenceSummary";

export type ClientSessionCadence = ClientSessionCadenceSummary & {
  isPending: boolean;
  // Newest first — the Session History table's own natural order.
  sessions: ClientSession[];
};

// Backs the Enrollment page's Sessions section (Client + Session
// Operations correction) — mirrors useEnrollmentOperationalData.ts's own
// "container hook fetches, a pure function computes" shape. See
// computeClientSessionCadenceSummary.ts for the actual comparison rules
// (directly unit-tested there). Reads the Enrollment's own frozen
// enrollment_expected_sessions slots (assigned server-side by
// sync_year_planning_calendar's own assignment pass — never the raw,
// shared expected_session_windows directly) and any
// client_session_cadence_issues resolution history alongside the
// sessions themselves — none of these three resources are ever written
// from here, only read.
export const useClientSessionCadence = (
  enrollmentId: Identifier | undefined,
  enabled: boolean,
): ClientSessionCadence => {
  const isEnabled = enabled && enrollmentId != null;

  const { data: sessionsData, isPending: isPendingSessions } =
    useGetList<ClientSession>(
      "client_sessions",
      {
        filter: { enrollment_id: enrollmentId },
        pagination: { page: 1, perPage: 200 },
        sort: { field: "scheduled_at", order: "DESC" },
      },
      { enabled: isEnabled },
    );

  const { data: slotsData, isPending: isPendingSlots } =
    useGetList<EnrollmentExpectedSession>(
      "enrollment_expected_sessions",
      {
        filter: { enrollment_id: enrollmentId },
        pagination: { page: 1, perPage: 12 },
        sort: { field: "ordinal", order: "ASC" },
      },
      { enabled: isEnabled },
    );

  const { data: issuesData, isPending: isPendingIssues } =
    useGetList<ClientSessionCadenceIssue>(
      "client_session_cadence_issues",
      {
        filter: { enrollment_id: enrollmentId },
        pagination: { page: 1, perPage: 200 },
        sort: { field: "id", order: "ASC" },
      },
      { enabled: isEnabled },
    );

  const sessions = sessionsData ?? [];

  return {
    isPending: isPendingSessions || isPendingSlots || isPendingIssues,
    sessions,
    ...computeClientSessionCadenceSummary({
      sessions,
      slots: slotsData ?? [],
      issues: issuesData ?? [],
    }),
  };
};

import type { DataProvider, Identifier } from "ra-core";

import type { ClientSession } from "../types";
import { findEnrollmentExpectedSessionForSession } from "./findEnrollmentExpectedSessionForSession";
import { resolveCadenceIssueFulfillment } from "./resolveCadenceIssueFulfillment";

export type ReverseClientSessionNoShowResult =
  | { status: "reversed" }
  // Idempotent no-op, same convention as markClientSessionNoShow.ts.
  | { status: "not-no-show" }
  | { status: "not-found" };

// The safe correction path for a no-show marked by mistake — clearing
// no_show_at makes the session fulfilled again by the normal default-
// attendance rule, with the correction itself durable in
// client_session_events (never a silent overwrite with no trace).
//
// Exception state-machine correction: if restoring fulfillment resolves
// the ONLY reason an expected window's cadence issue was open (never a
// real human classification — see resolveCadenceIssueFulfillment.ts),
// that issue auto-resolves here too, immediately.
export const reverseClientSessionNoShow = async (
  dataProvider: DataProvider,
  clientSessionId: Identifier,
): Promise<ReverseClientSessionNoShowResult> => {
  const { data: clientSession } = await dataProvider
    .getOne<ClientSession>("client_sessions", { id: clientSessionId })
    .catch(() => ({ data: null as ClientSession | null }));
  if (!clientSession) return { status: "not-found" };
  if (!clientSession.no_show_at) {
    return { status: "not-no-show" };
  }

  const now = new Date().toISOString();
  await dataProvider.update<ClientSession>("client_sessions", {
    id: clientSessionId,
    data: { no_show_at: null },
    previousData: clientSession,
  });

  await dataProvider.create("client_session_events", {
    data: {
      client_session_id: clientSessionId,
      kind: "no_show_reversed",
      occurred_at: now,
    },
  });

  if (clientSession.enrollment_id != null) {
    const slot = await findEnrollmentExpectedSessionForSession(dataProvider, {
      enrollmentId: clientSession.enrollment_id,
      scheduledAt: clientSession.scheduled_at,
    });
    if (slot) {
      await resolveCadenceIssueFulfillment(dataProvider, {
        enrollmentId: clientSession.enrollment_id,
        enrollmentExpectedSessionId: slot.id,
      });
    }
  }

  return { status: "reversed" };
};

import type { DataProvider, Identifier } from "ra-core";

import type {
  ClientSessionCadenceClassification,
  ClientSessionCadenceIssue,
} from "../types";
import {
  completeResolveCadenceIssueTask,
  findAnyResolveCadenceIssueTask,
} from "./resolveCadenceIssueTask";

// Client + Session Operations cadence correction: the human decisions
// the resolution UI (and ClientShow's own Attention section) offer for
// an expected 1:1 week — Known skip / Rescheduled / Missed-ghosted.
// Never guesses which classification is right (Atomic handles
// certainty; Leif handles ambiguity).
//
// Exception state-machine correction: a classification is a human
// JUDGMENT, not an immutable fact. setCadenceIssueClassification below
// both resolves an open issue AND reclassifies an already-resolved one —
// Leif can change his mind (known_skip -> rescheduled -> missed_ghosted)
// at any time. reopenCadenceIssue clears a classification entirely (made
// by mistake). Both preserve full audit history in
// client_session_cadence_issue_events; neither ever deletes the
// underlying issue row.
export type SetCadenceIssueClassificationResult =
  | { status: "resolved" }
  | { status: "reclassified" }
  // Idempotent no-op — re-submitting the SAME classification that's
  // already current is never a second event.
  | { status: "unchanged" }
  | { status: "not-found" };

const fetchIssue = async (
  dataProvider: DataProvider,
  cadenceIssueId: Identifier,
): Promise<ClientSessionCadenceIssue | null> =>
  await dataProvider
    .getOne<ClientSessionCadenceIssue>("client_session_cadence_issues", {
      id: cadenceIssueId,
    })
    .then(({ data }) => data)
    .catch(() => null);

export const setCadenceIssueClassification = async (
  dataProvider: DataProvider,
  {
    cadenceIssueId,
    classification,
    note,
  }: {
    cadenceIssueId: Identifier;
    classification: ClientSessionCadenceClassification;
    note?: string | null;
  },
): Promise<SetCadenceIssueClassificationResult> => {
  const issue = await fetchIssue(dataProvider, cadenceIssueId);
  if (!issue) return { status: "not-found" };

  const trimmedNote = note?.trim() || null;
  if (issue.resolved_at != null && issue.classification === classification) {
    return { status: "unchanged" };
  }

  const wasAlreadyClassified =
    issue.resolved_at != null && issue.classification != null;
  const now = new Date().toISOString();

  await dataProvider.update("client_session_cadence_issues", {
    id: issue.id,
    data: { classification, note: trimmedNote, resolved_at: now },
    previousData: issue,
  });
  await dataProvider.create("client_session_cadence_issue_events", {
    data: {
      cadence_issue_id: issue.id,
      kind: wasAlreadyClassified ? "reclassified" : "resolved",
      classification,
      note: trimmedNote,
      occurred_at: now,
    },
  });
  await completeResolveCadenceIssueTask(dataProvider, issue.id, now);

  return { status: wasAlreadyClassified ? "reclassified" : "resolved" };
};

export type ReopenCadenceIssueResult =
  | { status: "reopened" }
  // Idempotent no-op — already unresolved.
  | { status: "already-open" }
  | { status: "not-found" };

// The safe correction path for a classification made by mistake — clears
// it entirely (back to a plain unresolved issue, same as if it had never
// been classified) and reopens its linked Task, with the correction
// itself durable in client_session_cadence_issue_events.
export const reopenCadenceIssue = async (
  dataProvider: DataProvider,
  { cadenceIssueId }: { cadenceIssueId: Identifier },
): Promise<ReopenCadenceIssueResult> => {
  const issue = await fetchIssue(dataProvider, cadenceIssueId);
  if (!issue) return { status: "not-found" };
  if (issue.resolved_at == null) return { status: "already-open" };

  const now = new Date().toISOString();
  await dataProvider.update("client_session_cadence_issues", {
    id: issue.id,
    data: { classification: null, resolved_at: null, note: null },
    previousData: issue,
  });
  await dataProvider.create("client_session_cadence_issue_events", {
    data: { cadence_issue_id: issue.id, kind: "reopened", occurred_at: now },
  });

  const task = await findAnyResolveCadenceIssueTask(dataProvider, issue.id);
  if (task?.done_date) {
    await dataProvider.update("tasks", {
      id: task.id,
      data: { done_date: null, status: "pending" },
      previousData: task,
    });
  }

  return { status: "reopened" };
};

import type { DataProvider, Identifier } from "ra-core";

import { resolveDefaultTaskSalesId } from "../sales-calls/resolveDefaultTaskSalesId";
import type { Task } from "../types";

const RESOLVE_CADENCE_ISSUE_TASK_TYPE = "resolve_client_session_cadence";

// resolveSalesCallTask.ts's own find/complete shape, deterministic by
// cadence_issue_id (always set at creation — no legacy-Task fallback
// needed, unlike sales_call_id's). Exception state-machine correction: a
// resolve_client_session_cadence Task is no longer ONLY ever created by
// the calendar sync's own detection pass — see ensureCadenceIssueTaskOpen
// below, which the app itself now also calls synchronously (a No-show
// that breaks fulfillment must surface immediately, not wait for the
// next 6-hourly cron pass).
export const findAnyResolveCadenceIssueTask = async (
  dataProvider: DataProvider,
  cadenceIssueId: Identifier,
): Promise<Task | null> => {
  const { data } = await dataProvider.getList<Task>("tasks", {
    filter: {
      cadence_issue_id: cadenceIssueId,
      type: RESOLVE_CADENCE_ISSUE_TASK_TYPE,
    },
    pagination: { page: 1, perPage: 5 },
    sort: { field: "id", order: "ASC" },
  });
  return data[0] ?? null;
};

export const findPendingResolveCadenceIssueTask = async (
  dataProvider: DataProvider,
  cadenceIssueId: Identifier,
): Promise<Task | null> => {
  const task = await findAnyResolveCadenceIssueTask(
    dataProvider,
    cadenceIssueId,
  );
  return task && !task.done_date ? task : null;
};

export const completeResolveCadenceIssueTask = async (
  dataProvider: DataProvider,
  cadenceIssueId: Identifier,
  completedAt: string,
): Promise<void> => {
  const task = await findPendingResolveCadenceIssueTask(
    dataProvider,
    cadenceIssueId,
  );
  if (!task) return;
  await dataProvider.update("tasks", {
    id: task.id,
    data: { done_date: completedAt, status: "completed" },
    previousData: task,
  });
};

// The app-side create-or-reopen half — mirrors ensureResolveSalesCallTask.ts's
// own shape. Called whenever ensureCadenceIssueOpen.ts creates or reopens
// a client_session_cadence_issues row: a done Task for the SAME issue is
// reopened in place (never a second Task for one issue); no Task yet
// means one is created fresh.
export const ensureCadenceIssueTaskOpen = async (
  dataProvider: DataProvider,
  {
    cadenceIssueId,
    contactId,
    contactName,
    weekLabel,
  }: {
    cadenceIssueId: Identifier;
    contactId: Identifier;
    contactName: string;
    weekLabel: string;
  },
): Promise<void> => {
  const existing = await findAnyResolveCadenceIssueTask(
    dataProvider,
    cadenceIssueId,
  );
  if (existing) {
    if (!existing.done_date) return;
    await dataProvider.update("tasks", {
      id: existing.id,
      data: { done_date: null, status: "pending" },
      previousData: existing,
    });
    return;
  }

  const salesId = await resolveDefaultTaskSalesId(dataProvider);
  await dataProvider.create("tasks", {
    data: {
      contact_id: contactId,
      type: RESOLVE_CADENCE_ISSUE_TASK_TYPE,
      text: `${contactName} · No session booked for week of ${weekLabel}`,
      due_date: new Date().toISOString(),
      status: "pending",
      cadence_issue_id: cadenceIssueId,
      ...(salesId != null ? { sales_id: salesId } : {}),
    },
  });
};

import type { DataProvider, Identifier } from "ra-core";

import type { ClientSession, EnrollmentExpectedSession } from "../types";
import { completeResolveCadenceIssueTask } from "./resolveCadenceIssueTask";

export type ResolveCadenceIssueFulfillmentResult =
  | { status: "resolved" }
  | { status: "no-issue" }
  | { status: "already-resolved" }
  | { status: "not-fulfilled" }
  // A real human classification exists — never auto-touched, same rule
  // as ensureCadenceIssueOpen.ts's own "left-classified".
  | { status: "left-classified" };

const isFulfilling = (
  session: ClientSession,
  slot: Pick<EnrollmentExpectedSession, "window_start" | "window_end">,
) => {
  if (session.status === "cancelled" || session.no_show_at) return false;
  const scheduledAt = new Date(session.scheduled_at);
  return (
    scheduledAt >= new Date(slot.window_start) &&
    scheduledAt < new Date(slot.window_end)
  );
};

// Client + Session Operations cadence correction (exception state-
// machine fix): the other half of ensureCadenceIssueOpen.ts — called
// synchronously by reverseClientSessionNoShow.ts the moment a session's
// no-show is corrected. If that restores deterministic fulfillment for
// the Enrollment's own frozen slot AND the only reason the issue was
// open was the lost fulfillment (never a real human judgment),
// auto-resolve it — Atomic handles this certainty on its own. A real
// human classification is never silently overwritten just because a
// session showed up later.
export const resolveCadenceIssueFulfillment = async (
  dataProvider: DataProvider,
  {
    enrollmentId,
    enrollmentExpectedSessionId,
  }: { enrollmentId: Identifier; enrollmentExpectedSessionId: Identifier },
): Promise<ResolveCadenceIssueFulfillmentResult> => {
  const { data: existingList } = await dataProvider.getList(
    "client_session_cadence_issues",
    {
      filter: {
        enrollment_id: enrollmentId,
        enrollment_expected_session_id: enrollmentExpectedSessionId,
      },
      pagination: { page: 1, perPage: 1 },
      sort: { field: "id", order: "ASC" },
    },
  );
  const issue = existingList[0];
  if (!issue) return { status: "no-issue" };
  if (issue.resolved_at != null) {
    return issue.classification != null
      ? { status: "left-classified" }
      : { status: "already-resolved" };
  }

  const slot = await dataProvider
    .getOne<EnrollmentExpectedSession>("enrollment_expected_sessions", {
      id: enrollmentExpectedSessionId,
    })
    .then(({ data }) => data)
    .catch(() => null);
  if (!slot) return { status: "not-fulfilled" };

  const { data: sessions } = await dataProvider.getList<ClientSession>(
    "client_sessions",
    {
      filter: { enrollment_id: enrollmentId },
      pagination: { page: 1, perPage: 200 },
      sort: { field: "id", order: "ASC" },
    },
  );
  const fulfilled = sessions.some((session) => isFulfilling(session, slot));
  if (!fulfilled) return { status: "not-fulfilled" };

  const now = new Date().toISOString();
  await dataProvider.update("client_session_cadence_issues", {
    id: issue.id,
    data: { resolved_at: now },
    previousData: issue,
  });
  await dataProvider.create("client_session_cadence_issue_events", {
    data: { cadence_issue_id: issue.id, kind: "resolved", occurred_at: now },
  });
  await completeResolveCadenceIssueTask(dataProvider, issue.id, now);

  return { status: "resolved" };
};

import type { DataProvider, Identifier } from "ra-core";

import type { ClientSession } from "../types";

export type RescheduleClientSessionResult =
  | { status: "rescheduled"; clientSession: ClientSession }
  | { status: "not-found" }
  // Same new time already recorded — a duplicate reschedule webhook is a
  // safe no-op, never a second event. Mirrors sales-calls/
  // rescheduleSalesCall.ts exactly.
  | { status: "already-current"; clientSession: ClientSession }
  | { status: "cancelled-session" };

// A reschedule updates the SAME client_sessions row — it must never look
// like two independent sessions in the ledger. scheduled_at moves,
// reschedule_count increments, and the fact is preserved individually in
// client_session_events, same "durable individual events, not just a
// count" rationale as sales_call_events.
export const rescheduleClientSession = async (
  dataProvider: DataProvider,
  {
    clientSessionId,
    newScheduledAt,
  }: { clientSessionId: Identifier; newScheduledAt: string },
): Promise<RescheduleClientSessionResult> => {
  const { data: clientSession } = await dataProvider
    .getOne<ClientSession>("client_sessions", { id: clientSessionId })
    .catch(() => ({ data: null as ClientSession | null }));
  if (!clientSession) return { status: "not-found" };
  if (clientSession.status === "cancelled") {
    return { status: "cancelled-session" };
  }
  if (clientSession.scheduled_at === newScheduledAt) {
    return { status: "already-current", clientSession };
  }

  const now = new Date().toISOString();
  const previousScheduledAt = clientSession.scheduled_at;
  const { data: updated } = await dataProvider.update<ClientSession>(
    "client_sessions",
    {
      id: clientSessionId,
      data: {
        scheduled_at: newScheduledAt,
        reschedule_count: clientSession.reschedule_count + 1,
        last_rescheduled_at: now,
      },
      previousData: clientSession,
    },
  );

  await dataProvider.create("client_session_events", {
    data: {
      client_session_id: clientSessionId,
      kind: "rescheduled",
      occurred_at: now,
      previous_scheduled_at: previousScheduledAt,
      new_scheduled_at: newScheduledAt,
    },
  });

  return { status: "rescheduled", clientSession: updated };
};

import type { DataProvider } from "ra-core";

import type { ClientSession } from "../types";
import {
  bookClientSession,
  type BookClientSessionResult,
} from "./bookClientSession";
import {
  cancelClientSession,
  type CancelClientSessionResult,
} from "./cancelClientSession";
import { matchClientSessionAppointment } from "./matchClientSessionAppointment";
import {
  rescheduleClientSession,
  type RescheduleClientSessionResult,
} from "./rescheduleClientSession";

// The fixture-testable "domain service" boundary for paid-client-session
// Acuity events — mirrors sales-calls/acuityBookingService.ts's own shape
// exactly (same dual-implementation convention: supabase/functions/
// acuity_webhook/acuityClientSessionHandlers.ts is its production mirror).
// Callers (the Deno webhook, this module's own tests) are expected to have
// ALREADY determined the incoming appointment type maps to a paid-client-
// session Offer (via clientSessionAcuityMapping.ts) before reaching here —
// this module never touches sales_calls/resolve_sales_call Tasks/
// Opportunity sales stage in any way.
export type AcuityAppointmentPayload = {
  acuityAppointmentId: string;
  acuityAppointmentTypeId: string;
  email: string;
  firstName: string;
  lastName: string;
  datetime: string;
};

export type ProcessClientSessionEventResult =
  | {
      status: "booked";
      matchReason: "matched" | "none" | "ambiguous";
      booking: BookClientSessionResult;
    }
  | { status: "unknown-appointment-type" }
  | { status: "rescheduled"; result: RescheduleClientSessionResult }
  | { status: "cancelled"; result: CancelClientSessionResult }
  // A reschedule/cancel event referencing an appointment id this CRM never
  // recorded a session for (e.g. the original "scheduled" webhook was
  // missed) — same as acuityBookingService.ts's own "unknown-appointment".
  | { status: "unknown-appointment" };

export const processClientSessionAcuityEvent = async (
  dataProvider: DataProvider,
  action: "scheduled" | "rescheduled" | "canceled",
  appointment: AcuityAppointmentPayload,
): Promise<ProcessClientSessionEventResult> => {
  if (action === "canceled") {
    const existing = await findByAcuityAppointmentId(
      dataProvider,
      appointment.acuityAppointmentId,
    );
    if (!existing) return { status: "unknown-appointment" };
    const result = await cancelClientSession(dataProvider, existing.id);
    return { status: "cancelled", result };
  }

  if (action === "rescheduled") {
    const existing = await findByAcuityAppointmentId(
      dataProvider,
      appointment.acuityAppointmentId,
    );
    if (!existing) {
      return handleScheduled(dataProvider, appointment);
    }
    const result = await rescheduleClientSession(dataProvider, {
      clientSessionId: existing.id,
      newScheduledAt: appointment.datetime,
    });
    return { status: "rescheduled", result };
  }

  return handleScheduled(dataProvider, appointment);
};

const findByAcuityAppointmentId = async (
  dataProvider: DataProvider,
  acuityAppointmentId: string,
): Promise<ClientSession | null> => {
  const { data } = await dataProvider.getList<ClientSession>(
    "client_sessions",
    {
      filter: { acuity_appointment_id: acuityAppointmentId },
      pagination: { page: 1, perPage: 1 },
      sort: { field: "id", order: "ASC" },
    },
  );
  return data[0] ?? null;
};

const handleScheduled = async (
  dataProvider: DataProvider,
  appointment: AcuityAppointmentPayload,
): Promise<ProcessClientSessionEventResult> => {
  const match = await matchClientSessionAppointment(dataProvider, {
    email: appointment.email,
    firstName: appointment.firstName,
    lastName: appointment.lastName,
    acuityAppointmentTypeId: appointment.acuityAppointmentTypeId,
  });
  if (match.status === "unknown-appointment-type") {
    return { status: "unknown-appointment-type" };
  }

  const enrollmentId = match.status === "matched" ? match.enrollment.id : null;

  const booking = await bookClientSession({
    dataProvider,
    contactId: match.contact.id,
    enrollmentId,
    offerId: match.offer.id,
    scheduledAt: appointment.datetime,
    source: "acuity",
    acuityAppointmentId: appointment.acuityAppointmentId,
    acuityAppointmentTypeId: appointment.acuityAppointmentTypeId,
  });

  return {
    status: "booked",
    matchReason: match.status === "matched" ? "matched" : match.reason,
    booking,
  };
};

import type { DataProvider, Identifier } from "ra-core";

import type { Deal, Enrollment } from "../types";

export type ClientSessionEnrollmentMatch =
  | { kind: "matched"; enrollment: Enrollment }
  | { kind: "none" }
  | { kind: "ambiguous" };

// "Find the one legitimately serviceable Enrollment for this paid-client
// session" — never guessed. Only an ACTIVE Enrollment counts as legitimate
// (an onboarding/offboarding/completed Enrollment is not currently
// consuming sessions); zero or 2+ active matches both come back
// unresolved rather than picking one, mirroring sales-calls/
// matchAcuityBooking.ts's own findActiveOpportunityMatch exactly — the
// caller preserves the session with enrollment_id = null instead of
// silently attaching it to the wrong (or an ambiguous) Enrollment.
export const matchClientSessionEnrollment = async (
  dataProvider: DataProvider,
  { contactId, offerId }: { contactId: Identifier; offerId: Identifier },
): Promise<ClientSessionEnrollmentMatch> => {
  const { data: deals } = await dataProvider.getList<Deal>("deals", {
    filter: { contact_id: contactId, offer_id: offerId },
    pagination: { page: 1, perPage: 100 },
    sort: { field: "id", order: "ASC" },
  });
  if (deals.length === 0) return { kind: "none" };

  const dealIds = deals.map((deal) => deal.id);
  const { data: enrollments } = await dataProvider.getList<Enrollment>(
    "enrollments",
    {
      filter: {
        "opportunity_id@in": `(${dealIds.join(",")})`,
        status: "active",
      },
      pagination: { page: 1, perPage: 10 },
      sort: { field: "id", order: "ASC" },
    },
  );
  if (enrollments.length === 0) return { kind: "none" };
  if (enrollments.length > 1) return { kind: "ambiguous" };
  return { kind: "matched", enrollment: enrollments[0] };
};

import type { DataProvider } from "ra-core";

import type { Contact, Enrollment, Offer } from "../types";
import { normalizeEmail } from "../public-application/submitApplication";
import { resolveOfferForClientSessionAppointmentType } from "./clientSessionAcuityMapping";
import { matchClientSessionEnrollment } from "./matchClientSessionEnrollment";

// Normalized-email match-or-create — same matching principle as Native
// Application Intake / sales-calls/matchAcuityBooking.ts's own
// findOrCreateContact, duplicated per this codebase's documented
// convention (small independent modules over a shared private helper).
// Existing Contact data is never overwritten, only last_seen touched. In
// practice an already-enrolled paying client will almost always already
// exist as a Contact — this exists for the rare/anomalous case rather than
// assuming it.
const findOrCreateContact = async (
  dataProvider: DataProvider,
  {
    firstName,
    lastName,
    email,
  }: { firstName: string; lastName: string; email: string },
): Promise<Contact> => {
  const normalized = normalizeEmail(email);
  const { data: contacts } = await dataProvider.getList<Contact>("contacts", {
    filter: {},
    pagination: { page: 1, perPage: 1000 },
    sort: { field: "id", order: "ASC" },
  });
  const existing = contacts.find((contact) =>
    (contact.email_jsonb ?? []).some(
      (entry) => entry.email && normalizeEmail(entry.email) === normalized,
    ),
  );
  if (existing) {
    await dataProvider.update("contacts", {
      id: existing.id,
      data: { last_seen: new Date().toISOString() },
      previousData: existing,
    });
    return existing;
  }

  const { data: created } = await dataProvider.create<Contact>("contacts", {
    data: {
      first_name: firstName,
      last_name: lastName,
      email_jsonb: [{ email: normalized, type: "Other" }],
      phone_jsonb: [],
      tags: [],
      has_newsletter: false,
      first_seen: new Date().toISOString(),
      last_seen: new Date().toISOString(),
      sales_eligibility: "normal",
    },
  });
  return created;
};

export type MatchClientSessionAppointmentResult =
  | {
      status: "matched";
      contact: Contact;
      offer: Offer;
      enrollment: Enrollment;
    }
  | {
      status: "unmatched-enrollment";
      contact: Contact;
      offer: Offer;
      reason: "none" | "ambiguous";
    }
  // The appointment type isn't mapped to any Offer's paid-client-session
  // config yet — a configuration gap, not a Contact/booking problem. No
  // Contact is even looked up, matching matchAcuityBooking.ts's own
  // "unknown-appointment-type" precedent.
  | { status: "unknown-appointment-type" };

// Identity + Enrollment resolution for one incoming paid-client-session
// Acuity booking. Contact resolution always succeeds (find-or-create);
// Enrollment resolution can come back unresolved — see
// matchClientSessionEnrollment.ts above. Never creates or mutates an
// Opportunity/Enrollment — this is read-only matching against what
// already exists.
export const matchClientSessionAppointment = async (
  dataProvider: DataProvider,
  {
    email,
    firstName,
    lastName,
    acuityAppointmentTypeId,
  }: {
    email: string;
    firstName: string;
    lastName: string;
    acuityAppointmentTypeId: string;
  },
): Promise<MatchClientSessionAppointmentResult> => {
  const offer = await resolveOfferForClientSessionAppointmentType(
    dataProvider,
    acuityAppointmentTypeId,
  );
  if (!offer) return { status: "unknown-appointment-type" };

  const contact = await findOrCreateContact(dataProvider, {
    firstName,
    lastName,
    email,
  });

  const match = await matchClientSessionEnrollment(dataProvider, {
    contactId: contact.id,
    offerId: offer.id,
  });

  if (match.kind === "matched") {
    return { status: "matched", contact, offer, enrollment: match.enrollment };
  }
  return {
    status: "unmatched-enrollment",
    contact,
    offer,
    reason: match.kind === "ambiguous" ? "ambiguous" : "none",
  };
};

import type { DataProvider, Identifier } from "ra-core";

import type { ClientSession } from "../types";
import { ensureCadenceIssueOpen } from "./ensureCadenceIssueOpen";
import { findEnrollmentExpectedSessionForSession } from "./findEnrollmentExpectedSessionForSession";

export type MarkClientSessionNoShowResult =
  | { status: "no-show" }
  | { status: "not-found" }
  // Idempotent no-op — a double-click/stale tab is never a second write,
  // same convention as every other domain function in this app.
  | { status: "already-no-show" }
  | { status: "cancelled-session" }
  // A session that hasn't happened yet can't already be a no-show — same
  // "a fact about the clock, not a guess about attendance" deterministic
  // guard the old completeClientSession.ts relied on.
  | { status: "not-yet-occurred" };

// Client + Session Operations cadence correction: the ONE manual
// exception action the Enrollment page's session row offers, replacing
// the old "Mark Completed" — a booked session is assumed attended by
// default (see types.ts's own ClientSession comment), so the only thing
// worth a click is the negative case: this booking stood but the client
// did not show. Distinct from cancelClientSession.ts (the appointment
// itself was called off ahead of time, by Acuity) — a no-show is Leif's
// own after-the-fact correction, always reversible (see
// reverseClientSessionNoShow.ts), never a destructive edit.
//
// Exception state-machine correction: if this session was the one thing
// fulfilling an expected 1:1 window, marking it No-show must make that
// exception immediately actionable — never wait for the next 6-hourly
// calendar-sync detection pass. See ensureCadenceIssueOpen.ts.
export const markClientSessionNoShow = async (
  dataProvider: DataProvider,
  clientSessionId: Identifier,
): Promise<MarkClientSessionNoShowResult> => {
  const { data: clientSession } = await dataProvider
    .getOne<ClientSession>("client_sessions", { id: clientSessionId })
    .catch(() => ({ data: null as ClientSession | null }));
  if (!clientSession) return { status: "not-found" };
  if (clientSession.status === "cancelled") {
    return { status: "cancelled-session" };
  }
  if (clientSession.no_show_at) {
    return { status: "already-no-show" };
  }
  if (new Date(clientSession.scheduled_at) > new Date()) {
    return { status: "not-yet-occurred" };
  }

  const now = new Date().toISOString();
  await dataProvider.update<ClientSession>("client_sessions", {
    id: clientSessionId,
    data: { no_show_at: now },
    previousData: clientSession,
  });

  await dataProvider.create("client_session_events", {
    data: {
      client_session_id: clientSessionId,
      kind: "no_show",
      occurred_at: now,
    },
  });

  if (clientSession.enrollment_id != null) {
    const slot = await findEnrollmentExpectedSessionForSession(dataProvider, {
      enrollmentId: clientSession.enrollment_id,
      scheduledAt: clientSession.scheduled_at,
    });
    if (slot) {
      await ensureCadenceIssueOpen(dataProvider, {
        enrollmentId: clientSession.enrollment_id,
        enrollmentExpectedSessionId: slot.id,
      });
    }
  }

  return { status: "no-show" };
};

import type { DataProvider, Identifier } from "ra-core";

import type {
  ClientSession,
  ClientSessionCadenceIssue,
  Contact,
  Deal,
  Enrollment,
  EnrollmentExpectedSession,
} from "../types";
import { findNoShowSessionInSlot } from "./findNoShowSessionInSlot";

// Mirrors loadSalesCallResolutionContext.ts's own shape — loaded
// imperatively (not useGetOne/useQuery) so CadenceResolutionModal.tsx (the
// one shared resolution component, opened either as a local dialog on
// ClientShow or via the /client-session-cadence/:id/resolve route's own
// thin wrapper — UX correction: never two separate resolution
// implementations) can re-run it after an action completes, same "load
// once, act once, done" lifecycle.
//
// Exception state-machine correction: a single "found" state now covers
// both unresolved AND resolved issues — a classification is editable at
// any time (change it, or clear it back to unresolved), so the modal
// doesn't need two structurally different render branches for
// "resolvable" vs. "already-resolved". The issue's own resolved_at/
// classification fields are what it reads to decide what to show.
//
// Service Period model correction: `slot` is the Enrollment's own frozen
// enrollment_expected_sessions row, never the shared, editable
// expected_session_windows row — its dates/title are immune to a later
// edit of the source calendar event.
export type CadenceIssueResolutionContext =
  | { kind: "not-found" }
  | {
      kind: "found";
      contact: Contact;
      enrollment: Enrollment;
      slot: EnrollmentExpectedSession;
      issue: ClientSessionCadenceIssue;
      // UX correction: "Sep 3 session marked no-show" vs. plain "No
      // session booked" — same context line ClientShow's own Attention
      // row already shows, computed here once so the modal never
      // disagrees with it.
      noShowSession: ClientSession | null;
    };

export const loadCadenceIssueResolutionContext = async (
  dataProvider: DataProvider,
  cadenceIssueId: Identifier,
): Promise<CadenceIssueResolutionContext> => {
  const issue = await dataProvider
    .getOne<ClientSessionCadenceIssue>("client_session_cadence_issues", {
      id: cadenceIssueId,
    })
    .then(({ data }) => data)
    .catch(() => null);
  if (!issue) return { kind: "not-found" };

  const enrollment = await dataProvider
    .getOne<Enrollment>("enrollments", { id: issue.enrollment_id })
    .then(({ data }) => data)
    .catch(() => null);
  if (!enrollment) return { kind: "not-found" };

  const slot = await dataProvider
    .getOne<EnrollmentExpectedSession>("enrollment_expected_sessions", {
      id: issue.enrollment_expected_session_id,
    })
    .then(({ data }) => data)
    .catch(() => null);
  if (!slot) return { kind: "not-found" };

  const deal = await dataProvider
    .getOne<Deal>("deals", { id: enrollment.opportunity_id })
    .then(({ data }) => data)
    .catch(() => null);
  const contact = deal
    ? await dataProvider
        .getOne<Contact>("contacts", { id: deal.contact_id })
        .then(({ data }) => data)
        .catch(() => null)
    : null;
  if (!contact) return { kind: "not-found" };

  const { data: sessions } = await dataProvider.getList<ClientSession>(
    "client_sessions",
    {
      filter: { enrollment_id: enrollment.id },
      pagination: { page: 1, perPage: 200 },
      sort: { field: "id", order: "ASC" },
    },
  );
  const noShowSession = findNoShowSessionInSlot(sessions, slot);

  return { kind: "found", contact, enrollment, slot, issue, noShowSession };
};

import type { ClientSession, EnrollmentExpectedSession } from "../types";

// Shared between ClientShow's own Attention row and
// CadenceResolutionModal.tsx — a no-show'd session inside the slot gets
// more specific copy ("Sep 3 session marked no-show") than a plain
// never-booked week ("No session booked"); both are the SAME underlying
// unresolved issue, just worded from what actually happened. One
// implementation so both surfaces always agree.
export const findNoShowSessionInSlot = (
  sessions: ClientSession[],
  slot: Pick<EnrollmentExpectedSession, "window_start" | "window_end">,
) =>
  sessions.find(
    (session) =>
      session.no_show_at &&
      new Date(session.scheduled_at) >= new Date(slot.window_start) &&
      new Date(session.scheduled_at) < new Date(slot.window_end),
  ) ?? null;

import type { DataProvider, Identifier } from "ra-core";

import type { EnrollmentExpectedSession } from "../types";

// Client + Session Operations Service Period model: the shared lookup
// behind markClientSessionNoShow.ts/reverseClientSessionNoShow.ts —
// given a session's own Enrollment and scheduled time, finds the
// Enrollment's own frozen enrollment_expected_sessions slot it falls
// inside, if any (never the raw shared expected_session_windows —
// fulfillment/cadence always reads the Enrollment's own snapshotted
// dates, immune to a later edit of the source calendar event). A session
// outside every assigned slot (no Service Period slot covers it, or none
// have been assigned yet) resolves to null — callers must treat that as
// "nothing to reactivate," never guess a slot.
export const findEnrollmentExpectedSessionForSession = async (
  dataProvider: DataProvider,
  {
    enrollmentId,
    scheduledAt,
  }: { enrollmentId: Identifier; scheduledAt: string },
): Promise<EnrollmentExpectedSession | null> => {
  const { data: slots } = await dataProvider.getList<EnrollmentExpectedSession>(
    "enrollment_expected_sessions",
    {
      filter: { enrollment_id: enrollmentId },
      pagination: { page: 1, perPage: 12 },
      sort: { field: "ordinal", order: "ASC" },
    },
  );

  const scheduledTime = new Date(scheduledAt).getTime();
  return (
    slots.find(
      (slot) =>
        scheduledTime >= new Date(slot.window_start).getTime() &&
        scheduledTime < new Date(slot.window_end).getTime(),
    ) ?? null
  );
};

import type { DataProvider, Identifier } from "ra-core";

import type {
  Contact,
  Deal,
  Enrollment,
  EnrollmentExpectedSession,
} from "../types";
import { formatWindowWeekLabel } from "./cadenceWeekLabel";
import { ensureCadenceIssueTaskOpen } from "./resolveCadenceIssueTask";

export type EnsureCadenceIssueOpenResult =
  // Freshly created — no issue existed for this (Enrollment, slot) pair.
  | { status: "created"; issueId: Identifier }
  // Existed, was resolved with classification null (an auto-resolve —
  // e.g. Undo No-show previously restored fulfillment) — reopened.
  | { status: "reopened"; issueId: Identifier }
  // Idempotent no-op — already unresolved.
  | { status: "already-open"; issueId: Identifier }
  // Existed and already carries a real human classification — left
  // completely untouched. Per this slice's own governing rule, an
  // automated caller (No-show, the calendar sync's detection pass) NEVER
  // silently overwrites a human judgment.
  | { status: "left-classified"; issueId: Identifier };

// Client + Session Operations cadence correction (exception state-
// machine fix): the shared "make sure this slot's cadence issue is open
// and actionable" operation — called synchronously by
// markClientSessionNoShow.ts the moment a fulfilling session is marked
// No-show (never waiting for the next 6-hourly calendar-sync detection
// pass), and structurally identical to what that detection pass itself
// does server-side. `enrollmentExpectedSessionId` is the Enrollment's own
// frozen slot id (see enrollment_expected_sessions), never the shared,
// editable expected_session_windows row. Always ensures the linked Task
// exists/is reopened too (see resolveCadenceIssueTask.ts) — the durable
// issue row and its Dashboard Needs Attention Task are kept in lockstep,
// never drifting.
export const ensureCadenceIssueOpen = async (
  dataProvider: DataProvider,
  {
    enrollmentId,
    enrollmentExpectedSessionId,
  }: { enrollmentId: Identifier; enrollmentExpectedSessionId: Identifier },
): Promise<EnsureCadenceIssueOpenResult> => {
  const { data: existingList } = await dataProvider.getList(
    "client_session_cadence_issues",
    {
      filter: {
        enrollment_id: enrollmentId,
        enrollment_expected_session_id: enrollmentExpectedSessionId,
      },
      pagination: { page: 1, perPage: 1 },
      sort: { field: "id", order: "ASC" },
    },
  );
  const existing = existingList[0] ?? null;
  const now = new Date().toISOString();

  if (
    existing &&
    existing.resolved_at != null &&
    existing.classification != null
  ) {
    return { status: "left-classified", issueId: existing.id };
  }
  if (existing && existing.resolved_at == null) {
    return { status: "already-open", issueId: existing.id };
  }

  let issueId: Identifier;
  let outcome: "created" | "reopened";
  if (existing) {
    await dataProvider.update("client_session_cadence_issues", {
      id: existing.id,
      data: { resolved_at: null },
      previousData: existing,
    });
    await dataProvider.create("client_session_cadence_issue_events", {
      data: {
        cadence_issue_id: existing.id,
        kind: "reopened",
        occurred_at: now,
      },
    });
    issueId = existing.id;
    outcome = "reopened";
  } else {
    const { data: created } = await dataProvider.create(
      "client_session_cadence_issues",
      {
        data: {
          enrollment_id: enrollmentId,
          enrollment_expected_session_id: enrollmentExpectedSessionId,
        },
      },
    );
    await dataProvider.create("client_session_cadence_issue_events", {
      data: { cadence_issue_id: created.id, kind: "created", occurred_at: now },
    });
    issueId = created.id;
    outcome = "created";
  }

  const slot = await dataProvider
    .getOne<EnrollmentExpectedSession>("enrollment_expected_sessions", {
      id: enrollmentExpectedSessionId,
    })
    .then(({ data }) => data)
    .catch(() => null);
  const enrollment = await dataProvider
    .getOne<Enrollment>("enrollments", { id: enrollmentId })
    .then(({ data }) => data)
    .catch(() => null);
  const deal = enrollment
    ? await dataProvider
        .getOne<Deal>("deals", { id: enrollment.opportunity_id })
        .then(({ data }) => data)
        .catch(() => null)
    : null;
  const contact = deal
    ? await dataProvider
        .getOne<Contact>("contacts", { id: deal.contact_id })
        .then(({ data }) => data)
        .catch(() => null)
    : null;

  if (slot && contact) {
    const contactName =
      `${contact.first_name ?? ""} ${contact.last_name ?? ""}`.trim();
    await ensureCadenceIssueTaskOpen(dataProvider, {
      cadenceIssueId: issueId,
      contactId: contact.id,
      contactName,
      weekLabel: formatWindowWeekLabel(slot),
    });
  }

  return { status: outcome, issueId };
};

import type {
  ClientSession,
  ClientSessionCadenceIssue,
  EnrollmentExpectedSession,
} from "../types";

export type ExpectedWeekStatus =
  | "fulfilled"
  | "unresolved"
  | "pending"
  | "known_skip"
  | "rescheduled"
  | "missed_ghosted";

export type ExpectedWeekSummary = {
  slot: EnrollmentExpectedSession;
  status: ExpectedWeekStatus;
  fulfillingSession: ClientSession | null;
  issue: ClientSessionCadenceIssue | null;
};

export type ClientSessionCadenceSummary = {
  // 1-4, or null when the Enrollment has no assigned slots at all yet
  // (calendar sync/assignment hasn't run, or nothing eligible exists).
  currentServicePeriod: number | null;
  // The CURRENT Service Period's own slots only (up to 3) — real
  // calendar-derived windows, sequenced by the Service Period model
  // (Client + Session Operations correction: 12 total session
  // opportunities grouped into 4 Service Periods of exactly 3, defined
  // by the chronological sequence of qualifying Year Planning windows —
  // never a 30/31-day calendar month).
  expectedWeeks: ExpectedWeekSummary[];
  expectedCount: number;
  fulfilledCount: number;
  unresolvedCount: number;
  // The earliest still-booked (non-cancelled, non-no-show) session
  // strictly in the future, or null — independent of the current period.
  nextSession: ClientSession | null;
  // ClientShow's own "Needs attention" section (UX correction) —
  // EVERY still-open cadence issue for this Enrollment, regardless of
  // which Service Period its slot belongs to, so it stays in lockstep
  // with the Dashboard's own Needs Attention Task-based surface (the
  // same durable underlying issue, never two separate alert systems).
  attentionItems: ExpectedWeekSummary[];
};

const isFulfilling = (
  session: ClientSession,
  slot: Pick<EnrollmentExpectedSession, "window_start" | "window_end">,
) => {
  if (session.status === "cancelled" || session.no_show_at) return false;
  const scheduledAt = new Date(session.scheduled_at);
  return (
    scheduledAt >= new Date(slot.window_start) &&
    scheduledAt < new Date(slot.window_end)
  );
};

// 1-3 -> Period 1, 4-6 -> Period 2, 7-9 -> Period 3, 10-12 -> Period 4.
// Pure derived arithmetic — a Service Period number is never stored,
// only ever computed from a slot's own frozen ordinal.
const servicePeriodOf = (ordinal: number) => Math.ceil(ordinal / 3);

const computeSlotStatus = (
  slot: EnrollmentExpectedSession,
  sessions: ClientSession[],
  issues: ClientSessionCadenceIssue[],
  now: Date,
): ExpectedWeekSummary => {
  const fulfillingSession =
    sessions.find((session) => isFulfilling(session, slot)) ?? null;
  if (fulfillingSession) {
    return { slot, status: "fulfilled", fulfillingSession, issue: null };
  }

  const issue =
    issues.find(
      (candidate) =>
        String(candidate.enrollment_expected_session_id) === String(slot.id),
    ) ?? null;
  if (issue?.resolved_at && issue.classification) {
    return {
      slot,
      status: issue.classification,
      fulfillingSession: null,
      issue,
    };
  }
  // An issue that's still open is ALWAYS actionable, regardless of
  // whether the slot has technically closed by date yet (exception
  // state-machine correction) — ensureCadenceIssueOpen.ts only ever
  // creates/reopens one in response to a real, deterministic event (a
  // No-show), so its mere existence is itself the fact that matters, not
  // the calendar date.
  if (issue && issue.resolved_at == null) {
    return { slot, status: "unresolved", fulfillingSession: null, issue };
  }

  const slotHasClosed = new Date(slot.window_end) <= now;
  return {
    slot,
    status: slotHasClosed ? "unresolved" : "pending",
    fulfillingSession: null,
    issue,
  };
};

// The pure comparison behind the Enrollment page's cadence display
// (Client + Session Operations correction) — reads each Enrollment's own
// frozen, sequentially-assigned enrollment_expected_sessions slots
// (never a raw calendar-month filter over the shared
// expected_session_windows) — a booked/non-cancelled/non-no-show session
// inside a slot fulfills it BY DEFAULT, no manual completion step. An
// already-closed slot with nothing fulfilling it is "unresolved" until
// Leif classifies it; a slot that hasn't closed yet is merely "pending"
// (Leif may still book it), never flagged as a problem.
//
// "Current Service Period" = the highest-numbered period (1-4) whose own
// FIRST slot has already started (window_start <= now) — i.e. the period
// currently in progress, or the most recently begun one if all four have
// started, or Period 1 (shown with future/"Upcoming" slots) if the
// Enrollment hasn't reached its first slot's start date yet. This is a
// deliberate, explicit design choice (not dictated verbatim by the
// business rule) — see this slice's own report.
export const computeClientSessionCadenceSummary = (
  {
    sessions,
    slots,
    issues,
  }: {
    sessions: ClientSession[];
    slots: EnrollmentExpectedSession[];
    issues: ClientSessionCadenceIssue[];
  },
  now: Date = new Date(),
): ClientSessionCadenceSummary => {
  const sortedSlots = [...slots].sort((a, b) => a.ordinal - b.ordinal);

  let currentServicePeriod: number | null = null;
  if (sortedSlots.length > 0) {
    currentServicePeriod = 1;
    for (let period = 1; period <= 4; period++) {
      const firstOrdinalOfPeriod = (period - 1) * 3 + 1;
      const firstSlotOfPeriod = sortedSlots.find(
        (slot) => slot.ordinal === firstOrdinalOfPeriod,
      );
      if (
        firstSlotOfPeriod &&
        new Date(firstSlotOfPeriod.window_start) <= now
      ) {
        currentServicePeriod = period;
      }
    }
  }

  const periodSlots =
    currentServicePeriod == null
      ? []
      : sortedSlots.filter(
          (slot) => servicePeriodOf(slot.ordinal) === currentServicePeriod,
        );

  const expectedWeeks = periodSlots.map((slot) =>
    computeSlotStatus(slot, sessions, issues, now),
  );

  const fulfilledCount = expectedWeeks.filter(
    (week) => week.status === "fulfilled",
  ).length;
  const unresolvedCount = expectedWeeks.filter(
    (week) => week.status === "unresolved",
  ).length;

  const nextSession =
    sessions
      .filter(
        (session) =>
          session.status !== "cancelled" &&
          !session.no_show_at &&
          new Date(session.scheduled_at) > now,
      )
      .sort(
        (a, b) =>
          new Date(a.scheduled_at).getTime() -
          new Date(b.scheduled_at).getTime(),
      )[0] ?? null;

  // Every still-open issue, regardless of period — defensively re-checks
  // fulfillment (rather than trusting resolved_at alone) so a session
  // booked directly into the slot by some other path never leaves a
  // stale, already-fulfilled item sitting in Attention.
  const attentionItems: ExpectedWeekSummary[] = issues
    .filter((issue) => issue.resolved_at == null)
    .map((issue): ExpectedWeekSummary | null => {
      const slot = sortedSlots.find(
        (candidate) =>
          String(candidate.id) === String(issue.enrollment_expected_session_id),
      );
      if (!slot) return null;
      const fulfillingSession =
        sessions.find((session) => isFulfilling(session, slot)) ?? null;
      if (fulfillingSession) return null;
      return { slot, status: "unresolved", fulfillingSession: null, issue };
    })
    .filter((item): item is ExpectedWeekSummary => item != null)
    .sort((a, b) => a.slot.ordinal - b.slot.ordinal);

  return {
    currentServicePeriod,
    expectedWeeks,
    expectedCount: expectedWeeks.length,
    fulfilledCount,
    unresolvedCount,
    nextSession,
    attentionItems,
  };
};

import type { DataProvider } from "ra-core";

import type { Offer } from "../types";

// Durable mapping from an Acuity appointment type to the Offer whose PAID
// CLIENT SESSIONS it represents — e.g. The Living Example's real "Zoom
// 1:1", 90522599. Deliberately separate from sales-calls/
// offerCohortAcuityMapping.ts's resolver: that one maps a SALES CALL
// appointment type (a prospect deciding whether to buy); this one maps an
// already-enrolled client's recurring session. The two must never be
// confused merely because they can share a Contact/Offer — structurally
// impossible here since each reads its own distinct column
// (client_session_acuity_appointment_type_id vs
// acuity_appointment_type_id), enforced unique by its own partial index
// (supabase/schemas/01_tables.sql).
//
// Offer-level only in this slice (no Cohort-level session mapping — group-
// offer/cohort session attendance is explicitly out of scope for Client +
// Session Operations Slice A).
export const resolveOfferForClientSessionAppointmentType = async (
  dataProvider: DataProvider,
  acuityAppointmentTypeId: string,
): Promise<Offer | null> => {
  const { data: offers } = await dataProvider.getList<Offer>("offers", {
    filter: {
      client_session_acuity_appointment_type_id: acuityAppointmentTypeId,
    },
    pagination: { page: 1, perPage: 1 },
    sort: { field: "id", order: "ASC" },
  });
  return offers[0] ?? null;
};

import type { DataProvider, Identifier } from "ra-core";

import type { ClientSession } from "../types";

export type CancelClientSessionResult =
  | { status: "cancelled"; clientSession: ClientSession }
  | { status: "not-found" }
  // Already cancelled — a duplicate cancellation webhook is a safe no-op.
  | { status: "already-cancelled"; clientSession: ClientSession };

// Cancelling never touches enrollment_id/Enrollment state — it only marks
// the session itself cancelled and records the event. Mirrors sales-calls/
// cancelSalesCall.ts's shape, minus the "stranded Opportunity" follow-up
// logic (a sales-pipeline-specific concern that doesn't apply here).
// Leaves no_show_at untouched either way — a no-show already recorded on
// this session is its own independent, durable fact (see
// markClientSessionNoShow.ts); an out-of-order Acuity cancellation
// arriving afterward doesn't erase it.
export const cancelClientSession = async (
  dataProvider: DataProvider,
  clientSessionId: Identifier,
): Promise<CancelClientSessionResult> => {
  const { data: clientSession } = await dataProvider
    .getOne<ClientSession>("client_sessions", { id: clientSessionId })
    .catch(() => ({ data: null as ClientSession | null }));
  if (!clientSession) return { status: "not-found" };
  if (clientSession.status === "cancelled") {
    return { status: "already-cancelled", clientSession };
  }

  const now = new Date().toISOString();
  const { data: updated } = await dataProvider.update<ClientSession>(
    "client_sessions",
    {
      id: clientSessionId,
      data: { status: "cancelled", cancelled_at: now },
      previousData: clientSession,
    },
  );

  await dataProvider.create("client_session_events", {
    data: {
      client_session_id: clientSessionId,
      kind: "cancelled",
      occurred_at: now,
    },
  });

  return { status: "cancelled", clientSession: updated };
};

import { formatMonthDayString } from "../deals/dealUtils";

// Shared "Sep 5–Sep 6" formatting for an expected window/slot —
// window_end is EXCLUSIVE (Google Calendar's own all-day semantics), so
// the last day actually inside it is one day before it. Used everywhere
// a date range is shown to Leif (ClientShow, the resolution page, the
// Task text a No-show/detection pass creates) so the exact same label
// appears in every one of those places — works equally for a raw
// ExpectedSessionWindow or an Enrollment's own frozen
// EnrollmentExpectedSession slot, since both share this same shape.
export const formatCadenceWeekLabel = (
  windowStart: string,
  windowEnd: string,
): string => {
  const lastDay = new Date(windowEnd);
  lastDay.setDate(lastDay.getDate() - 1);
  return `${formatMonthDayString(windowStart)}–${formatMonthDayString(
    lastDay.toISOString().slice(0, 10),
  )}`;
};

export const formatWindowWeekLabel = (window: {
  window_start: string;
  window_end: string;
}): string => formatCadenceWeekLabel(window.window_start, window.window_end);

import type { DataProvider, Identifier } from "ra-core";

import type { ClientSession, ClientSessionSource } from "../types";

export type BookClientSessionInput = {
  dataProvider: DataProvider;
  contactId: Identifier;
  // null: could not be safely matched to exactly one legitimate active
  // Enrollment (see matchClientSessionEnrollment.ts) — preserved rather
  // than guessed.
  enrollmentId: Identifier | null;
  offerId: Identifier;
  scheduledAt: string;
  source: ClientSessionSource;
  acuityAppointmentId?: string | null;
  acuityAppointmentTypeId?: string | null;
};

export type BookClientSessionResult =
  | { status: "booked"; clientSession: ClientSession }
  // Same acuity_appointment_id already recorded — a duplicate webhook
  // delivery is a safe no-op, never a second row. Mirrors sales-calls/
  // bookSalesCall.ts's own first-line check exactly.
  | { status: "already-booked"; clientSession: ClientSession };

// Records a newly booked paid-client session. Unlike bookSalesCall.ts,
// there is no "one booked call per Opportunity" retargeting concept here —
// multiple sessions per service month are the normal, expected case, so
// every genuinely-new booking is its own row.
export const bookClientSession = async (
  input: BookClientSessionInput,
): Promise<BookClientSessionResult> => {
  const { dataProvider } = input;

  if (input.acuityAppointmentId) {
    const { data: existing } = await dataProvider.getList<ClientSession>(
      "client_sessions",
      {
        filter: { acuity_appointment_id: input.acuityAppointmentId },
        pagination: { page: 1, perPage: 1 },
        sort: { field: "id", order: "ASC" },
      },
    );
    if (existing[0]) {
      return { status: "already-booked", clientSession: existing[0] };
    }
  }

  const now = new Date().toISOString();
  const { data: clientSession } = await dataProvider.create<ClientSession>(
    "client_sessions",
    {
      data: {
        contact_id: input.contactId,
        enrollment_id: input.enrollmentId,
        offer_id: input.offerId,
        status: "booked",
        scheduled_at: input.scheduledAt,
        reschedule_count: 0,
        source: input.source,
        acuity_appointment_id: input.acuityAppointmentId ?? null,
        acuity_appointment_type_id: input.acuityAppointmentTypeId ?? null,
      },
    },
  );

  await dataProvider.create("client_session_events", {
    data: {
      client_session_id: clientSession.id,
      kind: "booked",
      occurred_at: now,
      new_scheduled_at: input.scheduledAt,
    },
  });

  return { status: "booked", clientSession };
};

