// Client + Session Operations, resolution UX correction: the ONE shared
// resolution component — a modal/lightbox over whatever page opened it,
// never a separate full-page workflow. Two entry points render it, never
// two implementations: ClientShow opens it as local dialog state (stays
// on /enrollments/:id/show, same scroll/context throughout); the
// /client-session-cadence/:id/resolve route (what a Dashboard/Task-row
// Resolve click still navigates to) is a thin wrapper around this same
// component that closes by going back in browser history — so "Dashboard
// → Resolve → close" lands back on the real Dashboard. Same durable
// client_session_cadence_issues row, same functions
// (setCadenceIssueClassification/reopenCadenceIssue) either way.
//
// The three classifications are Leif's own explicit decision; nothing
// here ever guesses which one applies (Atomic handles certainty, Leif
// handles ambiguity). A classification is a human judgment, never
// immutable — every button stays available even once resolved (clicking
// a DIFFERENT one reclassifies), and "Clear decision" clears it entirely
// for a judgment made by mistake, returning the issue (and Needs
// Attention, on both this client's page and the Dashboard) to
// unresolved. Escape/X/overlay-click all close it via the Dialog
// primitive's own onOpenChange — no bespoke modal/focus-trap logic here.
const classificationLabels: Record<ClientSessionCadenceClassification, string> =
  {
    known_skip: "Known skip",
    rescheduled: "Rescheduled",
    missed_ghosted: "Missed / ghosted",
  };

const ALL_CLASSIFICATIONS: ClientSessionCadenceClassification[] = [
  "known_skip",
  "rescheduled",
  "missed_ghosted",
];

export const CadenceResolutionModal = ({
  cadenceIssueId,
  onOpenChange,
  onChange,
}: {
  // null closes the dialog — the same prop doubles as both "which issue"
  // and "is it open".
  cadenceIssueId: Identifier | null;
  onOpenChange: (open: boolean) => void;
  // Called after every successful classify/clear, so a host page holding
  // its own cached cadence data (ClientShow) knows to refresh — never
  // required, since the modal's own display always reflects the latest
  // state regardless.
  onChange?: () => void;
}) => {
  const dataProvider = useDataProvider();
  const notify = useNotify();
  const translate = useTranslate();
  const [context, setContext] = useState<
    CadenceIssueResolutionContext | "pending"
  >("pending");
  const [busy, setBusy] = useState(false);
  const [note, setNote] = useState("");

  const load = useCallback(async () => {
    if (cadenceIssueId == null) return;
    const result = await loadCadenceIssueResolutionContext(
      dataProvider,
      cadenceIssueId,
    );
    setContext(result);
  }, [dataProvider, cadenceIssueId]);

  useEffect(() => {
    if (cadenceIssueId == null) return;
    setContext("pending");
    setNote("");
    load();
  }, [cadenceIssueId, load]);

  const handleClassify = async (
    classification: ClientSessionCadenceClassification,
  ) => {
    if (cadenceIssueId == null) return;
    setBusy(true);
    try {
      const result = await setCadenceIssueClassification(dataProvider, {
        cadenceIssueId,
        classification,
        note,
      });
      if (result.status === "not-found") {
        notify("resources.enrollments.cadence.not_found", {
          type: "warning",
          _: "This item no longer exists.",
        });
      }
      await load();
      onChange?.();
    } catch {
      notify("ra.notification.http_error", { type: "error" });
    } finally {
      setBusy(false);
    }
  };

  const handleClear = async () => {
    if (cadenceIssueId == null) return;
    setBusy(true);
    try {
      await reopenCadenceIssue(dataProvider, { cadenceIssueId });
      await load();
      onChange?.();
    } catch {
      notify("ra.notification.http_error", { type: "error" });
    } finally {
      setBusy(false);
    }
  };

  return (
    <Dialog open={cadenceIssueId != null} onOpenChange={onOpenChange}>
      {cadenceIssueId != null && (
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>
              {translate("resources.enrollments.cadence.modal_title", {
                _: "What happened this week?",
              })}
            </DialogTitle>
          </DialogHeader>

          {context === "pending" ? null : context.kind === "not-found" ? (
            <p className="text-sm text-muted-foreground">
              {translate("resources.enrollments.cadence.not_found", {
                _: "This item no longer exists.",
              })}
            </p>
          ) : (
            <ResolutionForm
              context={context}
              busy={busy}
              note={note}
              onNoteChange={setNote}
              onClassify={handleClassify}
              onClear={handleClear}
            />
          )}
        </DialogContent>
      )}
    </Dialog>
  );
};

const ResolutionForm = ({
  context,
  busy,
  note,
  onNoteChange,
  onClassify,
  onClear,
}: {
  context: Extract<CadenceIssueResolutionContext, { kind: "found" }>;
  busy: boolean;
  note: string;
  onNoteChange: (note: string) => void;
  onClassify: (classification: ClientSessionCadenceClassification) => void;
  onClear: () => void;
}) => {
  const translate = useTranslate();
  const { slot, issue, noShowSession } = context;
  const weekLabel = formatWindowWeekLabel(slot);
  const isResolved = issue.resolved_at != null && issue.classification != null;

  return (
    <div className="flex flex-col gap-4">
      <p className="text-sm text-muted-foreground">
        {weekLabel} ·{" "}
        {noShowSession
          ? translate("resources.enrollments.cadence.session_marked_no_show", {
              _: "%{date} session marked no-show",
              date: formatMonthDayString(
                noShowSession.scheduled_at.slice(0, 10),
              ),
            })
          : translate("resources.enrollments.cadence.no_session_booked", {
              _: "No session booked",
            })}
      </p>

      {isResolved && issue.classification ? (
        <p className="text-sm font-medium">
          {translate("resources.enrollments.cadence.currently", {
            _: "Currently: %{classification}",
            classification: classificationLabels[issue.classification],
          })}
        </p>
      ) : (
        <Textarea
          placeholder={translate(
            "resources.enrollments.cadence.note_placeholder",
            { _: "Note (optional)" },
          )}
          value={note}
          onChange={(event) => onNoteChange(event.target.value)}
        />
      )}

      <div className="flex flex-col gap-2">
        {ALL_CLASSIFICATIONS.map((classification) => (
          <Button
            key={classification}
            variant={
              issue.classification === classification ? "default" : "outline"
            }
            disabled={busy}
            onClick={() => onClassify(classification)}
          >
            {classificationLabels[classification]}
            {issue.classification === classification ? " ✓" : ""}
          </Button>
        ))}
      </div>

      {isResolved && (
        <div className="border-t pt-3">
          <Button variant="ghost" disabled={busy} onClick={onClear}>
            {translate("resources.enrollments.cadence.clear_decision", {
              _: "Clear decision",
            })}
          </Button>
        </div>
      )}
    </div>
  );
};

import type { DataProvider, Identifier } from "ra-core";

import type { SalesCall } from "../types";

// Mirrors the Postgres trigger sync_deal_sales_call_at() (supabase/schemas/
// 02_functions.sql) — keeps deals.sales_call_at (the existing "next
// scheduled call" denormalized convenience field, read unchanged by
// DealShow/DealInputs) in sync with sales_calls, the new source of truth.
// Recomputes from scratch rather than tracking "was this row the one
// currently reflected": always the scheduled_at of the Opportunity's most
// recent still-booked call, or null if none (e.g. cancelled with no
// rebooking). Called from providers/fakerest/dataProvider.ts's "sales_calls"
// resource hooks, mirroring the trigger's own AFTER INSERT/UPDATE/DELETE
// firing.
export const syncDealSalesCallAt = async (
  dataProvider: DataProvider,
  opportunityId: Identifier,
): Promise<void> => {
  const { data: bookedCalls } = await dataProvider.getList<SalesCall>(
    "sales_calls",
    {
      filter: { opportunity_id: opportunityId, status: "booked" },
      pagination: { page: 1, perPage: 1 },
      sort: { field: "scheduled_at", order: "DESC" },
    },
  );
  const latest = bookedCalls[0]?.scheduled_at ?? null;

  const { data: deal } = await dataProvider.getOne("deals", {
    id: opportunityId,
  });
  if ((deal.sales_call_at ?? null) === latest) return;

  await dataProvider.update("deals", {
    id: opportunityId,
    data: { sales_call_at: latest },
    previousData: deal,
  });
};

import type { SalesCall } from "../types";
import { scheduleDate } from "./salesCallSchedule";

// Which of an Opportunity's sales calls is THE one to show.
//
// The drawer used to take the highest id and call it current. That is the
// most recently CREATED row, which is not the same question, and Mihaela
// Petrova is the proof: her 28 July Mini Deep Dive no-show was recorded
// after her 18 September GYU booking, so the higher id belongs to the
// EARLIER call. Her drawer therefore announced "No-show" as the current
// state of a relationship whose actual latest event was Leif cancelling
// the September call — the opposite of what he needed to see.
//
// The order that answers the real question:
//
//   1. a call that is still BOOKED — there is something in the calendar,
//      and that outranks anything already concluded
//   2. otherwise the call that happened most recently
//
// Ties break on id descending, so two calls on the same day resolve to the
// more recently recorded one rather than arbitrarily.
export type SalesCallOrdering = {
  current: SalesCall | null;
  history: SalesCall[];
};

const scheduleKey = (call: SalesCall): string =>
  scheduleDate(call) ?? "0000-00-00";

const byMostRecentSchedule = (a: SalesCall, b: SalesCall): number => {
  const byDate = scheduleKey(b).localeCompare(scheduleKey(a));
  if (byDate !== 0) return byDate;
  return Number(b.id) - Number(a.id);
};

export const selectCurrentSalesCall = (
  salesCalls: readonly SalesCall[] | undefined,
): SalesCallOrdering => {
  if (!salesCalls?.length) return { current: null, history: [] };

  const ordered = [...salesCalls].sort(byMostRecentSchedule);
  const booked = ordered.filter((call) => call.status === "booked");
  const current = booked[0] ?? ordered[0];

  return {
    current,
    // Everything else, most recent first — the compact record of what
    // already happened with this person.
    history: ordered.filter((call) => String(call.id) !== String(current.id)),
  };
};

// What the drawer should call the current call's state, in the words Leif
// uses. Deliberately reads the call's own columns rather than the
// Opportunity's stage: the stage can lag, and the call is the fact.
export const describeSalesCallState = (call: SalesCall): string => {
  if (call.status === "cancelled") return "Cancelled";
  if (call.attendance === "no_show") return "No-show";
  if (call.attendance === "attended") return "Call happened";
  if (call.status === "booked") return "Booked";
  return "Outcome not recorded";
};

// FakeRest defense-in-depth for the "at most one booked call per
// Opportunity" rule (Acuity/Sales Call Lifecycle slice) — mirrors
// waitlist/waitlistEntryValidation.ts's own documented convention exactly:
// the real DB's partial unique index
// (sales_calls_one_booked_per_opportunity_idx) is defense-in-depth for
// direct SQL/races; FakeRest has no constraint engine at all, so this is
// the only thing that can enforce the rule there. bookSalesCall.ts's own
// find-or-retarget logic is expected to never trigger this in normal use
// (it always reuses/updates an existing booked row rather than creating a
// second one) — this hook exists to fail loudly rather than silently
// corrupt data if that's ever bypassed (a direct dataProvider.create call,
// a bug, a race).
import type { DataProvider, Identifier } from "ra-core";

import type { SalesCall } from "../types";

export class DuplicateBookedSalesCallError extends Error {}

export const assertNoDuplicateBookedSalesCall = async (
  dataProvider: DataProvider,
  {
    opportunityId,
    excludeSalesCallId,
  }: {
    opportunityId: Identifier | null | undefined;
    excludeSalesCallId?: Identifier;
  },
): Promise<void> => {
  if (opportunityId == null) return;

  const { data: existing } = await dataProvider.getList<SalesCall>(
    "sales_calls",
    {
      filter: { opportunity_id: opportunityId, status: "booked" },
      pagination: { page: 1, perPage: 10 },
      sort: { field: "id", order: "ASC" },
    },
  );
  const conflict = existing.find(
    (call) =>
      excludeSalesCallId == null ||
      String(call.id) !== String(excludeSalesCallId),
  );
  if (conflict) {
    throw new DuplicateBookedSalesCallError(
      `Opportunity ${opportunityId} already has a booked Sales Call (#${conflict.id})`,
    );
  }
};

import type { SalesCall } from "../types";

// Two different operational problems, two different task types.
//
// Production acceptance found one type doing both jobs: a task reading
// "SALES CALL NEEDS MATCHING — Megan Auron · call of Jul 7, 2026 — what
// happened?" opened a matching page that answered "This booking is already
// attached to an Opportunity." Both halves were right about their own
// concern and the pair was a contradiction, because Megan's call does not
// need matching at all — what is unknown is what HAPPENED on it.
//
//   sales_call_needs_matching — this booking is not attached to any
//     Opportunity. The open question is WHICH sales relationship it
//     belongs to, and the answer is given on the matching page.
//
//   resolve_sales_call — this booking is attached to the right
//     Opportunity already. The open question is ATTENDANCE/OUTCOME, and
//     the answer is one of the three canonical actions (call happened /
//     no-show / cancelled).
//
// Naming follows what each task asks for, so the Dashboard label and the
// screen it opens can never disagree again.
export const SALES_CALL_NEEDS_MATCHING_TASK_TYPE = "sales_call_needs_matching";
export const RESOLVE_SALES_CALL_TASK_TYPE = "resolve_sales_call";

export type SalesCallAmbiguity =
  // Not attached to an Opportunity, not dismissed: genuinely needs matching.
  | "needs-matching"
  // Attached, but nobody ever recorded what happened on a call whose time
  // has passed.
  | "needs-outcome"
  // Nothing outstanding: dismissed, cancelled, attendance already recorded,
  // or simply a call that has not happened yet.
  | "none";

// The single source of truth for "what, if anything, is still unknown
// about this booking".
//
// Deliberately state-derived rather than task-derived: it is what the
// resolution page branches on, so a stale task can never make the page
// show the wrong question, and a task deleted by hand cannot hide a real
// gap. It reads only columns sales_calls actually has.
//
// Note on scope: "needs-outcome" describes a call, NOT a promise that a
// task exists for it. 109 attached historical calls in production have
// attendance = null because the import recorded their result as pipeline
// stage rather than as attendance; they are not open questions and must
// never be turned into 109 dashboard alerts. Ambiguity tasks stay
// deliberately created by the flow that noticed the ambiguity.
export const classifySalesCallAmbiguity = (
  salesCall: Pick<
    SalesCall,
    | "opportunity_id"
    | "dismissed_at"
    | "attendance"
    | "status"
    | "scheduled_at"
    | "scheduled_on"
  >,
  now: Date = new Date(),
): SalesCallAmbiguity => {
  if (salesCall.dismissed_at != null) return "none";
  if (salesCall.opportunity_id == null) return "needs-matching";
  // A cancelled call has a known, terminal answer already — "cancelled" is
  // what happened to it.
  if (salesCall.status === "cancelled") return "none";
  if (salesCall.attendance != null) return "none";
  // A call still in the future has no outcome to record yet. Asking "what
  // happened?" about a call that has not happened is the same class of
  // falsehood this module exists to remove.
  return hasHappenedBy(salesCall, now) ? "needs-outcome" : "none";
};

const hasHappenedBy = (
  salesCall: Pick<SalesCall, "scheduled_at" | "scheduled_on">,
  now: Date,
): boolean => {
  if (salesCall.scheduled_at) {
    return new Date(salesCall.scheduled_at).getTime() <= now.getTime();
  }
  if (!salesCall.scheduled_on) return false;
  // A date-only call counts as past once the DAY is over, never earlier —
  // its clock time is genuinely unknown, so the end of the day is the only
  // moment the whole day is certainly behind us.
  return salesCall.scheduled_on < toDateKey(now);
};

const toDateKey = (value: Date): string =>
  `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, "0")}-${String(
    value.getDate(),
  ).padStart(2, "0")}`;

import type { DataProvider, Identifier } from "ra-core";

import type { Task } from "../types";

const SALES_CALL_TASK_TYPE = "sales_call";

// Mirrors applications/reviewApplicationTask.ts's own find/ensure/complete
// shape exactly (Task's only link to a Contact is contact_id — no
// sales_call_id FK on Task, same documented limitation as that module).
export const findPendingSalesCallTask = async (
  dataProvider: DataProvider,
  contactId: Identifier,
): Promise<Task | null> => {
  const { data } = await dataProvider.getList<Task>("tasks", {
    filter: { contact_id: contactId, type: SALES_CALL_TASK_TYPE },
    pagination: { page: 1, perPage: 50 },
    sort: { field: "id", order: "ASC" },
  });
  return data.find((task) => !task.done_date) ?? null;
};

// Creates (or, on a reschedule, retargets) the "Sales Call" task for a
// newly booked call — never a duplicate for the same pending call.
export const ensureSalesCallTask = async (
  dataProvider: DataProvider,
  {
    contactId,
    contactName,
    scheduledAt,
    salesId,
  }: {
    contactId: Identifier;
    contactName: string;
    scheduledAt: string;
    salesId?: Identifier | null;
  },
): Promise<void> => {
  const existing = await findPendingSalesCallTask(dataProvider, contactId);
  if (existing) {
    if (existing.due_date === scheduledAt) return;
    await dataProvider.update("tasks", {
      id: existing.id,
      data: { due_date: scheduledAt },
      previousData: existing,
    });
    return;
  }

  await dataProvider.create("tasks", {
    data: {
      contact_id: contactId,
      type: SALES_CALL_TASK_TYPE,
      text: `Sales call with ${contactName}`,
      due_date: scheduledAt,
      status: "pending",
      ...(salesId != null ? { sales_id: salesId } : {}),
    },
  });
};

// A reschedule keeps the same task, just retargeted to the new time — never
// a second "Sales Call" task for the same still-pending call.
export const updateSalesCallTaskDueDate = async (
  dataProvider: DataProvider,
  contactId: Identifier,
  scheduledAt: string,
): Promise<void> => {
  const task = await findPendingSalesCallTask(dataProvider, contactId);
  if (!task || task.due_date === scheduledAt) return;
  await dataProvider.update("tasks", {
    id: task.id,
    data: { due_date: scheduledAt },
    previousData: task,
  });
};

// A cancelled call has no more pending action attached to it — cancel
// (never delete) the task, mirroring the Task infrastructure's own
// "waiting"/"cancelled" states (tasks are reminders, not sales-status
// controls, so this only ever touches the Task, never the Opportunity).
export const cancelSalesCallTask = async (
  dataProvider: DataProvider,
  contactId: Identifier,
): Promise<void> => {
  const task = await findPendingSalesCallTask(dataProvider, contactId);
  if (!task) return;
  await dataProvider.update("tasks", {
    id: task.id,
    data: { status: "cancelled" },
    previousData: task,
  });
};

// The call happened (attended or no-show) — its "have the call" task is
// done either way. Completing it here is what marks it done, never the
// reverse: checking the task off manually must never change sales status
// (see sales-calls/completeSalesCallOutcome.ts, which is the only caller).
export const completeSalesCallTask = async (
  dataProvider: DataProvider,
  contactId: Identifier,
  completedAt: string,
): Promise<void> => {
  const task = await findPendingSalesCallTask(dataProvider, contactId);
  if (!task) return;
  await dataProvider.update("tasks", {
    id: task.id,
    data: { done_date: completedAt, status: "completed" },
    previousData: task,
  });
};

import { formatTimestampWithTimeString } from "../deals/dealUtils";
import type { SalesCall } from "../types";

// How to READ a Sales Call's schedule, whatever its precision.
//
// A historical call can be known to have happened on a particular day with
// no record anywhere of the clock time — no Acuity appointment, no calendar
// event, nothing. Those rows carry the date and NULL timestamps, because
// putting midnight or noon in the column would state a time the source
// never contained, and a reader cannot tell an invented time from a real
// one. So the precision is explicit and these helpers honour it.

type ScheduleLike = Pick<
  SalesCall,
  | "scheduled_on"
  | "schedule_precision"
  | "scheduled_at"
  | "original_scheduled_at"
>;

// Every row that predates the precision column is a real appointment.
export const isDateOnly = (call: ScheduleLike): boolean =>
  (call.schedule_precision ?? "exact") === "date_only";

// The date, for ordering and for grouping. Present for every call.
export const scheduleDate = (call: ScheduleLike): string | null =>
  call.scheduled_on ??
  (call.scheduled_at ? call.scheduled_at.slice(0, 10) : null);

// Human-readable, and deliberately WITHOUT a time when none is known —
// never "12:00 AM", which is the placeholder this whole model exists to
// avoid.
export const formatSalesCallSchedule = (call: ScheduleLike): string => {
  if (!isDateOnly(call) && call.scheduled_at) {
    return formatTimestampWithTimeString(call.scheduled_at);
  }
  const date = scheduleDate(call);
  if (!date) return "Date not recorded";
  // Parsed as UTC noon so a date-only value cannot slide a day in a
  // west-of-UTC timezone.
  return new Date(`${date}T12:00:00Z`).toLocaleDateString(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
};

// For the places that want to say so out loud.
export const formatSalesCallScheduleWithPrecision = (
  call: ScheduleLike,
): string =>
  isDateOnly(call)
    ? `${formatSalesCallSchedule(call)} · time unknown`
    : formatSalesCallSchedule(call);

