// Surfaces a booking that couldn't be safely matched to exactly one active
// Opportunity (Acuity/Sales Call Lifecycle slice, Decision 3: "must not
// become an invisible database record"). Resolved on the dedicated
// matching page (/sales-calls/:id/resolve), never the generic Task editor.
//
// This task is valid for exactly as long as sales_call.opportunity_id is
// NULL. The moment an Opportunity is attached — by the resolution page, by
// Acuity reconciliation, by a SQL backfill, by anything — the question is
// answered and the task must go. The app paths below call
// completeSalesCallNeedsMatchingTask directly; a database trigger
// (migration 20260918030000) is what makes that true for the paths that
// never run app code, which is how five of these went stale in production.
//
// Deterministic by sales_call_id when known (a returning Contact can have
// more than one unmatched booking at once — contact_id alone can't tell
// them apart). Falls back to the old contact_id+type search only for a
// legacy Task created before tasks.sales_call_id existed (migration
// 20260904240000 backfills every real one that was unambiguous at the
// time; this fallback is what still finds one that wasn't).
export const findPendingSalesCallNeedsMatchingTask = async (
  dataProvider: DataProvider,
  contactId: Identifier,
  salesCallId?: Identifier,
): Promise<Task | null> => {
  const { data } = await dataProvider.getList<Task>("tasks", {
    filter: {
      contact_id: contactId,
      type: SALES_CALL_NEEDS_MATCHING_TASK_TYPE,
    },
    pagination: { page: 1, perPage: 50 },
    sort: { field: "id", order: "ASC" },
  });
  const pending = data.filter((task) => !task.done_date);
  if (salesCallId != null) {
    const forThisCall = pending.find(
      (task) => String(task.sales_call_id) === String(salesCallId),
    );
    if (forThisCall) return forThisCall;
  }
  return pending.find((task) => task.sales_call_id == null) ?? null;
};

// The Task's own text is what the Dashboard/Contact page actually show
// (Task.tsx treats this type as self-describing) — "%{name} · %{offer} ·
// %{when}" so a returning Contact's several unmatched bookings read as
// genuinely distinct rows, never identical ones needing a click to tell
// apart.
export const ensureSalesCallNeedsMatchingTask = async (
  dataProvider: DataProvider,
  {
    contactId,
    contactName,
    salesCallId,
    scheduledAt,
    offerName,
    cohortName,
    salesId,
  }: {
    contactId: Identifier;
    contactName: string;
    salesCallId: Identifier;
    scheduledAt: string;
    offerName: string;
    cohortName?: string | null;
    salesId?: Identifier | null;
  },
): Promise<void> => {
  const existing = await findPendingSalesCallNeedsMatchingTask(
    dataProvider,
    contactId,
    salesCallId,
  );
  if (existing) return;

  const offerLabel = cohortName ? `${offerName} — ${cohortName}` : offerName;
  await dataProvider.create("tasks", {
    data: {
      contact_id: contactId,
      type: SALES_CALL_NEEDS_MATCHING_TASK_TYPE,
      text: `${contactName} · ${offerLabel} · ${formatTimestampWithTimeString(scheduledAt)}`,
      due_date: new Date().toISOString(),
      status: "pending",
      sales_call_id: salesCallId,
      ...(salesId != null ? { sales_id: salesId } : {}),
    },
  });
};

export const completeSalesCallNeedsMatchingTask = async (
  dataProvider: DataProvider,
  contactId: Identifier,
  completedAt: string,
