import type { DataProvider, Identifier } from "ra-core";

import type { SalesCall } from "../types";
import { updateSalesCallTaskDueDate } from "./salesCallTask";

export type RescheduleSalesCallResult =
  | { status: "rescheduled"; salesCall: SalesCall }
  | { status: "not-found" }
  // Same new time already recorded — a duplicate reschedule webhook is a
  // safe no-op, never a second event.
  | { status: "already-current"; salesCall: SalesCall }
  | { status: "cancelled-call" };

// A reschedule updates the SAME sales_calls row — it must never look like
// two independent calls in later conversion analytics (Leif's own
// requirement). original_scheduled_at never changes; scheduled_at moves,
// reschedule_count increments, and the fact is preserved individually in
// sales_call_events (not just the running count) per Leif's Decision 1
// addition.
export const rescheduleSalesCall = async (
  dataProvider: DataProvider,
  {
    salesCallId,
    newScheduledAt,
  }: { salesCallId: Identifier; newScheduledAt: string },
): Promise<RescheduleSalesCallResult> => {
  const { data: salesCall } = await dataProvider
    .getOne<SalesCall>("sales_calls", { id: salesCallId })
    .catch(() => ({ data: null as SalesCall | null }));
  if (!salesCall) return { status: "not-found" };
  if (salesCall.status === "cancelled") return { status: "cancelled-call" };
  if (salesCall.scheduled_at === newScheduledAt) {
    return { status: "already-current", salesCall };
  }

  const now = new Date().toISOString();
  const previousScheduledAt = salesCall.scheduled_at;
  const { data: updated } = await dataProvider.update<SalesCall>(
    "sales_calls",
    {
      id: salesCallId,
      data: {
        scheduled_at: newScheduledAt,
        reschedule_count: salesCall.reschedule_count + 1,
        last_rescheduled_at: now,
      },
      previousData: salesCall,
    },
  );

  await dataProvider.create("sales_call_events", {
    data: {
      sales_call_id: salesCallId,
      kind: "rescheduled",
      occurred_at: now,
      previous_scheduled_at: previousScheduledAt,
      new_scheduled_at: newScheduledAt,
    },
  });

  // Never touches Opportunity stage — a reschedule is the same call moving
  // in time, not a pipeline event. Only the Sales Call Task's due date
  // (when the Opportunity was matched and a task exists) moves with it.
  await updateSalesCallTaskDueDate(
    dataProvider,
    salesCall.contact_id,
    newScheduledAt,
  );

  return { status: "rescheduled", salesCall: updated };
};

import type { DataProvider, Identifier } from "ra-core";

import type { Contact, Deal, SalesCall, Tag, Task } from "../types";
import { completeResolveSalesCallTask } from "./resolveSalesCallTask";

// Gate B — the dev/FakeRest half of the dual-implementation No-show path.
// The production path is the Postgres function
// record_sales_call_no_show() (supabase/schemas/02_functions.sql), which
// applies all of this in ONE transaction. This module is the
// FakeRest-testable "logic of record" the function mirrors — the same
// dual-implementation pattern already used for public application intake
// (submit_public_application() <-> submitApplication.ts) and waitlist sync
// (deal_waitlist_sync trigger <-> waitlistSync.ts).
//
// The rule: marking a sales call No-show is certain enough to exit the
// Opportunity. Concretely —
//   Sales Call  canonical history: attendance 'no_show', status 'completed'
//   Opportunity leaves the ACTIVE pipeline via outcome 'lost'
//   Contact     carries a durable, visible "No-show" tag
//   Tasks       no new follow-up work is created
// Nothing is deleted, no stage is rewritten, and no new pipeline stage or
// outcome value is invented.

export const NO_SHOW_TAG_NAME = "No-show";
// Same palette the manual tag UI uses (tags/colors.ts).
const NO_SHOW_TAG_COLOR = "#fde2e4";

export type RecordSalesCallNoShowResult =
  | { status: "completed" }
  // Re-running the action on an already-no-showed call. Safe and
  // convergent: it re-asserts the exit and the tag rather than duplicating
  // anything.
  | { status: "already-no-show" }
  | { status: "not-found" }
  | { status: "no-opportunity" }
  // An attended outcome is already recorded; never silently overwritten.
  | { status: "already-completed" };

// The Supabase provider exposes the real transactional path; FakeRest and
// unit tests fall through to the mirror below.
type NoShowCapableProvider = DataProvider & {
  recordSalesCallNoShow?: (
    salesCallId: Identifier,
  ) => Promise<{ status: string }>;
};

export const recordSalesCallNoShow = async (
  dataProvider: DataProvider,
  salesCallId: Identifier,
): Promise<RecordSalesCallNoShowResult> => {
  const rpc = (dataProvider as NoShowCapableProvider).recordSalesCallNoShow;
  if (typeof rpc === "function") {
    const result = await rpc(salesCallId);
    return { status: result.status } as RecordSalesCallNoShowResult;
  }

  const { data: salesCall } = await dataProvider
    .getOne<SalesCall>("sales_calls", { id: salesCallId })
    .catch(() => ({ data: null as SalesCall | null }));
  if (!salesCall) return { status: "not-found" };
  if (salesCall.opportunity_id == null) return { status: "no-opportunity" };
  if (salesCall.attendance === "attended") {
    return { status: "already-completed" };
  }

  const alreadyNoShow = salesCall.attendance === "no_show";
  const now = new Date().toISOString();

  // 1. Sales Call — the canonical historical record. status leaves
  //    'booked' so a later genuine rebooking is not blocked by the partial
  //    unique index on (opportunity_id) WHERE status = 'booked'.
  if (!alreadyNoShow) {
    await dataProvider.update<SalesCall>("sales_calls", {
      id: salesCall.id,
      data: {
        attendance: "no_show",
        attendance_recorded_at: now,
        status: "completed",
      },
      previousData: salesCall,
    });
    await dataProvider.create("sales_call_events", {
      data: {
        sales_call_id: salesCall.id,
        kind: "attendance_recorded",
        occurred_at: now,
        attendance: "no_show",
      },
    });
  } else if (salesCall.status !== "completed") {
    // Already recorded as a no-show but never concluded: a row written
    // before a concluded call was required to leave 'booked'. Converge the
    // status WITHOUT inventing a second attendance timestamp or a
    // duplicate history event — the original attendance_recorded_at is the
    // truth about when it was observed. Leaving it at 'booked' would keep
    // blocking a genuine rebooking via the partial unique index.
    await dataProvider.update<SalesCall>("sales_calls", {
      id: salesCall.id,
      data: { status: "completed" },
      previousData: salesCall,
    });
  }

  // 2. The Opportunity exits the ACTIVE pipeline. "Active" is canonically
  //    archived_at null AND stage !== 'won' AND outcome null (DealList's
  //    own filter), so setting outcome is the existing exit mechanism.
  //    'lost' is the same exit the Do-Not-Engage path uses; the no-show
  //    REASON stays durable on the Sales Call, so no reason column is
  //    invented. stage is deliberately left alone — the Deal really did
  //    reach Call Booked, and rewriting that to mark an exit would falsify
  //    history.
  const { data: deal } = await dataProvider.getOne<Deal>("deals", {
    id: salesCall.opportunity_id,
  });
  if (
    deal.outcome == null &&
    deal.archived_at == null &&
    deal.stage !== "won"
  ) {
    await dataProvider.update<Deal>("deals", {
      id: deal.id,
      data: { outcome: "lost" },
      previousData: deal,
    });
  }

  // 3. Contact-level visible history, reusing the existing tag model.
  await ensureNoShowTag(dataProvider, salesCall.contact_id);

  // 4. The call concluded, so its own task is done. No follow-up task is
  //    created: the Opportunity has left the pipeline, so there is no
  //    stranded decision to re-surface. A 'sales_call_no_show' task left
  //    pending by the previous behavior is superseded work, closed here
  //    rather than left behind as impossible work.
  await completePendingTasks(dataProvider, salesCall.contact_id, now);
  // "No-show" is one of the three canonical answers to "what happened on
  // this call?", so a resolve_sales_call ambiguity task for THIS call is
  // answered by it. Scoped by sales_call_id rather than swept up by
  // contact above, because a returning Contact can have an open question
  // about a different call that this one does not answer.
  await completeResolveSalesCallTask(
    dataProvider,
    salesCall.contact_id,
    now,
    salesCall.id,
  );

  return { status: alreadyNoShow ? "already-no-show" : "completed" };
};

// Attaches the No-show tag exactly once, creating the tag itself only if
// the workspace does not already have one. Matched case-insensitively so a
// manually-created "No-Show" is reused rather than duplicated.
const ensureNoShowTag = async (
  dataProvider: DataProvider,
  contactId: Identifier,
): Promise<void> => {
  const { data: tags } = await dataProvider.getList<Tag>("tags", {
    filter: {},
    pagination: { page: 1, perPage: 500 },
    sort: { field: "id", order: "ASC" },
  });
  let tag =
    tags.find(
      (t) => t.name?.toLowerCase() === NO_SHOW_TAG_NAME.toLowerCase(),
    ) ?? null;
  if (!tag) {
    const { data: created } = await dataProvider.create<Tag>("tags", {
      data: {
        name: NO_SHOW_TAG_NAME,
        color: NO_SHOW_TAG_COLOR,
      } as Partial<Tag>,
    });
    tag = created;
  }

  const { data: contact } = await dataProvider.getOne<Contact>("contacts", {
    id: contactId,
  });
  const current = contact.tags ?? [];
  if (current.some((id) => String(id) === String(tag!.id))) return;
  await dataProvider.update<Contact>("contacts", {
    id: contact.id,
    data: { tags: [...current, tag.id] },
    previousData: contact,
  });
};

const completePendingTasks = async (
  dataProvider: DataProvider,
  contactId: Identifier,
  completedAt: string,
): Promise<void> => {
  const { data: tasks } = await dataProvider.getList<Task>("tasks", {
    filter: { contact_id: contactId },
    pagination: { page: 1, perPage: 100 },
    sort: { field: "id", order: "ASC" },
  });
  const superseded = tasks.filter(
    (task) =>
      !task.done_date &&
      (task.type === "sales_call" || task.type === "sales_call_no_show"),
  );
  for (const task of superseded) {
    await dataProvider.update<Task>("tasks", {
      id: task.id,
      data: { done_date: completedAt, status: "completed" },
      previousData: task,
    });
  }
};

import type { DataProvider } from "ra-core";

import type { Cohort, Offer } from "../types";

export type AcuityAppointmentTypeMapping =
  | { kind: "individual"; offer: Offer }
  // cohort is null when the mapping is durable at the Offer level — one
  // canonical appointment type shared by every Cohort of that group Offer
  // (see the resolver's own comment below for when this applies vs a
  // Cohort-specific mapping).
  | { kind: "group"; offer: Offer; cohort: Cohort | null };

// Durable mapping from an Acuity appointment type to the correct CRM
// Offer/Cohort context, via the stable acuity_appointment_type_id column
// already anticipated on both tables (never a display-name match — Acuity
// only ever sends the type's numeric id in a webhook/appointment payload,
// never its label). A partial unique index on each column (supabase/
// schemas/01_tables.sql) guarantees at most one Offer/Cohort ever claims a
// given appointment type.
//
// GYU real-infrastructure slice, sealing pass: a group Offer CAN carry its
// own acuity_appointment_type_id — this is the correct, durable home for
// one canonical appointment type meant to serve every Cohort of that Offer
// (GYU's real "Let's Meet", 64654501, is exactly this: one appointment
// type for all GYU rounds, not one per Cohort). Matching on the Offer here
// still correctly returns kind "group" (not "individual" — a group Offer
// stays a group Offer regardless of which level its mapping lives at) with
// cohort: null, since the appointment type alone doesn't identify which
// specific Cohort — matchAcuityBooking.ts already handles a null cohort
// correctly (matches by Contact+Offer only, relying on the matched Deal's
// own already-set cohort_id, fixed durably at application time and never
// re-derived from Acuity). A Cohort-level mapping remains available for
// the case a specific round genuinely needs its own separate appointment
// type/calendar (see cohorts.acuity_appointment_type_id's own comment) —
// checked second, so a Cohort-specific mapping always takes precedence
// over a shared Offer-level one for the same appointment type (though the
// partial unique indexes already prevent the same id being claimed twice).
export const resolveOfferCohortForAppointmentType = async (
  dataProvider: DataProvider,
  acuityAppointmentTypeId: string,
): Promise<AcuityAppointmentTypeMapping | null> => {
  const { data: offers } = await dataProvider.getList<Offer>("offers", {
    filter: { acuity_appointment_type_id: acuityAppointmentTypeId },
    pagination: { page: 1, perPage: 1 },
    sort: { field: "id", order: "ASC" },
  });
  if (offers[0]) {
    return offers[0].type === "group"
      ? { kind: "group", offer: offers[0], cohort: null }
      : { kind: "individual", offer: offers[0] };
  }

  const { data: cohorts } = await dataProvider.getList<Cohort>("cohorts", {
    filter: { acuity_appointment_type_id: acuityAppointmentTypeId },
    pagination: { page: 1, perPage: 1 },
    sort: { field: "id", order: "ASC" },
  });
  if (!cohorts[0]) return null;

  const { data: offer } = await dataProvider.getOne<Offer>("offers", {
    id: cohorts[0].offer_id,
  });
  return { kind: "group", offer, cohort: cohorts[0] };
};

import type { DataProvider, Identifier } from "ra-core";

import type { Cohort, Contact, Deal, Offer } from "../types";
import { normalizeEmail } from "../public-application/submitApplication";
import { resolveOfferCohortForAppointmentType } from "./offerCohortAcuityMapping";

// Same active-pipeline definition used throughout this app (waitlist/
// waitlistActions.ts, public-application/submitApplication.ts) — duplicated
// per those modules' own documented convention rather than imported from a
// private helper.
const isActiveDeal = (deal: Pick<Deal, "stage" | "outcome" | "archived_at">) =>
  deal.archived_at == null && deal.stage !== "won" && deal.outcome == null;

// Normalized-email match-or-create, the exact matching principle Native
// Application Intake established (§5 there) — no name-only fallback.
// Existing Contact data is never overwritten, only last_seen touched.
const findOrCreateContact = async (
  dataProvider: DataProvider,
  {
    firstName,
    lastName,
    email,
  }: {
    firstName: string;
    lastName: string;
    email: string;
  },
): Promise<Contact> => {
  const normalized = normalizeEmail(email);
  const { data: contacts } = await dataProvider.getList<Contact>("contacts", {
    filter: {},
    pagination: { page: 1, perPage: 1000 },
    sort: { field: "id", order: "ASC" },
  });
  const existing = contacts.find((contact) =>
    (contact.email_jsonb ?? []).some(
      (entry) => entry.email && normalizeEmail(entry.email) === normalized,
    ),
  );
  if (existing) {
    await dataProvider.update("contacts", {
      id: existing.id,
      data: { last_seen: new Date().toISOString() },
      previousData: existing,
    });
    return existing;
  }

  const { data: created } = await dataProvider.create<Contact>("contacts", {
    data: {
      first_name: firstName,
      last_name: lastName,
      email_jsonb: [{ email: normalized, type: "Other" }],
      phone_jsonb: [],
      tags: [],
      has_newsletter: false,
      first_seen: new Date().toISOString(),
      last_seen: new Date().toISOString(),
      sales_eligibility: "normal",
    },
  });
  return created;
};

export type OpportunityMatchResult =
  | { kind: "matched"; opportunity: Deal }
  | { kind: "none" }
  | { kind: "ambiguous" };

// The Contact's own active Opportunities compatible with a given Offer/
// Cohort mapping — "compatible" mirrors the exact appointment-type mapping
// rule (never attach across Offers merely because it's the same Contact).
// Unmatched Sales Call Resolution slice: also the candidate list the
// resolution UI's "Attach to Existing Opportunity" picker shows, so an
// incompatible Opportunity (e.g. a GYU one for an LE booking) is
// structurally impossible to select — it's just never in the list.
export const findCompatibleActiveOpportunities = async (
  dataProvider: DataProvider,
  {
    contactId,
    offerId,
    cohortId,
  }: {
    contactId: Identifier;
    offerId: Identifier;
    cohortId: Identifier | null;
  },
): Promise<Deal[]> => {
  const { data: deals } = await dataProvider.getList<Deal>("deals", {
    filter: {
      contact_id: contactId,
      offer_id: offerId,
      ...(cohortId != null ? { cohort_id: cohortId } : {}),
    },
    pagination: { page: 1, perPage: 100 },
    sort: { field: "id", order: "ASC" },
  });
  return deals.filter(isActiveDeal);
};

// "Find the appropriate active Opportunity for the booked offer/cohort" —
// never guessed. Zero matches or more than one both come back as
// unresolved rather than picking one; the caller preserves the booking
// with opportunity_id = null (Decision 3) instead of silently attaching it
// to an ambiguous Opportunity.
export const findActiveOpportunityMatch = async (
  dataProvider: DataProvider,
  args: {
    contactId: Identifier;
    offerId: Identifier;
    cohortId: Identifier | null;
  },
): Promise<OpportunityMatchResult> => {
  const active = await findCompatibleActiveOpportunities(dataProvider, args);
  if (active.length === 0) return { kind: "none" };
  if (active.length > 1) return { kind: "ambiguous" };
  return { kind: "matched", opportunity: active[0] };
};

export type MatchAcuityBookingResult =
  | {
      status: "matched";
      contact: Contact;
      opportunity: Deal;
      offer: Offer;
      cohort: Cohort | null;
    }
  | {
      status: "unmatched-opportunity";
      contact: Contact;
      offer: Offer;
      cohort: Cohort | null;
      reason: "none" | "ambiguous";
    }
  // Do not fabricate a match: an Acuity appointment type nobody has mapped
  // to an Offer/Cohort yet is a configuration gap, not a Contact/booking
  // problem — no Contact is even looked up, so nothing is created.
  | { status: "unknown-appointment-type" };

// Identity + intended-sales-process resolution for one incoming Acuity
// booking (Acuity/Sales Call Lifecycle slice). Contact resolution always
// succeeds (find-or-create); Opportunity resolution can come back
// unresolved — see findActiveOpportunityMatch above.
export const matchAcuityBooking = async (
  dataProvider: DataProvider,
  {
    email,
    firstName,
    lastName,
    acuityAppointmentTypeId,
  }: {
    email: string;
    firstName: string;
    lastName: string;
    acuityAppointmentTypeId: string;
  },
): Promise<MatchAcuityBookingResult> => {
  const mapping = await resolveOfferCohortForAppointmentType(
    dataProvider,
    acuityAppointmentTypeId,
  );
  if (!mapping) return { status: "unknown-appointment-type" };

  const contact = await findOrCreateContact(dataProvider, {
    firstName,
    lastName,
    email,
  });
  const cohort = mapping.kind === "group" ? mapping.cohort : null;

  const match = await findActiveOpportunityMatch(dataProvider, {
    contactId: contact.id,
    offerId: mapping.offer.id,
    cohortId: cohort?.id ?? null,
  });

  if (match.kind === "matched") {
    return {
      status: "matched",
      contact,
      opportunity: match.opportunity,
      offer: mapping.offer,
      cohort,
    };
  }
  return {
    status: "unmatched-opportunity",
    contact,
    offer: mapping.offer,
    cohort,
    reason: match.kind === "ambiguous" ? "ambiguous" : "none",
  };
};

import type { DataProvider, Identifier } from "ra-core";

import type { Contact, Deal, Offer, Cohort, SalesCall } from "../types";
import { findCompatibleActiveOpportunities } from "./matchAcuityBooking";
import { resolveOfferCohortForAppointmentType } from "./offerCohortAcuityMapping";

// Unmatched Sales Call Resolution slice: everything the dedicated
// resolution page (/sales-calls/:id/resolve) needs to render and act,
// loaded imperatively (not via useGetOne/useQuery) so it can be re-run
// after an action completes — same "async context + manual refetch"
// pattern OfferPage.tsx already established, not React Query's automatic
// invalidation, since this page's whole lifecycle is short (load once,
// act once, done).
export type SalesCallResolutionContext =
  | { kind: "not-found" }
  | {
      kind: "already-resolved";
      contact: Contact;
      salesCall: SalesCall;
      opportunity: Deal | null;
    }
  // The appointment type itself has no Offer/Cohort mapping at all yet —
  // a configuration gap (see matchAcuityBooking.ts's own comment), not a
  // Contact/booking problem. Only Dismiss is offered — there's nothing
  // authoritative to create or attach against.
  | { kind: "unknown-appointment-type"; contact: Contact; salesCall: SalesCall }
  | {
      kind: "resolvable";
      contact: Contact;
      salesCall: SalesCall;
      offer: Offer;
      cohort: Cohort | null;
      compatibleOpportunities: Deal[];
    };

export const loadSalesCallResolutionContext = async (
  dataProvider: DataProvider,
  salesCallId: Identifier,
): Promise<SalesCallResolutionContext> => {
  const salesCall = await dataProvider
    .getOne<SalesCall>("sales_calls", { id: salesCallId })
    .then(({ data }) => data)
    .catch(() => null);
  if (!salesCall) return { kind: "not-found" };

  const contact = await dataProvider
    .getOne<Contact>("contacts", { id: salesCall.contact_id })
    .then(({ data }) => data)
    .catch(() => null);
  if (!contact) return { kind: "not-found" };

  if (salesCall.opportunity_id != null || salesCall.dismissed_at != null) {
    const opportunity =
      salesCall.opportunity_id != null
        ? await dataProvider
            .getOne<Deal>("deals", { id: salesCall.opportunity_id })
            .then(({ data }) => data)
            .catch(() => null)
        : null;
    return { kind: "already-resolved", contact, salesCall, opportunity };
  }

  if (!salesCall.acuity_appointment_type_id) {
    return { kind: "unknown-appointment-type", contact, salesCall };
  }
  const mapping = await resolveOfferCohortForAppointmentType(
    dataProvider,
    salesCall.acuity_appointment_type_id,
  );
  if (!mapping) {
    return { kind: "unknown-appointment-type", contact, salesCall };
  }
  const cohort = mapping.kind === "group" ? mapping.cohort : null;

  const compatibleOpportunities = await findCompatibleActiveOpportunities(
    dataProvider,
    {
      contactId: contact.id,
      offerId: mapping.offer.id,
      cohortId: cohort?.id ?? null,
    },
  );

  return {
    kind: "resolvable",
    contact,
    salesCall,
    offer: mapping.offer,
    cohort,
    compatibleOpportunities,
  };
};

import type { DataProvider, Identifier } from "ra-core";

import { dateOnlyToTimestamp } from "../misc/dateOnlyToTimestamp";
import type { Task } from "../types";

const FOLLOW_UP_TASK_TYPE = "follow_up";

// deals.follow_up_date is a bare "YYYY-MM-DD" (a calendar date, not a
// moment in time — see supabase/schemas/01_tables.sql's own comment on
// this column), but tasks.due_date is a real timestamptz and Task.tsx
// always renders it via dealUtils.ts's formatTimestampString, which
// (correctly, per its own header) assumes its input already carries a
// time component. See misc/dateOnlyToTimestamp.ts for why this needs a
// conversion at all, and for the small polish/cleanup slice that also
// reuses it for Task.tsx's postpone-tomorrow/postpone-next-week actions.

// Mirrors applications/reviewApplicationTask.ts's find/ensure/complete
// shape. Created when a completed sales call's prospect decision is
// "Thinking" (sales-calls/completeSalesCallOutcome.ts) — completing or
// cancelling this task never changes deals.prospect_decision/
// follow_up_date itself (Tasks tell the user what to do; sales status
// tells the CRM what happened).
export const findPendingFollowUpTask = async (
  dataProvider: DataProvider,
  contactId: Identifier,
): Promise<Task | null> => {
  const { data } = await dataProvider.getList<Task>("tasks", {
    filter: { contact_id: contactId, type: FOLLOW_UP_TASK_TYPE },
    pagination: { page: 1, perPage: 50 },
    sort: { field: "id", order: "ASC" },
  });
  return data.find((task) => !task.done_date) ?? null;
};

// One pending Follow-up task at a time per Contact — a later completed
// call that's Thinking again retargets the existing task rather than
// stacking a second one.
export const ensureFollowUpTask = async (
  dataProvider: DataProvider,
  {
    contactId,
    contactName,
    followUpDate,
    salesId,
  }: {
    contactId: Identifier;
    contactName: string;
    followUpDate: string;
    salesId?: Identifier | null;
  },
): Promise<void> => {
  const dueDate = dateOnlyToTimestamp(followUpDate);
  const existing = await findPendingFollowUpTask(dataProvider, contactId);
  if (existing) {
    if (existing.due_date === dueDate) return;
    await dataProvider.update("tasks", {
      id: existing.id,
      data: { due_date: dueDate },
      previousData: existing,
    });
    return;
  }

  await dataProvider.create("tasks", {
    data: {
      contact_id: contactId,
      type: FOLLOW_UP_TASK_TYPE,
      text: `Follow up with ${contactName}`,
      due_date: dueDate,
      status: "pending",
      ...(salesId != null ? { sales_id: salesId } : {}),
    },
  });
};

import { addDays } from "date-fns/addDays";
import type { DataProvider, Identifier } from "ra-core";

import {
  applyDoNotEngageToContact,
  buildDoNotEngageDealUpdate,
} from "../deals/dneOutcome";
import type {
  Deal,
  OpportunityOwnerDecision,
  OpportunityProspectDecision,
  SalesCall,
  SalesCallAttendance,
} from "../types";
import { DEFAULT_THINKING_FOLLOW_UP_DAYS } from "./salesCallConstants";
import { completeSalesCallTask } from "./salesCallTask";
import { completeResolveSalesCallTask } from "./resolveSalesCallTask";
import { ensureFollowUpTask } from "./followUpTask";
import { resolveDefaultTaskSalesId } from "./resolveDefaultTaskSalesId";
import { ensureOfferPageToken } from "../deals/offerPageToken";
import { recordSalesCallNoShow } from "./recordSalesCallNoShow";

export type CompleteSalesCallOutcomeInput = {
  dataProvider: DataProvider;
  salesCallId: Identifier;
  contactName: string;
  attendance: SalesCallAttendance;
  // Required when attendance = "attended".
  ownerDecision?: OpportunityOwnerDecision | null;
  // Required when ownerDecision = "would_work_with".
  prospectDecision?: OpportunityProspectDecision | null;
  // Required when prospectDecision = "thinking"; defaults to +4 days if
  // omitted (the dialog always supplies one, editable — this default only
  // protects a non-UI caller, e.g. a test or a future Acuity-adjacent
  // automation, from an ambiguous write).
  followUpDate?: string | null;
};

export type CompleteSalesCallOutcomeResult =
  | { status: "completed" }
  | { status: "not-found" }
  // The call has no matched Opportunity yet (Decision 3 — an unmatched
  // booking) — nothing to decide until it's resolved onto one.
  | { status: "no-opportunity" }
  // attendance was already recorded — idempotent no-op, never a second
  // write (double-click, cached tab, Back/Forward — same convention as
  // reviewApplication.ts's "already-reviewed" guard).
  | { status: "already-completed" }
  | { status: "validation-error"; message: string };

// The single domain function behind the "Complete Sales Call" dialog
// (Acuity/Sales Call Lifecycle slice). Idempotent-via-refetch, same
// convention as applications/reviewApplication.ts: re-reads the current
// sales_calls row rather than trusting the caller's copy, so a stale UI
// can never silently overwrite a newer outcome. Every branch below mirrors
// the ticket's own decision table exactly — see this slice's report for
// the stage/outcome reasoning.
export const completeSalesCallOutcome = async (
  input: CompleteSalesCallOutcomeInput,
): Promise<CompleteSalesCallOutcomeResult> => {
  const { dataProvider } = input;
  const { data: salesCall } = await dataProvider
    .getOne<SalesCall>("sales_calls", { id: input.salesCallId })
    .catch(() => ({ data: null as SalesCall | null }));
  if (!salesCall) return { status: "not-found" };

  // Gate B: a No-show is a single atomic domain operation, so it branches
  // BEFORE any of the writes below. Routing it through the same
  // sequential path as an attended call is what allowed the half-states
  // this rule forbids (call recorded no_show, Opportunity still active).
  // It is also allowed to run on an already-no-showed call, so the guard
  // below deliberately does not short-circuit it — re-running converges
  // rather than duplicating.
  if (input.attendance === "no_show") {
    const result = await recordSalesCallNoShow(dataProvider, salesCall.id);
    switch (result.status) {
      case "completed":
      case "already-no-show":
        return { status: "completed" };
      case "already-completed":
        return { status: "already-completed" };
      case "no-opportunity":
        return { status: "no-opportunity" };
      default:
        return { status: "not-found" };
    }
  }

  if (salesCall.attendance != null) return { status: "already-completed" };
  if (salesCall.opportunity_id == null) return { status: "no-opportunity" };

  if (input.attendance === "attended" && !input.ownerDecision) {
    return {
      status: "validation-error",
      message: "An owner-fit decision is required for an attended call.",
    };
  }
  if (input.ownerDecision === "would_work_with" && !input.prospectDecision) {
    return {
      status: "validation-error",
      message: "A prospect decision is required when Would Work With.",
    };
  }
  if (input.prospectDecision === "thinking" && input.followUpDate === "") {
    return {
      status: "validation-error",
      message: "A follow-up date is required when Thinking.",
    };
  }

  const now = new Date().toISOString();
  await dataProvider.update<SalesCall>("sales_calls", {
    id: salesCall.id,
    // Go-Live Blocker: Sales-Call No-Show/Rebooking slice — status also
    // leaves 'booked' the instant an outcome is recorded (attended or
    // no-show), never just before. sales_calls_one_booked_per_opportunity_idx
    // is a partial unique index on (opportunity_id) WHERE status='booked';
    // leaving a concluded call at 'booked' forever either silently
    // corrupts a genuine rebooking (bookSalesCall.ts's own "existing
    // booked call" matching reuses/retargets THIS row instead of creating
    // a fresh one, leaving attendance permanently stuck) or blocks the
    // fresh row's INSERT outright with a unique-violation. See migration
    // 20260914165113.
    data: {
      attendance: input.attendance,
      attendance_recorded_at: now,
      status: "completed",
    },
    previousData: salesCall,
  });
  await dataProvider.create("sales_call_events", {
    data: {
      sales_call_id: salesCall.id,
      kind: "attendance_recorded",
      occurred_at: now,
      attendance: input.attendance,
    },
  });

  // The call happened (attended or no-show) either way — its task is done.
  // Never the reverse: completing/cancelling this task must not itself
  // mutate sales status (that already happened above; this only reflects
  // it on the Task).
  await completeSalesCallTask(dataProvider, salesCall.contact_id, now);
  // Recording what happened is exactly the answer a resolve_sales_call
  // ambiguity task was waiting for, so that task is answered too. A safe
  // no-op when none is pending.
  await completeResolveSalesCallTask(
    dataProvider,
    salesCall.contact_id,
    now,
    salesCall.id,
  );

  const { data: deal } = await dataProvider.getOne<Deal>("deals", {
    id: salesCall.opportunity_id,
  });
  const dealUpdate = buildAttendedDealUpdate({
    ownerDecision: input.ownerDecision!,
    prospectDecision: input.prospectDecision ?? null,
    followUpDate: input.followUpDate || null,
  });
  await dataProvider.update("deals", {
    id: deal.id,
    data: dealUpdate,
    previousData: deal,
  });

  if (dealUpdate.owner_decision === "do_not_engage") {
    await applyDoNotEngageToContact(dataProvider, deal.contact_id);
  }

  if (
    dealUpdate.owner_decision === "would_work_with" &&
    dealUpdate.prospect_decision === "thinking"
  ) {
    await ensureFollowUpTask(dataProvider, {
      contactId: deal.contact_id,
      contactName: input.contactName,
      followUpDate: dealUpdate.follow_up_date!,
      salesId: await resolveDefaultTaskSalesId(dataProvider),
    });
  }

  // Payment domain foundation slice: reaching Committed is what generates
  // the personalized Offer Page's access token — see offerPageToken.ts's
  // own comment for why it's idempotent and never rotates an
  // already-issued link.
  if (dealUpdate.stage === "committed") {
    await ensureOfferPageToken(dataProvider, deal.id);
  }

  return { status: "completed" };
};

const buildAttendedDealUpdate = ({
  ownerDecision,
  prospectDecision,
  followUpDate,
}: {
  ownerDecision: OpportunityOwnerDecision;
  prospectDecision: OpportunityProspectDecision | null;
  followUpDate: string | null;
}): Partial<Deal> => {
  if (ownerDecision === "do_not_engage") {
    return buildDoNotEngageDealUpdate();
  }

  if (ownerDecision === "workshops_only") {
    // A genuine pipeline exit, explicitly NOT a lost sale (§ Workshops
    // Only) — the prospect was never offered LE/GYU, so it must not read
    // as a decline in later conversion analytics.
    return { outcome: "workshops_only", owner_decision: "workshops_only" };
  }

  // ownerDecision === "would_work_with"
  if (prospectDecision === "yes") {
    return {
      owner_decision: "would_work_with",
      prospect_decision: "yes",
      follow_up_date: null,
      stage: "committed",
    };
  }
  if (prospectDecision === "no") {
    return {
      owner_decision: "would_work_with",
      prospect_decision: "no",
      follow_up_date: null,
      outcome: "lost",
    };
  }
  // prospectDecision === "thinking"
  return {
    owner_decision: "would_work_with",
    prospect_decision: "thinking",
    follow_up_date:
      followUpDate ??
      addDays(new Date(), DEFAULT_THINKING_FOLLOW_UP_DAYS)
        .toISOString()
        .split("T")[0],
    stage: "decision",
  };
};

import type { DataProvider, Identifier } from "ra-core";

import type { Deal, SalesCall, Task } from "../types";
import { cancelSalesCallTask } from "./salesCallTask";

// The ONE canonical cancellation, used by BOTH entry points: the manual
// "Cancelled" choice in Complete Sales Call, and the Acuity webhook when a
// client cancels their own booking. Production runs it as a single Postgres
// transaction (record_sales_call_cancelled); this module is the
// FakeRest-testable mirror, the same dual-implementation pattern as
// recordSalesCallNoShow.ts.
//
// A cancellation is NOT a no-show. A no-show says the person did not turn
// up — a fact about them, which earns a durable Contact tag. A cancellation
// says the meeting is not happening, which says nothing about whether they
// are still interested. So this never touches `attendance`, never attaches
// the No-show tag, and never sets an exit outcome.
//
// WHAT CHANGED, and why: this function used to leave the Opportunity in
// Call Booked and create a "stranded lead" follow-up task, on the reasoning
// that regressing the stage was a business decision it should not guess.
// The effect was that Call Booked kept asserting a booked call that did not
// exist, and a task was created to compensate for the stage lying. Leif's
// ruling is that Call Booked means exactly one thing — there is a genuine
// booked future call — so the stage now moves to `approved` (approved to
// have a call, none scheduled), which IS the "needs booking" signal the
// stranding task was standing in for. The task is therefore retired rather
// than kept alongside it.
//
// Outcome is still never decided here: whether to pursue somebody who
// cancelled is Leif's judgement (Jori and Brandon cancelled identically and
// got different dispositions), so it stays null and the Deal sits visibly
// at Approved with no call booked.

export type CancelSalesCallResult =
  | { status: "cancelled" }
  // A duplicate cancellation — a repeated webhook or a second click — is a
  // safe no-op rather than a second event.
  | { status: "already-cancelled" }
  | { status: "not-found" }
  // Someone attended it; cancelling afterwards would erase that.
  | { status: "already-attended" };

type CancelCapableProvider = DataProvider & {
  recordSalesCallCancelled?: (
    salesCallId: Identifier,
  ) => Promise<{ status: string }>;
};

// Entry point for callers: the transactional RPC where the provider offers
// one, the mirror below otherwise.
export const cancelSalesCall = async (
  dataProvider: DataProvider,
  salesCallId: Identifier,
): Promise<CancelSalesCallResult> => {
  const rpc = (dataProvider as CancelCapableProvider).recordSalesCallCancelled;
  if (typeof rpc === "function") {
    const result = await rpc(salesCallId);
    return { status: result.status } as CancelSalesCallResult;
  }
  return cancelSalesCallMirror(dataProvider, salesCallId);
};

// The step-by-step implementation, exported so a provider that registers
// itself as RPC-capable can point straight at it instead of having
// cancelSalesCall dispatch back into that same registration forever.
export const cancelSalesCallMirror = async (
  dataProvider: DataProvider,
  salesCallId: Identifier,
): Promise<CancelSalesCallResult> => {
  const { data: salesCall } = await dataProvider
    .getOne<SalesCall>("sales_calls", { id: salesCallId })
    .catch(() => ({ data: null as SalesCall | null }));
  if (!salesCall) return { status: "not-found" };
  if (salesCall.attendance === "attended") {
    return { status: "already-attended" };
  }
  if (salesCall.status === "cancelled") {
    return { status: "already-cancelled" };
  }

  const now = new Date().toISOString();

  // 1. The Sales Call is the canonical record of the cancellation.
  //    original_scheduled_at is untouched — when it WAS going to happen is
  //    part of the history — and status leaving 'booked' frees the
  //    one-booked-per-opportunity index for a genuine rebooking.
  await dataProvider.update<SalesCall>("sales_calls", {
    id: salesCall.id,
    data: {
      status: "cancelled",
      cancelled_at: salesCall.cancelled_at ?? now,
    },
    previousData: salesCall,
  });
  await dataProvider.create("sales_call_events", {
    data: { sales_call_id: salesCall.id, kind: "cancelled", occurred_at: now },
  });

  // 2. A task about this specific call is no longer real work. Cancelled
  //    rather than completed — nobody did it — and deliberately with no
  //    done_date.
  //    Two passes, because a booking task can be linked either way: the
  //    Acuity booking task is created against the CONTACT (the existing
  //    cancelSalesCallTask helper finds it), while tasks created later
  //    carry sales_call_id directly. Cancelling by only one of those left
  //    the other falsely pending.
  await cancelSalesCallTask(dataProvider, salesCall.contact_id);
  await cancelTasksForCall(dataProvider, salesCall.id);

  // 3. The Opportunity leaves Call Booked, because that stage asserts a
  //    booked call and there is none. Only from 'call_booked' and only
  //    while still active: a Deal that has since progressed or exited is
  //    never dragged backwards by cancelling an old call.
  if (salesCall.opportunity_id != null) {
    const { data: deal } = await dataProvider
      .getOne<Deal>("deals", { id: salesCall.opportunity_id })
      .catch(() => ({ data: null as Deal | null }));
    if (
      deal &&
      deal.stage === "call_booked" &&
      deal.outcome == null &&
      deal.archived_at == null
    ) {
      await dataProvider.update<Deal>("deals", {
        id: deal.id,
        data: { stage: "approved", stage_entered_at: now },
        previousData: deal,
      });
    }
  }

  return { status: "cancelled" };
};

const cancelTasksForCall = async (
  dataProvider: DataProvider,
  salesCallId: Identifier,
): Promise<void> => {
  const { data: tasks } = await dataProvider.getList<Task>("tasks", {
    filter: { sales_call_id: salesCallId },
    pagination: { page: 1, perPage: 100 },
    sort: { field: "id", order: "ASC" },
  });
  for (const task of tasks) {
    if (task.status !== "pending" && task.status !== "waiting") continue;
    await dataProvider.update<Task>("tasks", {
      id: task.id,
      // No done_date: a cancelled task was never done.
      data: { status: "cancelled" },
      previousData: task,
    });
  }
};

import type { DataProvider, Identifier } from "ra-core";

import type { Deal, SalesCall, SalesCallSource } from "../types";
import {
  ensureSalesCallTask,
  updateSalesCallTaskDueDate,
} from "./salesCallTask";
import { completeSalesCallCancelledTask } from "./salesCallCancelledTask";
import { completeSalesCallNoShowTask } from "./salesCallNoShowTask";
import { ensureSalesCallNeedsMatchingTask } from "./salesCallNeedsMatchingTask";
import { resolveDefaultTaskSalesId } from "./resolveDefaultTaskSalesId";

export type BookSalesCallInput = {
  dataProvider: DataProvider;
  contactId: Identifier;
  contactName: string;
  // null: could not be safely matched to exactly one active Opportunity
  // (see matchAcuityBooking.ts) — preserved rather than guessed.
  opportunityId: Identifier | null;
  scheduledAt: string;
  source: SalesCallSource;
  acuityAppointmentId?: string | null;
  acuityAppointmentTypeId?: string | null;
  // Only meaningful (and only ever read) when opportunityId is null — the
  // mapped Offer/Cohort matchAcuityBooking.ts already resolved, so the
  // resulting resolve_sales_call Task's own text can name it (Unmatched
  // Sales Call Resolution slice, human-acceptance repair: "Sales call
  // needs matching" rows must show enough context to triage without
  // opening anything).
  offerName?: string;
  cohortName?: string | null;
};

export type BookSalesCallResult =
  | { status: "booked"; salesCall: SalesCall }
  // Same acuity_appointment_id already recorded — a duplicate webhook
  // delivery is a safe no-op, never a second row.
  | { status: "already-booked"; salesCall: SalesCall }
  // This Opportunity already has a currently-booked call — a second
  // "book" for it (e.g. an Acuity retry that produced a different
  // appointment id, or a re-booking call) reuses/retargets that row
  // instead of creating a duplicate, mirroring this app's established
  // "reuse the existing active thing" convention (submitApplication.ts's
  // findOrCreateDeal, waitlistActions.ts's convertToOpportunity).
  | { status: "reused-existing-booking"; salesCall: SalesCall };

// Records a newly booked sales call and its side effects: advances the
// Opportunity from Approved to Call Booked (only from Approved — an
// Opportunity already further along is left alone rather than guessed at,
// see the inline comment below), and ensures the right Task exists —
// "Sales Call: {Person}" when the Opportunity is known, "Resolve Sales
// Call: {Person}" when it isn't (Decision 3). Never marks
// Yes/Thinking/No or Committed/Won — those are human decisions made later
// via completeSalesCallOutcome.ts.
export const bookSalesCall = async (
  input: BookSalesCallInput,
): Promise<BookSalesCallResult> => {
  const { dataProvider } = input;

  if (input.acuityAppointmentId) {
    const { data: existingByAcuityId } = await dataProvider.getList<SalesCall>(
      "sales_calls",
      {
        filter: { acuity_appointment_id: input.acuityAppointmentId },
        pagination: { page: 1, perPage: 1 },
        sort: { field: "id", order: "ASC" },
      },
    );
    if (existingByAcuityId[0]) {
      return { status: "already-booked", salesCall: existingByAcuityId[0] };
    }
  }

  if (input.opportunityId != null) {
    const { data: existingBooked } = await dataProvider.getList<SalesCall>(
      "sales_calls",
      {
        filter: { opportunity_id: input.opportunityId, status: "booked" },
        pagination: { page: 1, perPage: 1 },
        sort: { field: "id", order: "ASC" },
      },
    );
    if (existingBooked[0]) {
      const salesCall = await retargetExistingBooking(
        dataProvider,
        existingBooked[0],
        input.scheduledAt,
      );
      return { status: "reused-existing-booking", salesCall };
    }
  }

  const now = new Date().toISOString();
  const { data: salesCall } = await dataProvider.create<SalesCall>(
    "sales_calls",
    {
      data: {
        opportunity_id: input.opportunityId,
        contact_id: input.contactId,
        status: "booked",
        original_scheduled_at: input.scheduledAt,
        scheduled_at: input.scheduledAt,
        reschedule_count: 0,
        source: input.source,
        acuity_appointment_id: input.acuityAppointmentId ?? null,
        acuity_appointment_type_id: input.acuityAppointmentTypeId ?? null,
      },
    },
  );

  await dataProvider.create("sales_call_events", {
    data: {
      sales_call_id: salesCall.id,
      kind: "booked",
      occurred_at: now,
      new_scheduled_at: input.scheduledAt,
    },
  });

  const salesId = await resolveDefaultTaskSalesId(dataProvider);

  if (input.opportunityId != null) {
    await advanceApprovedToCallBooked(dataProvider, input.opportunityId);
    await ensureSalesCallTask(dataProvider, {
      contactId: input.contactId,
      contactName: input.contactName,
      scheduledAt: input.scheduledAt,
      salesId,
    });
    // The person is back on the calendar — resolves any "sales call was
    // cancelled, decide next steps" task a prior cancellation on this same
    // Opportunity left open (GYU real-infrastructure slice, human-
    // acceptance repair pass; see cancelSalesCall.ts). A safe no-op when
    // no such task is pending.
    await completeSalesCallCancelledTask(dataProvider, input.contactId, now);
    // Same resolution for a no-show's own "decide next steps" task
    // (Go-Live Blocker: Sales-Call No-Show/Rebooking slice) — a fresh
    // booking IS the rescheduling decision, so the task that asked "does
    // this person want to reschedule?" is answered. A safe no-op when no
    // such task is pending.
    await completeSalesCallNoShowTask(dataProvider, input.contactId, now);
  } else {
    await ensureSalesCallNeedsMatchingTask(dataProvider, {
      contactId: input.contactId,
      contactName: input.contactName,
      salesCallId: salesCall.id,
      scheduledAt: input.scheduledAt,
      offerName: input.offerName ?? "",
      cohortName: input.cohortName,
      salesId,
    });
  }

  return { status: "booked", salesCall };
};

// Only the exact "Approved -> Call Booked" transition the product model
// describes. An Opportunity already at Call Booked/Decision/Committed/Won
// (or anywhere unexpected) is left exactly where it is — a repeat/duplicate
// booking call must never regress or reinterpret a stage a human decision
// already advanced past.
// Exported: also reused by resolveUnmatchedSalesCall.ts's own attach/create
// paths — same rule applies whether the Opportunity was just matched by
// Acuity or resolved by hand later.
export const advanceApprovedToCallBooked = async (
  dataProvider: DataProvider,
  opportunityId: Identifier,
): Promise<void> => {
  const { data: deal } = await dataProvider.getOne<Deal>("deals", {
    id: opportunityId,
  });
  if (deal.stage !== "approved") return;
  await dataProvider.update("deals", {
    id: opportunityId,
    data: { stage: "call_booked" },
    previousData: deal,
  });
};

const retargetExistingBooking = async (
  dataProvider: DataProvider,
  existing: SalesCall,
  scheduledAt: string,
): Promise<SalesCall> => {
  if (existing.scheduled_at === scheduledAt) return existing;

  const now = new Date().toISOString();
  const { data: updated } = await dataProvider.update<SalesCall>(
    "sales_calls",
    {
      id: existing.id,
      data: {
        scheduled_at: scheduledAt,
        reschedule_count: existing.reschedule_count + 1,
        last_rescheduled_at: now,
      },
      previousData: existing,
    },
  );
  await dataProvider.create("sales_call_events", {
    data: {
      sales_call_id: existing.id,
      kind: "rescheduled",
      occurred_at: now,
      previous_scheduled_at: existing.scheduled_at,
      new_scheduled_at: scheduledAt,
    },
  });
  await updateSalesCallTaskDueDate(
    dataProvider,
    existing.contact_id,
    scheduledAt,
  );
  return updated;
};

import type { DataProvider } from "ra-core";

import type { SalesCall } from "../types";
import { bookSalesCall, type BookSalesCallResult } from "./bookSalesCall";
import { cancelSalesCall, type CancelSalesCallResult } from "./cancelSalesCall";
import { matchAcuityBooking } from "./matchAcuityBooking";
import {
  rescheduleSalesCall,
  type RescheduleSalesCallResult,
} from "./rescheduleSalesCall";

// This is the fixture-testable "domain service" boundary the Acuity/Sales
// Call Lifecycle slice's integration point is built against — see this
// slice's report for exactly what remains to connect against a real
// Acuity account. supabase/functions/acuity_webhook/index.ts is its
// production mirror (same dual-implementation convention as every other
// integration in this app): a real Acuity webhook only POSTs
// {action, id, calendarID, appointmentTypeID} and requires a follow-up
// authenticated GET to Acuity's API for the fields below (email, name,
// datetime) — this module's input IS the shape that GET call returns, so
// it is exercised end-to-end here with fixtures standing in for that call.
export type AcuityAppointmentPayload = {
  acuityAppointmentId: string;
  acuityAppointmentTypeId: string;
  email: string;
  firstName: string;
  lastName: string;
  // ISO 8601 — Acuity's own `datetime` field.
  datetime: string;
};

export type AcuityWebhookAction = "scheduled" | "rescheduled" | "canceled";

export type ProcessAcuityWebhookInput = {
  dataProvider: DataProvider;
  action: AcuityWebhookAction;
  appointment: AcuityAppointmentPayload;
};

export type ProcessAcuityWebhookResult =
  | {
      status: "booked";
      matchReason: "matched" | "none" | "ambiguous";
      booking: BookSalesCallResult;
    }
  | { status: "unknown-appointment-type" }
  | { status: "rescheduled"; result: RescheduleSalesCallResult }
  | { status: "cancelled"; result: CancelSalesCallResult }
  // A reschedule/cancel event referencing an appointment id this CRM never
  // recorded a booking for (e.g. the original "scheduled" webhook was
  // missed) — nothing to safely act on without the identity/offer context
  // only the "scheduled" flow resolves.
  | { status: "unknown-appointment" };

// Routes one Acuity lifecycle action to the right domain function. Acuity
// appointment occurrence never implies attendance (confirmed against
// Acuity's own public API docs: a canceled appointment can carry a
// noShow flag, but only an admin sets it in Acuity itself, and there is no
// "attended" signal at all) — this service never writes attendance;
// that stays completeSalesCallOutcome.ts's job, triggered by an explicit
// human action in the CRM.
export const processAcuityWebhookEvent = async (
  input: ProcessAcuityWebhookInput,
): Promise<ProcessAcuityWebhookResult> => {
  const { dataProvider, action, appointment } = input;

  if (action === "canceled") {
    const existing = await findByAcuityAppointmentId(
      dataProvider,
      appointment.acuityAppointmentId,
    );
    if (!existing) return { status: "unknown-appointment" };
    const result = await cancelSalesCall(dataProvider, existing.id);
    return { status: "cancelled", result };
  }

  if (action === "rescheduled") {
    const existing = await findByAcuityAppointmentId(
      dataProvider,
      appointment.acuityAppointmentId,
    );
    if (!existing) {
      // Never recorded the original booking — treat this as the first
      // booking we're able to record rather than dropping a real
      // scheduling fact on the floor.
      return handleScheduled(dataProvider, appointment);
    }
    const result = await rescheduleSalesCall(dataProvider, {
      salesCallId: existing.id,
      newScheduledAt: appointment.datetime,
    });
    return { status: "rescheduled", result };
  }

  return handleScheduled(dataProvider, appointment);
};

const findByAcuityAppointmentId = async (
  dataProvider: DataProvider,
  acuityAppointmentId: string,
): Promise<SalesCall | null> => {
  const { data } = await dataProvider.getList<SalesCall>("sales_calls", {
    filter: { acuity_appointment_id: acuityAppointmentId },
    pagination: { page: 1, perPage: 1 },
    sort: { field: "id", order: "ASC" },
  });
  return data[0] ?? null;
};

const handleScheduled = async (
  dataProvider: DataProvider,
  appointment: AcuityAppointmentPayload,
): Promise<ProcessAcuityWebhookResult> => {
  const match = await matchAcuityBooking(dataProvider, {
    email: appointment.email,
    firstName: appointment.firstName,
    lastName: appointment.lastName,
    acuityAppointmentTypeId: appointment.acuityAppointmentTypeId,
  });
  if (match.status === "unknown-appointment-type") {
    return { status: "unknown-appointment-type" };
  }

  const opportunityId =
    match.status === "matched" ? match.opportunity.id : null;
  const contactName =
    `${match.contact.first_name ?? ""} ${match.contact.last_name ?? ""}`.trim();

  const booking = await bookSalesCall({
    dataProvider,
    contactId: match.contact.id,
    contactName,
    opportunityId,
    scheduledAt: appointment.datetime,
    source: "acuity",
    acuityAppointmentId: appointment.acuityAppointmentId,
    acuityAppointmentTypeId: appointment.acuityAppointmentTypeId,
    offerName: match.offer.name,
    cohortName: match.cohort?.name,
  });

  return {
    status: "booked",
    matchReason: match.status === "matched" ? "matched" : match.reason,
    booking,
  };
};

import { useCallback, useEffect, useState } from "react";
import { useDataProvider, useTranslate } from "ra-core";
import { Link, useParams } from "react-router";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";

import type { SalesCallResolutionContext } from "./loadSalesCallResolutionContext";
import { loadSalesCallResolutionContext } from "./loadSalesCallResolutionContext";
import { formatSalesCallScheduleWithPrecision } from "./salesCallSchedule";
import { classifySalesCallAmbiguity } from "./salesCallTaskTypes";
import { CompleteSalesCallDialog } from "./CompleteSalesCallDialog";

// "What happened on this call?" — the destination for a resolve_sales_call
// Task.
//
// Production acceptance found the Dashboard offering "SALES CALL NEEDS
// MATCHING — Megan Auron · call of Jul 7, 2026 — what happened?" and then
// opening a matching page that answered "This booking is already attached
// to an Opportunity." Megan's call never needed matching; what was unknown
// was its outcome. This page answers that question instead, using the same
// canonical three-way action the Opportunity's own Sales Call section uses
// (CompleteSalesCallDialog: call happened / no-show / cancelled) — one
// implementation, so a call resolved from here and a call resolved from
// the Opportunity page take exactly the same path through the pipeline.
export const SalesCallOutcomePage = () => {
  const { id } = useParams();
  const dataProvider = useDataProvider();
  const translate = useTranslate();
  const [context, setContext] = useState<
    SalesCallResolutionContext | "pending"
  >("pending");
  const [dialogOpen, setDialogOpen] = useState(false);

  const load = useCallback(async () => {
    if (!id) {
      setContext({ kind: "not-found" });
      return;
    }
    setContext(await loadSalesCallResolutionContext(dataProvider, id));
  }, [dataProvider, id]);

  useEffect(() => {
    load();
  }, [load]);

  if (context === "pending") return null;

  const title = translate("resources.sales_calls.outcome.title", {
    _: "Resolve sales call",
  });

  if (context.kind === "not-found") {
    return (
      <PageShell title={title}>
        <p className="text-sm text-muted-foreground">
          {translate("resources.sales_calls.resolve.not_found", {
            _: "This booking no longer exists.",
          })}
        </p>
      </PageShell>
    );
  }

  const { contact, salesCall } = context;
  const contactName =
    `${contact.first_name ?? ""} ${contact.last_name ?? ""}`.trim();
  const opportunity =
    context.kind === "already-resolved" ? context.opportunity : null;

  // The page branches on the booking's ACTUAL state, never on the Task that
  // brought us here. A task that has gone stale — someone resolved the call
  // from the Opportunity page in another tab — shows the truth rather than
  // offering an action that would contradict it.
  const ambiguity = classifySalesCallAmbiguity(salesCall);

  if (ambiguity === "needs-matching") {
    return (
      <PageShell title={title}>
        <Card>
          <CardContent className="flex flex-col gap-2">
            <p className="text-sm">
              {translate("resources.sales_calls.outcome.not_attached", {
                _: "This booking isn't attached to an Opportunity yet, so there's no outcome to record.",
              })}
            </p>
            <Link
              to={`/sales-calls/${salesCall.id}/resolve`}
              className="text-sm underline hover:no-underline"
            >
              {translate("resources.sales_calls.outcome.go_match", {
                _: "Match it to an Opportunity first",
              })}
            </Link>
          </CardContent>
        </Card>
      </PageShell>
    );
  }

  return (
    <PageShell title={title}>
      <Card>
        <CardContent className="flex flex-col gap-3">
          <div>
            <p className="text-sm font-medium">{contactName}</p>
            <p className="text-sm text-muted-foreground">
              {formatSalesCallScheduleWithPrecision(salesCall)}
            </p>
          </div>

          {ambiguity === "none" ? (
            <p className="text-sm">
              {translate("resources.sales_calls.outcome.already_resolved", {
                _: "This call is already resolved.",
              })}
            </p>
          ) : (
            <>
              <p className="text-sm">
                {translate("resources.sales_calls.outcome.question", {
                  _: "What happened on this call?",
                })}
              </p>
              <Button
                type="button"
                className="self-start"
                onClick={() => setDialogOpen(true)}
              >
                {translate("resources.sales_calls.outcome.record", {
                  _: "Record what happened",
                })}
              </Button>
            </>
          )}

          {opportunity && (
            <Link
              to={`/deals/${opportunity.id}/show`}
              className="text-sm underline hover:no-underline"
            >
              {translate("resources.sales_calls.resolve.view_opportunity", {
                _: "View the Opportunity",
              })}
            </Link>
          )}
        </CardContent>
      </Card>

      <CompleteSalesCallDialog
        open={dialogOpen}
        onOpenChange={(open) => {
          setDialogOpen(open);
          // Re-read on close so the page reflects whatever was just
          // recorded, including the case where the dialog was cancelled.
          if (!open) load();
        }}
        salesCallId={salesCall.id}
        contactName={contactName}
      />
    </PageShell>
  );
};

const PageShell = ({
  title,
  children,
}: {
  title: string;
  children: React.ReactNode;
}) => (
  <div className="max-w-lg mx-auto mt-8 flex flex-col gap-2">
    <h1 className="text-xl font-semibold">{title}</h1>
    {children}
  </div>
);

