import { useState } from "react";
import { useDataProvider, useNotify, useRefresh, useTranslate } from "ra-core";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import type { Identifier } from "ra-core";
import { bookSalesCall } from "./bookSalesCall";

// Human-acceptance repair pass, §Repair 2: recovery action for a legacy/
// inconsistent Opportunity — a Call Booked (or later) stage with no
// sales_calls record behind it (Judy Holloway's fixture predated the
// entity; a real record could end up the same way from a data import or a
// manual stage edit). This does NOT fabricate historical event data —
// Leif enters the real date the call happened/was scheduled for, and this
// calls the same bookSalesCall domain service the Acuity boundary uses,
// so the resulting Sales Call is a genuine (if backfilled) record, not a
// silent guess. source: "manual" makes that provenance explicit.
export const LogSalesCallDialog = ({
  open,
  onOpenChange,
  contactId,
  contactName,
  opportunityId,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  contactId: Identifier;
  contactName: string;
  opportunityId: Identifier;
}) => {
  const translate = useTranslate();
  const dataProvider = useDataProvider();
  const notify = useNotify();
  const refresh = useRefresh();
  const [scheduledAt, setScheduledAt] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleOpenChange = (next: boolean) => {
    if (!next) setScheduledAt("");
    onOpenChange(next);
  };

  const handleSubmit = async () => {
    if (!scheduledAt || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await bookSalesCall({
        dataProvider,
        contactId,
        contactName,
        opportunityId,
        scheduledAt: new Date(scheduledAt).toISOString(),
        source: "manual",
      });
      notify("resources.deals.sales_call.logged", {
        type: "info",
        _: "Sales call logged.",
      });
      handleOpenChange(false);
      refresh();
    } catch {
      notify("ra.notification.http_error", { type: "error" });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>
            {translate("resources.deals.sales_call.log_title", {
              _: "Log Sales Call",
            })}
          </DialogTitle>
          <DialogDescription>
            {translate("resources.deals.sales_call.log_description", {
              _: "This Opportunity reached Call Booked before call tracking existed. Enter when %{name}'s call actually happened (or is scheduled) to continue.",
              name: contactName,
            })}
          </DialogDescription>
        </DialogHeader>

        <div className="flex flex-col gap-2">
          <Label htmlFor="log-sales-call-date" className="text-sm font-medium">
            {translate("resources.deals.sales_call.scheduled_at", {
              _: "Call date",
            })}
          </Label>
          <Input
            id="log-sales-call-date"
            type="datetime-local"
            value={scheduledAt}
            onChange={(event) => setScheduledAt(event.target.value)}
          />
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => handleOpenChange(false)}
            disabled={isSubmitting}
          >
            {translate("ra.action.cancel")}
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={!scheduledAt || isSubmitting}
          >
            {translate("resources.deals.sales_call.log_action", {
              _: "Log Sales Call",
            })}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

import { useState } from "react";
import { useGetList, useRecordContext, useTranslate } from "ra-core";
import {
  describeSalesCallState,
  selectCurrentSalesCall,
} from "./selectCurrentSalesCall";
import { CheckCircle2, XCircle } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

import {
  ownerDecisions,
  prospectDecisions,
} from "../deals/opportunityConstants";
import { formatISODateString } from "../deals/dealUtils";
import type { Deal, SalesCall } from "../types";
import { salesCallAttendances } from "./salesCallConstants";
import { formatSalesCallScheduleWithPrecision } from "./salesCallSchedule";
import { CompleteSalesCallDialog } from "./CompleteSalesCallDialog";
import { LogSalesCallDialog } from "./LogSalesCallDialog";

const findLabel = (
  choices: { value: string; label: string }[],
  value?: string | null,
) => choices.find((choice) => choice.value === value)?.label;

// Stages the sales-call flow itself produces (bookSalesCall.ts only ever
// advances Approved -> Call Booked) — a legacy/inconsistent record here
// with no sales_calls row behind it is what makes "Complete Sales Call"
// go missing (Human-acceptance repair pass, §Repair 2).
const CALL_LIFECYCLE_STAGES = new Set(["call_booked", "decision", "committed"]);

const describeNextStep = (
  deal: Pick<
    Deal,
    "stage" | "owner_decision" | "prospect_decision" | "follow_up_date"
  >,
  translate: (key: string, options?: Record<string, unknown>) => string,
): string | null => {
  if (deal.owner_decision === "do_not_engage") {
    return findLabel(ownerDecisions, "do_not_engage") ?? null;
  }
  if (deal.owner_decision === "workshops_only") {
    return findLabel(ownerDecisions, "workshops_only") ?? null;
  }
  if (deal.prospect_decision === "yes") {
    return translate("resources.deals.sales_call.next_step_committed", {
      _: "Committed",
    });
  }
  if (deal.prospect_decision === "no") {
    return translate("resources.deals.sales_call.next_step_lost", {
      _: "Lost",
    });
  }
  if (deal.prospect_decision === "thinking" && deal.follow_up_date) {
    return translate("resources.deals.sales_call.next_step_follow_up", {
      _: "Follow up %{date}",
      date: formatISODateString(deal.follow_up_date),
    });
  }
  return null;
};

// The "wherever the call naturally appears" home for the Complete Sales
// Call action (Acuity/Sales Call Lifecycle slice; promoted to a prominent,
// impossible-to-miss position by the Human-acceptance repair pass, §Repair
// 1) — the Opportunity page, above Description/Notes. Reads the most
// recent Sales Call for this Opportunity regardless of status, so a
// cancelled or already-completed call still shows its real state rather
// than silently disappearing. Three distinct states: nothing to show yet
// (Opportunity hasn't reached a call-lifecycle stage), a legacy/
// inconsistent record (stage says Call Booked+ but no sales_calls row —
// §Repair 2), and a normal booked/completed call.
export const DealSalesCallSection = () => {
  const record = useRecordContext<Deal>();
  const translate = useTranslate();
  const [completeDialogOpen, setCompleteDialogOpen] = useState(false);
  const [logDialogOpen, setLogDialogOpen] = useState(false);

  const { data: salesCalls, isPending } = useGetList<SalesCall>(
    "sales_calls",
    {
      filter: { opportunity_id: record?.id },
      // Every call, not just the most recently created one: which call is
      // CURRENT is a question about schedules and statuses, not insertion
      // order, and the prior ones are the history shown beneath it.
      pagination: { page: 1, perPage: 50 },
      sort: { field: "id", order: "DESC" },
    },
    { enabled: !!record },
  );
  const { current: salesCall, history: priorSalesCalls } =
    selectCurrentSalesCall(salesCalls);

  if (!record || isPending) return null;

  const contactName = record.name;

  if (!salesCall) {
    if (!CALL_LIFECYCLE_STAGES.has(record.stage)) return null;

    // Legacy/inconsistent record — never silently invent a call that
    // wasn't tracked; give Leif a clear, honest recovery action instead
    // of a dead end.
    return (
      <div className="flex flex-col gap-3 m-4 rounded-lg border border-dashed p-4">
        <div className="flex flex-col gap-1">
          <span className="text-sm font-medium">
            {translate("resources.deals.sales_call.name", {
              _: "Sales Call",
            })}
          </span>
          <span className="text-sm text-muted-foreground">
            {translate("resources.deals.sales_call.no_record", {
              _: "This Opportunity reached %{stage} without a tracked sales call.",
              stage:
                findLabel(
                  [{ value: "call_booked", label: "Call Booked" }],
                  record.stage,
                ) ?? record.stage,
            })}
          </span>
        </div>
        <Button
          size="sm"
          variant="outline"
          className="self-start"
          onClick={() => setLogDialogOpen(true)}
        >
          {translate("resources.deals.sales_call.log_action", {
            _: "Log Sales Call",
          })}
        </Button>
        <LogSalesCallDialog
          open={logDialogOpen}
          onOpenChange={setLogDialogOpen}
          contactId={record.contact_id}
          contactName={contactName}
          opportunityId={record.id}
        />
      </div>
    );
  }

  const isPendingOutcome =
    salesCall.status === "booked" && !salesCall.attendance;

  return (
    <div
      className={`flex flex-col gap-3 m-4 rounded-lg border p-4 ${
        isPendingOutcome ? "border-primary" : ""
      }`}
    >
      {salesCall.status === "cancelled" ? (
        <div className="flex flex-col gap-1">
          <span className="text-sm font-medium">
            {translate("resources.deals.sales_call.latest_heading", {
              _: "Latest Sales Call",
            })}
          </span>
          <Badge variant="outline" className="self-start">
            {translate("resources.deals.sales_call.status_cancelled", {
              _: "Cancelled",
            })}
          </Badge>
          <span className="text-sm text-muted-foreground">
            {formatSalesCallScheduleWithPrecision(salesCall)}
          </span>
        </div>
      ) : isPendingOutcome ? (
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex flex-col">
            <span className="text-sm font-medium">
              {translate("resources.deals.sales_call.name", {
                _: "Sales Call",
              })}
            </span>
            <span className="text-base">
              {/* A historical date-only call has no clock time to show. */}
              {formatSalesCallScheduleWithPrecision(salesCall)}
            </span>
            {salesCall.reschedule_count > 0 && (
              <span className="text-xs text-muted-foreground">
                {translate("resources.deals.sales_call.rescheduled_count", {
                  _: "rescheduled %{count}×",
                  count: salesCall.reschedule_count,
                })}
              </span>
            )}
          </div>
          <Button size="lg" onClick={() => setCompleteDialogOpen(true)}>
            {translate("resources.deals.sales_call.complete_action", {
              _: "Complete Sales Call",
            })}
          </Button>
        </div>
      ) : (
        <>
          <span className="text-sm font-medium">
            {translate("resources.deals.sales_call.completed_heading", {
              _: "Sales Call · Completed",
            })}
          </span>
          <div className="flex items-center gap-2 text-sm">
            {salesCall.attendance === "attended" ? (
              <CheckCircle2 className="size-4 text-primary" />
            ) : (
              <XCircle className="size-4 text-muted-foreground" />
            )}
            {findLabel(salesCallAttendances, salesCall.attendance)}
          </div>

          {salesCall.attendance === "attended" && (
            <div className="flex flex-wrap gap-8">
              {record.owner_decision && (
                <div className="flex flex-col">
                  <span className="text-xs text-muted-foreground tracking-wide">
                    {translate("resources.deals.sales_call.my_decision", {
                      _: "My decision",
                    })}
                  </span>
                  <span className="text-sm">
                    {findLabel(ownerDecisions, record.owner_decision)}
                  </span>
                </div>
              )}
              {record.owner_decision === "would_work_with" &&
                record.prospect_decision && (
                  <div className="flex flex-col">
                    <span className="text-xs text-muted-foreground tracking-wide">
                      {translate("resources.deals.sales_call.their_decision", {
                        _: "Their decision",
                      })}
                    </span>
                    <span className="text-sm">
                      {findLabel(prospectDecisions, record.prospect_decision)}
                    </span>
                  </div>
                )}
              {describeNextStep(record, translate) && (
                <div className="flex flex-col">
                  <span className="text-xs text-muted-foreground tracking-wide">
                    {translate("resources.deals.sales_call.next_step", {
                      _: "Next step",
                    })}
                  </span>
                  <span className="text-sm">
                    {describeNextStep(record, translate)}
                  </span>
                </div>
              )}
            </div>
          )}
        </>
      )}

      <PriorSalesCalls calls={priorSalesCalls} />

      <CompleteSalesCallDialog
        open={completeDialogOpen}
        onOpenChange={setCompleteDialogOpen}
        salesCallId={salesCall.id}
        contactName={contactName}
      />
    </div>
  );
};

// The calls that came before the current one, most recent first.
//
// Mihaela Petrova is why this exists: her relationship reads "cancelled in
// September, after a no-show in July", and showing only one of those two
// facts — whichever one happened to win the sort — described a different
// person each time. Compact on purpose: this is context for the decision
// above it, not a second screen.
const PriorSalesCalls = ({ calls }: { calls: SalesCall[] }) => {
  const translate = useTranslate();
  if (!calls.length) return null;

  return (
    <div className="flex flex-col gap-1 border-t pt-3">
      <span className="text-xs uppercase tracking-wide text-muted-foreground">
        {translate("resources.deals.sales_call.previous_heading", {
          _: "Previously",
        })}
      </span>
      {calls.map((call) => (
        <span key={call.id} className="text-sm text-muted-foreground">
          {formatSalesCallScheduleWithPrecision(call)} ·{" "}
          {describeSalesCallState(call)}
        </span>
      ))}
    </div>
  );
};

import { addDays } from "date-fns/addDays";
import { useState } from "react";
import {
  useDataProvider,
  useNotify,
  useRefresh,
  useTranslate,
  type Identifier,
} from "ra-core";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";

import {
  ownerDecisions,
  prospectDecisions,
} from "../deals/opportunityConstants";
import type {
  OpportunityOwnerDecision,
  OpportunityProspectDecision,
} from "../types";
import {
  DEFAULT_THINKING_FOLLOW_UP_DAYS,
  salesCallOutcomeChoices,
  type SalesCallOutcomeChoice,
} from "./salesCallConstants";
import { completeSalesCallOutcome } from "./completeSalesCallOutcome";
import { cancelSalesCall } from "./cancelSalesCall";

const defaultFollowUpDate = () =>
  addDays(new Date(), DEFAULT_THINKING_FOLLOW_UP_DAYS)
    .toISOString()
    .split("T")[0];

// The one human-facing action this slice adds: "Complete Sales Call"
// (Acuity/Sales Call Lifecycle slice — see this slice's report for why a
// single progressively-revealed form, not a multi-step wizard, matches
// this app's existing conditional-section convention, e.g. deals/
// DealInputs.tsx's own DealSalesProcessInputs). Every field maps directly
// onto the SAME owner_decision/prospect_decision/follow_up_date fields
// DealInputs.tsx already edits — this is a guided front door onto them,
// not a second representation. A single call to
// completeSalesCallOutcome.ts on submit; this component owns none of the
// business logic itself.
export const CompleteSalesCallDialog = ({
  open,
  onOpenChange,
  salesCallId,
  contactName,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  salesCallId: Identifier;
  contactName: string;
}) => {
  const translate = useTranslate();
  const dataProvider = useDataProvider();
  const notify = useNotify();
  const refresh = useRefresh();

  // The three-way human answer. Only 'attended'/'no_show' are attendance
  // values the database understands; 'cancelled' is a different kind of
  // fact and goes down its own canonical path.
  const [outcome, setOutcome] = useState<SalesCallOutcomeChoice | null>(null);
  const [ownerDecision, setOwnerDecision] =
    useState<OpportunityOwnerDecision | null>(null);
  const [prospectDecision, setProspectDecision] =
    useState<OpportunityProspectDecision | null>(null);
  const [followUpDate, setFollowUpDate] = useState<string>("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const reset = () => {
    setOutcome(null);
    setOwnerDecision(null);
    setProspectDecision(null);
    setFollowUpDate("");
  };

  const handleOpenChange = (next: boolean) => {
    if (!next) reset();
    onOpenChange(next);
  };

  const canSubmit =
    outcome === "cancelled" ||
    outcome === "no_show" ||
    (outcome === "attended" &&
      ownerDecision != null &&
      (ownerDecision !== "would_work_with" ||
        (prospectDecision != null &&
          (prospectDecision !== "thinking" || !!followUpDate))));

  const handleSubmit = async () => {
    if (!outcome || isSubmitting) return;
    setIsSubmitting(true);
    try {
      // Cancellation is not an attendance outcome, so it does not go
      // through completeSalesCallOutcome at all — it uses the same
      // canonical action the Acuity webhook uses, so a call cancelled in
      // the CRM and one cancelled by the client end in identical state.
      if (outcome === "cancelled") {
        const cancelled = await cancelSalesCall(dataProvider, salesCallId);
        if (
          cancelled.status === "cancelled" ||
          cancelled.status === "already-cancelled"
        ) {
          notify("resources.deals.sales_call.cancelled", {
            type: "info",
            _: "Sales call cancelled. The Opportunity needs a new booking.",
          });
          handleOpenChange(false);
          refresh();
        } else {
          notify("ra.notification.http_error", { type: "error" });
        }
        return;
      }

      const result = await completeSalesCallOutcome({
        dataProvider,
        salesCallId,
        contactName,
        attendance: outcome,
        ownerDecision,
        prospectDecision,
        followUpDate: prospectDecision === "thinking" ? followUpDate : null,
      });

      if (result.status === "completed") {
        notify("resources.deals.sales_call.completed", {
          type: "info",
          _: "Sales call completed.",
        });
        handleOpenChange(false);
        refresh();
      } else if (result.status === "already-completed") {
        notify("resources.deals.sales_call.already_completed", {
          type: "warning",
          _: "This call's outcome was already recorded.",
        });
        handleOpenChange(false);
        refresh();
      } else {
        notify("ra.notification.http_error", { type: "error" });
      }
    } catch {
      notify("ra.notification.http_error", { type: "error" });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>
            {translate("resources.deals.sales_call.complete_title", {
              _: "Complete Sales Call",
            })}
          </DialogTitle>
          <DialogDescription>
            {translate("resources.deals.sales_call.complete_description", {
              _: "%{name}'s sales call",
              name: contactName,
            })}
          </DialogDescription>
        </DialogHeader>

        <div className="flex flex-col gap-6">
          <fieldset className="flex flex-col gap-3">
            <Label className="text-sm font-medium">
              {/* Works for all three: "Attendance" cannot describe a call
                  that never happened. */}
              {translate("resources.deals.sales_call.what_happened", {
                _: "What happened with this call?",
              })}
            </Label>
            <RadioGroup
              value={outcome ?? undefined}
              onValueChange={(value) =>
                setOutcome(value as SalesCallOutcomeChoice)
              }
            >
              {salesCallOutcomeChoices.map((choice) => (
                <div key={choice.value} className="flex items-center gap-2">
                  <RadioGroupItem
                    value={choice.value}
                    id={`attendance-${choice.value}`}
                  />
                  <Label
                    htmlFor={`attendance-${choice.value}`}
                    className="font-normal"
                  >
                    {choice.label}
                  </Label>
                </div>
              ))}
            </RadioGroup>
          </fieldset>

          {outcome === "attended" && (
            <fieldset className="flex flex-col gap-3 rounded-lg border p-4">
              <Label className="text-sm font-medium">
                {translate("resources.deals.sales_call.owner_fit_question", {
                  _: "Would I work with this person?",
                })}
              </Label>
              <RadioGroup
                value={ownerDecision ?? undefined}
                onValueChange={(value) => {
                  setOwnerDecision(value as OpportunityOwnerDecision);
                  setProspectDecision(null);
                }}
              >
                {ownerDecisions.map((choice) => (
                  <div key={choice.value} className="flex items-center gap-2">
                    <RadioGroupItem
                      value={choice.value}
                      id={`owner-${choice.value}`}
                    />
                    <Label
                      htmlFor={`owner-${choice.value}`}
                      className="font-normal"
                    >
                      {choice.label}
                    </Label>
                  </div>
                ))}
              </RadioGroup>

              {ownerDecision === "would_work_with" && (
                <div className="flex flex-col gap-3 rounded-lg border p-4 mt-2">
                  <Label className="text-sm font-medium">
                    {translate(
                      "resources.deals.sales_call.prospect_decision_question",
                      { _: "Their decision" },
                    )}
                  </Label>
                  <RadioGroup
                    value={prospectDecision ?? undefined}
                    onValueChange={(value) => {
                      const next = value as OpportunityProspectDecision;
                      setProspectDecision(next);
                      if (next === "thinking" && !followUpDate) {
                        setFollowUpDate(defaultFollowUpDate());
                      }
                    }}
                  >
                    {prospectDecisions.map((choice) => (
                      <div
                        key={choice.value}
                        className="flex items-center gap-2"
                      >
                        <RadioGroupItem
                          value={choice.value}
                          id={`prospect-${choice.value}`}
                        />
                        <Label
                          htmlFor={`prospect-${choice.value}`}
                          className="font-normal"
                        >
                          {choice.label}
                        </Label>
                      </div>
                    ))}
                  </RadioGroup>

                  {prospectDecision === "thinking" && (
                    <div className="flex flex-col gap-2 mt-2">
                      <Label
                        htmlFor="follow-up-date"
                        className="text-sm font-medium"
                      >
                        {translate("resources.deals.sales_call.follow_up_on", {
                          _: "Follow up on",
                        })}
                      </Label>
                      <Input
                        id="follow-up-date"
                        type="date"
                        value={followUpDate}
                        onChange={(event) =>
                          setFollowUpDate(event.target.value)
                        }
                      />
                    </div>
                  )}
                </div>
              )}
            </fieldset>
          )}
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => handleOpenChange(false)}
            disabled={isSubmitting}
          >
            {translate("ra.action.cancel")}
          </Button>
          <Button onClick={handleSubmit} disabled={!canSubmit || isSubmitting}>
            {translate("resources.deals.sales_call.complete_action", {
              _: "Complete Sales Call",
            })}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

import type { Identifier } from "ra-core";
import { useGetManyAggregate } from "ra-core";

export const useGetSalesName = (
  id?: Identifier,
  options?: { enabled?: boolean },
) => {
  const enabled = options?.enabled ?? id != null;
  const { data, error } = useGetManyAggregate(
    "sales",
    { ids: id !== null ? [id] : undefined },
    { enabled },
  );

  return data && data[0]
    ? `${data[0].first_name} ${data[0].last_name}`
    : error
      ? "??"
      : "";
};

