import { useState } from "react";
import { CreateBase, Form, useTranslate } from "ra-core";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogTitle } from "@/components/ui/dialog";
import { SaveButton } from "@/components/admin/form";

import { CohortInputs } from "../cohorts/CohortInputs";
import { OfferInputs } from "../offers/OfferInputs";
import type { Offer, OfferType } from "../types";

type Step =
  | { kind: "choose_type" }
  | { kind: "offer_form"; type: OfferType }
  | { kind: "cohort_form"; offer: Offer };

// "+ New Program" (§7 of the Programs + Opportunity UX slice): a clean
// choice between a 1:1 program and a group program, then just enough form
// to set it up — no DB terminology ("Offer"/"Cohort") shown to the user,
// and no wizard beyond what a Group program genuinely needs (its Offer,
// then its first Cohort).
export const NewProgramDialog = ({
  open,
  onOpenChange,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) => {
  const translate = useTranslate();
  const [step, setStep] = useState<Step>({ kind: "choose_type" });

  const handleClose = () => {
    onOpenChange(false);
    // Reset after the close animation finishes so the dialog doesn't flash
    // back to step 1 while it's fading out.
    setTimeout(() => setStep({ kind: "choose_type" }), 200);
  };

  return (
    <Dialog open={open} onOpenChange={(next) => !next && handleClose()}>
      <DialogContent className="sm:max-w-md">
        <DialogTitle>
          {translate("crm.programs.new_program_title", { _: "New Program" })}
        </DialogTitle>

        {step.kind === "choose_type" && (
          <div className="flex flex-col gap-3 pt-2">
            <p className="text-sm text-muted-foreground">
              {translate("crm.programs.new_program_choose", {
                _: "How do you work with clients in this program?",
              })}
            </p>
            <Button
              variant="outline"
              className="h-auto flex-col items-start gap-1 p-4 whitespace-normal"
              onClick={() =>
                setStep({ kind: "offer_form", type: "individual" })
              }
            >
              <span className="font-medium">
                {translate("crm.programs.one_on_one_program", {
                  _: "1:1 Program",
                })}
              </span>
              <span className="text-xs text-muted-foreground font-normal">
                {translate("crm.programs.one_on_one_program_hint", {
                  _: "Ongoing individual coaching, like The Living Example.",
                })}
              </span>
            </Button>
            <Button
              variant="outline"
              className="h-auto flex-col items-start gap-1 p-4 whitespace-normal"
              onClick={() => setStep({ kind: "offer_form", type: "group" })}
            >
              <span className="font-medium">
                {translate("crm.programs.group_program", {
                  _: "Group Program",
                })}
              </span>
              <span className="text-xs text-muted-foreground font-normal">
                {translate("crm.programs.group_program_hint", {
                  _: "A cohort-based program, like Growing Yourself Up.",
                })}
              </span>
            </Button>
          </div>
        )}

        {step.kind === "offer_form" && (
          <CreateBase
            resource="offers"
            redirect={false}
            mutationOptions={{
              onSuccess: (offer: Offer) => {
                if (offer.type === "group") {
                  setStep({ kind: "cohort_form", offer });
                } else {
                  handleClose();
                }
              },
            }}
          >
            <Form defaultValues={{ type: step.type, is_active: true }}>
              <div className="flex flex-col gap-4 pt-2">
                <OfferInputs />
                <div className="flex justify-end gap-2 pt-1">
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => setStep({ kind: "choose_type" })}
                  >
                    {translate("ra.action.back", { _: "Back" })}
                  </Button>
                  <SaveButton
                    label={translate("resources.offers.action.create", {
                      _: "Create Offer",
                    })}
                  />
                </div>
              </div>
            </Form>
          </CreateBase>
        )}

        {step.kind === "cohort_form" && (
          <CreateBase
            resource="cohorts"
            redirect={false}
            mutationOptions={{ onSuccess: handleClose }}
          >
            <Form defaultValues={{ offer_id: step.offer.id, status: "draft" }}>
              <div className="flex flex-col gap-4 pt-2">
                <p className="text-sm text-muted-foreground">
                  {translate("crm.programs.new_program_first_cohort", {
                    _: "%{offer} was created. Now set up its first Cohort.",
                    offer: step.offer.name,
                  })}
                </p>
                <CohortInputs />
                <div className="flex justify-end gap-2 pt-1">
                  <SaveButton
                    label={translate("resources.cohorts.action.create", {
                      _: "Create Cohort",
                    })}
                  />
                </div>
              </div>
            </Form>
          </CreateBase>
        )}
      </DialogContent>
    </Dialog>
  );
};

import { useEffect } from "react";
import { useTranslate } from "ra-core";
import { useLocation, useParams } from "react-router";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";

import { PageHeader, PersonCard, Section } from "../misc/ProgramLayout";
import { formatMonthDayString } from "../deals/dealUtils";
import { enrollmentStatusLabels } from "../enrollments/enrollmentConstants";
import { CopyApplicationLinkButton } from "../public-application/CopyApplicationLinkButton";
import { LivingExampleApplicationPage } from "../public-application/LivingExampleApplicationPage";
import { AddToWaitlistButton } from "../waitlist/AddToWaitlistButton";
import { WaitlistSection } from "../waitlist/WaitlistSection";
import { useWaitlistEntries } from "../waitlist/useWaitlistEntries";
import { useIndividualProgramData } from "./useIndividualProgramData";

// The Living Example (or any future 1:1 Offer's) program page — §8-9 of the
// Programs + Opportunity UX slice. A real user-facing page over the
// existing Offer + Enrollment data, not a new "Program" table. Its visual
// language (PageHeader/Section/PersonCard from misc/ProgramLayout.tsx) is
// the reference the Runtime + Visual Consistency slice carries to the GYU
// Cohort page and beyond.
export const IndividualProgramPage = () => {
  const { offerId } = useParams();
  const location = useLocation();
  const translate = useTranslate();
  const { isPending, offer, capacity, currentClients, upcomingOpenings } =
    useIndividualProgramData(offerId);
  const { isPending: waitlistPending, entries: waitlist } = useWaitlistEntries({
    offerId,
    cohortId: null,
  });

  // The Dashboard's "Next opening" link (LivingExampleCapacityCard.tsx)
  // points at this page's #upcoming-openings anchor. HashRouter's own `#`
  // means the browser never fires its native fragment-scroll for a
  // client-side route change, so it's done by hand once the content (and
  // the target element) actually exists.
  useEffect(() => {
    if (isPending || !location.hash) return;
    const target = document.getElementById(location.hash.slice(1));
    target?.scrollIntoView({ block: "start" });
  }, [isPending, location.hash]);

  if (isPending || waitlistPending) return null;
  if (!offer) {
    return (
      <div className="p-4">
        <p className="text-sm text-muted-foreground">
          {translate("crm.programs.individual_not_found", {
            _: "This program could not be found.",
          })}
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 mt-1 p-1 max-w-3xl">
      <div className="flex items-start justify-between gap-4">
        <PageHeader
          title={offer.name}
          summary={
            <>
              {capacity?.active}
              {capacity?.max != null && <span> / {capacity.max}</span>}{" "}
              {translate("crm.dashboard.capacity_active", { _: "active" })}
              {capacity?.openings != null && (
                <span>
                  {" · "}
                  {translate("crm.dashboard.capacity_openings", {
                    _: "%{count} openings",
                    count: capacity.openings,
                  })}
                </span>
              )}
              {waitlist.length > 0 && (
                <span>
                  {" · "}
                  {translate("resources.waitlist_entries.count", {
                    _: "%{count} waiting",
                    count: waitlist.length,
                  })}
                </span>
              )}
            </>
          }
        />
        <div className="flex items-center gap-2">
          <CopyApplicationLinkButton
            path={LivingExampleApplicationPage.path}
            label={offer.name}
          />
          <AddToWaitlistButton offerId={offer.id} cohortId={null} />
        </div>
      </div>

      <Section
        title={translate("crm.programs.current_clients", {
          _: "Current Clients",
        })}
      >
        {currentClients.length === 0 ? (
          <p className="text-sm text-muted-foreground">
            {translate("crm.programs.no_current_clients", {
              _: "No current clients.",
            })}
          </p>
        ) : (
          <div className="flex flex-col gap-2">
            {currentClients.map((client) => (
              <PersonCard
                key={client.enrollmentId}
                contactId={client.contactId}
                name={client.name}
                trailing={
                  <Badge variant="outline">
                    {enrollmentStatusLabels[client.status]}
                  </Badge>
                }
              />
            ))}
          </div>
        )}
      </Section>

      <Section
        id="upcoming-openings"
        title={translate("crm.programs.upcoming_openings", {
          _: "Upcoming Openings",
        })}
      >
        {upcomingOpenings.length === 0 ? (
          <p className="text-sm text-muted-foreground">
            {translate("crm.programs.no_upcoming_openings", {
              _: "No upcoming openings.",
            })}
          </p>
        ) : (
          <div className="flex flex-col gap-2">
            {upcomingOpenings.map((opening) => (
              <Card key={opening.date} className="p-0">
                <CardContent className="px-4 py-2.5">
                  <p className="text-sm font-medium">
                    {formatMonthDayString(opening.date)}
                    {" — "}
                    {translate("crm.programs.opening_count", {
                      _: "%{count} opening |||| %{count} openings",
                      smart_count: opening.count,
                      count: opening.count,
                    })}
                  </p>
                  <p className="text-xs text-muted-foreground truncate">
                    {opening.clients
                      .map((client) =>
                        translate("crm.programs.opening_completes", {
                          _: "%{name} completes",
                          name: client.name,
                        }),
                      )
                      .join(", ")}
                  </p>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </Section>

      <WaitlistSection
        entries={waitlist}
        offerId={offer.id}
        offerName={offer.name}
        cohortId={null}
      />
    </div>
  );
};

