import { useGetList, useGetOne } from "ra-core";

import type {
  Cohort,
  Contact,
  Deal,
  Enrollment,
  EnrollmentOffboardingItem,
  EnrollmentOnboardingItem,
  Offer,
  Task,
  DealPaymentScheduleItem,
} from "../types";

// Backs the Enrollment/Client page (Contracts + Onboarding slice, extended
// by the Client Offboarding slice) — same "walk the Opportunity to its
// Contact/Offer/Cohort" shape as useApplicationReviewData.ts, extended
// with both checklists (onboarding and offboarding) and their linked
// Tasks — everything the page needs to be the real fulfillment-lifecycle
// operational home: payment context (from the Deal's own frozen
// snapshot), both checklists, and any Task still open for an incomplete
// item.
export const useEnrollmentOperationalData = (enrollment?: Enrollment) => {
  const { data: deal, isPending: dealPending } = useGetOne<Deal>(
    "deals",
    { id: enrollment?.opportunity_id as Deal["id"] },
    { enabled: enrollment != null },
  );

  const { data: contact, isPending: contactPending } = useGetOne<Contact>(
    "contacts",
    { id: deal?.contact_id as Contact["id"] },
    { enabled: deal?.contact_id != null },
  );

  const { data: offer, isPending: offerPending } = useGetOne<Offer>(
    "offers",
    { id: deal?.offer_id as Offer["id"] },
    { enabled: deal != null },
  );

  const { data: cohort, isPending: cohortPending } = useGetOne<Cohort>(
    "cohorts",
    { id: deal?.cohort_id as Cohort["id"] },
    { enabled: deal?.cohort_id != null },
  );

  // The agreed payment schedule, when this Deal has one. Absent for a
  // simple plan, which still renders from the Deal's own snapshot — see
  // resolveCommercialTerms for which wins.
  //
  // Deliberately NOT part of isPending below. A schedule is supplementary:
  // most Deals have none, and resolveCommercialTerms already treats "no
  // rows" as "fall back to the Deal snapshot". Gating the whole Client page
  // on it meant one slow or failing supplementary query blanked the page —
  // including every operational thing on it that has nothing to do with
  // money. It resolves a moment later and the Payment card re-renders.
  const { data: scheduleItems, isPending: schedulePending } =
    useGetList<DealPaymentScheduleItem>(
      "deal_payment_schedule_items",
      {
        filter: { deal_id: deal?.id },
        pagination: { page: 1, perPage: 100 },
        sort: { field: "sequence", order: "ASC" },
      },
      { enabled: deal != null },
    );

  const { data: items, isPending: itemsPending } =
    useGetList<EnrollmentOnboardingItem>(
      "enrollment_onboarding_items",
      {
        filter: { enrollment_id: enrollment?.id },
        pagination: { page: 1, perPage: 100 },
        sort: { field: "sort_order", order: "ASC" },
      },
      { enabled: enrollment != null },
    );

  const { data: offboardingItems, isPending: offboardingItemsPending } =
    useGetList<EnrollmentOffboardingItem>(
      "enrollment_offboarding_items",
      {
        filter: { enrollment_id: enrollment?.id },
        pagination: { page: 1, perPage: 100 },
        sort: { field: "sort_order", order: "ASC" },
      },
      { enabled: enrollment != null },
    );

  const { data: tasks, isPending: tasksPending } = useGetList<Task>(
    "tasks",
    {
      filter: { enrollment_id: enrollment?.id },
      pagination: { page: 1, perPage: 100 },
      sort: { field: "id", order: "ASC" },
    },
    { enabled: enrollment != null },
  );

  const isPending =
    enrollment == null ||
    dealPending ||
    (deal?.contact_id != null && contactPending) ||
    offerPending ||
    (deal?.cohort_id != null && cohortPending) ||
    itemsPending ||
    offboardingItemsPending ||
    tasksPending;

  return {
    isPending,
    deal: isPending ? undefined : deal,
    contact: isPending ? undefined : contact,
    offer: isPending ? undefined : offer,
    cohort: deal?.cohort_id != null && !cohortPending ? cohort : undefined,
    items: isPending ? [] : (items ?? []),
    offboardingItems: isPending ? [] : (offboardingItems ?? []),
    tasks: isPending ? [] : (tasks ?? []),
    scheduleItems: schedulePending ? [] : (scheduleItems ?? []),
  };
};

import { useGetList, useGetMany } from "ra-core";
import type { Identifier } from "ra-core";

import type { Cohort, Deal, Enrollment, Offer } from "../types";
import {
  byNewestStartFirst,
  bySoonestStartFirst,
  classifyEnrollment,
  type EnrollmentPhase,
} from "./classifyEnrollment";

export type ClientRow = {
  enrollment: Enrollment;
  contactId: Identifier | undefined;
  offer: Offer | undefined;
  cohort: Cohort | undefined;
  phase: EnrollmentPhase;
};

export type CohortGroup = {
  key: string;
  title: string;
  rows: ClientRow[];
};

// Backs the Clients list.
//
// Two things were wrong with the old grouping. It split on enrollment
// STATUS alone, so Daniel Alexander — agreed, set up, and starting on 8
// November — appeared under current clients seven weeks early. And it
// merged The Living Example and Growing Yourself Up into one undifferentiated
// list, which hides the only distinction that matters operationally: LE is
// a rolling 1:1 container with its own dates per person, GYU is a cohort
// that runs as a group.
//
// So: LE splits by TIME (upcoming / current / past), GYU groups by cohort,
// and each offer keeps its own shape.
export const useClientsGrouped = (): {
  isPending: boolean;
  livingExample: Record<EnrollmentPhase, ClientRow[]>;
  gyuCohorts: CohortGroup[];
  gyuPast: ClientRow[];
  other: ClientRow[];
} => {
  const { data: enrollments, isPending: enrollmentsPending } =
    useGetList<Enrollment>("enrollments", {
      pagination: { page: 1, perPage: 1000 },
      sort: { field: "created_at", order: "DESC" },
    });

  const dealIds = [
    ...new Set((enrollments ?? []).map((e) => e.opportunity_id)),
  ];
  const { data: deals, isPending: dealsPending } = useGetMany<Deal>(
    "deals",
    { ids: dealIds },
    { enabled: dealIds.length > 0 },
  );

  const offerIds = [...new Set((deals ?? []).map((d) => d.offer_id))];
  const { data: offers, isPending: offersPending } = useGetMany<Offer>(
    "offers",
    { ids: offerIds },
    { enabled: offerIds.length > 0 },
  );

  const cohortIds = [
    ...new Set(
      (deals ?? [])
        .map((d) => d.cohort_id)
        .filter((id): id is Identifier => id != null),
    ),
  ];
  const { data: cohorts, isPending: cohortsPending } = useGetMany<Cohort>(
    "cohorts",
    { ids: cohortIds },
    { enabled: cohortIds.length > 0 },
  );

  const isPending =
    enrollmentsPending ||
    (dealIds.length > 0 &&
      (dealsPending ||
        (offerIds.length > 0 && offersPending) ||
        (cohortIds.length > 0 && cohortsPending)));

  const empty = {
    livingExample: { upcoming: [], current: [], past: [] },
    gyuCohorts: [],
    gyuPast: [],
    other: [],
  };

  if (isPending) return { isPending: true, ...empty };

  const dealById = new Map((deals ?? []).map((d) => [String(d.id), d]));
  const offerById = new Map((offers ?? []).map((o) => [String(o.id), o]));
  const cohortById = new Map((cohorts ?? []).map((c) => [String(c.id), c]));

  const livingExample: Record<EnrollmentPhase, ClientRow[]> = {
    upcoming: [],
    current: [],
    past: [],
  };
  const gyuByCohort = new Map<string, ClientRow[]>();
  const gyuPast: ClientRow[] = [];
  const other: ClientRow[] = [];

  for (const enrollment of enrollments ?? []) {
    const deal = dealById.get(String(enrollment.opportunity_id));
    const offer = deal ? offerById.get(String(deal.offer_id)) : undefined;
    const row: ClientRow = {
      enrollment,
      contactId: deal?.contact_id ?? undefined,
      offer,
      cohort:
        deal?.cohort_id != null
          ? cohortById.get(String(deal.cohort_id))
          : undefined,
      phase: classifyEnrollment(enrollment),
    };

    if (offer?.type === "group") {
      // A cohort that has finished for somebody is history regardless of
      // which cohort it was, so terminal rows leave the cohort sections.
      if (row.phase === "past") {
        gyuPast.push(row);
        continue;
      }
      const key = row.cohort ? String(row.cohort.id) : "no-cohort";
      const bucket = gyuByCohort.get(key) ?? [];
      bucket.push(row);
      gyuByCohort.set(key, bucket);
      continue;
    }

    if (offer?.type === "individual") {
      livingExample[row.phase].push(row);
      continue;
    }

    // An Enrollment whose Offer could not be resolved is shown rather
    // than silently dropped.
    other.push(row);
  }

  // Current: newest-starting at the top, Leif's stated order. Upcoming
  // reads forwards — the next container to prepare for comes first. Past
  // is most recently finished first.
  livingExample.current.sort((a, b) =>
    byNewestStartFirst(a.enrollment, b.enrollment),
  );
  livingExample.upcoming.sort((a, b) =>
    bySoonestStartFirst(a.enrollment, b.enrollment),
  );
  livingExample.past.sort((a, b) =>
    byNewestStartFirst(a.enrollment, b.enrollment),
  );

  const gyuCohorts: CohortGroup[] = [...gyuByCohort.entries()]
    .map(([key, rows]) => ({
      key,
      title: rows[0]?.cohort?.name ?? "No cohort assigned",
      rows: rows.sort((a, b) =>
        (a.contactId ?? 0) > (b.contactId ?? 0) ? 1 : -1,
      ),
    }))
    // Newest cohort first, by name descending — cohort names carry their
    // own period ("Fall 2026", "January 2027"), so id order is the stable
    // proxy for when Leif set them up.
    .sort((a, b) => b.key.localeCompare(a.key, undefined, { numeric: true }));

  gyuPast.sort((a, b) => byNewestStartFirst(a.enrollment, b.enrollment));

  return { isPending: false, livingExample, gyuCohorts, gyuPast, other };
};

import type { DataProvider, Identifier } from "ra-core";

import type { Enrollment } from "../types";

export type StartOffboardingResult =
  | { applied: true }
  | { applied: false; reason: "not-active" };

// Client Offboarding slice: the explicit human "Start offboarding" action
// (§5 — Leif decides when the relationship is entering offboarding; never
// inferred from dates or session counts). Mirrors activateEnrollment.ts's
// own shape: re-fetches current server state (never trusts the caller's
// copy) so a double-click, a stale tab, or Back/Forward is a safe no-op
// rather than a second write — the caller checks `applied` and shows the
// real current state rather than assuming success.
//
// Unlike activateEnrollment.ts, there are no PREREQUISITE requirements to
// check here (nothing must be complete before offboarding can start) —
// the only guard is the transition itself: only an ACTIVE Enrollment can
// start offboarding (never onboarding -> offboarding as a shortcut, per
// §1). The DB's own handle_enrollment_offboarding_started() trigger
// fires on this same update and performs the actual checklist/Task
// snapshot — this function's job is purely the guarded status write.
export const startOffboarding = async (
  dataProvider: DataProvider,
  enrollmentId: Identifier,
): Promise<StartOffboardingResult> => {
  const { data: enrollment } = await dataProvider.getOne<Enrollment>(
    "enrollments",
    { id: enrollmentId },
  );
  if (enrollment.status !== "active") {
    return { applied: false, reason: "not-active" };
  }

  await dataProvider.update("enrollments", {
    id: enrollment.id,
    data: { status: "offboarding" },
    previousData: enrollment,
  });

  return { applied: true };
};

import type { Deal, DealPaymentScheduleItem } from "../types";

// ONE place that decides what a Deal's commercial terms actually are, so the
// Payment card never has to choose between two stories.
//
// Source of truth, in order:
//   1. An explicit payment SCHEDULE, when one exists. It is strictly more
//      expressive than the Deal's snapshot — unequal amounts, real due
//      dates, per-item paid state — so where it exists it wins outright.
//   2. The Deal's own equal-installment snapshot (selected_payment_total +
//      count + per-payment amount). Still exactly right for a simple plan,
//      and untouched: Mel's single $700, Sam's 4 x $175 and Gigi's 4 x $750
//      keep rendering from it with no schedule rows at all.
//   3. Nothing. Then the terms are UNKNOWN and must be shown as unknown —
//      never as the Offer's list price, which is a fact about the product
//      and not about the person. That substitution is what displayed a
//      scholarship client as "$1,400 Paid in full".
//
// The two are never mixed into one total. A schedule that disagreed with the
// snapshot would be two contradictory truths, so if a schedule exists the
// snapshot is not consulted for amounts at all.

export type CommercialTerms =
  | { kind: "unknown" }
  | {
      kind: "simple";
      total: number;
      installments: number;
      installmentAmount: number | null;
    }
  | {
      kind: "schedule";
      total: number;
      paidTotal: number;
      outstandingTotal: number;
      items: DealPaymentScheduleItem[];
      // True only when every live item is paid. Derived, never stored —
      // and still only a statement about the agreed schedule, not proof a
      // payment processor saw the money.
      fullySettled: boolean;
      // Whether any paid item is backed by a verified Stripe transaction,
      // so the UI can be honest about how it knows.
      hasVerifiedPayment: boolean;
    };

const isLive = (item: DealPaymentScheduleItem) => item.status !== "void";

export const resolveCommercialTerms = (
  deal: Pick<
    Deal,
    | "selected_payment_total"
    | "selected_installment_count"
    | "selected_installment_amount"
  >,
  scheduleItems: DealPaymentScheduleItem[] = [],
): CommercialTerms => {
  const live = scheduleItems.filter(isLive);

  if (live.length > 0) {
    const ordered = [...live].sort((a, b) => a.sequence - b.sequence);
    const total = ordered.reduce((sum, item) => sum + Number(item.amount), 0);
    const paidTotal = ordered
      .filter((item) => item.status === "paid")
      .reduce((sum, item) => sum + Number(item.amount), 0);
    return {
      kind: "schedule",
      total,
      paidTotal,
      outstandingTotal: total - paidTotal,
      items: ordered,
      fullySettled: ordered.every((item) => item.status === "paid"),
      hasVerifiedPayment: ordered.some(
        (item) => item.status === "paid" && item.source === "stripe",
      ),
    };
  }

  const total = deal.selected_payment_total;
  if (total == null) return { kind: "unknown" };

  return {
    kind: "simple",
    total: Number(total),
    installments: deal.selected_installment_count ?? 1,
    installmentAmount:
      deal.selected_installment_amount != null
        ? Number(deal.selected_installment_amount)
        : null,
  };
};

