  | { applied: false; reason: "not-offboarding" }
  | {
      applied: false;
      reason: "requirements-incomplete";
      missingKeys: string[];
    };

// Client Offboarding slice (§8): the explicit human "Complete client"
// action — mirrors activateEnrollment.ts's own shape exactly, including
// its own header comment's reasoning: re-fetches current server state
// (never trusts the caller's copy) so a double-click, a stale tab, or
// Back/Forward is a safe no-op rather than a second write.
//
// The DB's own enforce_enrollment_completion_requirements() trigger
// (02_functions.sql) is the authoritative guard — it fires on this same
// update and would reject it regardless of what this function checks
// first. The check here exists so the UI can show a specific, friendly
// `requirements-incomplete` reason (with the actual missing keys) instead
// of surfacing a raised Postgres exception.
export const completeClient = async (
  dataProvider: DataProvider,
  enrollmentId: Identifier,
): Promise<CompleteClientResult> => {
  const { data: enrollment } = await dataProvider.getOne<Enrollment>(
    "enrollments",
    { id: enrollmentId },
  );
  if (enrollment.status !== "offboarding") {
    return { applied: false, reason: "not-offboarding" };
  }

  const { data: items } = await dataProvider.getList<EnrollmentOffboardingItem>(
    "enrollment_offboarding_items",
    {
      filter: { enrollment_id: enrollmentId },
      pagination: { page: 1, perPage: 100 },
      sort: { field: "sort_order", order: "ASC" },
    },
  );
  const missingKeys = items
    .filter((item) => item.is_required && item.status !== "done")
    .map((item) => item.requirement_key);
  if (missingKeys.length > 0) {
    return { applied: false, reason: "requirements-incomplete", missingKeys };
  }

  await dataProvider.update("enrollments", {
    id: enrollment.id,
    data: { status: "completed" },
    previousData: enrollment,
  });

  return { applied: true };
};

import type { Enrollment } from "../types";

// Whether somebody is a client RIGHT NOW is a question about dates, not
// about a status column.
//
// Daniel Alexander appeared under Current Clients with a container that
// starts on 8 November — seven weeks away. His Enrollment status is
// "active", and status alone was the whole classification, so "we have
// agreed and set this up" was being read as "this is happening now". Leif
// cannot plan around a Current list that includes people he has not
// started working with.
//
// So the four inputs the question actually depends on are all used:
// start_date, end_date, the terminal statuses, and today.
export type EnrollmentPhase = "upcoming" | "current" | "past";

// completed / withdrawn / ended are all historically finished, however
// differently they got there — the row's own status badge is what
// distinguishes someone who finished from someone who left.
const TERMINAL_STATUSES: ReadonlySet<string> = new Set([
  "completed",
  "withdrawn",
  "ended",
]);

export const classifyEnrollment = (
  enrollment: Pick<Enrollment, "status" | "start_date" | "end_date">,
  today: string = toDateKey(new Date()),
): EnrollmentPhase => {
  // A terminal status is decisive regardless of dates: somebody who
  // withdrew last week is not "current" because their container would
  // still have been running.
  if (TERMINAL_STATUSES.has(enrollment.status)) return "past";

  // A container whose end date has passed is finished in substance even if
  // nobody has recorded the terminal status yet.
  if (enrollment.end_date && enrollment.end_date < today) return "past";

  // Not started yet. Includes onboarding — agreeing terms and setting
  // somebody up is real work, but it is not the programme running.
  if (enrollment.start_date && enrollment.start_date > today) {
    return "upcoming";
  }

  // Started and not finished. An enrollment with no start_date at all
  // falls here rather than being hidden: it is live work whose date was
  // never recorded, and the row says "Start date not set" truthfully
  // instead of being filed as upcoming on a date nobody knows.
  return "current";
};

// Current clients, newest-starting first — Leif's own requested order, so
// the person he most recently began with is at the top. An enrollment with
// no start date sorts last rather than being treated as infinitely old,
// and id descending breaks ties so the order never shuffles between
// renders.
export const byNewestStartFirst = (
  a: Pick<Enrollment, "id" | "start_date">,
  b: Pick<Enrollment, "id" | "start_date">,
): number => {
  const aKey = a.start_date ?? "";
  const bKey = b.start_date ?? "";
  if (aKey !== bKey) {
    if (!aKey) return 1;
    if (!bKey) return -1;
    return bKey.localeCompare(aKey);
  }
  return Number(b.id) - Number(a.id);
};

// Upcoming reads the other way round: the container starting soonest is
// the one Leif needs to prepare for next.
export const bySoonestStartFirst = (
  a: Pick<Enrollment, "id" | "start_date">,
  b: Pick<Enrollment, "id" | "start_date">,
): number => {
  const aKey = a.start_date ?? "";
  const bKey = b.start_date ?? "";
  if (aKey !== bKey) {
    if (!aKey) return 1;
    if (!bKey) return -1;
    return aKey.localeCompare(bKey);
  }
  return Number(a.id) - Number(b.id);
};

const toDateKey = (value: Date): string =>
  `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, "0")}-${String(
    value.getDate(),
  ).padStart(2, "0")}`;

import type { DataProvider, Identifier } from "ra-core";

import type { Enrollment, EnrollmentOnboardingItem } from "../types";

export type ActivateEnrollmentResult =
  | { applied: true }
  | { applied: false; reason: "not-onboarding" }
  | {
      applied: false;
      reason: "requirements-incomplete";
      missingKeys: string[];
    };

// Contracts + Onboarding slice: the explicit human Activate action
// (architecture review, §6 — Leif's approved bias, option B). Mirrors
// reviewApplication.ts's own shape exactly: re-fetches current server
// state (never trusts the caller's copy) so a double-click, a stale tab,
// or Back/Forward is a safe no-op rather than a second write — the caller
// checks `applied` and shows the real current state rather than assuming
// success.
//
// The DB's own enforce_enrollment_activation_requirements() trigger
// (02_functions.sql) is the authoritative guard — it fires on this same
// update and would reject it regardless of what this function checks
// first. The check here exists so the UI can show a specific, friendly
// `requirements-incomplete` reason (with the actual missing keys) instead
// of surfacing a raised Postgres exception.
export const activateEnrollment = async (
  dataProvider: DataProvider,
  enrollmentId: Identifier,
): Promise<ActivateEnrollmentResult> => {
  const { data: enrollment } = await dataProvider.getOne<Enrollment>(
    "enrollments",
    { id: enrollmentId },
  );
  if (enrollment.status !== "onboarding") {
    return { applied: false, reason: "not-onboarding" };
  }

  const { data: items } = await dataProvider.getList<EnrollmentOnboardingItem>(
    "enrollment_onboarding_items",
    {
      filter: { enrollment_id: enrollmentId },
      pagination: { page: 1, perPage: 100 },
      sort: { field: "sort_order", order: "ASC" },
    },
  );
  const missingKeys = items
    .filter((item) => item.is_required && item.status !== "done")
    .map((item) => item.requirement_key);
  if (missingKeys.length > 0) {
    return { applied: false, reason: "requirements-incomplete", missingKeys };
  }

  await dataProvider.update("enrollments", {
    id: enrollment.id,
    data: {
      status: "active",
      // Client + Session Operations slice A: the authoritative "trustworthy
      // service start date" the Service Period model is built on (see
      // sync_year_planning_calendar/assignEnrollmentExpectedSessions.ts) —
      // "when did this client's own 12-session cadence begin." Already populated
      // for a cohort-based Enrollment (handle_deal_won() snapshots the
      // Cohort's program_start_at); an individually-paced Enrollment (e.g.
      // a 1:1 Living Example engagement) has no Cohort to snapshot from,
      // so this is where it becomes known — the real moment onboarding
      // finished and active service begins. Never overwrites an
      // already-set date (idempotent, and never rewrites a genuine
      // Cohort-derived date).
      ...(enrollment.start_date == null
        ? { start_date: new Date().toISOString().split("T")[0] }
        : {}),
    },
    previousData: enrollment,
  });

  return { applied: true };
};

