import { useClientSessionCadence } from "../sessions/useClientSessionCadence";
import type {
  ClientSession,
  Contact,
  Enrollment,
  EnrollmentOffboardingItem,
  EnrollmentOnboardingItem,
  Offer,
  DealPaymentScheduleItem,
} from "../types";
