  const start = row.enrollment.start_date
    ? `Starts ${formatISODateString(row.enrollment.start_date)}`
    : "Start date not set";
  const end = row.enrollment.end_date
    ? `Ends ${formatISODateString(row.enrollment.end_date)}`
