// Loads the (small, fixture-scale) deals/offers/enrollments once and
// returns a lookup function, so every row rendered by the Person field's
// AutocompleteInput shares one cached fetch instead of one each.
export const usePersonContextLabels = () => {
  const { data: deals } = useGetList<Deal>("deals", {
    pagination: { page: 1, perPage: 1000 },
    sort: { field: "id", order: "ASC" },
  });
  const { data: offers } = useGetList<Offer>("offers", {
    pagination: { page: 1, perPage: 100 },
  });
  const { data: enrollments } = useGetList<Enrollment>("enrollments", {
    pagination: { page: 1, perPage: 1000 },
  });

  return useMemo(() => {
    const offersById = new Map(
      (offers ?? []).map((offer) => [String(offer.id), offer]),
    );
    const enrollmentsByOpportunity = new Map(
      (enrollments ?? []).map((enrollment) => [
        String(enrollment.opportunity_id),
        enrollment,
      ]),
    );
    return (contactId: Identifier) =>
      derivePersonContextLabel({
        contactId,
        deals: deals ?? [],
        offersById,
        enrollmentsByOpportunity,
      });
  }, [deals, offers, enrollments]);
};

import { getSupabaseClient } from "../providers/supabase/supabase";

// "Sync Stripe" for one person.
//
// The browser never holds a Stripe key. supabase.functions.invoke sends
// the signed-in user's own JWT, and the Edge Function — which is where the
// Stripe credentials live — verifies it before doing anything. The only
// customers it can ever touch are the ones already VERIFIED as belonging
// to the Contact whose id is passed, so this cannot be used to walk
// somebody else's Stripe account, and an unverified customer found by
// matching an email address is never reachable this way at all.
export type SyncStripeResult = {
  status: "linked" | "already-linked" | "none-found" | "needs-review" | "error";
  message: string;
};

export const syncStripeForContact = async (
  contactId: number | string,
): Promise<SyncStripeResult> => {
  const numericId = Number(contactId);
  if (!Number.isInteger(numericId) || numericId <= 0) {
    return { status: "error", message: "That person has no usable id." };
  }

  const { data, error } = await getSupabaseClient().functions.invoke<{
    status?: string;
    delta?: {
      schedulesLinked: number;
      subscriptionsLinked: number;
      alreadyLinked: number;
      noStripePlan: number;
      paymentsIngested: number;
      planObjectsRecorded: number;
      planObjectsUpdated: number;
      needsReview: { contactId: number; reason: string }[];
      ambiguous: { contactId: number; candidates: string[] }[];
      errors: string[];
    };
  }>(`stripe_webhook?action=reconcile&contactId=${numericId}`, {
    method: "POST",
    body: {},
  });

  if (error || !data?.delta) {
    return {
      status: "error",
      message: "Could not reach Stripe just now — nothing was changed.",
    };
  }

  const delta = data.delta;

  if (delta.errors.length > 0) {
    return { status: "error", message: delta.errors[0] };
  }
  if (delta.ambiguous.length > 0) {
    // Fails closed rather than picking one, and says so.
    return {
      status: "needs-review",
      message:
        "Stripe match needs review — more than one plan or Opportunity could be the right one.",
    };
  }
  // A review raised by the sweep outranks the good news, because it is
  // the thing a human has to act on.
  if (delta.needsReview?.length > 0) {
    return { status: "needs-review", message: delta.needsReview[0].reason };
  }

  // Said in the order a person cares about: a new plan is the headline, new
  // money next, and "nothing changed" is a real, useful answer.
  if (delta.subscriptionsLinked > 0 || delta.schedulesLinked > 0) {
    return {
      status: "linked",
      message: "Stripe synced — new subscription found.",
    };
  }
  if (delta.paymentsIngested > 0) {
    const count = delta.paymentsIngested;
    return {
      status: "linked",
      message: `Stripe synced — ${count} payment${count === 1 ? "" : "s"} recorded.`,
    };
  }
  if (delta.planObjectsRecorded > 0 || delta.planObjectsUpdated > 0) {
    return { status: "linked", message: "Stripe synced — payments updated." };
  }
  if (delta.alreadyLinked > 0) {
    return {
      status: "already-linked",
      message: "Stripe synced — no new Stripe records.",
    };
  }
  return {
    status: "none-found",
    message: "Stripe synced — no Stripe records found for this person.",
  };
};

// Finding a Stripe Customer the CRM has never seen, for somebody who has
// none verified at all.
//
// Reconciliation only ever reads verified customers, which is what stops
// it attaching the wrong person's money — and which leaves a real gap when
// Leif creates a subscription by hand in the Stripe dashboard against a
// customer the CRM has no record of. Sam Milz is that case. Nothing fires,
// nothing matches, and the plan stays invisible forever.
//
// So the CRM proposes and the human decides. These two calls are that
// split, and an email match never links anything on its own.
export type DiscoveredStripeCustomer = {
  stripeCustomerId: string;
  name: string | null;
  email: string | null;
  created: string;
  liveSubscriptions: number;
  liveSchedules: number;
  succeededPayments: number;
  collectedMinor: number;
};

export const discoverStripeCustomers = async (
  contactId: number | string,
): Promise<DiscoveredStripeCustomer[]> => {
  const numericId = Number(contactId);
  if (!Number.isInteger(numericId) || numericId <= 0) return [];

  const { data, error } = await getSupabaseClient().functions.invoke<{
    candidates?: DiscoveredStripeCustomer[];
  }>(`stripe_webhook?action=discover&contactId=${numericId}`, {
    method: "POST",
    body: {},
  });
  if (error || !data?.candidates) return [];
  return data.candidates;
};

export const linkStripeCustomer = async (
  contactId: number | string,
  stripeCustomerId: string,
): Promise<SyncStripeResult> => {
  const numericId = Number(contactId);
  if (!Number.isInteger(numericId) || numericId <= 0) {
    return { status: "error", message: "That person has no usable id." };
  }

  const { data, error } = await getSupabaseClient().functions.invoke<{
    status?: string;
    contactId?: number;
  }>(
    `stripe_webhook?action=link_customer&contactId=${numericId}&customerId=${encodeURIComponent(stripeCustomerId)}`,
    { method: "POST", body: {} },
  );

  if (error || !data?.status) {
    return {
      status: "error",
      message: "Could not reach Stripe just now — nothing was changed.",
    };
  }
  if (data.status === "claimed-by-another-contact") {
    // Refused rather than moved. Two people cannot own one customer.
    return {
      status: "needs-review",
      message:
        "That Stripe customer is already linked to somebody else. Nothing was changed.",
    };
  }
  if (data.status === "already-linked") {
    return { status: "already-linked", message: "Already linked." };
  }
  if (data.status === "error") {
    return { status: "error", message: "Could not link that Stripe customer." };
  }
  return { status: "linked", message: "Stripe customer linked and synced." };
};

import type { ConfigurationContextValue } from "../root/ConfigurationContext";
import type { Deal, SalesCall } from "../types";
import {
  comparatorForStage,
  nextBookedCallByOpportunity,
} from "./pipelineOrdering";

export type DealsByStage = Record<Deal["stage"], Deal[]>;

export const getDealsByStage = (
  unorderedDeals: Deal[],
  dealStages: ConfigurationContextValue["dealStages"],
  // Sales calls are what Call Booked is ordered by. Optional so every
  // existing caller keeps working; without them that column falls back to
  // "no booking known" for everyone and stays deterministic.
  salesCalls?: readonly Pick<
    SalesCall,
    "opportunity_id" | "status" | "scheduled_at" | "scheduled_on"
  >[],
  now?: number,
) => {
  if (!dealStages) return {};
  const dealsByStage: Record<Deal["stage"], Deal[]> = unorderedDeals.reduce(
    (acc, deal) => {
      // if deal has a stage that does not exist in configuration, assign it to the first stage
      const stage = dealStages.find((s) => s.value === deal.stage)
        ? deal.stage
        : dealStages[0].value;
      acc[stage].push(deal);
      return acc;
    },
    dealStages.reduce(
      (obj, stage) => ({ ...obj, [stage.value]: [] }),
      {} as Record<Deal["stage"], Deal[]>,
    ),
  );
  // Each column sorts by what that column is FOR — see
  // pipelineOrdering.ts for the rule per stage and why. One shared
  // "longest in stage first" rule used to apply everywhere, which put a
  // stale unresolved call above a call happening in two hours.
  const nextCallAt = nextBookedCallByOpportunity(salesCalls);
  dealStages.forEach((stage) => {
    dealsByStage[stage.value] = dealsByStage[stage.value].sort(
      comparatorForStage(stage.value, { nextCallAt, now }),
    );
  });

  return dealsByStage;
};

import type { DataProvider, Identifier } from "ra-core";

import type {
  OfferPaymentOption,
  PricingMode,
  ScholarshipSlot,
} from "../types";

// Scholarship Pricing + Capacity slice: the FakeRest mirror of the
// Postgres-side scholarship-slot mechanism (handle_deal_saved()/
// handle_deal_won()/handle_enrollment_scholarship_slot_transition() in
// supabase/schemas/02_functions.sql) — same dual-implementation convention
// as offerCohortValidation.ts/waitlistEntryValidation.ts. FakeRest is
// single-threaded and sequential (no real races), so a plain read-then-
// write is sufficient there; the actual atomic, race-proof guarantee is
// the real Postgres trigger's `INSERT ... ON CONFLICT ... WHERE` — see
// that function's own comment. This file exists so demo/dev mode enforces
// the identical business rule, not to itself prove concurrency safety.

export class ScholarshipSlotUnavailableError extends Error {}
export class ScholarshipPricingModeError extends Error {}

const findScholarshipSlot = async (
  dataProvider: DataProvider,
  offerId: Identifier,
): Promise<ScholarshipSlot | null> => {
  const { data } = await dataProvider.getList<ScholarshipSlot>(
    "scholarship_slots",
    {
      filter: { offer_id: offerId },
      pagination: { page: 1, perPage: 1 },
      sort: { field: "id", order: "ASC" },
    },
  );
  return data[0] ?? null;
};

const isFree = (slot: ScholarshipSlot | null): boolean =>
  !slot || (slot.holder_deal_id == null && slot.holder_enrollment_id == null);

const appendSlotEvent = async (
  dataProvider: DataProvider,
  event: {
    offerId: Identifier;
    dealId?: Identifier | null;
    enrollmentId?: Identifier | null;
    eventType:
      | "scholarship_granted"
      | "scholarship_released"
      | "deal_converted_to_enrollment"
      | "enrollment_completed_slot_released"
      | "slot_reclaimed_after_backward_lifecycle_correction";
  },
): Promise<void> => {
  await dataProvider.create("scholarship_slot_events", {
    data: {
      offer_id: event.offerId,
      deal_id: event.dealId ?? null,
      enrollment_id: event.enrollmentId ?? null,
      event_type: event.eventType,
      occurred_at: new Date().toISOString(),
    },
  });
};

// Atomic (in FakeRest's single-threaded sense) grant: claims this Offer's
// single scholarship slot for this Deal. Throws ScholarshipSlotUnavailableError
// if another Deal/Enrollment already holds it — never silently displaces
// a holder.
export const claimScholarshipSlotForDeal = async (
  dataProvider: DataProvider,
  { offerId, dealId }: { offerId: Identifier; dealId: Identifier },
): Promise<void> => {
  const slot = await findScholarshipSlot(dataProvider, offerId);
  if (!isFree(slot)) {
    throw new ScholarshipSlotUnavailableError(
      `Scholarship slot for offer ${offerId} is already held`,
    );
  }
  const reservedAt = new Date().toISOString();
  if (slot) {
    await dataProvider.update("scholarship_slots", {
      id: slot.id,
      data: { holder_deal_id: dealId, reserved_at: reservedAt },
      previousData: slot,
    });
  } else {
    await dataProvider.create("scholarship_slots", {
      data: {
        offer_id: offerId,
        holder_deal_id: dealId,
        reserved_at: reservedAt,
      },
    });
  }
  await appendSlotEvent(dataProvider, {
    offerId,
    dealId,
    eventType: "scholarship_granted",
  });
};

// Releases a slot this exact Deal currently holds. A safe no-op (matching
// the Postgres trigger's own guarantee) if this Deal isn't actually the
// current holder — the pre-Won immutability guard and the "only ever the
// genuine holder can reach this branch" invariant already make that the
// expected case in practice, not something this function needs to enforce
// itself.
export const releaseScholarshipSlotForDeal = async (
  dataProvider: DataProvider,
  { offerId, dealId }: { offerId: Identifier; dealId: Identifier },
): Promise<void> => {
  const slot = await findScholarshipSlot(dataProvider, offerId);
  if (!slot || String(slot.holder_deal_id ?? "") !== String(dealId)) return;

  await dataProvider.update("scholarship_slots", {
    id: slot.id,
    data: { holder_deal_id: null, reserved_at: null },
    previousData: slot,
  });
  await appendSlotEvent(dataProvider, {
    offerId,
    dealId,
    eventType: "scholarship_released",
  });
};

// Won transition: atomically (in FakeRest's sequential sense) hands the
// slot this Deal held over to its newly-created Enrollment — mirrors
// handle_deal_won()'s own single-UPDATE transition exactly.
export const transitionScholarshipSlotToEnrollment = async (
  dataProvider: DataProvider,
  {
    offerId,
    dealId,
    enrollmentId,
  }: { offerId: Identifier; dealId: Identifier; enrollmentId: Identifier },
): Promise<void> => {
  const slot = await findScholarshipSlot(dataProvider, offerId);
  if (!slot || String(slot.holder_deal_id ?? "") !== String(dealId)) {
    throw new ScholarshipPricingModeError(
      `Deal ${dealId} reached Won as scholarship but held no scholarship slot for offer ${offerId} — data inconsistency`,
    );
  }
  await dataProvider.update("scholarship_slots", {
    id: slot.id,
    data: { holder_deal_id: null, holder_enrollment_id: enrollmentId },
    previousData: slot,
  });
  await appendSlotEvent(dataProvider, {
    offerId,
    dealId,
    enrollmentId,
    eventType: "deal_converted_to_enrollment",
  });
};

// Enrollment completion: releases the slot this Enrollment holds, if any
// (a standard Enrollment never holds one, so this is a safe no-op for it).
export const releaseScholarshipSlotForEnrollment = async (
  dataProvider: DataProvider,
  { enrollmentId }: { enrollmentId: Identifier },
): Promise<void> => {
  const { data: slots } = await dataProvider.getList<ScholarshipSlot>(
    "scholarship_slots",
    {
      filter: { holder_enrollment_id: enrollmentId },
      pagination: { page: 1, perPage: 1 },
      sort: { field: "id", order: "ASC" },
    },
  );
  const slot = slots[0];
  if (!slot) return;

  await dataProvider.update("scholarship_slots", {
    id: slot.id,
    data: { holder_enrollment_id: null },
    previousData: slot,
  });
  await appendSlotEvent(dataProvider, {
    offerId: slot.offer_id,
    enrollmentId,
    eventType: "enrollment_completed_slot_released",
  });
};

// Backward lifecycle correction off of "completed": attempts to reclaim
// the slot for this Enrollment's Offer. Throws ScholarshipSlotUnavailableError
// if another Deal/Enrollment has since claimed it — the correction must be
// rejected outright, never silently displacing another holder.
export const reclaimScholarshipSlotForEnrollment = async (
  dataProvider: DataProvider,
  { offerId, enrollmentId }: { offerId: Identifier; enrollmentId: Identifier },
): Promise<void> => {
  const slot = await findScholarshipSlot(dataProvider, offerId);
  if (!isFree(slot)) {
    throw new ScholarshipSlotUnavailableError(
      `Cannot reopen enrollment ${enrollmentId}: scholarship slot for offer ${offerId} is already held by another Deal/Enrollment`,
    );
  }
  const reservedAt = new Date().toISOString();
  if (slot) {
    await dataProvider.update("scholarship_slots", {
      id: slot.id,
      data: { holder_enrollment_id: enrollmentId, reserved_at: reservedAt },
      previousData: slot,
    });
  } else {
    await dataProvider.create("scholarship_slots", {
      data: {
        offer_id: offerId,
        holder_enrollment_id: enrollmentId,
        reserved_at: reservedAt,
      },
    });
  }
  await appendSlotEvent(dataProvider, {
    offerId,
    enrollmentId,
    eventType: "slot_reclaimed_after_backward_lifecycle_correction",
  });
};

// --- Deal-save validation guards (mirror handle_deal_saved()'s own raises) ---

export const assertScholarshipGrantedOnlyViaEdit = (
  isCreate: boolean,
  pricingMode: PricingMode | undefined,
): void => {
  if (isCreate && pricingMode === "scholarship") {
    throw new ScholarshipPricingModeError(
      "A new Opportunity cannot be created directly as scholarship — grant scholarship pricing via Deal edit after creation",
    );
  }
};

export const assertPricingModeImmutableOnceWon = (
  previousData: { stage?: string; pricing_mode?: PricingMode } | undefined,
  nextPricingMode: PricingMode | undefined,
  dealId: Identifier,
): void => {
  if (
    previousData?.stage === "won" &&
    nextPricingMode != null &&
    nextPricingMode !== previousData.pricing_mode
  ) {
    throw new ScholarshipPricingModeError(
      `Cannot change pricing_mode on deal ${dealId} once it has reached Won`,
    );
  }
};

export const assertNoOfferChangeWhileScholarship = (
  previousData:
    | { pricing_mode?: PricingMode; offer_id?: Identifier }
    | undefined,
  nextOfferId: Identifier | undefined,
  dealId: Identifier,
): void => {
  if (
    previousData?.pricing_mode === "scholarship" &&
    nextOfferId != null &&
    String(nextOfferId) !== String(previousData.offer_id)
  ) {
    throw new ScholarshipPricingModeError(
      `Cannot change offer_id on deal ${dealId} while it holds a scholarship reservation — release scholarship pricing first`,
    );
  }
};

export const assertPaymentOptionMatchesPricingMode = (
  option: { offer_id: Identifier; pricing_mode?: PricingMode },
  offerId: Identifier,
  pricingMode: PricingMode,
  dealId: Identifier | undefined,
  paymentOptionId: Identifier,
): void => {
  if (
    String(option.offer_id) !== String(offerId) ||
    (option.pricing_mode ?? "standard") !== pricingMode
  ) {
    throw new ScholarshipPricingModeError(
      `Payment option ${paymentOptionId} does not match deal ${dealId}'s offer/pricing_mode`,
    );
  }
};

// Shared by grantScholarshipPricing.ts/releaseScholarshipReservation.ts —
// NOT a FakeRest mirror (dataProvider-agnostic, used identically against
// either backend). A payment option selected under the OLD pricing_mode is,
// by definition, invalid under the new one — clearing it in the SAME write
// that changes pricing_mode avoids the DB's own cross-validation
// (assertPaymentOptionMatchesPricingMode / handle_deal_saved()'s mirror)
// rejecting the grant/release outright whenever a now-stale option happens
// to still be selected. Returns an empty object when there's nothing stale
// to clear, so a plain spread into the update payload is always safe.
export const buildStalePaymentOptionClear = async (
  dataProvider: DataProvider,
  deal: { selected_payment_option_id?: Identifier | null },
  nextPricingMode: PricingMode,
): Promise<
  Partial<{
    selected_payment_option_id: null;
    selected_payment_total: null;
    selected_installment_count: null;
    selected_installment_amount: null;
  }>
> => {
  if (deal.selected_payment_option_id == null) return {};

  const option = await dataProvider
    .getOne<OfferPaymentOption>("offer_payment_options", {
      id: deal.selected_payment_option_id,
    })
    .then(({ data }) => data)
    .catch(() => null);

  if (option && (option.pricing_mode ?? "standard") === nextPricingMode) {
    return {};
  }

  return {
    selected_payment_option_id: null,
    selected_payment_total: null,
    selected_installment_count: null,
    selected_installment_amount: null,
  };
};

import type { Identifier } from "ra-core";

// Scholarship Pricing + Capacity slice, stale-Checkout-Session invariant:
// "old commercial terms must not remain payable after Leif changes a
// Deal's pricing mode" (Leif's own explicit decision). The Postgres
// pricing_mode UPDATE and an external Stripe API call can never share one
// database transaction, so this is a deliberately BEST-EFFORT, non-
// blocking side effect — never a gate on the grant/release itself
// succeeding (that would let an unrelated Stripe outage block a purely
// commercial CRM decision). The real, bulletproof backstop that does NOT
// depend on this call ever succeeding is reactive: stripe_webhook/index.ts
// re-validates a Checkout Session's own pricing_mode against the Deal's
// CURRENT pricing_mode at the moment a payment actually succeeds, and
// refuses to mark Won on a stale-terms match. This invalidator only
// removes the (rare, narrow) window where a bored/curious prospect could
// still see a stale, already-superseded payment link — see
// grantScholarshipPricing.ts/releaseScholarshipReservation.ts for how its
// outcome is surfaced (never silently swallowed) rather than pretended
// consistent.
export type InvalidateStaleCheckoutResult =
  | { status: "not-applicable" }
  | { status: "invalidated" }
  | { status: "failed" };

export type ScholarshipCheckoutInvalidator = (
  dealId: Identifier,
) => Promise<InvalidateStaleCheckoutResult>;

// Demo/FakeRest default: no real Stripe integration exists in demo mode, so
// there is never a live Checkout Session to invalidate.
export const noopScholarshipCheckoutInvalidator: ScholarshipCheckoutInvalidator =
  async () => ({ status: "not-applicable" });

import type { DataProvider, Identifier } from "ra-core";

import type { Contact, Deal, OfferPaymentOption } from "../types";
import type { ConfigurationContextValue } from "../root/ConfigurationContext";

// Stripe test-mode integration slice: the SECURITY-CRITICAL authorization
// boundary between the public Offer Page and real money. The browser only
// ever sends a Deal's opaque token and the id of the payment option it
// wants — every commercial term actually charged (amount, currency,
// installment count) is resolved fresh from CRM state here, never trusted
// from the request. Mirrors publicOfferPageContext.ts's own token
// resolution and payment-option-authorization logic exactly (both must
// agree on "which options are valid for this Deal" — see
// publicOfferPageContext.test.ts for the shared cases).
//
// Deliberately READ-ONLY — never writes selected_payment_option_id itself.
// An earlier version of this function froze the Deal's commercial snapshot
// the moment a Checkout attempt was authorized, which turned out wrong:
// it conflated two different meanings of that one field — Leif explicitly
// pre-authorizing ONE specific option before the Offer Page ever existed
// (the case this function's own "only that option is valid" rule is
// about), versus a prospect's own still-changeable in-progress choice
// during checkout (which must stay free to change — including across an
// abandoned attempt — until money actually changes hands). Freezing the
// snapshot now belongs to the payment-success path instead (the Edge
// Function's fulfillment step, alongside the Won transition) — commercial
// terms become durable exactly when a real payment succeeds, not merely
// when a Checkout Session was created. This function only ever reads.
//
// Never calls the Stripe API itself — that's the Edge Function's job
// (untestable via FakeRest); this module stays the FakeRest-testable
// "logic of record" it mirrors by hand, same dual-implementation
// convention as every other integration in this app.
export type CheckoutTermsResult =
  | { status: "not-found" }
  | { status: "already-won" }
  | { status: "unauthorized-option" }
  | {
      status: "authorized";
      dealId: Identifier;
      contactId: Identifier;
      contactName: string;
      contactEmail: string | null;
      existingStripeCustomerId: string | null;
      currency: string;
      offerName: string;
      paymentOptionId: Identifier;
      // installments === 1 means a one-time payment (PIF); > 1 means the
      // fixed-installment plan (Architecture B, approved 2026-09).
      installments: number;
      // Always the amount of ONE charge in the smallest currency unit
      // (cents for USD) — total for PIF, per-installment amount
      // otherwise. Stripe's own unit, computed here so the Edge Function
      // never does its own arithmetic on a client-supplied number.
      unitAmountCents: number;
    };

export const resolveAuthorizedCheckoutTerms = async (
  dataProvider: DataProvider,
  { token, paymentOptionId }: { token: string; paymentOptionId: Identifier },
): Promise<CheckoutTermsResult> => {
  const { data: deals } = await dataProvider.getList<Deal>("deals", {
    filter: { offer_page_token: token },
    pagination: { page: 1, perPage: 1 },
    sort: { field: "id", order: "ASC" },
  });
  const deal = deals[0];
  if (!deal || deal.offer_price_snapshot == null)
    return { status: "not-found" };
  if (deal.stage === "won") return { status: "already-won" };

  const option = await resolveAuthorizedOption(
    dataProvider,
    deal,
    paymentOptionId,
  );
  if (!option) return { status: "unauthorized-option" };

  const contact = await dataProvider
    .getOne<Contact>("contacts", { id: deal.contact_id! })
    .then(({ data }) => data)
    .catch(() => null);
  if (!contact) return { status: "not-found" };

  const { data: configRecord } = await dataProvider
    .getOne<{
      id: number;
      config: ConfigurationContextValue;
    }>("configuration", { id: 1 })
    .catch(() => ({
      data: null as { config: ConfigurationContextValue } | null,
    }));
  const currency = configRecord?.config?.currency ?? "USD";

  const unitAmountCents = Math.round(
    (option.installments === 1 ? option.total : option.installment_amount) *
      100,
  );

  return {
    status: "authorized",
    dealId: deal.id,
    contactId: contact.id,
    contactName:
      `${contact.first_name ?? ""} ${contact.last_name ?? ""}`.trim(),
    contactEmail: contact.email_jsonb?.[0]?.email ?? null,
    existingStripeCustomerId: contact.stripe_customer_id ?? null,
    currency,
    offerName: deal.offer_name_snapshot ?? "",
    paymentOptionId: option.id,
    installments: option.installments,
    unitAmountCents,
  };
};

// Same rule publicOfferPageContext.ts's own resolvePaymentOptions applies:
// exactly the one option Leif already authorized for this Deal (set
// through the normal Deal edit form, never by this function), or every
// publicly-offered option of the Deal's Offer otherwise. Returns the live
// offer_payment_options row (never the Deal's own snapshot, which may not
// exist yet before a payment has ever succeeded).
//
// Scholarship Pricing + Capacity slice: every path below is also scoped by
// deal.pricing_mode — a standard-priced option (including a non-public
// Financial Need plan) can never become selectable for a scholarship Deal,
// and a scholarship option can never become selectable for a standard
// Deal, even if a stale/mismatched selected_payment_option_id somehow
// reached this Deal (the DB's own handle_deal_saved() cross-validation is
// the authoritative backstop for that — see this function's own header).
const resolveAuthorizedOption = async (
  dataProvider: DataProvider,
  deal: Deal,
  requestedOptionId: Identifier,
): Promise<OfferPaymentOption | null> => {
  if (deal.selected_payment_option_id != null) {
    if (String(deal.selected_payment_option_id) !== String(requestedOptionId)) {
      return null;
    }
    const option = await dataProvider
      .getOne<OfferPaymentOption>("offer_payment_options", {
        id: deal.selected_payment_option_id,
      })
      .then(({ data }) => data)
      .catch(() => null);
    return option &&
      (option.pricing_mode ?? "standard") === (deal.pricing_mode ?? "standard")
      ? option
      : null;
  }

  const { data: options } = await dataProvider.getList<OfferPaymentOption>(
    "offer_payment_options",
    {
      filter: {
        offer_id: deal.offer_id,
        is_public: true,
        pricing_mode: deal.pricing_mode ?? "standard",
      },
      pagination: { page: 1, perPage: 20 },
      sort: { field: "id", order: "ASC" },
    },
  );
  return (
    options.find((option) => String(option.id) === String(requestedOptionId)) ??
    null
  );
};

import type { DataProvider, Identifier } from "ra-core";

import type { Deal } from "../types";

// Approved usually means "approved, and no call is currently booked" —
// which is exactly where Mihaela landed after Leif cancelled her call.
// There was no way to resolve somebody from there except dragging the card
// to a trash metaphor, which is wrong twice over: nothing is deleted, and
// "gone from my board" covers at least two different business meanings
// that Leif needs to tell apart later.
//
// These reuse the outcomes the app already has. No new stage and no new
// outcome value is introduced — Approved already exists, and waiting in it
// is a legitimate state rather than a gap to fill.
export type ApprovedResolution =
  // Stay Approved and wait for them to book. Explicitly an answer, so the
  // UI can offer "I looked at this and there is nothing to do yet" instead
  // of leaving Leif to wonder whether he forgot someone.
  | "await-booking"
  // Not now, but not over. Leaves the active pipeline; the relationship
  // stays real.
  | "nurture"
  // Over.
  | "lost";

export type ResolveApprovedResult =
  | { status: "resolved"; resolution: ApprovedResolution }
  | { status: "unchanged" }
  | { status: "not-found" }
  | { status: "already-resolved" };

export const resolveApprovedOpportunity = async (
  dataProvider: DataProvider,
  {
    opportunityId,
    resolution,
  }: { opportunityId: Identifier; resolution: ApprovedResolution },
): Promise<ResolveApprovedResult> => {
  const { data: deal } = await dataProvider
    .getOne<Deal>("deals", { id: opportunityId })
    .catch(() => ({ data: null as Deal | null }));
  if (!deal) return { status: "not-found" };

  if (
    deal.archived_at != null ||
    deal.outcome != null ||
    deal.stage === "won"
  ) {
    return { status: "already-resolved" };
  }

  // Keeping it Approved is a real answer, and the truthful implementation
  // of that answer is to change nothing. It must not invent a timestamp or
  // a stage event to look like it did something.
  if (resolution === "await-booking") {
    return { status: "unchanged" };
  }

  await dataProvider.update<Deal>("deals", {
    id: deal.id,
    data: { outcome: resolution === "nurture" ? "nurture" : "lost" },
    previousData: deal,
  });

  return { status: "resolved", resolution };
};

export const isAwaitingBooking = (
  deal: Pick<Deal, "stage" | "outcome" | "archived_at">,
): boolean =>
  deal.archived_at == null && deal.outcome == null && deal.stage === "approved";

import type { DataProvider, Identifier } from "ra-core";

import type { Contact, Deal } from "../types";
import { ensureContactTag } from "../tags/ensureContactTag";
import { closeSalesDecisionTasks } from "./closeSalesTasks";
import { resolveDefaultTaskSalesId } from "../sales-calls/resolveDefaultTaskSalesId";
import { GHOSTED_TAG_NAME } from "./recordOpportunityDecision";
import {
  canRemoveFromPipeline,
  findExitReason,
  type PipelineExitReason,
} from "./pipelineExit";

const GHOSTED_TAG_COLOR = "#c9ccd2";

export type RemoveFromPipelineResult =
  | { status: "removed"; reason: PipelineExitReason }
  | { status: "not-found" }
  // Already out, or already Won. A second click, a stale tab, or two tabs
  // on the same drawer is a safe no-op — never a second write and never a
  // reopening.
  | { status: "already-resolved" }
  | { status: "note-required" };

// Ending a sales process, from any active stage.
//
// Nothing is deleted and nothing is archived: the Contact, the Deal, the
// calls, the notes and the history all stay exactly as they are. What
// changes is that this Opportunity stops being active work, and the CRM
// records which of the several meanings of "over" applies.
export const removeFromPipeline = async (
  dataProvider: DataProvider,
  {
    opportunityId,
    reason,
    note,
  }: {
    opportunityId: Identifier;
    reason: PipelineExitReason;
    note?: string | null;
  },
): Promise<RemoveFromPipelineResult> => {
  const definition = findExitReason(reason);
  const trimmedNote = note?.trim() || null;

  if (definition.requiresNote && !trimmedNote) {
    return { status: "note-required" };
  }

  const { data: deal } = await dataProvider
    .getOne<Deal>("deals", { id: opportunityId })
    .catch(() => ({ data: null as Deal | null }));
  if (!deal) return { status: "not-found" };
  if (!canRemoveFromPipeline(deal)) return { status: "already-resolved" };

  await dataProvider.update<Deal>("deals", {
    id: deal.id,
    data: {
      outcome: definition.outcome,
      exit_reason: definition.reason,
      exit_note: trimmedNote,
      // Only set when the reason actually carries that meaning — never
      // overwritten with null, so a decision recorded earlier survives.
      ...(definition.prospectDecision
        ? { prospect_decision: definition.prospectDecision }
        : {}),
      ...(definition.ownerDecision
        ? { owner_decision: definition.ownerDecision }
        : {}),
    },
    previousData: deal,
  });

  // The stage is deliberately left where it is. They really did reach
  // Decision, or Committed, or wherever they got to, and rewriting that to
  // mark an exit would falsify the history the board is built on.

  if (definition.appliesGhostedTag) {
    await ensureContactTag(
      dataProvider,
      deal.contact_id,
      GHOSTED_TAG_NAME,
      GHOSTED_TAG_COLOR,
    );
  }

  if (definition.setsContactDoNotEngage) {
    // A standing gate on future selling belongs to the person, not to one
    // Opportunity they happened to have.
    const { data: contact } = await dataProvider.getOne<Contact>("contacts", {
      id: deal.contact_id,
    });
    if (contact.sales_eligibility !== "do_not_engage") {
      await dataProvider.update<Contact>("contacts", {
        id: contact.id,
        data: { sales_eligibility: "do_not_engage" },
        previousData: contact,
      });
    }
  }

  // Human-readable history, in the place Leif already reads history. The
  // structured reason lives on the Deal; this is so the story is legible
  // months later without decoding an enum.
  const salesId = await resolveDefaultTaskSalesId(dataProvider);
  await dataProvider.create("deal_notes", {
    data: {
      deal_id: deal.id,
      text: trimmedNote
        ? `Removed from pipeline — ${definition.label}: ${trimmedNote}`
        : `Removed from pipeline — ${definition.label}`,
      date: new Date().toISOString(),
      ...(salesId != null ? { sales_id: salesId } : {}),
    },
  });

  // Anything that was waiting on this decision is answered by it.
  await closeSalesDecisionTasks(
    dataProvider,
    deal.contact_id,
    new Date().toISOString(),
  );

  return { status: "removed", reason: definition.reason };
};

import type { DataProvider, Identifier } from "ra-core";

import type { Deal, Offer } from "../types";
import {
  noopScholarshipCheckoutInvalidator,
  type InvalidateStaleCheckoutResult,
  type ScholarshipCheckoutInvalidator,
} from "./scholarshipCheckoutInvalidator";
import { buildStalePaymentOptionClear } from "./scholarshipSlotValidation";

export type ReleaseScholarshipReservationResult =
  | {
      status: "released";
      staleCheckoutInvalidation: InvalidateStaleCheckoutResult;
    }
  | { status: "not-found" }
  | { status: "not-scholarship" }
  | { status: "already-won" };

// The reverse of grantScholarshipPricing.ts — Leif explicitly reverting an
// outstanding (unpaid) scholarship Deal back to standard pricing. Only
// valid pre-Won (the DB trigger/FakeRest mirror already refuses a
// pricing_mode change once Won — see handle_deal_saved()'s own
// immutability guard); "already-won" here means "there is nothing left to
// release", not a genuine error.
export const releaseScholarshipReservation = async (
  dataProvider: DataProvider,
  dealId: Identifier,
  invalidateStaleCheckout: ScholarshipCheckoutInvalidator = noopScholarshipCheckoutInvalidator,
): Promise<ReleaseScholarshipReservationResult> => {
  const { data: deal } = await dataProvider
    .getOne<Deal>("deals", { id: dealId })
    .catch(() => ({ data: null as Deal | null }));
  if (!deal) return { status: "not-found" };
  if (deal.pricing_mode !== "scholarship") return { status: "not-scholarship" };
  if (deal.stage === "won") return { status: "already-won" };

  // See grantScholarshipPricing.ts's identical comment — a scholarship-only
  // option selected before release is invalid once standard again.
  const staleOptionClear = await buildStalePaymentOptionClear(
    dataProvider,
    deal,
    "standard",
  );

  // "Potential Value" (amount) follows the offer's current standard price
  // once released, for the same reason grantScholarshipPricing.ts sets it
  // to the scholarship price — never left stale at the old frozen amount.
  const { data: offer } = await dataProvider.getOne<Offer>("offers", {
    id: deal.offer_id,
  });

  await dataProvider.update<Deal>("deals", {
    id: deal.id,
    data: {
      pricing_mode: "standard",
      amount: offer.current_price,
      ...staleOptionClear,
    },
    previousData: deal,
  });

  const staleCheckoutInvalidation = await invalidateStaleCheckout(deal.id);
  return { status: "released", staleCheckoutInvalidation };
};

import type { DataProvider, Identifier } from "ra-core";

import type { Deal } from "../types";
import { closeSalesDecisionTasks } from "./closeSalesTasks";

// Yes or No, in Leif's words.
//
// The previous version offered Committed / Declined offer / Ghosted, which
// are CRM stages wearing human clothes: it made Leif decide what the
// internal model should do rather than telling the CRM what happened.
//
// YES means the sale was accepted. That is a SALES fact and nothing else,
// so it sets Won and stops there.
//
// An earlier draft of this gated Won on payment authority — Won only if a
// Stripe subscription or a recorded payment already existed, Committed
// otherwise. That is wrong, and four live clients proved it: Denise
// Cormier, Ava Frotton, Linda Turner and Emma Wijns were all stuck at
// Committed with no Enrollment, one of them PAID IN FULL and another
// already onboarded, purely because the CRM had not created their Stripe
// plan itself. Gating the sale on the payment plumbing made the CRM
// disagree with the business about who its clients were.
//
// These are four independent dimensions, and none of them may overwrite
// another:
//
//   sales outcome   did they say yes            -> deals.stage / outcome
//   payment         what has been agreed/paid   -> schedule items, Stripe
//   enrollment      are they in the programme    -> enrollments
//   onboarding      is their setup done          -> checklist items
//
// So Won does NOT mean paid in full, does not mean a subscription is
// active, and does not mean onboarding is complete. Payment remains
// visible and actionable in the drawer as its own outstanding work.
//
// NO hands straight to the same canonical reason flow as the Remove from
// pipeline action — one exit machinery, not two.
export type SalesDecisionResult =
  | { status: "won" }
  | { status: "not-found" }
  // Already out of the pipeline, or already Won. A second click or a stale
  // tab is a safe no-op, never a second write.
  | { status: "already-resolved" };

export const recordYes = async (
  dataProvider: DataProvider,
  { opportunityId }: { opportunityId: Identifier },
): Promise<SalesDecisionResult> => {
  const { data: deal } = await dataProvider
    .getOne<Deal>("deals", { id: opportunityId })
    .catch(() => ({ data: null as Deal | null }));
  if (!deal) return { status: "not-found" };

  if (
    deal.archived_at != null ||
    deal.outcome != null ||
    deal.stage === "won"
  ) {
    return { status: "already-resolved" };
  }

  await dataProvider.update<Deal>("deals", {
    id: deal.id,
    data: {
      stage: "won",
      stage_entered_at: new Date().toISOString(),
      prospect_decision: "yes",
    },
    previousData: deal,
  });

  // Gil's "follow up on Sep 22" existed because nobody knew what he
  // would decide. Now somebody does.
  await closeSalesDecisionTasks(
    dataProvider,
    deal.contact_id,
    new Date().toISOString(),
  );

  // The Enrollment follows from Won on the database side
  // (handle_deal_won(), idempotent on enrollments.opportunity_id), so the
  // client container and its onboarding checklist appear without this
  // action needing to know how either works.
  return { status: "won" };
};

import type { DataProvider, Identifier } from "ra-core";

import type { Deal } from "../types";
import { ensureContactTag } from "../tags/ensureContactTag";

// What happens when somebody at Decision actually decides.
//
// The Dashboard could show who was deciding and the Kanban could show the
// column, but there was no way to record the answer except by editing
// fields by hand — so people sat at Decision indefinitely and the widget
// that was supposed to say "these need you" slowly stopped meaning
// anything. These are canonical state mutations, not notes.
export const GHOSTED_TAG_NAME = "Ghosted";
// Same palette the manual tag UI uses (tags/colors.ts).
const GHOSTED_TAG_COLOR = "#c9ccd2";

export type OpportunityDecision =
  // They said yes. Stage advances; this is NOT Won — Won is payment
  // authority, and nobody has paid because somebody said yes.
  | "committed"
  // They considered the offer and said no.
  | "declined"
  // They stopped replying. Commercially the same as declined, humanly not
  // the same at all, and the difference is what decides whether Leif ever
  // writes to them again.
  | "ghosted";

export type RecordOpportunityDecisionResult =
  | { status: "recorded"; decision: OpportunityDecision }
  | { status: "not-found" }
  // Already closed or archived: a second click, a stale tab, or two tabs
  // open on the same Dashboard card is a safe no-op, never a second write
  // and never a reopening.
  | { status: "already-resolved" };

const DECIDING_STAGE = "decision";

export const recordOpportunityDecision = async (
  dataProvider: DataProvider,
  {
    opportunityId,
    decision,
  }: { opportunityId: Identifier; decision: OpportunityDecision },
): Promise<RecordOpportunityDecisionResult> => {
  const { data: deal } = await dataProvider
    .getOne<Deal>("deals", { id: opportunityId })
    .catch(() => ({ data: null as Deal | null }));
  if (!deal) return { status: "not-found" };

  // Never re-decide something that has already left the pipeline.
  if (
    deal.archived_at != null ||
    deal.outcome != null ||
    deal.stage === "won"
  ) {
    return { status: "already-resolved" };
  }

  const now = new Date().toISOString();

  if (decision === "committed") {
    if (deal.stage === "committed") {
      return { status: "already-resolved" };
    }
    await dataProvider.update<Deal>("deals", {
      id: deal.id,
      data: {
        stage: "committed",
        stage_entered_at: now,
        prospect_decision: "yes",
      },
      previousData: deal,
    });
    return { status: "recorded", decision };
  }

  // Both exits leave the ACTIVE pipeline through outcome — the canonical
  // exit mechanism this app already uses everywhere (archived_at null AND
  // stage <> 'won' AND outcome null is what "active" means). The stage is
  // deliberately left where it is: they really did reach Decision, and
  // rewriting that to mark an exit would falsify the history.
  await dataProvider.update<Deal>("deals", {
    id: deal.id,
    data: {
      outcome: "lost",
      prospect_decision: decision === "ghosted" ? "ghosted" : "no",
    },
    previousData: deal,
  });

  if (decision === "ghosted") {
    // Durable, Contact-level, and survives this Opportunity — the next
    // time this person appears, Leif can see they have gone quiet before.
    // Declining does NOT get a tag: saying no is a normal, healthy answer
    // and is not a behavioural pattern worth carrying forward.
    await ensureContactTag(
      dataProvider,
      deal.contact_id,
      GHOSTED_TAG_NAME,
      GHOSTED_TAG_COLOR,
    );
  }

  return { status: "recorded", decision };
};

// The Dashboard's People Deciding list and the Kanban's Decision column
// answer the same question, so they share this predicate rather than each
// deciding for themselves what "deciding" means.
export const isAtDecision = (
  deal: Pick<Deal, "stage" | "outcome" | "archived_at">,
): boolean =>
  deal.archived_at == null &&
  deal.outcome == null &&
  deal.stage === DECIDING_STAGE;

import type { DataProvider, Identifier } from "ra-core";

import type { Deal } from "../types";

// Payment domain foundation slice: "did they even look" — a lightweight
// signal, not a state machine (see the schema's own comment on
// deals.offer_page_opened_at). Idempotent: only the FIRST open is ever
// recorded; a re-visit never overwrites it, so it stays meaningful as
// "when this offer was first actually seen."
export const recordOfferPageOpened = async (
  dataProvider: DataProvider,
  dealId: Identifier,
): Promise<void> => {
  const { data: deal } = await dataProvider.getOne<Deal>("deals", {
    id: dealId,
  });
  if (deal.offer_page_opened_at) return;

  await dataProvider.update<Deal>("deals", {
    id: dealId,
    data: { offer_page_opened_at: new Date().toISOString() },
    previousData: deal,
  });
};

import type { DataProvider, Identifier } from "ra-core";

import type { Deal, Enrollment } from "../types";

export type RecordDealPaymentSucceededResult =
  | { status: "won"; enrollmentId: Identifier }
  // Idempotent: a duplicate/out-of-order/replayed payment-succeeded event
  // for a Deal already processed is a safe no-op, never a second Won
  // transition or a second Enrollment (Payment domain foundation slice —
  // mirrors cancelSalesCall.ts's own "already-cancelled" convention).
  | { status: "already-won"; enrollmentId: Identifier | null }
  | { status: "not-found" }
  // A real successful payment for an Opportunity someone already
  // explicitly exited (lost/DNE/workshops_only/...) is a genuine anomaly —
  // never silently overridden or dropped. Surfaced to the caller to log/
  // alert on, mirroring how this codebase never guesses a human decision
  // it wasn't given (see cancelSalesCall.ts's own restraint on stage).
  | { status: "outcome-conflict"; outcome: string };

// The single domain function behind "a real payment for this Deal just
// succeeded" — Payment domain foundation slice. First successful payment
// is the Won boundary (Leif's own explicit decision) — full installment-
// plan completion is NOT required.
//
// Deliberately does NOT create the Enrollment itself. Audited before
// writing this: an Opportunity's Enrollment is already created
// automatically, exactly at status "onboarding" with dates from its
// Cohort's own program dates, the instant deals.stage genuinely becomes
// 'won' — a real, already-deployed Postgres trigger
// (handle_deal_won()/on_deal_won, supabase/schemas/02_functions.sql +
// 04_triggers.sql, confirmed live and firing correctly against the real
// linked project during this slice's own verification) in production, and
// its FakeRest mirror (providers/fakerest/dataProvider.ts's own
// ensureEnrollmentForWonDeal) in dev/demo. Duplicating that here would
// have meant two independent "creates the Enrollment" code paths racing
// each other for no reason — this function's only remaining job is the
// idempotent stage transition itself, then handing back the id of the
// Enrollment the existing infrastructure already created. Both the real
// trigger and its FakeRest mirror are themselves idempotent (ON CONFLICT
// DO NOTHING / an existence check), so a duplicate/out-of-order call here
// is still fully safe even without this function's own "already-won"
// short-circuit — that check exists for a fast, cheap, informative
// no-op, not as the only safety net.
//
// Deliberately Stripe-agnostic: takes only a Deal id. The eventual Stripe
// integration slice is what calls this, after it has independently
// verified and persisted its own Stripe-specific fields — this function's
// only job is the CRM-side consequence of "payment succeeded", exactly
// the same separation bookSalesCall.ts keeps from the Acuity-specific
// fetch/match layer above it.
//
// Idempotent-via-refetch, same convention as reviewApplication.ts/
// cancelSalesCall.ts: re-reads the current Deal rather than trusting the
// caller, so a duplicate or out-of-order webhook delivery can never
// double-process.
//
// paymentOptionId, when provided, is the option the successful payment was
// actually for (resolveAuthorizedCheckoutTerms.ts's own read-only
// authorization already validated it before Checkout was ever created) —
// this is where the Deal's commercial snapshot gets frozen
// (selected_payment_option_id, via the existing handle_deal_saved()
// trigger), deliberately not any earlier: a prospect's in-progress choice
// must stay freely changeable across an abandoned/retried Checkout
// attempt, so freezing happens exactly when a payment actually succeeds,
// never before. A no-op if the Deal already has this exact option set
// (e.g. Leif pre-authorized it, or a duplicate webhook delivery).
export const recordDealPaymentSucceeded = async (
  dataProvider: DataProvider,
  dealId: Identifier,
  { paymentOptionId }: { paymentOptionId?: Identifier } = {},
): Promise<RecordDealPaymentSucceededResult> => {
  const { data: deal } = await dataProvider
    .getOne<Deal>("deals", { id: dealId })
    .catch(() => ({ data: null as Deal | null }));
  if (!deal) return { status: "not-found" };

  if (deal.stage === "won") {
    const existing = await findEnrollment(dataProvider, deal.id);
    return { status: "already-won", enrollmentId: existing?.id ?? null };
  }

  if (deal.outcome != null) {
    return { status: "outcome-conflict", outcome: deal.outcome };
  }

  const needsOptionFreeze =
    paymentOptionId != null &&
    String(deal.selected_payment_option_id ?? "") !== String(paymentOptionId);

  await dataProvider.update<Deal>("deals", {
    id: deal.id,
    data: {
      stage: "won",
      ...(needsOptionFreeze
        ? { selected_payment_option_id: paymentOptionId }
        : {}),
    },
    previousData: deal,
  });

  // The trigger/hook above already created the Enrollment, synchronously,
  // within the same write this function just awaited — safe to read back
  // immediately, no polling/retry needed.
  const enrollment = await findEnrollment(dataProvider, deal.id);
  if (!enrollment) {
    throw new Error(
      `Deal ${deal.id} reached Won but no Enrollment was found — the handle_deal_won() trigger (or its FakeRest mirror) may be missing or disabled.`,
    );
  }
  return { status: "won", enrollmentId: enrollment.id };
};

const findEnrollment = async (
  dataProvider: DataProvider,
  opportunityId: Identifier,
): Promise<Enrollment | null> => {
  const { data } = await dataProvider.getList<Enrollment>("enrollments", {
    filter: { opportunity_id: opportunityId },
    pagination: { page: 1, perPage: 1 },
    sort: { field: "id", order: "ASC" },
  });
  return data[0] ?? null;
};

import type { DataProvider, Identifier } from "ra-core";

import type { PublicOfferPageContext } from "./publicOfferPageContext";
import { getOfferPageContext } from "./publicOfferPageContext";
import { recordOfferPageOpened } from "./recordOfferPageOpened";
import { resolveAuthorizedCheckoutTerms } from "./resolveAuthorizedCheckoutTerms";
import { recordDealPaymentSucceeded } from "./recordDealPaymentSucceeded";

export type CreateCheckoutResult =
  | { status: "created"; url: string }
  | { status: "not-found" }
  | { status: "already-won" }
  | { status: "unauthorized-option" }
  | { status: "error" };

// The boundary the public Offer Page actually depends on — same dual-
// implementation convention as public-application/
// publicApplicationDataSource.ts: a FakeRest/dev implementation (reads go
// straight through the shared dataProvider) and a production one
// (supabase/publicOfferPageDataSource.ts, calling stripe_checkout — a real
// Stripe Checkout Session, since every table's RLS is `to authenticated`
// only and Stripe itself is server-side only). Each app entry picks the
// one that matches its own environment — the page component never knows
// which one it got.
//
// createCheckout's dev/demo implementation has no real Stripe to redirect
// to, so it completes the Deal directly through the same fulfillment path
// a real webhook would eventually reach — an honest demo (the click really
// does something), not a fake Stripe illusion.
export type PublicOfferPageDataSource = {
  getContext: (token: string) => Promise<PublicOfferPageContext>;
  recordOpened: (token: string) => Promise<void>;
  createCheckout: (
    token: string,
    paymentOptionId: Identifier,
  ) => Promise<CreateCheckoutResult>;
};

export const createDataProviderPublicOfferPageDataSource = (
  dataProvider: DataProvider,
): PublicOfferPageDataSource => ({
  getContext: (token) => getOfferPageContext(dataProvider, token),
  recordOpened: async (token) => {
    const deal = await findDealByToken(dataProvider, token);
    if (deal) await recordOfferPageOpened(dataProvider, deal.id);
  },
  createCheckout: async (token, paymentOptionId) => {
    const terms = await resolveAuthorizedCheckoutTerms(dataProvider, {
      token,
      paymentOptionId,
    });
    if (terms.status !== "authorized") {
      return { status: terms.status };
    }
    const result = await recordDealPaymentSucceeded(
      dataProvider,
      terms.dealId,
      {
        paymentOptionId: terms.paymentOptionId,
      },
    );
    if (result.status !== "won" && result.status !== "already-won") {
      return { status: "error" };
    }
    return { status: "created", url: `#/offer/${token}?checkout=success` };
  },
});

const findDealByToken = async (dataProvider: DataProvider, token: string) => {
  const { data: deals } = await dataProvider.getList("deals", {
    filter: { offer_page_token: token },
    pagination: { page: 1, perPage: 1 },
    sort: { field: "id", order: "ASC" },
  });
  return deals[0] ?? null;
};

import type { DataProvider, Identifier } from "ra-core";

import type { Cohort, Contact, Deal, OfferPaymentOption } from "../types";

// Payment domain foundation slice: the public Offer Page's own read-side
// context — only the handful of fields a prospect is allowed to see
// (their own name, the frozen offer/price, which payment option(s) they
// may choose among), never internal ids, sales notes, or anyone else's
// data. Mirrors public-application/publicOfferContext.ts's own shape and
// its own header comment: this is the FakeRest-testable "logic of record"
// a production Edge Function mirrors by hand (RLS blocks an anon client
// from reading "deals"/"contacts"/etc. directly — every table's RLS is
// `to authenticated` only, same as every other public-facing surface in
// this app).
export type OfferPagePaymentOption = {
  id: Identifier;
  name: string;
  total: number;
  installments: number;
  installmentAmount: number;
};

export type PublicOfferPageContext =
  | { kind: "not-found" }
  | {
      kind: "found";
      contactName: string;
      offerName: string;
      cohortName: string | null;
      frozenPrice: number;
      // Scholarship Pricing + Capacity slice: lets the Offer Page clearly
      // identify scholarship pricing to the prospect — offerName itself
      // never encodes pricing mode (see offers.scholarship_price's own
      // schema comment: pricing_mode carries that identity, not the Offer
      // name).
      isScholarship: boolean;
      // Exactly one entry when Leif has already authorized a specific
      // option for this Deal (selected_payment_option_id set); every
      // publicly-offered option of this Deal's Offer otherwise — see
      // offer_payment_options.is_public's own schema comment for why a
      // prospect only ever sees a subset by default.
      paymentOptions: OfferPagePaymentOption[];
      // Lets the page show "you've already completed this" instead of a
      // stale payment CTA on a revisit — never exposes anything the
      // prospect doesn't already know.
      alreadyWon: boolean;
    };

export const getOfferPageContext = async (
  dataProvider: DataProvider,
  token: string,
): Promise<PublicOfferPageContext> => {
  const { data: deals } = await dataProvider.getList<Deal>("deals", {
    filter: { offer_page_token: token },
    pagination: { page: 1, perPage: 1 },
    sort: { field: "id", order: "ASC" },
  });
  const deal = deals[0];
  if (!deal || deal.offer_price_snapshot == null) return { kind: "not-found" };

  const contact = await dataProvider
    .getOne<Contact>("contacts", { id: deal.contact_id! })
    .then(({ data }) => data)
    .catch(() => null);
  if (!contact) return { kind: "not-found" };

  const cohort =
    deal.cohort_id != null
      ? await dataProvider
          .getOne<Cohort>("cohorts", { id: deal.cohort_id })
          .then(({ data }) => data)
          .catch(() => null)
      : null;

  const paymentOptions = await resolvePaymentOptions(dataProvider, deal);

  return {
    kind: "found",
    contactName:
      `${contact.first_name ?? ""} ${contact.last_name ?? ""}`.trim(),
    offerName: deal.offer_name_snapshot ?? "",
    cohortName: cohort?.name ?? null,
    frozenPrice: deal.offer_price_snapshot,
    isScholarship: deal.pricing_mode === "scholarship",
    paymentOptions,
    alreadyWon: deal.stage === "won",
  };
};

const resolvePaymentOptions = async (
  dataProvider: DataProvider,
  deal: Deal,
): Promise<OfferPagePaymentOption[]> => {
  // Leif already authorized exactly one option for this Deal (public or
  // not) — the frozen snapshot IS the option, no further choice offered.
  if (deal.selected_payment_option_id != null) {
    return deal.selected_payment_total != null &&
      deal.selected_installment_count != null &&
      deal.selected_installment_amount != null
      ? [
          {
            id: deal.selected_payment_option_id,
            name: await resolveOptionName(
              dataProvider,
              deal.selected_payment_option_id,
            ),
            total: deal.selected_payment_total,
            installments: deal.selected_installment_count,
            installmentAmount: deal.selected_installment_amount,
          },
        ]
      : [];
  }

  const { data: options } = await dataProvider.getList<OfferPaymentOption>(
    "offer_payment_options",
    {
      filter: {
        offer_id: deal.offer_id,
        is_public: true,
        pricing_mode: deal.pricing_mode ?? "standard",
      },
      pagination: { page: 1, perPage: 20 },
      sort: { field: "id", order: "ASC" },
    },
  );
  return options.map((option) => ({
    id: option.id,
    name: option.name,
    total: option.total,
    installments: option.installments,
    installmentAmount: option.installment_amount,
  }));
};

const resolveOptionName = async (
  dataProvider: DataProvider,
  optionId: Identifier,
): Promise<string> =>
  dataProvider
    .getOne<OfferPaymentOption>("offer_payment_options", { id: optionId })
    .then(({ data }) => data.name)
    .catch(() => "");

import type { Deal, SalesCall } from "../types";

// Every Kanban column sorts by the thing that column is actually for.
//
// All six columns used to share one rule — longest time in stage first —
// which is a reasonable default and the wrong answer for most of them. In
// Call Booked it put a stale unresolved call above a call happening in two
// hours; nothing on the board said "this is what today looks like".
//
// The rules below are deterministic, fully tie-broken, and derived only
// from fields that already exist. No scoring, no weighting, nothing
// invented.
//
//   Interested / Application Received
//     Most recently entered the stage FIRST. A new applicant is the
//     actionable one; somebody who has sat in Interested for months is
//     not more urgent, they are colder.
//
//   Approved
//     Same: most recently approved first. These are people waiting to
//     book, and the freshest approval is the one most likely to convert.
//
//   Call Booked
//     The next genuine booked call FIRST, farthest LAST — Leif's stated
//     requirement. A call whose time has passed and was never resolved
//     sorts BELOW every future booking rather than above them: it is
//     unfinished admin, not the next thing happening. An Opportunity in
//     this stage with no booked call at all sorts last of all.
//
//   Decision
//     Soonest follow-up date FIRST, because that date is a commitment
//     Leif made. Opportunities with no follow-up date fall back to
//     longest-waiting, which is the genuine urgency signal when no
//     promise has been made.
//
//   Committed
//     Longest waiting FIRST. Committed means somebody said yes and
//     something is still required of Leif; the one who said yes earliest
//     has been waiting longest for it.
//
// Ties everywhere break on Opportunity id descending so the order is
// stable across renders and never depends on row arrival order.

export type SalesCallForOrdering = Pick<
  SalesCall,
  "opportunity_id" | "status" | "scheduled_at" | "scheduled_on"
>;

// The booked call an Opportunity is currently waiting on. Mirrors
// sales-calls/selectCurrentSalesCall.ts's precedence (a still-booked call
// outranks anything concluded) without importing its richer shape.
export const nextBookedCallByOpportunity = (
  salesCalls: readonly SalesCallForOrdering[] | undefined,
): Map<string, string> => {
  const byOpportunity = new Map<string, string>();
  for (const call of salesCalls ?? []) {
    if (call.status !== "booked") continue;
    if (call.opportunity_id == null) continue;
    const key = String(call.opportunity_id);
    const at = call.scheduled_at ?? `${call.scheduled_on}T23:59:00.000Z`;
    const existing = byOpportunity.get(key);
    // Earliest booked call is the one the column is about.
    if (!existing || at < existing) byOpportunity.set(key, at);
  }
  return byOpportunity;
};

const byIdDescending = (a: Deal, b: Deal): number =>
  Number(b.id) - Number(a.id);

const enteredStageAt = (deal: Deal): number =>
  new Date(deal.stage_entered_at).getTime();

const mostRecentlyEnteredFirst = (a: Deal, b: Deal): number => {
  const diff = enteredStageAt(b) - enteredStageAt(a);
  return diff !== 0 ? diff : byIdDescending(a, b);
};

const longestWaitingFirst = (a: Deal, b: Deal): number => {
  const diff = enteredStageAt(a) - enteredStageAt(b);
  return diff !== 0 ? diff : byIdDescending(a, b);
};

const nextCallFirst =
  (nextCallAt: Map<string, string>, now: number) =>
  (a: Deal, b: Deal): number => {
    // Three bands, in this order: future bookings (soonest first), past
    // unresolved bookings (soonest first), then no booking at all.
    const rank = (deal: Deal): { band: number; at: string } => {
      const at = nextCallAt.get(String(deal.id));
      if (!at) return { band: 2, at: "" };
      return { band: new Date(at).getTime() >= now ? 0 : 1, at };
    };

    const ra = rank(a);
    const rb = rank(b);
    if (ra.band !== rb.band) return ra.band - rb.band;
    if (ra.at !== rb.at) return ra.at.localeCompare(rb.at);
    return byIdDescending(a, b);
  };

const soonestFollowUpFirst = (a: Deal, b: Deal): number => {
  const aDate = a.follow_up_date ?? "";
  const bDate = b.follow_up_date ?? "";
  if (aDate !== bDate) {
    // A promised follow-up outranks having made no promise.
    if (!aDate) return 1;
    if (!bDate) return -1;
    return aDate.localeCompare(bDate);
  }
  return longestWaitingFirst(a, b);
};

export const comparatorForStage = (
  stage: string,
  context: { nextCallAt: Map<string, string>; now?: number },
): ((a: Deal, b: Deal) => number) => {
  switch (stage) {
    case "interested":
    case "application_received":
    case "approved":
      return mostRecentlyEnteredFirst;
    case "call_booked":
      return nextCallFirst(context.nextCallAt, context.now ?? Date.now());
    case "decision":
      return soonestFollowUpFirst;
    case "committed":
      return longestWaitingFirst;
    default:
      // An unrecognized or custom stage keeps the previous behaviour
      // rather than throwing or guessing a new rule.
      return longestWaitingFirst;
  }
};

// Human-readable, so the board can say why it is ordered the way it is
// instead of leaving Leif to reverse-engineer it.
export const ORDERING_RULE_LABELS: Record<string, string> = {
  interested: "Newest first",
  application_received: "Newest first",
  approved: "Newest first",
  call_booked: "Next call first",
  decision: "Follow-up soonest first",
  committed: "Waiting longest first",
};

import type { Deal, OpportunityOutcome } from "../types";

// The one place that knows how a human reason becomes canonical state.
//
// Leif needs to end a sales process from anywhere in the pipeline, and
// until now the only ways out were Archive (which means "hide this", not
// "this ended") and dragging a card at a trash icon (which means nothing
// at all and covered several unrelated business outcomes at once).
//
// Every reason below maps onto an outcome that already exists, so this
// introduces no parallel status system: `outcome` still decides whether an
// Opportunity is in the active pipeline, and `exit_reason` records which
// of the several meanings of that outcome applies.
export type PipelineExitReason =
  | "nurture"
  | "timing"
  | "declined_offer"
  | "money"
  | "afraid"
  | "ghosted"
  | "not_fit"
  | "needs_higher_care"
  | "do_not_engage"
  | "other";

export type PipelineExitDefinition = {
  reason: PipelineExitReason;
  label: string;
  // What it does to the pipeline. Leif reads this, not the enum.
  help: string;
  outcome: OpportunityOutcome;
  prospectDecision?: Deal["prospect_decision"];
  ownerDecision?: Deal["owner_decision"];
  // Only Ghosted earns a durable behavioural tag. Declining is a normal,
  // healthy answer and is not a pattern worth carrying to the next
  // Opportunity.
  appliesGhostedTag?: boolean;
  // Do-not-engage is a standing gate on future selling, so it also sets
  // the Contact's own eligibility rather than living only on this Deal.
  setsContactDoNotEngage?: boolean;
  requiresNote?: boolean;
};

export const PIPELINE_EXIT_REASONS: readonly PipelineExitDefinition[] = [
  {
    reason: "nurture",
    label: "Nurture",
    help: "Not now, but the relationship stays real",
    outcome: "nurture",
  },
  {
    reason: "timing",
    label: "Timing",
    help: "They want this, just not yet",
    outcome: "nurture",
    prospectDecision: "no",
  },
  {
    reason: "declined_offer",
    label: "Declined the offer",
    help: "They considered it and said no",
    outcome: "lost",
    prospectDecision: "no",
  },
  {
    reason: "money",
    label: "Money",
    help: "They said no on price or affordability",
    outcome: "lost",
    prospectDecision: "no",
  },
  {
    reason: "afraid",
    label: "Afraid",
    help: "They pulled back rather than decided against it",
    outcome: "lost",
    prospectDecision: "no",
  },
  {
    reason: "ghosted",
    label: "Ghosted",
    help: "They stopped replying — adds a Ghosted tag",
    outcome: "lost",
    prospectDecision: "ghosted",
    appliesGhostedTag: true,
  },
  {
    reason: "not_fit",
    label: "Not a fit",
    help: "This is not the right work for them",
    outcome: "not_fit",
  },
  {
    reason: "needs_higher_care",
    label: "Needs higher care",
    help: "They need more support than this offer provides",
    outcome: "needs_higher_care",
  },
  {
    reason: "do_not_engage",
    label: "Do not engage",
    help: "Stop selling to this person — also set on their Contact",
    outcome: "lost",
    ownerDecision: "do_not_engage",
    setsContactDoNotEngage: true,
  },
  {
    reason: "other",
    label: "Other",
    help: "Say what happened in a sentence",
    outcome: "lost",
    requiresNote: true,
  },
];

export const findExitReason = (
  reason: PipelineExitReason,
): PipelineExitDefinition => {
  const found = PIPELINE_EXIT_REASONS.find((r) => r.reason === reason);
  if (!found) throw new Error(`unknown pipeline exit reason: ${reason}`);
  return found;
};

// An Opportunity can be removed from the pipeline whenever it is still in
// it. Deliberately not restricted to particular stages: a sales process
// can end at Approved, at Decision, at Committed, or anywhere else Leif
// legitimately decides it is over.
export const canRemoveFromPipeline = (
  deal: Pick<Deal, "stage" | "outcome" | "archived_at">,
): boolean =>
  deal.archived_at == null && deal.outcome == null && deal.stage !== "won";

import type { Identifier } from "ra-core";

import type { Deal, Enrollment, EnrollmentStatus, Offer } from "../types";

// Mirrors dashboard/livingExampleCapacity.ts's ACTIVE_ENROLLMENT_STATUSES —
// "Completed" never reads as a currently-active relationship, here or there.
const ACTIVE_ENROLLMENT_STATUSES: ReadonlySet<EnrollmentStatus> = new Set([
  "onboarding",
  "active",
  "offboarding",
]);

export type PersonContextInput = {
  contactId: Identifier;
  deals: Pick<
    Deal,
    "id" | "contact_id" | "offer_id" | "outcome" | "archived_at"
  >[];
  offersById: Map<string, Pick<Offer, "id" | "name">>;
  enrollmentsByOpportunity: Map<string, Pick<Enrollment, "status">>;
};

// A small, optional contextual label next to a search result in the
// Opportunity "Person" field — e.g. "Past GYU client", "Active opportunity"
// — so a returning client is recognizable before selection. Pure/testable:
// never fetches, only reads already-loaded deals/offers/enrollments.
// Priority: an active Enrollment beats an open Opportunity beats a
// completed (past) Enrollment.
export const derivePersonContextLabel = ({
  contactId,
  deals,
  offersById,
  enrollmentsByOpportunity,
}: PersonContextInput): string | null => {
  const contactDeals = deals.filter(
    (deal) => String(deal.contact_id) === String(contactId),
  );
  if (contactDeals.length === 0) return null;

  let activeLabel: string | null = null;
  let openOpportunityLabel: string | null = null;
  let pastLabel: string | null = null;

  for (const deal of contactDeals) {
    const offerName = offersById.get(String(deal.offer_id))?.name ?? null;
    const enrollment = enrollmentsByOpportunity.get(String(deal.id));

    if (enrollment && ACTIVE_ENROLLMENT_STATUSES.has(enrollment.status)) {
      activeLabel = offerName ? `Active ${offerName} client` : "Active client";
    } else if (enrollment && enrollment.status === "completed") {
      pastLabel = offerName ? `Past ${offerName} client` : "Past client";
    } else if (!enrollment && !deal.archived_at && deal.outcome == null) {
      openOpportunityLabel = offerName
        ? `Active ${offerName} opportunity`
        : "Active opportunity";
    }
  }

  return activeLabel ?? openOpportunityLabel ?? pastLabel ?? null;
};

// "People Deciding" is ONE population with ONE definition, shared by the
// Dashboard and the Pipeline: the Opportunities sitting at the Decision
// stage that are still live.
//
// It used to mean something narrower on the Dashboard —
// `prospect_decision === 'thinking' && owner_decision === 'would_work_with'`
// — while the Pipeline's Decision column meant `stage === 'decision'`. The
// two disagreed in production: the Pipeline showed 8 people deciding and the
// Dashboard said "Nobody is currently deciding", because those two optional
// follow-up fields are set on exactly one Opportunity out of 120. The stage
// is the fact that is always recorded, so the stage is the definition.
//
// The decision fields are still meaningful — they say how a conversation is
// going — but they annotate a person who is deciding, they do not decide
// whether the person is in the list.

// The live-pipeline condition every other view already uses (see
// DealList.tsx): not archived, not Won, no exit outcome.
const isActiveOpportunity = (deal: {
  stage: string;
  outcome?: string | null;
  archived_at?: string | null;
}): boolean =>
  deal.archived_at == null && deal.stage !== "won" && deal.outcome == null;

export const DECIDING_STAGE = "decision";

export const isPersonDeciding = (deal: {
  stage: string;
  outcome?: string | null;
  archived_at?: string | null;
}): boolean => isActiveOpportunity(deal) && deal.stage === DECIDING_STAGE;

// Has this person actually told Leif they are thinking it over? Optional
// colour for the row, never a filter — an imported Opportunity at the
// Decision stage records the stage but not the conversation.
export const hasStatedDeciding = (deal: {
  prospect_decision?: string | null;
  owner_decision?: string | null;
}): boolean =>
  deal.prospect_decision === "thinking" &&
  deal.owner_decision === "would_work_with";

import type { DataProvider, Identifier } from "ra-core";

import type {
  Deal,
  DealPaymentScheduleItem,
  DealStripePlanObject,
} from "../types";

// Where the money stands, in the words Leif uses — reported, never a gate.
//
// An earlier version of this decided whether somebody was Won. Four live
// clients showed why that is wrong: Denise Cormier, Ava Frotton, Linda
// Turner and Emma Wijns were all stuck at Committed with no Enrollment —
// one PAID IN FULL, another already onboarded — purely because the CRM had
// not created their Stripe plan itself.
//
// Sales outcome, payment, enrollment and onboarding are four independent
// dimensions. This one describes payment and nothing else.
//
// The second correction, and the reason this file reads money rather than
// plans: A MISSING SUBSCRIPTION IS NOT EVIDENCE OF A MISSING PAYMENT.
// Emily Loeb paid $3,700 in one go, which creates no subscription at all.
// Jules Litman-Cleper is four installments into six behind a schedule
// Stripe marks "completed". Jess Beauchamp paid all four and then had her
// card removed on purpose. All three read as "Payment setup pending".
//
// So the distinctions that matter, and that the old logic blurred:
//
//   scheduled           is not  active
//   active              is not  paid in full
//   owner-confirmed     is not  Stripe-linked
//   setup pending       is not  unknown
//   no subscription     is not  no payment
//   no card on file     is not  unpaid
//   uncertain           is not  setup pending
//   one subscription    is not  the whole plan
//   transactions        is not  installments
//
// The last two are Jules Litman-Cleper and Jess Beauchamp. Jules agreed
// six payments of $666; his first subscription was built with only four
// cycles, ended, and a replacement now carries the remaining two — so his
// plan is neither finished nor missing. Jess agreed four installments and
// paid them in three transactions, one of which covered two.
export type PaymentState =
  | "paid_in_full"
  | "active_plan"
  | "scheduled_plan"
  | "owner_confirmed_plan"
  | "setup_pending"
  // Something does not add up and a human must look. It exists so that
  // uncertainty is never quietly filed as "this person owes you a payment
  // plan", which is what setup_pending reads as.
  | "needs_review"
  | "unknown";

export type PaymentStatus = {
  state: PaymentState;
  // The one-line headline, e.g. "Scheduled payment plan".
  headline: string;
  // Supporting facts, each already true — never a guess. e.g.
  // "Starts Sep 30, 2026", "4 of 6 payments received".
  detail: string[];
  // The single operational thing still to do, when there is one.
  outstanding: string | null;
  stripeLinked: boolean;
  // Why a human is being asked to look, verbatim. Shown alongside a
  // confident state too: "paid in full, but check this" is a real answer.
  reviewReason: string | null;
  // Where the figure that "paid in full" is measured against came from.
  // Every historical LE Opportunity carries the CURRENT $4,000 list price
  // from the import, and LE used to be $3,700 — so a list-price total is
  // reported as exactly that, never as the agreed price.
  agreedTotal: number | null;
  agreedTotalSource: "deal" | "offer_list_price" | "none";
  // Installments satisfied, which is not the number of transactions.
  installmentsSatisfied: number;
  installmentsAgreed: number;
  collected: number;
};

// due_date and paid_on are date-only. Passing "2026-09-30" to Date() parses
// it as UTC midnight, which renders as the 29th anywhere behind UTC — so a
// plan starting on the 30th would be shown starting a day early. Reading
// the parts directly keeps the day the day.
const formatDate = (value: string): string => {
  const dateOnly = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  const date = dateOnly
    ? new Date(
        Number(dateOnly[1]),
        Number(dateOnly[2]) - 1,
        Number(dateOnly[3]),
      )
    : new Date(value);
  return date.toLocaleDateString(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
};

const formatMoney = (amount: number): string =>
  new Intl.NumberFormat(undefined, {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 2,
  }).format(amount);

const unknownStatus = (headline: string): PaymentStatus => ({
  state: "unknown",
  headline,
  detail: [],
  outstanding: null,
  stripeLinked: false,
  reviewReason: null,
  agreedTotal: null,
  agreedTotalSource: "none",
  installmentsSatisfied: 0,
  installmentsAgreed: 0,
  collected: 0,
});

export const assessPaymentStatus = async (
  dataProvider: DataProvider,
  opportunityId: Identifier,
): Promise<PaymentStatus> => {
  const { data: deal } = await dataProvider
    .getOne<Deal>("deals", { id: opportunityId })
    .catch(() => ({ data: null as Deal | null }));
  if (!deal) return unknownStatus("Payment status unknown");

  const { data: items } = await dataProvider
    .getList<DealPaymentScheduleItem>("deal_payment_schedule_items", {
      filter: { deal_id: opportunityId },
      pagination: { page: 1, perPage: 100 },
      sort: { field: "sequence", order: "ASC" },
    })
    .catch(() => ({ data: [] as DealPaymentScheduleItem[] }));

  // Every Stripe object that has carried this plan, live or ended.
  const { data: planRows } = await dataProvider
    .getList<DealStripePlanObject>("deal_stripe_plan_objects", {
      filter: { deal_id: opportunityId },
      pagination: { page: 1, perPage: 100 },
      sort: { field: "id", order: "ASC" },
    })
    .catch(() => ({ data: [] as DealStripePlanObject[] }));
  const planObjects = planRows ?? [];

  const scheduleItems = items ?? [];
  const paid = scheduleItems.filter((i) => i.status === "paid");
  const scheduled = scheduleItems.filter((i) => i.status === "scheduled");

  const paidTotal = paid.reduce((sum, i) => sum + Number(i.amount ?? 0), 0);

  // A Deal-specific total is authoritative. The Offer's list price is only
  // a fallback, and is reported as such: every historical LE Opportunity
  // carries today's $4,000 from the import, and LE used to sell at $3,700.
  const agreedTotalSource: PaymentStatus["agreedTotalSource"] =
    deal.selected_payment_total != null
      ? "deal"
      : deal.offer_price_snapshot != null
        ? "offer_list_price"
        : "none";
  const agreed = Number(
    deal.selected_payment_total ?? deal.offer_price_snapshot ?? 0,
  );
  const expectedCount = Number(deal.selected_installment_count ?? 0);
  const installmentAmount = Number(deal.selected_installment_amount ?? 0);

  // Installments satisfied come from the MONEY, not from how many times a
  // card was charged. Jess Beauchamp's four installments arrived as three
  // transactions, because one payment of $2,000 covered two of them.
  const installmentsSatisfied =
    installmentAmount > 0
      ? Math.min(
          expectedCount > 0 ? expectedCount : Number.MAX_SAFE_INTEGER,
          Math.round(paidTotal / installmentAmount),
        )
      : paid.length;

  // A live plan is one kind of Stripe evidence. Collected money is
  // another, and it survives the plan being completed or cancelled.
  const planLinked = Boolean(
    deal.stripe_subscription_id ||
      deal.stripe_subscription_schedule_id ||
      planObjects.some((o) => o.is_current),
  );
  // More than one subscription behind one agreement means an earlier plan
  // was replaced — worth saying, because "your subscription ended" and
  // "you have finished paying" are different facts.
  const replacedPlan =
    planObjects.filter((o) => o.object_type === "subscription").length > 1;
  const moneyFromStripe = paid.some(
    (i) => i.source === "stripe" || i.stripe_payment_intent_id != null,
  );
  const stripeLinked = planLinked || moneyFromStripe;
  const reviewReason = deal.payment_review_reason ?? null;

  const provenance = moneyFromStripe
    ? "Confirmed in Stripe"
    : planLinked
      ? "Stripe linked"
      : "Recorded outside Stripe";

  const measures = {
    agreedTotal: agreedTotalSource === "none" ? null : agreed,
    agreedTotalSource,
    installmentsSatisfied,
    installmentsAgreed: expectedCount,
    collected: paidTotal,
  };

  const base = classify({
    deal,
    paid,
    scheduled,
    paidTotal,
    agreed,
    expectedCount,
    installmentsSatisfied,
    planLinked,
    stripeLinked,
    replacedPlan,
    provenance,
  });

  if (!reviewReason) return { ...base, ...measures, reviewReason: null };

  // A review outranks every state except a payment that fully reconciles
  // against agreed terms. Mia Cosme is why: her linked customer shows one
  // $925 payment, which looks exactly like an ordinary part-paid plan.
  // Calling that "Active payment plan" would state a fact nobody has
  // established.
  if (base.state === "paid_in_full")
    return { ...base, ...measures, reviewReason };

  return {
    state: "needs_review",
    headline: "Payment status needs review",
    detail: base.detail,
    outstanding: "Check this before acting on it",
    stripeLinked,
    reviewReason,
    ...measures,
  };
};

type Classified = Pick<
  PaymentStatus,
  "state" | "headline" | "detail" | "outstanding" | "stripeLinked"
>;

const classify = ({
  deal,
  paid,
  scheduled,
  paidTotal,
  agreed,
  expectedCount,
  installmentsSatisfied,
  planLinked,
  stripeLinked,
  replacedPlan,
  provenance,
}: {
  deal: Deal;
  paid: DealPaymentScheduleItem[];
  scheduled: DealPaymentScheduleItem[];
  paidTotal: number;
  agreed: number;
  expectedCount: number;
  installmentsSatisfied: number;
  planLinked: boolean;
  stripeLinked: boolean;
  replacedPlan: boolean;
  provenance: string;
}): Classified => {
  // Paid in full outranks everything: the money is in, however it arrived
  // — one payment, four installments, or outside Stripe entirely. Nothing
  // about a card on file enters into it.
  if (paid.length > 0 && agreed > 0 && paidTotal >= agreed) {
    const paidOn = paid[paid.length - 1]?.paid_on ?? null;
    return {
      state: "paid_in_full",
      headline: "Paid in full",
      detail: [
        // What was agreed, satisfied — not how many times a card was
        // charged. Jess's four installments arrived in three payments.
        ...(expectedCount > 1
          ? [`${expectedCount} of ${expectedCount} installments paid`]
          : []),
        ...(paid.length > 1 ? [`${paid.length} transactions`] : []),
        ...(paidOn ? [`Settled ${formatDate(paidOn)}`] : []),
        provenance,
      ],
      outstanding: null,
      stripeLinked,
    };
  }

  // Money is arriving. This is true whether or not the subscription that
  // produced it is still live — Jules's schedule reads "completed" and he
  // is four of six installments in.
  if (paid.length > 0) {
    const remaining = agreed > 0 ? agreed - paidTotal : 0;
    const remainingCount =
      expectedCount > installmentsSatisfied
        ? expectedCount - installmentsSatisfied
        : 0;
    return {
      state: "active_plan",
      headline: "Active payment plan",
      detail: [
        expectedCount > 0
          ? `${installmentsSatisfied} of ${expectedCount} installments paid`
          : `${paid.length} payment${paid.length === 1 ? "" : "s"} received`,
        `${formatMoney(paidTotal)} collected`,
        // Said plainly, because a client whose first subscription ended is
        // otherwise indistinguishable from one who has finished paying.
        ...(replacedPlan
          ? [
              planLinked
                ? "Replacement Stripe subscription carrying the rest"
                : "Earlier Stripe subscription ended",
            ]
          : []),
        provenance,
      ],
      outstanding:
        remaining > 0
          ? remainingCount > 0
            ? `${formatMoney(remaining)} remaining over ${remainingCount} payment${remainingCount === 1 ? "" : "s"}`
            : `${formatMoney(remaining)} remaining`
          : null,
      stripeLinked,
    };
  }

  // A schedule with no payment taken yet is SCHEDULED. Saying "no payment
  // plan" here is the defect this state machine exists to remove — Denise
  // and Ava both read that way for weeks.
  if (planLinked) {
    const startsFrom = scheduled.find((i) => i.due_date)?.due_date ?? null;
    return {
      state: "scheduled_plan",
      headline: "Scheduled payment plan",
      detail: [
        ...(startsFrom ? [`Starts ${formatDate(startsFrom)}`] : []),
        "Stripe linked",
      ],
      outstanding: null,
      stripeLinked,
    };
  }

  // Terms Leif has stated, with no Stripe record to back them yet. Real
  // truth, explicitly not the same as a linked plan.
  if (scheduled.length > 0) {
    return {
      state: "owner_confirmed_plan",
      headline: "Payment plan — owner confirmed",
      detail: [`${scheduled.length} scheduled`],
      outstanding: "Stripe link pending",
      stripeLinked: false,
    };
  }

  // Nothing anywhere, and we looked. For a Won Opportunity that is a real
  // outstanding job — Emma Wijns is onboarded and this is all that is left
  // for her. Reached only when no payment and no review exist, so it never
  // stands in for uncertainty.
  if (deal.stage === "won") {
    return {
      state: "setup_pending",
      headline: "Payment setup pending",
      detail: [],
      outstanding: "Create payment plan",
      stripeLinked: false,
    };
  }

  return {
    state: "unknown",
    headline: "Payment truth unknown",
    detail: [],
    outstanding: null,
    stripeLinked: false,
  };
};

