import type { DataProvider, Identifier } from "ra-core";

import type { Deal } from "../types";

// Payment domain foundation slice: generates the opaque public token the
// personalized Offer Page resolves a Deal by (never the Deal's own
// sequential id — see the schema's own comment on deals.offer_page_token).
// Idempotent: a Deal that already has a token keeps it — re-running this
// (e.g. a second "would_work_with"/"yes" outcome recorded on the same
// Opportunity, which completeSalesCallOutcome.ts's own idempotent guard
// should already prevent, but this stays defensive) never rotates an
// already-issued, possibly-already-shared link out from under a prospect.
export const ensureOfferPageToken = async (
  dataProvider: DataProvider,
  dealId: Identifier,
): Promise<string> => {
  const { data: deal } = await dataProvider.getOne<Deal>("deals", {
    id: dealId,
  });
  if (deal.offer_page_token) return deal.offer_page_token;

  const token = crypto.randomUUID();
  await dataProvider.update<Deal>("deals", {
    id: dealId,
    data: { offer_page_token: token },
    previousData: deal,
  });
  return token;
};

// Payment domain foundation slice, human-acceptance repair: the public
// Offer Page must make the currency explicit (Leif works with
// international clients — a bare "$" is ambiguous between USD/CAD/AUD/
// etc.). Reuses this app's own existing currency source of truth
// (ConfigurationContextValue.currency, an ISO 4217 code — see
// root/ConfigurationContext.tsx — the same value every other money
// display in this app already reads via Intl.NumberFormat) rather than
// hardcoding "USD": the symbol/format come from Intl for whatever currency
// is actually configured, with the currency code appended explicitly so
// it's never ambiguous regardless of symbol. Whole-amount only (no cents)
// — matches this app's own real data, which is never fractional (GYU's
// $1,400/$700/$350, LE's $4,000).
export const formatOfferPageAmount = (
  amount: number,
  currency: string,
): string => {
  const formatted = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount);
  return `${formatted} ${currency}`;
};

// Shared validation for the Offer <-> Cohort relationship on an Opportunity.
// Mirrors the Postgres trigger `handle_deal_saved()` (see
// supabase/schemas/02_functions.sql) so the rule is enforced identically in
// FakeRest/demo mode and in production — not just as a UI convention.
import type { Cohort, Offer } from "../types";

export class OfferCohortMismatchError extends Error {}

export const validateOfferCohort = (
  offer: Pick<Offer, "id" | "type">,
  cohort: Pick<Cohort, "id" | "offer_id"> | null | undefined,
): void => {
  if (!cohort) return;

  if (offer.type !== "group") {
    throw new OfferCohortMismatchError(
      "cohort_id can only be set on a group offer",
    );
  }

  if (cohort.offer_id != offer.id) {
    throw new OfferCohortMismatchError(
      `Cohort ${cohort.id} does not belong to offer ${offer.id}`,
    );
  }
};

import React from "react";

const DealList = React.lazy(() => import("./DealList"));

export default {
  list: DealList,
