import { format } from "date-fns";

import type { DealStage } from "../types";

export const findDealLabel = (dealStages: DealStage[], dealValue: string) => {
  const dealStage = dealStages.find((stage) => stage.value === dealValue);
  return dealStage?.label;
};

export function getRelativeTimeString(
  dateString: string,
  locale = "en",
): string {
  const date = new Date(dateString);
  date.setHours(0, 0, 0, 0);

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const diff = date.getTime() - today.getTime();
  const unitDiff = Math.round(diff / (1000 * 60 * 60 * 24));

  // Check if the date is more than one week old
  if (Math.abs(unitDiff) > 7) {
    return new Intl.DateTimeFormat(locale, {
      day: "numeric",
      month: "long",
    }).format(date);
  }

  // Intl.RelativeTimeFormat for dates within the last week
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  return ucFirst(rtf.format(unitDiff, "day"));
}

function ucFirst(str: string): string {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

const isoDateStringRegex = /^\d{4}-\d{2}-\d{2}$/;

export function formatISODateString(dateString: string) {
  if (!isoDateStringRegex.test(dateString)) {
    throw new Error("Invalid date format. Expected YYYY-MM-DD.");
  }
  // Some browsers will consider a date in the format YYYY-MM-DD as UTC, which can cause off-by-one-day issues depending on the user's timezone.
  // To avoid this, we can parse the date components manually and create a date object in the local timezone.
  const [year, month, day] = dateString.split("-").map(Number);
  const date = new Date(year, month - 1, day);

  return format(date, "PP");
}

// For full timestamps (timestamptz columns, e.g. Application.submitted_at)
// where formatISODateString's YYYY-MM-DD guard would throw — no local-noon
// reinterpretation issue here since the value already carries a time
// component. Kept distinct from formatISODateString rather than relaxing
// its regex, so a date-only value still fails loudly if it's ever passed
// somewhere that expects a real timestamp.
export function formatTimestampString(timestamp: string) {
  return format(new Date(timestamp), "PP");
}

// Same timestamptz shape as formatTimestampString, plus the time of day
// ("Sep 3, 4:00 PM") — for the few places the time genuinely matters, e.g.
// a Sales Call's own scheduled_at (Unmatched Sales Call Resolution slice).
export function formatTimestampWithTimeString(timestamp: string) {
  return format(new Date(timestamp), "PP · p");
}

// Short "Oct 31" form of a "YYYY-MM-DD" (or "YYYY-MM") date-only string —
// the same UTC/local-safe manual parsing as formatISODateString above (a
// bare `new Date(str).toLocaleDateString()` risks an off-by-one day
// depending on the viewer's timezone), just a terser output format.
// Extracted here after this exact logic was independently duplicated in
// programs/IndividualProgramPage.tsx and dashboard/
// LivingExampleCapacityCard.tsx — Next Up / Coming Up (Dashboard slice) is
// a third caller, past the point where copy-pasting it again was
// reasonable.
export function formatMonthDayString(isoDate: string) {
  const [year, month, day] = isoDate.split("-").map(Number);
  return new Date(year!, month! - 1, day!).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
  });
}

import type { Offer, OfferPaymentOption } from "../types";

// The Opportunity's "Potential Value" should never be something the user
// types when it's already encoded elsewhere (§3 of the Programs +
// Opportunity UX slice): a selected payment option's total wins, falling
// back to the Offer's current list price when no option is selected yet.
// Returns null when neither is known (nothing to auto-fill).
export const resolveOpportunityAmount = (
  paymentOption: Pick<OfferPaymentOption, "total"> | null | undefined,
  offer: Pick<Offer, "current_price"> | null | undefined,
): number | null => {
  if (paymentOption) return paymentOption.total;
  if (offer) return offer.current_price;
  return null;
};

import type { DataProvider, Identifier } from "ra-core";

import type { Task } from "../types";

// A sales decision answers the tasks that were waiting for it.
//
// Gil Lelli's follow-up is the case: "Follow up with Gil Lelli, due Sep
// 22" exists precisely because nobody knew yet what he would decide. Once
// Leif records yes or removes Gil from the pipeline, that task is not
// outstanding work any more, and leaving it on the Dashboard trains him to
// ignore the Dashboard.
//
// Only the task types that genuinely ask "what did they decide?" are
// closed. A sales_call task for a booking that still exists is untouched,
// because a decision about the Opportunity is not a decision about
// whether the call happens.
const DECISION_ANSWERING_TYPES: ReadonlySet<string> = new Set([
  "follow_up",
  "nurture_follow_up",
  "sales_call_cancelled",
]);

export const closeSalesDecisionTasks = async (
  dataProvider: DataProvider,
  contactId: Identifier,
  completedAt: string,
): Promise<number> => {
  const { data } = await dataProvider.getList<Task>("tasks", {
    filter: { contact_id: contactId },
    pagination: { page: 1, perPage: 100 },
    sort: { field: "id", order: "ASC" },
  });

  const answered = (data ?? []).filter(
    (task) =>
      !task.done_date &&
      task.type != null &&
      DECISION_ANSWERING_TYPES.has(task.type),
  );

  for (const task of answered) {
    await dataProvider.update<Task>("tasks", {
      id: task.id,
      data: { done_date: completedAt, status: "completed" },
      previousData: task,
    });
  }

  return answered.length;
};

import type { DataProvider } from "ra-core";
import type { DropResult } from "@hello-pangea/dnd";

import type { Deal } from "../types";
import type { DealsByStage } from "./stages";

// What a Kanban drop actually does, lifted out of the component so it can
// be proven.
//
// It used to live inline in DealListContent's onDragEnd, where nothing
// could reach it: the only way to exercise the single most-used gesture on
// the board was to simulate a browser drag, and the parts that can be
// silently wrong are not the gesture — they are whether the move became
// durable, whether it recorded its history exactly once, and whether a
// second drop of the same card can double-write.
//
// Takes the library's own DropResult, so the contract under test is the
// real one rather than a convenient re-shaping of it.
export type DealStageDropOutcome =
  | { applied: true; deal: Deal; from: string; to: string }
  // Dropped outside any column, or back into the column it came from.
  // Columns sort by stage_entered_at rather than a manual position, so a
  // same-column drop has nothing to persist.
  | {
      applied: false;
      reason: "no-destination" | "same-column" | "unknown-card";
    };

export const applyDealStageDrop = async (
  dataProvider: DataProvider,
  { result, dealsByStage }: { result: DropResult; dealsByStage: DealsByStage },
): Promise<DealStageDropOutcome> => {
  const { destination, source } = result;
  if (!destination) return { applied: false, reason: "no-destination" };

  const from = source.droppableId;
  const to = destination.droppableId;
  if (from === to) return { applied: false, reason: "same-column" };

  const deal = dealsByStage[from]?.[source.index];
  if (!deal) return { applied: false, reason: "unknown-card" };

  // The one shared path every other stage-changing pathway already uses
  // (Application review, sales-call booking and outcomes): the "deals"
  // resource hook stamps stage_entered_at and appends the
  // deal_stage_events history row, so there is deliberately nothing else
  // to write here. A drop must not become a second, parallel way to change
  // a stage — that is how two mechanisms drift apart.
  await dataProvider.update("deals", {
    id: deal.id,
    data: { stage: to },
    previousData: deal,
  });

  return { applied: true, deal, from, to };
};

import { useState } from "react";
import {
  useDataProvider,
  useGetOne,
  useNotify,
  useRecordContext,
  useRefresh,
} from "ra-core";
import { Button } from "@/components/ui/button";

import { useScholarshipCheckoutInvalidator } from "./ScholarshipCheckoutInvalidatorContext";
import { grantScholarshipPricing } from "./grantScholarshipPricing";
import { releaseScholarshipReservation } from "./releaseScholarshipReservation";
import type { Deal, Offer } from "../types";

// Scholarship Pricing + Capacity slice: granting/releasing scholarship
// pricing is a business EVENT, not passive Deal metadata — same precedent
// DealSalesProcessInputs.tsx's own header comment already establishes for
// owner_decision/prospect_decision. A plain form field bound to
// pricing_mode would bypass the atomic slot-claim/release entirely — this
// control always goes through grantScholarshipPricing.ts/
// releaseScholarshipReservation.ts instead of the generic Deal edit form's
// own save.
//
// Human-acceptance repair: the first version gave this its own full-width
// bordered card, which read as if scholarship were a normal, everyday
// Opportunity step rather than the occasional exception Leif herself
// controls. Deliberately quiet now — one small metadata-row item, same
// text-xs-label/text-sm-value shape as every other compact field on this
// page (source, entry_path, payment option), with a link-styled action
// rather than a solid/outline button. Still unambiguous when active (the
// small "Scholarship" badge next to the Offer name, set by DealShow.tsx,
// is the actual "this is exceptional" signal — this control is just where
// the action lives).
export const ScholarshipPricingControl = () => {
  const record = useRecordContext<Deal>();
  const dataProvider = useDataProvider();
  const notify = useNotify();
  const refresh = useRefresh();
  const invalidateStaleCheckout = useScholarshipCheckoutInvalidator();
  const [isPending, setIsPending] = useState(false);

  const { data: offer } = useGetOne<Offer>(
    "offers",
    { id: record?.offer_id },
    { enabled: record?.offer_id != null },
  );

  if (!record || record.stage === "won") return null;

  const isScholarship = record.pricing_mode === "scholarship";
  // Nothing to offer if this Offer has no scholarship price configured —
  // never invite a grant attempt that can only fail.
  if (!isScholarship && offer?.scholarship_price == null) return null;

  const handleGrant = async () => {
    setIsPending(true);
    try {
      const result = await grantScholarshipPricing(
        dataProvider,
        record.id,
        invalidateStaleCheckout,
      );
      if (result.status === "granted") {
        notify("Scholarship pricing granted.", { type: "success" });
      } else if (result.status === "slot-unavailable") {
        notify(
          `Scholarship slot unavailable${result.heldByDescription ? ` — held by ${result.heldByDescription}` : ""}.`,
          { type: "warning" },
        );
      } else if (result.status === "no-scholarship-price-configured") {
        notify("This Offer has no scholarship price configured.", {
          type: "warning",
        });
      } else {
        notify("Could not grant scholarship pricing.", { type: "warning" });
      }
      refresh();
    } finally {
      setIsPending(false);
    }
  };

  const handleRelease = async () => {
    setIsPending(true);
    try {
      const result = await releaseScholarshipReservation(
        dataProvider,
        record.id,
        invalidateStaleCheckout,
      );
      if (result.status === "released") {
        notify("Scholarship pricing released.", { type: "success" });
      } else {
        notify("Could not release scholarship pricing.", { type: "warning" });
      }
      refresh();
    } finally {
      setIsPending(false);
    }
  };

  return (
    <div className="flex flex-col mr-10">
      <span className="text-xs text-muted-foreground tracking-wide">
        Scholarship
      </span>
      {isScholarship ? (
        <Button
          size="sm"
          variant="link"
          className="h-auto p-0 justify-start text-sm"
          disabled={isPending}
          onClick={handleRelease}
        >
          Release scholarship
        </Button>
      ) : (
        <Button
          size="sm"
          variant="link"
          className="h-auto p-0 justify-start text-sm text-muted-foreground"
          disabled={isPending}
          onClick={handleGrant}
        >
          Grant (${offer?.scholarship_price})
        </Button>
      )}
    </div>
  );
};

