import { useGetList, useGetMany } from "ra-core";
import type { Identifier } from "ra-core";

import type { Contact, Deal, Offer, ScholarshipSlot } from "../types";

export type OutstandingScholarshipReservationRow = {
  dealId: Identifier;
  offerName: string;
  contactName: string;
};

// Scholarship Pricing + Capacity slice: the small operational Dashboard
// surface for the ONE risk the locked "no TTL, no automatic expiration"
// reservation design deliberately accepts — an unpaid scholarship grant
// that sits outstanding indefinitely until Leif explicitly releases it.
// Deliberately narrow (per Leif's own instruction): only outstanding
// (Deal-held, unpaid) reservations — a CURRENT scholarship Enrollment is
// already visible everywhere Enrollments normally are, so duplicating it
// here would turn this into the "scholarship-management subsystem" this
// slice explicitly does not want to build.
export const useOutstandingScholarshipReservations = (): {
  isPending: boolean;
  rows: OutstandingScholarshipReservationRow[];
} => {
  const { data: slots, isPending: slotsPending } = useGetList<ScholarshipSlot>(
    "scholarship_slots",
    {
      filter: {},
      pagination: { page: 1, perPage: 100 },
      sort: { field: "id", order: "ASC" },
    },
  );

  const outstanding = (slots ?? []).filter(
    (slot) => slot.holder_deal_id != null,
  );
  const dealIds = outstanding.map((slot) => slot.holder_deal_id!);
  const { data: deals, isPending: dealsPending } = useGetMany<Deal>(
    "deals",
    { ids: dealIds },
    { enabled: dealIds.length > 0 },
  );

  const offerIds = [...new Set((deals ?? []).map((deal) => deal.offer_id))];
  const { data: offers, isPending: offersPending } = useGetMany<Offer>(
    "offers",
    { ids: offerIds },
    { enabled: offerIds.length > 0 },
  );

  const contactIds = [
    ...new Set(
      (deals ?? [])
        .map((deal) => deal.contact_id)
        .filter((id): id is Identifier => id != null),
    ),
  ];
  const { data: contacts, isPending: contactsPending } = useGetMany<Contact>(
    "contacts",
    { ids: contactIds },
    { enabled: contactIds.length > 0 },
  );

  const isPending =
    slotsPending ||
    (dealIds.length > 0 && dealsPending) ||
    (offerIds.length > 0 && offersPending) ||
    (contactIds.length > 0 && contactsPending);

  if (isPending) return { isPending: true, rows: [] };

  const dealById = new Map(
    (deals ?? []).map((deal) => [String(deal.id), deal]),
  );
  const offerById = new Map(
    (offers ?? []).map((offer) => [String(offer.id), offer]),
  );
  const contactById = new Map(
    (contacts ?? []).map((contact) => [String(contact.id), contact]),
  );

  const rows: OutstandingScholarshipReservationRow[] = outstanding
    .map((slot) => {
      const deal = dealById.get(String(slot.holder_deal_id));
      const contact = deal?.contact_id
        ? contactById.get(String(deal.contact_id))
        : undefined;
      const offer = deal ? offerById.get(String(deal.offer_id)) : undefined;
      return {
        dealId: slot.holder_deal_id!,
        offerName: offer?.name ?? deal?.offer_name_snapshot ?? "",
        contactName: contact
          ? `${contact.first_name ?? ""} ${contact.last_name ?? ""}`.trim()
          : (deal?.name ?? ""),
      };
    })
    // A deal that no longer exists (unlikely — a slot always keeps its
    // holder consistent, but stay defensive) never renders a broken row.
    .filter((row) => dealById.has(String(row.dealId)));

  return { isPending: false, rows };
};

import { useGetList, useGetMany } from "ra-core";
import type { Identifier } from "ra-core";

import type {
  Deal,
  Contact,
  Enrollment,
  EnrollmentOnboardingItem,
  DealPaymentScheduleItem,
} from "../types";
import {
  resolveCommercialTerms,
  type CommercialTerms,
} from "../enrollments/resolveCommercialTerms";

export type NeedsOnboardingRow = {
  enrollmentId: Identifier;
  contactName: string;
  offerName: string;
  // The amount actually charged so far — the first installment for a
  // What this person actually agreed to and has actually paid, resolved by
  // the one shared resolver. Deliberately NOT a single "amountReceived"
  // number: the old field fell back through selected_payment_total to
  // offer_price_snapshot and the card called the result "paid", so a client
  // who had paid a $400 deposit was announced as having paid $1,400.
  terms: CommercialTerms;
  requiredDone: number;
  requiredTotal: number;
};

// Contracts + Onboarding slice: the Dashboard's primary "this person cannot
// disappear" signal (architecture review, §1/§9) — reads directly off
// Enrollment state, not Tasks, so it stays correct whether or not any Task
// happens to exist. Sorted oldest-first (enrollment created_at ascending)
// so a long-stalled onboarding surfaces at the top — the same "age in
// onboarding" signal the review recommended instead of a new status/column.
export const useNeedsOnboardingItems = (): {
  isPending: boolean;
  rows: NeedsOnboardingRow[];
} => {
  const { data: enrollments, isPending: enrollmentsPending } =
    useGetList<Enrollment>("enrollments", {
      filter: { status: "onboarding" },
      pagination: { page: 1, perPage: 100 },
      sort: { field: "created_at", order: "ASC" },
    });

  const dealIds = [
    ...new Set((enrollments ?? []).map((e) => e.opportunity_id)),
  ];
  const { data: deals, isPending: dealsPending } = useGetMany<Deal>(
    "deals",
    { ids: dealIds },
    { enabled: dealIds.length > 0 },
  );

  const contactIds = [
    ...new Set(
      (deals ?? [])
        .map((deal) => deal.contact_id)
        .filter((id): id is Identifier => id != null),
    ),
  ];
  const { data: contacts, isPending: contactsPending } = useGetMany<Contact>(
    "contacts",
    { ids: contactIds },
    { enabled: contactIds.length > 0 },
  );

  // Paid-to-date lives in the payment schedule, never in the Deal snapshot
  // (which records what was AGREED).
  const { data: scheduleItems, isPending: schedulePending } =
    useGetList<DealPaymentScheduleItem>(
      "deal_payment_schedule_items",
      {
        filter: { "deal_id@in": `(${dealIds.join(",")})` },
        pagination: { page: 1, perPage: 1000 },
        sort: { field: "sequence", order: "ASC" },
      },
      { enabled: dealIds.length > 0 },
    );

  const enrollmentIds = (enrollments ?? []).map((e) => e.id);
  const { data: items, isPending: itemsPending } =
    useGetList<EnrollmentOnboardingItem>(
      "enrollment_onboarding_items",
      {
        filter: { "enrollment_id@in": `(${enrollmentIds.join(",")})` },
        pagination: { page: 1, perPage: 1000 },
        sort: { field: "id", order: "ASC" },
      },
      { enabled: enrollmentIds.length > 0 },
    );

  const isPending =
    enrollmentsPending ||
    (dealIds.length > 0 && dealsPending) ||
    (contactIds.length > 0 && contactsPending) ||
    (enrollmentIds.length > 0 && itemsPending) ||
    (dealIds.length > 0 && schedulePending);

  if (isPending) return { isPending: true, rows: [] };

  const dealById = new Map((deals ?? []).map((d) => [String(d.id), d]));
  const contactById = new Map((contacts ?? []).map((c) => [String(c.id), c]));

  const rows: NeedsOnboardingRow[] = (enrollments ?? []).map((enrollment) => {
    const deal = dealById.get(String(enrollment.opportunity_id));
    const contact = deal?.contact_id
      ? contactById.get(String(deal.contact_id))
      : undefined;
    const enrollmentItems = (items ?? []).filter(
      (item) => String(item.enrollment_id) === String(enrollment.id),
    );
    const requiredItems = enrollmentItems.filter((item) => item.is_required);
    return {
      enrollmentId: enrollment.id,
      contactName: contact
        ? `${contact.first_name ?? ""} ${contact.last_name ?? ""}`.trim()
        : (deal?.name ?? ""),
      offerName: deal?.offer_name_snapshot ?? "",
      terms: deal
        ? resolveCommercialTerms(
            deal,
            (scheduleItems ?? []).filter(
              (item) => String(item.deal_id) === String(deal.id),
            ),
          )
        : { kind: "unknown" },
      requiredDone: requiredItems.filter((item) => item.status === "done")
        .length,
      requiredTotal: requiredItems.length,
    };
  });

  return { isPending: false, rows };
};

import { useGetList } from "ra-core";

import type { Deal, Enrollment, Offer } from "../types";
import { computeLivingExampleCapacity } from "./livingExampleCapacity";

// Finds "the" individual Offer with a capacity ceiling — Living Example
// today, and whichever individual offer plays that role later — rather
// than hardcoding a name or id.
export const useLivingExampleCapacityData = () => {
  const { data: offers, isPending: offersPending } = useGetList<Offer>(
    "offers",
    {
      filter: { type: "individual" },
      pagination: { page: 1, perPage: 10 },
      sort: { field: "id", order: "ASC" },
    },
  );
  const offer = offers?.find((o) => o.max_active_clients != null);

  const { data: deals, isPending: dealsPending } = useGetList<Deal>(
    "deals",
    {
      filter: { offer_id: offer?.id },
      pagination: { page: 1, perPage: 1000 },
      sort: { field: "id", order: "ASC" },
    },
    { enabled: offer != null },
  );

  const dealIds = deals?.map((deal) => deal.id) ?? [];
  const { data: enrollments, isPending: enrollmentsPending } =
    useGetList<Enrollment>(
      "enrollments",
      {
        filter: { "opportunity_id@in": `(${dealIds.join(",")})` },
        pagination: { page: 1, perPage: 1000 },
        sort: { field: "id", order: "ASC" },
      },
      { enabled: !dealsPending && offer != null },
    );

  const isPending =
    offersPending || (offer != null && (dealsPending || enrollmentsPending));

  if (isPending || !offer) {
    return { isPending, offer: offer ?? null, capacity: null };
  }

  return {
    isPending: false,
    offer,
    capacity: computeLivingExampleCapacity(
      enrollments ?? [],
      offer.max_active_clients ?? null,
    ),
  };
};

import { useMemo } from "react";
import { useGetList } from "ra-core";

import type { Cohort, Deal, Enrollment, Offer } from "../types";
import { useIndividualProgramData } from "../programs/useIndividualProgramData";
import { getDenverDateString } from "./artOracle/selectDailyArtwork";
import {
  computeCohortEvents,
  computeEnrolledCountByCohort,
} from "./cohortEvents";
import { buildComingUpItems, type NextUpItem } from "./comingUpProjection";

// §19/§12: a calm, scannable Coming Up list, not a dumped calendar.
const MAX_ITEMS = 8;

// Next Up / Coming Up's single data-fetching hook (Dashboard temporal-
// intelligence slice, §14/§27): a small constant number of queries
// regardless of how many Cohorts or Enrollments exist — Living Example via
// the SAME useIndividualProgramData.ts the Program page itself uses (its
// upcomingOpenings is not recomputed here), Cohorts via one list query plus
// one Deals query and one Enrollments query scoped to those Cohorts'
// Opportunities (computeEnrolledCountByCohort aggregates all of them in one
// pass — never one useCohortCapacity call per Cohort).
export const useComingUpItems = (): {
  isPending: boolean;
  items: NextUpItem[];
} => {
  const { data: offers, isPending: offersPending } = useGetList<Offer>(
    "offers",
    {
      filter: { type: "individual" },
      pagination: { page: 1, perPage: 10 },
      sort: { field: "id", order: "ASC" },
    },
  );
  // Finds "the" individual Offer with a capacity ceiling, same discovery
  // rule as dashboard/useLivingExampleCapacityData.ts — never a hardcoded
  // name/id.
  const leOffer = offers?.find((offer) => offer.max_active_clients != null);

  const { isPending: leProgramPending, upcomingOpenings } =
    useIndividualProgramData(leOffer?.id);

  const { data: cohorts, isPending: cohortsPending } = useGetList<Cohort>(
    "cohorts",
    {
      pagination: { page: 1, perPage: 100 },
      sort: { field: "program_start_at", order: "ASC" },
    },
  );
  const cohortIds = (cohorts ?? []).map((cohort) => cohort.id);

  const { data: cohortDeals, isPending: cohortDealsPending } = useGetList<Deal>(
    "deals",
    {
      filter: { "cohort_id@in": `(${cohortIds.join(",")})` },
      pagination: { page: 1, perPage: 1000 },
      sort: { field: "id", order: "ASC" },
    },
    { enabled: cohortIds.length > 0 },
  );

  const cohortDealIds = (cohortDeals ?? []).map((deal) => deal.id);
  const { data: cohortEnrollments, isPending: cohortEnrollmentsPending } =
    useGetList<Enrollment>(
      "enrollments",
      {
        filter: { "opportunity_id@in": `(${cohortDealIds.join(",")})` },
        pagination: { page: 1, perPage: 1000 },
        sort: { field: "id", order: "ASC" },
      },
      { enabled: cohortDealIds.length > 0 },
    );

  const isPending =
    offersPending ||
    (leOffer != null && leProgramPending) ||
    cohortsPending ||
    (cohortIds.length > 0 &&
      (cohortDealsPending ||
        (cohortDealIds.length > 0 && cohortEnrollmentsPending)));

  const items = useMemo(() => {
    if (isPending) return [];

    const today = getDenverDateString();
    const enrolledByCohort = computeEnrolledCountByCohort(
      cohortDeals ?? [],
      cohortEnrollments ?? [],
    );
    const cohortEvents = computeCohortEvents(
      cohorts ?? [],
      enrolledByCohort,
      today,
    );

    return buildComingUpItems({
      leOfferId: leOffer?.id ?? null,
      upcomingOpenings: leOffer ? upcomingOpenings : [],
      cohortEvents,
      limit: MAX_ITEMS,
    });
  }, [
    isPending,
    cohorts,
    cohortDeals,
    cohortEnrollments,
    leOffer,
    upcomingOpenings,
  ]);

  return { isPending, items };
};

import type { Enrollment } from "../types";

// Enrollment lifecycle statuses that occupy a Living Example client slot.
// Mirrors cohorts/cohortCapacity.ts's ACTIVE_ENROLLMENT_STATUSES exactly —
// "Completed" never occupies capacity, here or there.
const ACTIVE_ENROLLMENT_STATUSES: ReadonlySet<Enrollment["status"]> = new Set([
  "onboarding",
  "active",
  "offboarding",
]);

export type NextOpening = {
  date: string;
  // How many active Enrollments end in the same calendar month as `date`.
  countInMonth: number;
};

export type LivingExampleCapacity = {
  active: number;
  max: number | null;
  openings: number | null;
  nextOpening: NextOpening | null;
};

// Pure so the "how full is my 1:1 practice" math is unit-testable without a
// data provider. `now` is injectable for deterministic tests.
export const computeLivingExampleCapacity = (
  enrollments: Pick<Enrollment, "status" | "end_date">[],
  max: number | null,
  now: Date = new Date(),
): LivingExampleCapacity => {
  const activeEnrollments = enrollments.filter((enrollment) =>
    ACTIVE_ENROLLMENT_STATUSES.has(enrollment.status),
  );
  const active = activeEnrollments.length;
  const openings = max != null ? Math.max(max - active, 0) : null;

  const futureEndDates = activeEnrollments
    .map((enrollment) => enrollment.end_date)
    .filter((date): date is string => !!date)
    .filter((date) => new Date(date) >= now)
    .sort();

  let nextOpening: NextOpening | null = null;
  if (futureEndDates.length > 0) {
    const earliest = futureEndDates[0]!;
    const earliestMonth = earliest.slice(0, 7); // YYYY-MM
    const countInMonth = futureEndDates.filter(
      (date) => date.slice(0, 7) === earliestMonth,
    ).length;
    nextOpening = { date: earliest, countInMonth };
  }

  return { active, max, openings, nextOpening };
};

import type { Task } from "../types";
import { getDenverDateString } from "./artOracle/selectDailyArtwork";

// Extracted as a pure function (an explicit `now` parameter, never
// `new Date()` internally) so the America/Denver day-boundary logic can be
// tested deterministically without faking timers — vitest-browser-react's
// render hangs under vi.useFakeTimers() in this codebase (see Dashboard.
// comingUp.test.tsx's own header), and livingExampleCapacity.test.ts
// already established injecting `now` as the reliable alternative.
export const selectCompletedToday = (
  tasks: Task[],
  now: Date = new Date(),
): Task[] => {
  const today = getDenverDateString(now);
  return tasks.filter(
    (task) =>
      task.done_date && getDenverDateString(new Date(task.done_date)) === today,
  );
};

import type { Identifier } from "ra-core";

import type { UpcomingOpening } from "../programs/upcomingOpenings";
import type { CohortEvent } from "./cohortEvents";

// Next Up / Coming Up (Dashboard temporal-intelligence slice, §14): the
// centralized VIEW MODEL every Coming Up row renders from — never a
// persisted entity (see this slice's report for why). Deliberately
// structured (not pre-rendered title/detail strings) so ComingUp.tsx does
// the actual translate() calls, the same way every other presentational
// component in this app owns its own i18n rather than baking English text
// into a domain/projection layer.
export type NextUpItem =
  | {
      id: string;
      type: "living_example_opening";
      date: string; // YYYY-MM-DD
      destination: string;
      clientNames: string[];
      openingCount: number;
    }
  | {
      id: string;
      type:
        | "cohort_start"
        | "cohort_end"
        | "cohort_applications_open"
        | "cohort_applications_close";
      date: string; // YYYY-MM-DD
      destination: string;
      cohortName: string;
      enrolledCount: number;
      maxCapacity: number | null;
    };

type CohortNextUpItemType =
  | "cohort_start"
  | "cohort_end"
  | "cohort_applications_open"
  | "cohort_applications_close";

const cohortEventKindToItemType: Record<
  CohortEvent["kind"],
  CohortNextUpItemType
> = {
  applications_open: "cohort_applications_open",
  applications_close: "cohort_applications_close",
  cohort_start: "cohort_start",
  cohort_end: "cohort_end",
};

// Combines the Living Example openings (reusing programs/
// upcomingOpenings.ts's own grouping — never recomputed here) and Cohort
// events into ONE chronological projection, nearest first, capped to
// `limit` (§12/§19: "the next 6-10 meaningful business events", not a
// dumped year of dates). Each underlying fact produces exactly one row —
// see this slice's report for the dedupe rules this depends on upstream
// (computeUpcomingOpenings already merges same-day completions into one
// event; Tasks are never projected here at all).
export const buildComingUpItems = ({
  leOfferId,
  upcomingOpenings,
  cohortEvents,
  limit,
}: {
  leOfferId: Identifier | null;
  upcomingOpenings: UpcomingOpening[];
  cohortEvents: CohortEvent[];
  limit: number;
}): NextUpItem[] => {
  const leItems: NextUpItem[] =
    leOfferId == null
      ? []
      : upcomingOpenings.map((opening) => ({
          id: `le-opening-${opening.date}`,
          type: "living_example_opening",
          date: opening.date,
          destination: `/programs/individual/${leOfferId}#upcoming-openings`,
          clientNames: opening.clients.map((client) => client.name),
          openingCount: opening.count,
        }));

  const cohortItems: NextUpItem[] = cohortEvents.map((event) => ({
    id: `cohort-${event.cohortId}-${event.kind}`,
    type: cohortEventKindToItemType[event.kind],
    date: event.date,
    destination: `/cohorts/${event.cohortId}/show`,
    cohortName: event.cohortName,
    enrolledCount: event.enrolledCount,
    maxCapacity: event.maxCapacity,
  }));

  return [...leItems, ...cohortItems]
    .sort((a, b) => a.date.localeCompare(b.date) || a.id.localeCompare(b.id))
    .slice(0, limit);
};

export type CohortThresholdStatus =
  | "below_minimum"
  | "minimum_reached"
  | "target_reached"
  | "full"
  | "unknown";

// Describes where a Cohort's enrolled count sits relative to its own
// minimum/target/maximum thresholds. Pure formatting only — the enrolled
// count itself must come from the shared cohort capacity classification
// (cohorts/useCohortCapacity.ts), never recomputed here.
export const describeCohortThreshold = ({
  enrolled,
  minimum,
  target,
  maximum,
}: {
  enrolled: number;
  minimum?: number | null;
  target?: number | null;
  maximum?: number | null;
}): CohortThresholdStatus => {
  if (maximum != null && enrolled >= maximum) return "full";
  if (target != null && enrolled >= target) return "target_reached";
  if (minimum != null && enrolled >= minimum) return "minimum_reached";
  if (minimum != null) return "below_minimum";
  return "unknown";
};

import type { Identifier } from "ra-core";

import type { Cohort, Deal, Enrollment } from "../types";

export type CohortEventKind =
  | "applications_open"
  | "applications_close"
  | "cohort_start"
  | "cohort_end";

export type CohortEvent = {
  cohortId: Identifier;
  cohortName: string;
  kind: CohortEventKind;
  date: string; // YYYY-MM-DD
  enrolledCount: number;
  maxCapacity: number | null;
};

type CohortInput = Pick<
  Cohort,
  | "id"
  | "name"
  | "applications_open_at"
  | "applications_close_at"
  | "program_start_at"
  | "program_end_at"
  | "maximum_capacity"
>;

// Next Up / Coming Up (Dashboard temporal-intelligence slice, §7): projects
// each Cohort's own structured dates into discrete future events — never
// inferred or fabricated from a name/status, only from a column that is
// actually set. `todayDateString` must already be an America/Denver
// "YYYY-MM-DD" (dashboard/artOracle/selectDailyArtwork.ts's
// getDenverDateString) — Cohort dates are plain Postgres `date` columns
// (no time component, confirmed in supabase/schemas/01_tables.sql), so
// comparing them as plain strings against that is exact; there is no
// timezone conversion to get wrong here, unlike Task.due_date
// (timestamptz — see tasksPredicate.ts for that one instead).
export const computeCohortEvents = (
  cohorts: CohortInput[],
  enrolledCountByCohortId: Map<string, number>,
  todayDateString: string,
): CohortEvent[] => {
  const events: CohortEvent[] = [];

  const pushIfFuture = (
    cohort: CohortInput,
    kind: CohortEventKind,
    date: string | null | undefined,
  ) => {
    if (!date || date < todayDateString) return;
    events.push({
      cohortId: cohort.id,
      cohortName: cohort.name,
      kind,
      date,
      enrolledCount: enrolledCountByCohortId.get(String(cohort.id)) ?? 0,
      maxCapacity: cohort.maximum_capacity ?? null,
    });
  };

  for (const cohort of cohorts) {
    pushIfFuture(cohort, "applications_open", cohort.applications_open_at);
    pushIfFuture(cohort, "applications_close", cohort.applications_close_at);
    pushIfFuture(cohort, "cohort_start", cohort.program_start_at);
    pushIfFuture(cohort, "cohort_end", cohort.program_end_at);
  }

  return events.sort((a, b) => a.date.localeCompare(b.date));
};

// Enrollment lifecycle statuses that occupy a Cohort seat. Mirrors
// cohorts/cohortCapacity.ts's own ACTIVE_ENROLLMENT_STATUSES exactly — same
// deliberate per-file local copy convention already established there and
// in dashboard/livingExampleCapacity.ts / programs/useIndividualProgramData.ts,
// not a new pattern.
const ACTIVE_ENROLLMENT_STATUSES: ReadonlySet<Enrollment["status"]> = new Set([
  "onboarding",
  "active",
  "offboarding",
]);

// Groups active-enrollment counts by Cohort, via the Deal that links an
// Enrollment to a Cohort — the same relationship useCohortCapacity.ts reads,
// just aggregated across every Cohort in one pass instead of one Cohort at
// a time, so Coming Up's projection stays at a small constant number of
// queries regardless of how many Cohorts exist (no N+1 useCohortCapacity
// call per Cohort).
export const computeEnrolledCountByCohort = (
  deals: Pick<Deal, "id" | "cohort_id">[],
  enrollments: Pick<Enrollment, "opportunity_id" | "status">[],
): Map<string, number> => {
  const cohortIdByDeal = new Map(
    deals
      .filter((deal) => deal.cohort_id != null)
      .map((deal) => [String(deal.id), String(deal.cohort_id)]),
  );

  const counts = new Map<string, number>();
  for (const enrollment of enrollments) {
    if (!ACTIVE_ENROLLMENT_STATUSES.has(enrollment.status)) continue;
    const cohortId = cohortIdByDeal.get(String(enrollment.opportunity_id));
    if (!cohortId) continue;
    counts.set(cohortId, (counts.get(cohortId) ?? 0) + 1);
  }
  return counts;
};

