// Centralizes the Do Not Engage guard (Native Applications repair pass,
// §4; reused by the Waitlists slice, §5) so it lives in exactly one place
// rather than being reimplemented per "select a Contact" field — the
// Opportunity Person field and the Waitlist Person field both call this.
import type { DataProvider, Identifier } from "ra-core";

import type { Contact } from "../types";

export const isContactDoNotEngage = async (
  dataProvider: DataProvider,
  contactId: Identifier,
): Promise<boolean> => {
  const { data: contact } = await dataProvider.getOne<Contact>("contacts", {
    id: contactId,
  });
  return contact.sales_eligibility === "do_not_engage";
};

// An async validate() function for react-admin's `validate` prop on any
// "select a Contact" input. The Contact stays fully selectable in the
// field itself (hiding them would just invite an accidental duplicate
// Contact) — this only blocks the *submission* that would create a new
// direct-sales relationship for them. `enabled` lets the caller scope
// blocking narrowly (e.g. never when merely editing something that
// already exists for a Contact who became DNE afterward).
export const doNotEngageValidator =
  (dataProvider: DataProvider, message: string, enabled = true) =>
  async (value?: Identifier) => {
    if (!enabled || !value) return undefined;
    const isDne = await isContactDoNotEngage(dataProvider, value);
    return isDne ? message : undefined;
  };

import type { SortOption } from "@/components/admin/sort-button";

// Every ordering the Contacts list offers, named in business language.
//
// Spelled out rather than using SortButton's `fields` API, which shows one
// entry per field and flips direction on re-click: a field you are not
// already sorting by always starts ASC, so "Date added — newest first"
// would take two clicks and "oldest first" would be unreachable in one.
// For date columns the direction IS the thing being chosen.
//
// first_seen is when the Contact first entered the CRM's knowledge and
// last_seen their most recent known activity — both real columns on
// contacts_summary, so every option below actually sorts.
export const CONTACT_SORT_OPTIONS: SortOption[] = [
  { field: "first_seen", order: "DESC", label: "Date added — newest first" },
  { field: "first_seen", order: "ASC", label: "Date added — oldest first" },
  { field: "last_seen", order: "DESC", label: "Last activity — newest first" },
  { field: "last_seen", order: "ASC", label: "Last activity — oldest first" },
  { field: "first_name", order: "ASC", label: "First name — A→Z" },
  { field: "first_name", order: "DESC", label: "First name — Z→A" },
  { field: "last_name", order: "ASC", label: "Last name — A→Z" },
  { field: "last_name", order: "DESC", label: "Last name — Z→A" },
];

// Newest-first: for daily operation the people who just arrived are the
// ones Leif is most likely to be looking for. Supersedes the previous
// alphabetical default, which was chosen when first_seen/last_seen carried
// no data for most Contacts — see the backfill in
// 20260917230000_contact_first_last_seen_backfill.sql.
export const CONTACT_DEFAULT_SORT = {
  field: "first_seen",
  order: "DESC" as const,
};

import { Mars, NonBinary, Venus } from "lucide-react";

import type { Company, Contact, ContactGender } from "../types";

export const defaultEmailJsonb = [{ email: null, type: null }];
export const defaultPhoneJsonb = [{ number: null, type: null }];

const cleanContactArrayFields = (data: Contact) => {
  const cleanedEmailJsonb =
    data.email_jsonb?.filter((e) => e.email != null) || [];
  const cleanedPhoneJsonb =
    data.phone_jsonb?.filter((p) => p.number != null) || [];
  return {
    ...data,
    phone_jsonb: cleanedPhoneJsonb.length > 0 ? cleanedPhoneJsonb : null,
    email_jsonb: cleanedEmailJsonb.length > 0 ? cleanedEmailJsonb : null,
  };
};

export const cleanupContactForCreate = (data: Contact) => {
  return cleanContactArrayFields({
    ...data,
    first_seen: new Date().toISOString(),
    last_seen: new Date().toISOString(),
    tags: [],
  });
};

export const cleanupContactForEdit = cleanContactArrayFields;

