import { useGetList, useGetMany, type Identifier } from "ra-core";

import type { Application, Cohort, Contact, Offer } from "../types";

// The 159 imported Applications, which the Applications page could not show
// at all: useApplicationsGrouped filters the WHOLE page to
// source = 'public_form', so with every Application imported the page read
// "No applications yet" while production held 159 of them.
//
// That filter is right for Needs Review — a back-filled record of something
// that already happened is not present-day review work — and stays exactly
// as it is. This hook is the other half: the same records, browsable as
// history.
//
// Two things make this NOT a copy of useApplicationsGrouped:
//   - It resolves Offer and Cohort from the APPLICATION's own offer_id /
//     intended_cohort_id, so the 88 imported Applications with no
//     Opportunity still appear. Grouping via the Deal drops every one of
//     them, because there is no Deal to read an offer off.
//   - It never contributes to any review queue or count.

export type HistoricalApplicationRow = {
  applicationId: Identifier;
  contactId: Identifier;
  contactName: string;
  status: Application["status"];
  submittedAt: string;
  // A historical Application with no Opportunity is a real and common
  // shape, not a broken row — surfaced so the UI can say so plainly.
  hasOpportunity: boolean;
  opportunityId: Identifier | null;
};

export type HistoricalApplicationGroup = {
  key: string;
  offer: Offer | undefined;
  cohort: Cohort | undefined;
  label: string;
  applications: HistoricalApplicationRow[];
};

export const useHistoricalApplications = (): {
  isPending: boolean;
  total: number;
  groups: HistoricalApplicationGroup[];
} => {
  const { data: applications, isPending: applicationsPending } =
    useGetList<Application>("applications", {
      // No filter: partitioned below on source instead. A "not equal"
      // operator is not mapped by the FakeRest adapter (see AGENTS.md on
      // filter operators), so filtering here would work against Supabase
      // and silently return nothing in the demo/test provider.
      filter: {},
      pagination: { page: 1, perPage: 1000 },
      sort: { field: "submitted_at", order: "DESC" },
    });

  // Imported records only. A live public-form submission is present-day
  // review work and belongs to useApplicationsGrouped, never to history.
  const historical = (applications ?? []).filter(
    (application) => application.source !== "public_form",
  );

  const contactIds = [...new Set(historical.map((a) => a.contact_id))].filter(
    (id): id is Identifier => id != null,
  );
  const { data: contacts, isPending: contactsPending } = useGetMany<Contact>(
    "contacts",
    { ids: contactIds },
    { enabled: contactIds.length > 0 },
  );

  const { data: offers, isPending: offersPending } = useGetList<Offer>(
    "offers",
    {
      pagination: { page: 1, perPage: 100 },
      sort: { field: "id", order: "ASC" },
    },
  );
  const { data: cohorts, isPending: cohortsPending } = useGetList<Cohort>(
    "cohorts",
    {
      pagination: { page: 1, perPage: 200 },
      sort: { field: "id", order: "ASC" },
    },
  );

  const isPending =
    applicationsPending ||
    offersPending ||
    cohortsPending ||
    (contactIds.length > 0 && contactsPending);

  if (isPending) return { isPending: true, total: 0, groups: [] };

  const contactById = new Map((contacts ?? []).map((c) => [String(c.id), c]));
  const offerById = new Map((offers ?? []).map((o) => [String(o.id), o]));
  const cohortById = new Map((cohorts ?? []).map((c) => [String(c.id), c]));

  const byKey = new Map<string, HistoricalApplicationGroup>();

  for (const application of historical) {
    const offer =
      application.offer_id != null
        ? offerById.get(String(application.offer_id))
        : undefined;
    const cohort =
      application.intended_cohort_id != null
        ? cohortById.get(String(application.intended_cohort_id))
        : undefined;
    const contact = contactById.get(String(application.contact_id));

    // Cohort-specific intent groups under that cohort; otherwise under the
    // Offer. An Application whose Offer cannot be resolved still gets a
    // group rather than disappearing — losing a real record to a lookup
    // miss is worse than an "Unassigned" heading.
    const key = cohort
      ? `cohort:${cohort.id}`
      : offer
        ? `offer:${offer.id}`
        : "unassigned";
    const label = cohort?.name ?? offer?.name ?? "Program not recorded";

    const group = byKey.get(key) ?? {
      key,
      offer,
      cohort,
      label,
      applications: [],
    };
    group.applications.push({
      applicationId: application.id,
      contactId: application.contact_id,
      contactName: contact
        ? `${contact.first_name} ${contact.last_name}`
        : "Contact not found",
      status: application.status,
      submittedAt: application.submitted_at,
      hasOpportunity: application.opportunity_id != null,
      opportunityId: application.opportunity_id ?? null,
    });
    byKey.set(key, group);
  }

  const groups = [...byKey.values()].sort((a, b) =>
    a.label.localeCompare(b.label),
  );

  return {
    isPending: false,
    total: historical.length,
    groups,
  };
};

import { useGetList, useGetMany, type Identifier } from "ra-core";

import type { Application, Cohort, Contact, Deal, Offer } from "../types";

export type ApplicationRow = {
  applicationId: Identifier;
  dealId: Identifier;
  contactId: Identifier;
  contactName: string;
  status: Application["status"];
  submittedAt: string;
};

export type IndividualOfferGroup = {
  offer: Offer;
  applications: ApplicationRow[];
};

export type CohortGroup = {
  cohort: Cohort;
  applications: ApplicationRow[];
};

export type GroupOfferGroup = {
  offer: Offer;
  cohorts: CohortGroup[];
};

export type ApplicationGroups = {
  individualGroups: IndividualOfferGroup[];
  groupOfferGroups: GroupOfferGroup[];
};

// Backs the Applications page's Needs Review / Reviewed split (UX cleanup
// pass, §3) over the SAME Offer/1:1 vs Cohort/GYU grouping the page
// already used (Runtime + Visual Consistency slice, §5): real Offer/Cohort
// relationships, not a new Application table or a hand-maintained grouping
// list. An Application with no matching deal/offer (shouldn't happen, but
// data can always be mid-migration) is simply omitted rather than crashing
// the page. "Needs review" is exactly `status === 'pending'` — the same
// vocabulary reviewApplication.ts and applicationConstants.ts already use;
// no new review-state concept introduced.
export const useApplicationsGrouped = (): {
  isPending: boolean;
  needsReview: ApplicationGroups;
  reviewed: ApplicationGroups;
} => {
  const { data: applications, isPending: applicationsPending } =
    useGetList<Application>("applications", {
      // Live submissions only. Imported historical Applications keep their
      // true status ('pending', 'approved', ...) because that is what the
      // source recorded, but a back-filled record of something that already
      // happened is not present-day review work — without this filter the
      // historical import would drop ~97 "pending" rows into the Needs
      // Review queue. Distinguished by record origin rather than by
      // falsifying status.
      filter: { source: "public_form" },
      pagination: { page: 1, perPage: 1000 },
      sort: { field: "submitted_at", order: "DESC" },
    });

  // opportunity_id is optional now, so only Applications that actually have
  // an Opportunity contribute a Deal id to look up.
  const dealIds = [
    ...new Set(
      (applications ?? [])
        .map((a) => a.opportunity_id)
        .filter((id): id is Identifier => id != null),
    ),
  ];
  const { data: deals, isPending: dealsPending } = useGetMany<Deal>(
    "deals",
    { ids: dealIds },
    { enabled: dealIds.length > 0 },
  );

  const offerIds = [...new Set((deals ?? []).map((d) => d.offer_id))];
  const { data: offers, isPending: offersPending } = useGetMany<Offer>(
    "offers",
    { ids: offerIds },
    { enabled: offerIds.length > 0 },
  );

  const cohortIds = [
    ...new Set(
      (deals ?? [])
        .map((d) => d.cohort_id)
        .filter((id): id is Identifier => id != null),
    ),
  ];
  const { data: cohorts, isPending: cohortsPending } = useGetMany<Cohort>(
    "cohorts",
    { ids: cohortIds },
    { enabled: cohortIds.length > 0 },
  );

  const contactIds = [...new Set((deals ?? []).map((d) => d.contact_id))];
  const { data: contacts, isPending: contactsPending } = useGetMany<Contact>(
    "contacts",
    { ids: contactIds },
    { enabled: contactIds.length > 0 },
  );

  const isPending =
    applicationsPending ||
    (dealIds.length > 0 &&
      (dealsPending ||
        (offerIds.length > 0 && offersPending) ||
        (cohortIds.length > 0 && cohortsPending) ||
        (contactIds.length > 0 && contactsPending)));

  const empty: ApplicationGroups = {
    individualGroups: [],
    groupOfferGroups: [],
  };
  if (isPending) {
    return { isPending: true, needsReview: empty, reviewed: empty };
  }

  const dealById = new Map((deals ?? []).map((d) => [String(d.id), d]));
  const offerById = new Map((offers ?? []).map((o) => [String(o.id), o]));
  const contactById = new Map((contacts ?? []).map((c) => [String(c.id), c]));

  const buildGroups = (rows: ApplicationRow[]): ApplicationGroups => {
    const rowsByOfferId = new Map<string, ApplicationRow[]>();
    const rowsByCohortId = new Map<string, ApplicationRow[]>();

    for (const row of rows) {
      const deal = dealById.get(String(row.dealId));
      if (!deal) continue;
      const offer = offerById.get(String(deal.offer_id));
      if (!offer) continue;

      if (offer.type === "individual") {
        const key = String(offer.id);
        rowsByOfferId.set(key, [...(rowsByOfferId.get(key) ?? []), row]);
      } else if (deal.cohort_id != null) {
        const key = String(deal.cohort_id);
        rowsByCohortId.set(key, [...(rowsByCohortId.get(key) ?? []), row]);
      }
    }

    const individualGroups: IndividualOfferGroup[] = (offers ?? [])
      .filter((offer) => offer.type === "individual")
      .map((offer) => ({
        offer,
        applications: rowsByOfferId.get(String(offer.id)) ?? [],
      }))
      .filter((group) => group.applications.length > 0);

    const groupOfferGroups: GroupOfferGroup[] = (offers ?? [])
      .filter((offer) => offer.type === "group")
      .map((offer) => ({
        offer,
        cohorts: (cohorts ?? [])
          .filter((cohort) => String(cohort.offer_id) === String(offer.id))
          .map((cohort) => ({
            cohort,
            applications: rowsByCohortId.get(String(cohort.id)) ?? [],
          }))
          .filter((cohortGroup) => cohortGroup.applications.length > 0),
      }))
      .filter((group) => group.cohorts.length > 0);

    return { individualGroups, groupOfferGroups };
  };

  const needsReviewRows: ApplicationRow[] = [];
  const reviewedRows: ApplicationRow[] = [];

  for (const application of applications ?? []) {
    const deal = dealById.get(String(application.opportunity_id));
    if (!deal) continue;
    const offer = offerById.get(String(deal.offer_id));
    if (!offer) continue;
    const contact = contactById.get(String(deal.contact_id));

    const row: ApplicationRow = {
      applicationId: application.id,
      dealId: deal.id,
      contactId: deal.contact_id,
      contactName: contact
        ? `${contact.first_name} ${contact.last_name}`
        : deal.name,
      status: application.status,
      submittedAt: application.submitted_at,
    };

    (application.status === "pending" ? needsReviewRows : reviewedRows).push(
      row,
    );
  }

  return {
    isPending: false,
    needsReview: buildGroups(needsReviewRows),
    reviewed: buildGroups(reviewedRows),
  };
};

import { useGetOne } from "ra-core";

import type { Application, Cohort, Contact, Deal, Offer } from "../types";

// Backs the Application review page (Native Applications slice, §2/§3):
// the Application's linked Opportunity, and that Opportunity's Contact/
// Offer/Cohort — everything the page needs to show "Rosalind Park — The
// Living Example · Submitted Aug 31, 2026 · Pending" instead of a raw
// "Application #4" title, and to know what to write when a review
// decision is made.
export const useApplicationReviewData = (application?: Application) => {
  const { data: deal, isPending: dealPending } = useGetOne<Deal>(
    "deals",
    { id: application?.opportunity_id as Deal["id"] },
    { enabled: application != null },
  );

  const { data: contact, isPending: contactPending } = useGetOne<Contact>(
    "contacts",
    { id: deal?.contact_id as Contact["id"] },
    { enabled: deal != null },
  );

  const { data: offer, isPending: offerPending } = useGetOne<Offer>(
    "offers",
    { id: deal?.offer_id as Offer["id"] },
    { enabled: deal != null },
  );

  const { data: cohort, isPending: cohortPending } = useGetOne<Cohort>(
    "cohorts",
    { id: deal?.cohort_id as Cohort["id"] },
    { enabled: deal?.cohort_id != null },
  );

  const isPending =
    application == null ||
    dealPending ||
    contactPending ||
    offerPending ||
    (deal?.cohort_id != null && cohortPending);

  return {
    isPending,
    deal: isPending ? undefined : deal,
    contact: isPending ? undefined : contact,
    offer: isPending ? undefined : offer,
    cohort: deal?.cohort_id != null && !cohortPending ? cohort : undefined,
  };
};

import type { DataProvider, Identifier } from "ra-core";

import type { Task } from "../types";

const REVIEW_APPLICATION_TASK_TYPE = "review_application";

// Task's only link to a Contact is `contact_id` — there is no
// opportunity_id/application_id FK on Task (Native Applications slice,
// §19: adding one would be a second schema change beyond the one already
// agreed for this slice). This matches "the" pending review task for a
// Contact heuristically: correct for the product's normal one-application-
// at-a-time pattern. Known limitation: if a Contact ever has two
// concurrently pending Applications, this resolves to whichever such task
// was created first, not necessarily the one for the Application just
// reviewed.
export const findPendingReviewApplicationTask = async (
  dataProvider: DataProvider,
  contactId: Identifier,
): Promise<Task | null> => {
  const { data } = await dataProvider.getList<Task>("tasks", {
    filter: { contact_id: contactId, type: REVIEW_APPLICATION_TASK_TYPE },
    pagination: { page: 1, perPage: 50 },
    sort: { field: "id", order: "ASC" },
  });
  return data.find((task) => !task.done_date) ?? null;
};

// Creates the "Review Application" task for a newly pending Application,
// unless one already exists for this Contact (§8: one pending task per
// pending Application, never a duplicate).
export const ensureReviewApplicationTask = async (
  dataProvider: DataProvider,
  {
    contactId,
    applicantName,
    salesId,
  }: {
    contactId: Identifier;
    applicantName: string;
    salesId?: Identifier | null;
  },
): Promise<void> => {
  const existing = await findPendingReviewApplicationTask(
    dataProvider,
    contactId,
  );
  if (existing) return;

  await dataProvider.create("tasks", {
    data: {
      contact_id: contactId,
      type: REVIEW_APPLICATION_TASK_TYPE,
      text: `Review ${applicantName}'s application`,
      due_date: new Date().toISOString(),
      status: "pending",
      ...(salesId != null ? { sales_id: salesId } : {}),
    },
  });
};

// Completing the review is what completes the task — never the reverse
// (§8: a Task only represents work to do; completing it manually must
// never change Application status, and this function is the only writer
// that flips done_date on a review_application task from application
// review).
export const completeReviewApplicationTask = async (
  dataProvider: DataProvider,
  contactId: Identifier,
  completedAt: string,
): Promise<void> => {
  const task = await findPendingReviewApplicationTask(dataProvider, contactId);
  if (!task) return;

  await dataProvider.update("tasks", {
    id: task.id,
    // done_date/status are set together explicitly rather than relying on
    // FakeRest's done_date -> status sync hook, since the real Supabase
    // provider has no equivalent trigger (see reviewApplication.ts).
    data: { done_date: completedAt, status: "completed" },
    previousData: task,
  });
};

import type { DataProvider } from "ra-core";

import type { Application, Deal } from "../types";
import {
  applyDoNotEngageToContact,
  buildDoNotEngageDealUpdate,
} from "../deals/dneOutcome";
import { completeReviewApplicationTask } from "./reviewApplicationTask";

// Deliberately an explicit literal union, NOT `Exclude<ApplicationStatus,
// "pending">` — ApplicationStatus also carries 'denied'/'waitlist'
// (historical-import-only values, Phase 4H). Deriving this type from
// ApplicationStatus would silently let those two leak in here as if a live
// review action could set them, and buildDealUpdate's switch below would
// return undefined for them with no compiler error (no exhaustiveness
// check on a switch without a `never` default). Neither value is ever a
// choice Leif makes via a review action.
export type ApplicationReviewOutcome =
  | "approved"
  | "needs_higher_care"
  | "not_fit"
  | "do_not_engage";

export type ReviewApplicationResult =
  | { applied: true }
  | { applied: false; reason: "already-reviewed" };

// Centralizes every write an Application review decision requires across
// Application / Opportunity / Contact / Task (Native Applications slice,
// §19 — the UI calls this trustworthy domain operation, business rules
// never live in a button's onClick). Idempotent: re-running against an
// Application that is no longer "pending" is a safe no-op rather than a
// second write, so a double-click, a cached tab, or Back/Forward can never
// silently overwrite a newer decision (§17.F/G) — the caller checks
// `applied` and tells the user rather than assuming success. The pending
// check re-fetches the Application rather than trusting the caller's
// `application` argument: a stale UI's copy of that argument is exactly as
// stale as what it's meant to guard against, so only the server's current
// state can actually detect "someone else already reviewed this".
export const reviewApplication = async ({
  dataProvider,
  application,
  deal,
  outcome,
}: {
  dataProvider: DataProvider;
  application: Pick<Application, "id">;
  deal: Pick<
    Deal,
    "id" | "contact_id" | "stage" | "outcome" | "owner_decision"
  >;
  outcome: ApplicationReviewOutcome;
}): Promise<ReviewApplicationResult> => {
  const { data: currentApplication } = await dataProvider.getOne<Application>(
    "applications",
    { id: application.id },
  );
  if (currentApplication.status !== "pending") {
    return { applied: false, reason: "already-reviewed" };
  }

  const { data: currentDeal } = await dataProvider.getOne<Deal>("deals", {
    id: deal.id,
  });

  const reviewedAt = new Date().toISOString();

  await dataProvider.update("applications", {
    id: currentApplication.id,
    data: { status: outcome, reviewed_at: reviewedAt },
    previousData: currentApplication,
  });

  await dataProvider.update("deals", {
    id: currentDeal.id,
    data: buildDealUpdate(outcome),
    previousData: currentDeal,
  });

  if (outcome === "do_not_engage") {
    await applyDoNotEngageToContact(dataProvider, currentDeal.contact_id);
  }

  // Review Application completes automatically on any outcome (§4-§7) —
  // never the reverse (see reviewApplicationTask.ts).
  await completeReviewApplicationTask(
    dataProvider,
    currentDeal.contact_id,
    reviewedAt,
  );

  return { applied: true };
};

const buildDealUpdate = (outcome: ApplicationReviewOutcome): Partial<Deal> => {
  switch (outcome) {
    case "approved":
      // "Qualified enough for a sales call" — the pipeline moves forward;
      // final personal fit is still undecided (§1/§4). outcome stays null,
      // explicitly re-asserted here in case a prior review round set one.
      return { stage: "approved", outcome: null };
    case "needs_higher_care":
      return { outcome: "needs_higher_care" };
    case "not_fit":
      return { outcome: "not_fit" };
    case "do_not_engage":
      // See deals/dneOutcome.ts for why this is 'lost' + owner_decision
      // rather than a dedicated Opportunity outcome value (§7) — shared
      // with sales-calls/completeSalesCallOutcome.ts's own Do Not Engage
      // branch so the logic lives in exactly one place.
      return buildDoNotEngageDealUpdate();
  }
};

