  { value: "approved", label: "Approved" },
  { value: "needs_higher_care", label: "Needs Higher Care" },
  { value: "not_fit", label: "Not Fit" },
  { value: "do_not_engage", label: "Do Not Engage" },
  { value: "denied", label: "Denied (historical)" },
